export const ttcmSentences: Sentence[] = [
  {"id":"s_work_ttcm_1_1","chapterId":"ch_work_ttcm_1","text":"序論","sortOrder":1},
  {"id":"s_work_ttcm_1_2","chapterId":"ch_work_ttcm_1","text":"謂之《正蒙》者，養蒙以聖功之正也。聖功久矣，大矣，而正之惟其始。蒙者，知之始也。孟子曰：“始條理者，智之事也。”其始不正，未有能成章而達者也。","sortOrder":2},
  {"id":"s_work_ttcm_1_3","chapterId":"ch_work_ttcm_1","text":"或疑之曰：“古之大學，造之以《詩》《書》《禮》《樂》，迪之以三德六行，皆日用易知簡能之理。而《正蒙》推極夫窮神、知化、達天德之蘊，則疑與大學異。”子夏曰：“有始有卒者，其惟聖人乎？”今以是養蒙，恐未能猝喻而益其疑。則請釋之曰：“大學之教，先王所以廣教天下而納之軌物，使賢者即以之上達而中人以之寡過。先王不能望天下以皆聖，故尧舜之仅有禹、皋陶，湯之仅有伊尹、萊朱，文王之仅有太公望、散宜生，其他則德其成人，造其小子，不強之以聖功而俟其自得，非有吝也。《正蒙》者，以奖大心者而使之希聖，所由不得不異也。”","sortOrder":3},
  {"id":"s_work_ttcm_1_4","chapterId":"ch_work_ttcm_1","text":"抑古之為士者，秀而未離乎其朴，下之無記誦詞章以取爵祿之科，次之無權謀功利苟且以就功名之術；其尤正者，無狂思陋测，荡天理，蔑彝倫而自矜獨悟，如老聃、浮屠之邪說，以誘聰明果毅之士而生其逸獲神聖之心，則但習於人倫物理之當然，而性命之正自不言而喻，至於東周而邪慝作矣。故夫子贊《易》而闡形而上之道，以顯諸仁而藏諸用，而孟子推生物一本之理，以極惻隱、羞惡、辭讓、是非之所由生。《大學》之道，明德以修己，新民以治人，人道備矣。而必申之曰“止於至善”。不知止至善，則不定，不靜，不安，而慮非所慮，未有能得者也。故夫子曰：“吾十有五而志於學。”所志者，知命、耳順、不逾之矩也，知其然者，志不及之，則雖聖人未有得之於志外者也。故孟子曰：“大匠不為拙工改废繩墨，羿不為拙射变其彀率。”宜若登天而不可使逸獲於企及也。特在孟子之世，楊墨雖盈天下，而儒者猶不屑曲吾道以證其邪，故可引而不發以需其自得。而自漢魏以降，儒者無所不淫，苟不抉其躍如之藏，則志之搖搖者，差之黍米而已背之霄壤矣，此《正蒙》之所由不得不異也。","sortOrder":4},
  {"id":"s_work_ttcm_1_5","chapterId":"ch_work_ttcm_1","text":"宋自周子出，而始發明聖道之所由，一出於太極陰陽人道生化之終始，二程子引而申之，而實之以靜一誠敬之功，然遊、謝之徒，且歧出以趨於浮屠之蹊径。故朱子以格物窮理為始教，而檠括學者於顯道之中；乃其一再傳而後，流為双峰、勿軒諸儒，逐跡躡影，沉溺於訓詁。故白沙起而厭弃之，然而遂啟姚江王氏陽儒陰釋、誣聖之邪說；其究也為刑戮之民，為閹賊之党，皆爭附焉，而以充其無善無惡、圓融理事之狂妄，流害以相激而相成，則中道不立、矯枉過正有以啟之也。","sortOrder":5},
  {"id":"s_work_ttcm_1_6","chapterId":"ch_work_ttcm_1","text":"人之生也，君子而極乎聖，小人而極乎禽獸，然而吉凶窮達之數，於此於彼，未有定焉。不知所以生，不知所以死，則為善為惡，皆非性分之所固有，職分之所當為，下焉者何弗荡弃彝倫以遂其苟且私利之欲！其稍有恥之心而厭焉者，則見為寄生兩間，去來無准，惡為赘疣，善亦弁髦，生無所從，而名義皆屬漚瀑，兩滅無餘，以求異於逐而不返之顽鄙。乃其究也不可以終日，則又必佚出猖狂，為無縛無礙之邪說，終歸於無忌憚。自非究吾之所始與其所終，神之所化，鬼之所歸，效天地之正而不容不懼以終始，惡能釋其惑而使信於學！故《正蒙》特揭陰陽之固有，屈伸之必然，以立中道，而至當百順之大經，皆率此以成，故曰“率性之謂道”。天之外無道，氣之外無神，神之外無化，死不足忧而生不可罔，一瞬一息，一宵一晝，一言一動，赫然在出王遊衍之中，善吾伸者以善吾屈。然後知聖人之存神盡性，反經精義，皆性所必有之良能，而為職分之所當修，非可以見聞所及而限為有，不見不聞而疑其無，偷用其蕞然之聰明，或窮大而失居，或卑近而自蔽之可以希觊聖功也。呜呼！張子之學，上承孔、孟之志，下救來茲之失，如皎日麗天，無幽不燭，聖人复起，未有能易焉者也。學之興於宋也，周子得二程子而道著。程於之道廣，而一時之英才輻輳於其門；張子教學於關中，其門人未有殆庶者。而當時鉅公耆儒如富、文、司馬諸公，張子皆以素位隱居而末由相為羽翼，是以其道之行，曾不得與邵康節之數學相與頡颃，而世之信從者寡，故道之誠然者不著。貞邪相競而互為畸勝，是以不百年而陆子靜之異說興，又二百年而王伯安之邪說熹，其以朱子格物、道問學之教爭貞勝者，猶水之勝火，一盈一虛而莫適有定。使張子之學晓然大明，以正童蒙之志於始，則浮屠生死之狂惑，不折而自摧；陆子靜、王伯安之蕞然者，亦惡能傲君子以所獨知，而為浮屠作率獸食人之伥乎！","sortOrder":6},
  {"id":"s_work_ttcm_1_7","chapterId":"ch_work_ttcm_1","text":"周易者，天道之顯也，性之藏也，聖功之牖也，陰陽、動靜、幽明、屈伸，誠有之而神行焉，禮樂之精微存焉，鬼神之化裁出焉，仁義之大用興焉，治亂、吉凶、生死之數准焉，故夫子曰“弥纶天下之道以崇德而廣業”者也。張子之學，無非《易》也，即無非《詩》之志，《書》之事，《禮》之節，《樂》之和，《春秋》之大法也。論、孟之要歸也，自朱子慮學者之骛遠而忘邇，测微而遺顯；其教門人也，以《易》為占筮之書而不使之學，蓋亦矯枉之過，幾令伏羲、文王、周公、孔子繼天立極、扶正人心之大法，下同京房、管辂、郭璞、贾耽壬遁奇禽之小技。而張子言無非《易》，立天，立地，立人，反經研幾，精義存神，以綱維三才，貞生而安死，則往聖之傳，非張子其孰與歸！","sortOrder":7},
  {"id":"s_work_ttcm_1_8","chapterId":"ch_work_ttcm_1","text":"呜呼！孟子之功不在禹下，張子之功又豈非疏洚水之歧流，引萬派而歸墟，使斯人去昏墊而履平康之坦道哉！是匠者之繩墨也，射者之彀率也，雖力之未逮，養之未熟，見為登天之難不可企及，而志於是則可至焉，不志於是未有能至者也，養蒙以是為聖功之所自定，而邪說之淫蠱不足以亂之矣，故曰《正蒙》也。衡陽王夫之論。","sortOrder":8},
  {"id":"s_work_ttcm_2_1","chapterId":"ch_work_ttcm_2","text":"張子正蒙註卷一","sortOrder":1},
  {"id":"s_work_ttcm_2_2","chapterId":"ch_work_ttcm_2","text":"太和篇","sortOrder":2},
  {"id":"s_work_ttcm_2_3","chapterId":"ch_work_ttcm_2","text":"此篇首明道之所自出，物之所自生，性之所自受，而作聖之功，下學之事，必達於此，而後不為異端所惑，蓋即太極圖說之旨而發其所函之蘊也。","sortOrder":3},
  {"id":"s_work_ttcm_2_4","chapterId":"ch_work_ttcm_2","text":"太和所謂道，","sortOrder":4},
  {"id":"s_work_ttcm_2_5","chapterId":"ch_work_ttcm_2","text":"太和，和之至也。道者，天地人物之通理，即所謂太極也。陰陽異撰，而其絪缊於太虛之中，合同而不相悖害，浑淪無間，和之至矣。未有形器之先，本無不和，既有形器之後，其和不失，故曰太和。","sortOrder":5},
  {"id":"s_work_ttcm_2_6","chapterId":"ch_work_ttcm_2","text":"中涵浮沉、升降、動靜相感之性，是生絪缊相荡、勝負屈伸之始。","sortOrder":6},
  {"id":"s_work_ttcm_2_7","chapterId":"ch_work_ttcm_2","text":"涵，如水中涵影之象；中涵者其體，是生者其用也。輕者浮，重者沉，親上者升，親下者降，動而趨行者動，動而赴止者靜，皆陰陽和合之氣所必有之幾，而成乎情之固然，猶人之有性也。絪缊，太和未分之本然；相荡，其必然之理势；勝負，因其分數之多寡；乘乎時位，一盈一虛也。勝則伸，負則屈；勝負屈伸，衰王死生之成象，其始則動之幾也。此言天地人物消長死生自然之數，皆太和必有之幾。","sortOrder":7},
  {"id":"s_work_ttcm_2_8","chapterId":"ch_work_ttcm_2","text":"其來也幾微易簡，其究也廣大堅固。","sortOrder":8},
  {"id":"s_work_ttcm_2_9","chapterId":"ch_work_ttcm_2","text":"來，謂始動而化之初；究，謂已成形體也。幾微，氣之初；動易簡者，唯陽健陰順而已。廣大，品物流形，堅固，體成而不易毀也。乾、坤有體則必生用，用而還成其體。體靜而用動，故曰“靜極而動，動極而靜”，動靜無端。","sortOrder":9},
  {"id":"s_work_ttcm_2_10","chapterId":"ch_work_ttcm_2","text":"起知於易者《乾》乎！效法於簡者《坤》乎！","sortOrder":10},
  {"id":"s_work_ttcm_2_11","chapterId":"ch_work_ttcm_2","text":"太和本然之體，未有知也，未有能也，易簡而已。而其所涵之性，有健有順，故知於此起，法於此效，而大用行矣。","sortOrder":11},
  {"id":"s_work_ttcm_2_12","chapterId":"ch_work_ttcm_2","text":"散殊而可象為氣，清通而不可象為神。","sortOrder":12},
  {"id":"s_work_ttcm_2_13","chapterId":"ch_work_ttcm_2","text":"太和之中，有氣有神。神者非他，二氣清通之理也。不可象者，即在象中。陰與陽和，氣與神和，是謂太和。人生而物感交，氣逐於物，役氣而遺神，神為使而迷其健順之性，非其生之本然也。","sortOrder":13},
  {"id":"s_work_ttcm_2_14","chapterId":"ch_work_ttcm_2","text":"不如野馬、絪缊，不足謂之太和。","sortOrder":14},
  {"id":"s_work_ttcm_2_15","chapterId":"ch_work_ttcm_2","text":"此言體道者不於物感未交、喜怒哀樂未倚之中，合氣於神，合神於性，以健順五常之理融會於清通，生其变化，而有滯有息，則不足以肖太和之本體，而用亦不足以行矣。敔按：清通者，心之神，变化者，心之化","sortOrder":15},
  {"id":"s_work_ttcm_2_16","chapterId":"ch_work_ttcm_2","text":"語道者知此，謂之知道；學《易》者見此，謂之見《易》。","sortOrder":16},
  {"id":"s_work_ttcm_2_17","chapterId":"ch_work_ttcm_2","text":"見，實證之於心也。《易》曰：“陰陽相摩，八卦相荡，鼓之以雷霆，润之以風雨，日月運行，一寒一暑，乾道成男，坤道成女。”此之謂也。健順合而太和，其幾必動，氣以成形，神以居理，性固具足於神氣之中，天地之生人物，人之肖德於天地者，唯此而已矣。","sortOrder":17},
  {"id":"s_work_ttcm_2_18","chapterId":"ch_work_ttcm_2","text":"不如此，雖周公才美，其智不足稱也已。","sortOrder":18},
  {"id":"s_work_ttcm_2_19","chapterId":"ch_work_ttcm_2","text":"待其已感、因事而效能者，才也；智則灼見道體，而知無不起，法無不效矣。敔按：知道見易，始謂之智；智不足而恃才，雖美如周公，亦不足稱","sortOrder":19},
  {"id":"s_work_ttcm_2_20","chapterId":"ch_work_ttcm_2","text":"太虛無形，氣之本體；","sortOrder":20},
  {"id":"s_work_ttcm_2_21","chapterId":"ch_work_ttcm_2","text":"於太虛之中具有而未成乎形，氣自足也，聚散变化，而其本體不為之損益。敔按：理具陰陽，陰陽具理，理氣浑然，是為本體","sortOrder":21},
  {"id":"s_work_ttcm_2_22","chapterId":"ch_work_ttcm_2","text":"其聚其散，变化之客形爾。","sortOrder":22},
  {"id":"s_work_ttcm_2_23","chapterId":"ch_work_ttcm_2","text":"日月之發斂，四時之推遷，百物之生死，與風雨露雷乘時而興，乘時而息，一也，皆客形也。有去有來謂之客。發斂，謂日月出入之道","sortOrder":23},
  {"id":"s_work_ttcm_2_24","chapterId":"ch_work_ttcm_2","text":"至靜無感，性之淵源；","sortOrder":24},
  {"id":"s_work_ttcm_2_25","chapterId":"ch_work_ttcm_2","text":"於物感未交、至靜之中，健順之性承於天者，固有不失，有本而不窮。","sortOrder":25},
  {"id":"s_work_ttcm_2_26","chapterId":"ch_work_ttcm_2","text":"有識有知，物交之客感爾。","sortOrder":26},
  {"id":"s_work_ttcm_2_27","chapterId":"ch_work_ttcm_2","text":"識知者，五常之性所與天下相通而起用者也。知其物乃知其名，知其名乃知其義，不與物交，則心具此理，而名不能言，事不能成。赤子之無知，精未彻也；愚蒙之無知，物不審也。自外至曰客。","sortOrder":27},
  {"id":"s_work_ttcm_2_28","chapterId":"ch_work_ttcm_2","text":"客感客形與無感無形，唯盡性者一之。","sortOrder":28},
  {"id":"s_work_ttcm_2_29","chapterId":"ch_work_ttcm_2","text":"靜而萬理皆備，心無不正，動而本體不失，意無不誠，盡性者也。性盡，則生死屈伸一貞乎道，而不撓太虛之本體，動靜語默一貞乎仁，而不丧健順之良能，不以客形之來去易其心，不以客感之貞淫易其志，所謂“夭寿不貳，修身以俟之”，“不顯亦臨，無射亦保”也。蓋其生也異於禽獸之生，則其死也異於禽獸之死，全健順太和之理以還造化，存順而没亦寧。其靜也異於下愚之靜，則其動也異於下愚之動，充五常百順之實以宰百為，志繼而事亦述矣。無他，人之生死、動靜有間，而太和之絪缊本無間也。","sortOrder":29},
  {"id":"s_work_ttcm_2_30","chapterId":"ch_work_ttcm_2","text":"此上二章，兼動靜、生死而言。動靜之幾，盡性之事，死生之故，立命之事，而一動一靜，一屈一伸，理所必有而通於一，則一也。","sortOrder":30},
  {"id":"s_work_ttcm_2_31","chapterId":"ch_work_ttcm_2","text":"天地之氣，雖聚散、攻取百途，然其為理也順而不妄。","sortOrder":31},
  {"id":"s_work_ttcm_2_32","chapterId":"ch_work_ttcm_2","text":"聚則見有，散則疑無，既聚而成形象，則才质性情各依其類。同者取之，異者攻之，故庶物繁興，各成品匯，乃其品匯之成各有條理，故露雷霜雪各以其時，動植飛潛各以其族，必無長夏霜雪、嚴冬露雷、人禽草木互相淆雜之理。故善氣恒於善，惡氣恒於惡，治氣恒於治，亂氣恒於亂，屈伸往來順其故而不妄。不妄者，氣之清通，天之誠也。","sortOrder":32},
  {"id":"s_work_ttcm_2_33","chapterId":"ch_work_ttcm_2","text":"氣之為物，散入無形，適得吾體；聚為有象，不失吾常。","sortOrder":33},
  {"id":"s_work_ttcm_2_34","chapterId":"ch_work_ttcm_2","text":"散而歸於太虛，复其絪缊之本體，非消滅也。聚而為庶物之生，自絪缊之常性，非幻成也。聚而不失其常，故有生之後，雖氣禀物欲相窒相梏，而克自修治，即可复健順之性。散而仍得吾體，故有生之善惡治亂，至形亡之後，清濁猶依其類。","sortOrder":34},
  {"id":"s_work_ttcm_2_35","chapterId":"ch_work_ttcm_2","text":"太虛不能無氣，氣不能不聚而為萬物。萬物不能不散而為太虛。循是出入，是皆不得已而然也。","sortOrder":35},
  {"id":"s_work_ttcm_2_36","chapterId":"ch_work_ttcm_2","text":"氣之聚散，物之死生，出而來，入而往，皆理势之自然，不能已止者也。不可據之以為常，不可揮之而使散，不可挽之而使留，是以君子安生安死，於氣之屈伸無所施其作為，俟命而已矣。","sortOrder":36},
  {"id":"s_work_ttcm_2_37","chapterId":"ch_work_ttcm_2","text":"然則聖人盡道其間，兼體而不累者，存神其至矣。","sortOrder":37},
  {"id":"s_work_ttcm_2_38","chapterId":"ch_work_ttcm_2","text":"氣無可容吾作為，聖人所存者神爾。兼體，謂存順没寧也。神清通而不可象，而健順五常之理以順，天地之經以貫，萬事之治以達，萬物之志皆其所涵。存者，不為物欲所遷，而學以聚之，問以辨之，宽以居之，仁以守之，使與太和絪缊之本體相合無間，則生以盡人道而無歉，死以返太虛而無累，全而生之，全而歸之，斯聖人之至德矣。","sortOrder":38},
  {"id":"s_work_ttcm_2_39","chapterId":"ch_work_ttcm_2","text":"彼語寂滅者，往而不返；釋氏以滅盡無餘為大涅槃。","sortOrder":39},
  {"id":"s_work_ttcm_2_40","chapterId":"ch_work_ttcm_2","text":"徇生執有者，物而不化；","sortOrder":40},
  {"id":"s_work_ttcm_2_41","chapterId":"ch_work_ttcm_2","text":"物，滯於物也。魏伯陽、張平叔之流，鉗魂守魄，謂可長生。","sortOrder":41},
  {"id":"s_work_ttcm_2_42","chapterId":"ch_work_ttcm_2","text":"二者雖有間矣，","sortOrder":42},
  {"id":"s_work_ttcm_2_43","chapterId":"ch_work_ttcm_2","text":"徇生執有者尤拂經而為必不可成之事。","sortOrder":43},
  {"id":"s_work_ttcm_2_44","chapterId":"ch_work_ttcm_2","text":"以言乎失道則均焉。","sortOrder":44},
  {"id":"s_work_ttcm_2_45","chapterId":"ch_work_ttcm_2","text":"皆不知氣之未嘗有有無而神之通於太和也。","sortOrder":45},
  {"id":"s_work_ttcm_2_46","chapterId":"ch_work_ttcm_2","text":"此章乃一篇之大指，貞生死以盡人道，乃張子之絕學，發前聖之蘊，以辟佛、老而正人心者也。朱子以其言既聚而散，散而复聚，譏其為大輪回。而愚以為朱子之說反近於釋氏滅盡之言，而與聖人之言異。孔子曰：“未知生，焉知死。”則生之散而為死，死之可复聚為生，其理一轍，明矣。《易》曰：“精氣為物，遊魂為变。”遊魂者，魂之散而遊於虛也，為变，則還以生变化，明矣。又曰：“屈伸相感而利生焉。”伸之感而屈，生而死也；屈之感而伸，非既屈者因感而可复伸乎？又曰：“形而上者謂之道，形而下者謂之器。”形而上，即所謂清通而不可象者也。器有成毀，而不可象者寓於器以起用，未嘗成，亦不可毀，器敝而道未嘗息也。以天運物象言之，春夏為生、為來、為伸，秋冬為殺、為往、為屈，而秋冬生氣潛藏於地中，枝葉槁而根本固榮，則非秋冬之一消滅而更無餘也。車薪之火，一烈已盡，而為焰、為煙、為燼，木者仍歸木，水者仍歸水，土者仍歸土，特希微而人不見爾。一甑之炊，濕熱之氣，蓬蓬勃勃，必有所歸，若庵蓋嚴密，則鬱而不散。汞見火則飛，不知何往，而究歸於地。有形者且然，况其絪缊不可象者乎！未嘗有辛勤歲月之積，一旦悉化為乌有，明矣。故曰往來，曰屈伸，曰聚散，曰幽明，而不曰生滅。生滅者，釋氏之陋說也。倘如散盡無餘之說，則此太極浑淪之內，何處為其翕受消歸之府乎？又雲造化日新而不用其故，則此太虛之內，亦何從得此無盡之储，以終古趨於滅而不匮邪？且以人事言之，君子修身俟命，所以事天；全而生之，全而歸之，所以事親。使一死而消散無餘，則諺所謂伯夷、盜跖同歸一丘者，又何恤而不逞志縱欲，不亡以待盡乎！惟存神以盡性，則與太虛通為一體，生不失其常，死可適得其體，而妖孽、灾眚、奸回、濁亂之氣不留滯於兩間，斯尧、舜、周、孔之所以萬年，而《詩》雲“文王在上，於昭於天“，為聖人與天合德之極致。聖賢大公至正之道異於異端之邪說者以此，則謂張子之言非明睿所照者，愚不敢知也。","sortOrder":46},
  {"id":"s_work_ttcm_2_47","chapterId":"ch_work_ttcm_2","text":"聚亦吾體，散亦吾體，知死之不亡者，可與言性矣。","sortOrder":47},
  {"id":"s_work_ttcm_2_48","chapterId":"ch_work_ttcm_2","text":"聚而成形，散而歸於太虛，氣猶是氣也。神者，氣之靈，不離乎氣而相與為體，則神猶是神也，聚而可見，散而不可見爾，其體豈有不順而妄者乎！故尧、舜之神，桀、紂之氣，存於絪缊之中，至今而不易。然桀、紂之所暴者，氣也，養之可使醇，持之可使正，澄之可使清也；其始得於天者，健順之良能未嘗損也，存乎其人而已矣。","sortOrder":48},
  {"id":"s_work_ttcm_2_49","chapterId":"ch_work_ttcm_2","text":"知虛空即氣，則有無、隱顯，神化、性命，通一無二，顧聚散、出入、形不形、能推本所從來，則深於《易》者也。","sortOrder":49},
  {"id":"s_work_ttcm_2_50","chapterId":"ch_work_ttcm_2","text":"虛空者，氣之量；氣弥淪無涯而希微不形，則人見虛空而不見氣。凡虛空皆氣也，聚則顯，顯則人謂之有，散則隱，隱則人謂之無。神化者，氣之聚散不测之妙，然而有跡可見；性命者，氣之健順有常之理，主持神化而寓於神化之中，無跡可見。若其實，則理在氣中，氣無非理，氣在空中，空無非氣，通一而無二者也。其聚而出為人物則形，散而入於太虛則不形，抑必有所從來。蓋陰陽者氣之二體，動靜者氣之二幾，體同而用異則相感而動，動而成象則靜，動靜之幾，聚散、出入、形不形之從來也。《易》之為道，乾、坤而已，乾六陽以成健，坤六陰以成順，而陰陽相摩，則生六子以生五十六卦，皆動之不容已者，或聚或散，或出或入，错綜变化，要以動靜夫陰陽。而陰陽一太極之實體，唯其富有充滿於虛空，故变化日新，而六十四卦之吉凶大業生焉。陰陽之消長隱見不可测，而天地人物屈伸往來之故盡於此。知此者，盡《易》之蘊矣。","sortOrder":50},
  {"id":"s_work_ttcm_2_51","chapterId":"ch_work_ttcm_2","text":"若謂虛能生氣，則虛無窮，氣有限，體用殊絕，入老氏有生於無自然之論，不識所謂有無混一之常。","sortOrder":51},
  {"id":"s_work_ttcm_2_52","chapterId":"ch_work_ttcm_2","text":"老氏以天地如橐龠，動而生風，是虛能於無生有，变幻無窮；而氣不鼓動則無，是有限矣，然則孰鼓其橐龠令生氣乎？有無混一者，可見謂之有，不可見遂謂之無，其實動靜有時而陰陽常在，有無無異也。誤解《太極圖》者，謂太極本末有陰陽，因動而始生陽，靜而始生陰。不知動靜所生之陰陽，為寒暑、润燥、男女之情质，乃固有之蘊，其絪缊充滿在動靜之先。動靜者即此陰陽之動靜，動則陰变於陽，靜則陽凝於陰，一震、巽、坎、離、艮、兑之生於乾、坤也；非動而後有陽，靜而後有陰，本無二氣，由動靜而生，如老氏之說也。","sortOrder":52},
  {"id":"s_work_ttcm_2_53","chapterId":"ch_work_ttcm_2","text":"若謂萬象為太虛中所見之物，則物與虛不相資，形自形，性自性，形性、天人不相待而有，陷於浮屠，以山河大地為見病之說。","sortOrder":53},
  {"id":"s_work_ttcm_2_54","chapterId":"ch_work_ttcm_2","text":"浮屠謂真空常寂之圓成實性，止一光明，藏而地水火風根尘等皆由妄現，知見妄立，執為實相。若謂太極本無陰陽，乃動靜所顯之影象，則性本清空，禀於太極，形有消長，生於变化，性中增形，形外有性，人不資氣而生而於氣外求理，則形為妄而性為真，陷於其邪說矣。","sortOrder":54},
  {"id":"s_work_ttcm_2_55","chapterId":"ch_work_ttcm_2","text":"此道不明，正由懵者略知體虛空為性，","sortOrder":55},
  {"id":"s_work_ttcm_2_56","chapterId":"ch_work_ttcm_2","text":"差愈於告子“食色性也”、荀子性惡之論爾。","sortOrder":56},
  {"id":"s_work_ttcm_2_57","chapterId":"ch_work_ttcm_2","text":"不知本天道為用，","sortOrder":57},
  {"id":"s_work_ttcm_2_58","chapterId":"ch_work_ttcm_2","text":"天即道為用，以生萬物。誠者，天之道也，陰陽有實之謂誠。","sortOrder":58},
  {"id":"s_work_ttcm_2_59","chapterId":"ch_work_ttcm_2","text":"反以人見之小因緣天地。","sortOrder":59},
  {"id":"s_work_ttcm_2_60","chapterId":"ch_work_ttcm_2","text":"但見來無所從，去無所歸，遂謂性本真空，天地皆緣幻立，事物倫理一從意見橫生，不睹不聞之中別無理氣。近世王氏之說本此，唯其見之小也。","sortOrder":60},
  {"id":"s_work_ttcm_2_61","chapterId":"ch_work_ttcm_2","text":"明有不盡，則誣世界乾坤為幻化。幽明不能舉其要，遂躐等妄意而然。","sortOrder":61},
  {"id":"s_work_ttcm_2_62","chapterId":"ch_work_ttcm_2","text":"未能窮理知性而言天人之际，是謂躐等。","sortOrder":62},
  {"id":"s_work_ttcm_2_63","chapterId":"ch_work_ttcm_2","text":"不悟一陰一陽，范围天地，通乎晝夜，三極大中之矩。","sortOrder":63},
  {"id":"s_work_ttcm_2_64","chapterId":"ch_work_ttcm_2","text":"陰陽二氣充滿太虛，此外更無他物，亦無間隙，天之象，地之形，皆其所范围也。散入無形而適得氣之體，聚為有形而不失氣之常，通乎死生猶晝夜也。晝夜者，豈陰陽之或有或無哉！日出而人能見物，則謂之晝，日入而人不見物，則謂之夜；陰陽之運行，則通一無二也。在天而天以為象，在地而地以為形，在人而人以為性，性在氣中，屈伸通於一，而裁成变化存焉，此不可逾之中道也。","sortOrder":64},
  {"id":"s_work_ttcm_2_65","chapterId":"ch_work_ttcm_2","text":"遂使儒、佛、老、莊混然一途，語天道性命者，不罔於恍惚夢幻，則定以有生於無，為窮高極微之論。入德之途，不知擇術而求，多見其蔽於诐而陷於淫矣。","sortOrder":65},
  {"id":"s_work_ttcm_2_66","chapterId":"ch_work_ttcm_2","text":"陷於佛者，如李翱、張九成之流，而富鄭公、趙清獻雖賢而不免；若陆子靜及近世王伯安，則屈聖人之言以附會之，說愈淫矣。陷於老者，如王弼註《易》及何晏、夏侯湛辈皆其流也；若王安石、呂惠卿及近世王畿、李贽之屬，則又合佛、老以溷聖道，尤其淫而無紀者也。","sortOrder":66},
  {"id":"s_work_ttcm_2_67","chapterId":"ch_work_ttcm_2","text":"氣坱然太虛，","sortOrder":67},
  {"id":"s_work_ttcm_2_68","chapterId":"ch_work_ttcm_2","text":"坱然，猶言滃然，充滿盛動貌。遍太虛中皆氣也。","sortOrder":68},
  {"id":"s_work_ttcm_2_69","chapterId":"ch_work_ttcm_2","text":"升降飛扬，未嘗止息，《易》所謂“絪缊”，莊生所謂“生物以息相吹”、“野馬”者與！","sortOrder":69},
  {"id":"s_work_ttcm_2_70","chapterId":"ch_work_ttcm_2","text":"升降飛扬，乃二氣和合之動幾，雖陰陽未形，而已全具殊质矣。“生物以息相吹”之說非也，此乃太虛之流動洋溢，非仅生物之息也。引此者，言莊生所疑為生物之息者此也。","sortOrder":70},
  {"id":"s_work_ttcm_2_71","chapterId":"ch_work_ttcm_2","text":"此虛實、動靜之極，陰陽、刚柔之始。","sortOrder":71},
  {"id":"s_work_ttcm_2_72","chapterId":"ch_work_ttcm_2","text":"虛者，太虛之量；實者，氣之充周也。升降飛扬而無間隙，則有動者以流行，則有靜者以凝止。於是而靜者以陰為性，雖陽之靜亦陰也；動者以陽為性，雖陰之動亦陽也。陰陽分象而刚柔分形，刚者陽之质，而刚中非無陰；柔者陰之质，而柔中非無陽。就象而言之，分陰分陽；就形而言之，分柔分刚；就性而言之，分仁分義；分言之則辨其異，合體之則會其通，故張子統言陰陽刚柔以概之。機者，飛扬升降不容已之幾；始者，形象之所由生也。","sortOrder":72},
  {"id":"s_work_ttcm_2_73","chapterId":"ch_work_ttcm_2","text":"浮而上者陽之清，降而下者陰之濁。","sortOrder":73},
  {"id":"s_work_ttcm_2_74","chapterId":"ch_work_ttcm_2","text":"天地之法象，人之血氣表里、耳目手足，以至魚鳥飛潛，草木華實，雖陰陽不相離，而抑各成乎陰陽之體。就其昭明流動者謂之清，就其凝滯堅強者謂之濁；陽之清，引陰以偕升，陰之濁，挟陽以俱降，其神之清通者，則貫彻乎其中而未有礙也。","sortOrder":74},
  {"id":"s_work_ttcm_2_75","chapterId":"ch_work_ttcm_2","text":"其感遇聚散，為風雨，為雪霜，萬品之流形，山川之融結，糟粕煨燼，無非教也。","sortOrder":75},
  {"id":"s_work_ttcm_2_76","chapterId":"ch_work_ttcm_2","text":"感者，交相感；陰感於陽而形乃成，陽感於陰而象乃著。遇者，類相遇；陰與陰遇，形乃滋，陽與陽遇，象乃明。感遇則聚，聚已必散，皆升降飛扬自然之理势。風雨、雪霜、山川、人物，象之顯藏，形之成毀，屢遷而已結者，雖遲久而必歸其原，條理不迷，誠信不爽，理在其中矣。教者，朱子所謂“示人以理”是也。","sortOrder":76},
  {"id":"s_work_ttcm_2_77","chapterId":"ch_work_ttcm_2","text":"氣聚，則離明得施而有形，","sortOrder":77},
  {"id":"s_work_ttcm_2_78","chapterId":"ch_work_ttcm_2","text":"離明，在天為日，在人為目，光之所麗以著其形。有形則人得而見之，明也。","sortOrder":78},
  {"id":"s_work_ttcm_2_79","chapterId":"ch_work_ttcm_2","text":"不聚，則離明不得施而無形。","sortOrder":79},
  {"id":"s_work_ttcm_2_80","chapterId":"ch_work_ttcm_2","text":"無形則人不得而見之，幽也。無形，非無形也，人之目力窮於微，遂見為無也。心量窮於大，耳目之力窮於小。","sortOrder":80},
  {"id":"s_work_ttcm_2_81","chapterId":"ch_work_ttcm_2","text":"方其聚也，安得不謂之客；方其散也，安得遽謂之無。","sortOrder":81},
  {"id":"s_work_ttcm_2_82","chapterId":"ch_work_ttcm_2","text":"聚而明得施，人遂謂之有；散而明不可施，人遂謂之無。不知聚者暫聚，客也，非必為常存之主；散者，返於虛也，非無固有之實。人以見不見而言之，是以滯爾。","sortOrder":82},
  {"id":"s_work_ttcm_2_83","chapterId":"ch_work_ttcm_2","text":"故聖人仰觀俯察，但雲“知幽明之故”，不雲“知有無之故”。","sortOrder":83},
  {"id":"s_work_ttcm_2_84","chapterId":"ch_work_ttcm_2","text":"明則謂有，幽則謂無，眾人之陋爾；聖人不然。","sortOrder":84},
  {"id":"s_work_ttcm_2_85","chapterId":"ch_work_ttcm_2","text":"盈天地之間者，法象而已矣。","sortOrder":85},
  {"id":"s_work_ttcm_2_86","chapterId":"ch_work_ttcm_2","text":"示人以可見者，此而已矣。","sortOrder":86},
  {"id":"s_work_ttcm_2_87","chapterId":"ch_work_ttcm_2","text":"文理之察，非離不相睹也。","sortOrder":87},
  {"id":"s_work_ttcm_2_88","chapterId":"ch_work_ttcm_2","text":"法象中之文理，唯目能察之，而所察者止於此；因而窮之，知其動靜之機，陰陽之始，屈伸聚散之通，非心思不著。","sortOrder":88},
  {"id":"s_work_ttcm_2_89","chapterId":"ch_work_ttcm_2","text":"方其形也，有以知幽之因；方其不形也，有以知明之故。","sortOrder":89},
  {"id":"s_work_ttcm_2_90","chapterId":"ch_work_ttcm_2","text":"盡心思以窮神知化，則方其可見而知其必有所歸往，則明之中具幽之理；方其不可見而知其必且相感以聚，則幽之中具明之理；此聖人所以知幽明之故而不言有無也。言有無者，徇目而已；不斥言目而言離者，目其靜之形，敔按：成形則靜離其動之用也。敔按：藏用於動蓋天下惡有所謂無者哉！於物或未有，於事非無；於事或未有，於理非無；尋求而不得，怠惰而不求，則曰無而巳矣。甚矣言無之陋也！敔按：此即前章形不形之所從來也","sortOrder":90},
  {"id":"s_work_ttcm_2_91","chapterId":"ch_work_ttcm_2","text":"氣之聚散於太虛，猶冰凝釋於水；知太虛即氣，則無無。","sortOrder":91},
  {"id":"s_work_ttcm_2_92","chapterId":"ch_work_ttcm_2","text":"人之所見為太虛者，氣也，非虛也。虛涵氣，氣充虛，無有所謂無者。敔按：先子《和陳白沙六經總在虛無里詩》雲：“六經總在虛無里，方信虛無不是無。”","sortOrder":92},
  {"id":"s_work_ttcm_2_93","chapterId":"ch_work_ttcm_2","text":"故聖人語性與天道之極，盡於參伍之神变易而已。","sortOrder":93},
  {"id":"s_work_ttcm_2_94","chapterId":"ch_work_ttcm_2","text":"性天之旨盡於《易》，《易》卦陰陽互相叁伍，隨時变易，而天人之蘊，幽明之故，吉凶大業之至赜備矣。《乾》有六陽，《坤》有六陰；而其交也，至《屯》《蒙》而二陽參四陰，至《需》《訟》而二陰參四陽，非陰陽之有缺也。《屯》《蒙》之二陽麗於明，四陽處於幽，《需》《訟》之二陰處於明，四陰處於幽；其形而見者為《屯》《蒙》，其隱而未見者為《鼎》《革》；形而見者為《需》《訟》，隱而未見者為《晉》《明夷》餘仿此：变易而各乘其時，居其位，成其法象，非所見者有，所不見者無也。故曰“《乾》《坤》其《易》之蘊邪”，言《易》藏畜陰陽，具足充滿，以因時而成六十二象。惟其富有，是以日新，有幽明而無有無，明矣。","sortOrder":94},
  {"id":"s_work_ttcm_2_95","chapterId":"ch_work_ttcm_2","text":"諸子淺妄，有有無之分，非窮理之學也。","sortOrder":95},
  {"id":"s_work_ttcm_2_96","chapterId":"ch_work_ttcm_2","text":"淺則據離明所得施為有，不得施為無，徇目而心不通；妄則誣有為無，莊、列、淮南之流以之；而近世以無善無惡為良知者，亦惟其淺而成乎妄也。","sortOrder":96},
  {"id":"s_work_ttcm_2_97","chapterId":"ch_work_ttcm_2","text":"太虛為清，清則無礙，無礙故神；反清為濁，濁則礙，礙則形。","sortOrder":97},
  {"id":"s_work_ttcm_2_98","chapterId":"ch_work_ttcm_2","text":"氣之未聚於太虛，希微而不可見，故清；清則有形有象者皆可入於中，而抑可入於形象之中，不行而至神也。反者，屈伸聚散相對之謂，氣聚於太虛之中則重而濁，物不能入，不能入物，拘礙於一而不相通，形之凝滯然也。其在於人，太虛者，心涵神也；濁而礙者，耳目口體之各成其形也。礙而不能相通，故嗜欲止於其所便利，而人己不相為謀；官骸不相易，而目不取聲，耳不取色；物我不相知，則利其所利，私其所私；聰明不相及，則執其所見，疑其所罔。聖人知氣之聚散無恒而神通於一，故存神以盡性，复健順之本體，同於太虛，知周萬物而仁覆天下矣。","sortOrder":98},
  {"id":"s_work_ttcm_2_99","chapterId":"ch_work_ttcm_2","text":"凡氣，清則通，昏則壅，","sortOrder":99},
  {"id":"s_work_ttcm_2_100","chapterId":"ch_work_ttcm_2","text":"天有光風霁月、曀陰霾霧之異，人有高明廣大、庸沓鄙陋之殊，其理一也。","sortOrder":100},
  {"id":"s_work_ttcm_2_101","chapterId":"ch_work_ttcm_2","text":"清極則神。","sortOrder":101},
  {"id":"s_work_ttcm_2_102","chapterId":"ch_work_ttcm_2","text":"不為形礙，則有形者昭明寧靜以聽心之用而清極矣。神則合物我於一原，達死生於一致，絪缊合德，死而不亡。","sortOrder":102},
  {"id":"s_work_ttcm_2_103","chapterId":"ch_work_ttcm_2","text":"故聚而有間，則風行而聲聞具達，清之验與！","sortOrder":103},
  {"id":"s_work_ttcm_2_104","chapterId":"ch_work_ttcm_2","text":"間，形中之虛也。心之种居形之間，惟存養其清通而不為物欲所塞，則物我死生，曠然達一，形不能礙，如風之有牖即入，笙管之音具達矣。","sortOrder":104},
  {"id":"s_work_ttcm_2_105","chapterId":"ch_work_ttcm_2","text":"不行而至，通之極與！","sortOrder":105},
  {"id":"s_work_ttcm_2_106","chapterId":"ch_work_ttcm_2","text":"神，故不行而至。至清而通，神之效也。蓋耳目止於聞見，唯心之神彻於六合，周於百世。所存在此，則猶曠窅之墟，空洞之籁，無所礙而風行聲達矣。","sortOrder":106},
  {"id":"s_work_ttcm_2_107","chapterId":"ch_work_ttcm_2","text":"此二章言存神為聖功之極致。","sortOrder":107},
  {"id":"s_work_ttcm_2_108","chapterId":"ch_work_ttcm_2","text":"由太虛，有天之名；由氣化，有道之名；合虛與氣，有性之名；合性與知覺，有心之名。","sortOrder":108},
  {"id":"s_work_ttcm_2_109","chapterId":"ch_work_ttcm_2","text":"名者，言道者分析而名；言之各有所指，故一理而多為之名，其實一也。太虛即氣，絪缊之本體，陰陽合於太和，雖其實氣也，而未可名之為氣；其升降飛扬，莫之為而為萬物之資始者，於此言之則謂之天。氣化者，氣之化也。陰陽具於太虛絪缊之中，其一陰一陽，或動或靜，相與摩荡，乘其時位以著其功能，五行萬物之融結流止、飛潛動植，各自成其條理而不妄，則物有物之道，鬼神有鬼神之道，而知之必明，處之必當，皆循此以為當然之則，於此言之則謂之道。此二句兼人物言之；下言性心，則专言人矣。太虛者，陰陽之藏，健順之德存焉；氣化者，一陰一陽，動靜之幾，品匯之節具焉。秉太虛和氣健順相涵之實，而合五行之秀以成乎人之秉彝，此人之所以有性也。原於天而順乎道，凝於形氣，而五常百行之理無不可知，無不可能，於此言之則謂之性。人之有性，函之於心而感物以通，象著而數陳，名立而義起，習其故而心喻之，形也，神也，物也，三相遇而知覺乃發。故由性生知，以知知性，交涵於聚而有間之中，統於一心，由此言之則謂之心。順而言之，則惟天有道，以道成性，性發知道；逆而推之，則以心盡性，以性合道，以道事天。惟其理本一原，故人心即天；而盡心知性，則存順没寧，死而全歸於太虛之本體，不以客感雜滯遺造化以疵類，聖學所以天人合一，而非異端之所可溷也。","sortOrder":109},
  {"id":"s_work_ttcm_2_110","chapterId":"ch_work_ttcm_2","text":"鬼神者，二氣之良能也。","sortOrder":110},
  {"id":"s_work_ttcm_2_111","chapterId":"ch_work_ttcm_2","text":"陰陽相感，聚而生人物者為神；合於人物之身，用久則神隨形敝，敝而不足以存，复散而合於絪缊者為鬼。神自幽而之明，成乎人之能，而固與天相通；鬼自明而返乎幽，然歷乎人之能，抑可與人相感。就其一幽一明者言之，則神陽也，鬼陰也，而神者陽伸而陰亦隨伸，鬼者陰屈而陽先屈，故皆為二氣之良能。良能者，無心之感合，成其往來之妙者也。凡陰用之分，不可執一言者，類如此；學者因所指而詳察，乃無拘滯之失。若謂死則消散無有，則是有神而無鬼，與聖人所言“鬼神之德盛”者異矣。","sortOrder":111},
  {"id":"s_work_ttcm_2_112","chapterId":"ch_work_ttcm_2","text":"聖者，至誠得天之謂；神者，太虛妙應之目。","sortOrder":112},
  {"id":"s_work_ttcm_2_113","chapterId":"ch_work_ttcm_2","text":"至誠體太虛至和之實理，與絪缊未分之道通一不二，是得天之所以為天也。其所存之神，不行而至，與太虛妙應以生人物之良能一矣。如此則生而不失吾常，死而適得吾體，跡有屈伸，而神無損益也。","sortOrder":113},
  {"id":"s_work_ttcm_2_114","chapterId":"ch_work_ttcm_2","text":"凡天地法象，皆神化之糟粕爾。","sortOrder":114},
  {"id":"s_work_ttcm_2_115","chapterId":"ch_work_ttcm_2","text":"日月、雷風、水火、山泽固神化之所為，而亦氣聚之客形，或久或暫，皆已用之餘也，而况人之耳目官骸乎！故形有屈伸，而神無幽明之異。語寂滅者不知不亡之良能，執有徇生者據糟粕為常，其迷均矣。","sortOrder":115},
  {"id":"s_work_ttcm_2_116","chapterId":"ch_work_ttcm_2","text":"天道不窮，寒暑已；眾動不窮，屈伸已。","sortOrder":116},
  {"id":"s_work_ttcm_2_117","chapterId":"ch_work_ttcm_2","text":"寒已而暑，暑已而寒，循環而如相反，四時之行，生殺之用，盡此矣：蓋二氣之噓吸也。屈者屈其所伸，伸者伸其所屈，群動之变，不能離此二用，動靜、語默、喜怒、行藏之变，盡此矣：蓋二氣之舒斂也。","sortOrder":117},
  {"id":"s_work_ttcm_2_118","chapterId":"ch_work_ttcm_2","text":"鬼神之實，不越二端而已矣。","sortOrder":118},
  {"id":"s_work_ttcm_2_119","chapterId":"ch_work_ttcm_2","text":"一噓一吸，一舒一斂，升降離合於太虛之中，乃陰陽必有之幾。則鬼神者，天之所顯而即人之藏也。靜以成形，鬼之屬也，而可以迎神而來；動而成用，神之屬也，而將成乎鬼以往。屈伸因乎時，而盡性以存神，則天命立於在我，與鬼神合其吉凶矣。","sortOrder":119},
  {"id":"s_work_ttcm_2_120","chapterId":"ch_work_ttcm_2","text":"兩不立則一不可見，","sortOrder":120},
  {"id":"s_work_ttcm_2_121","chapterId":"ch_work_ttcm_2","text":"陰陽未分，二氣合一，絪缊太和之真體，非目力所及，不可得而見也。","sortOrder":121},
  {"id":"s_work_ttcm_2_122","chapterId":"ch_work_ttcm_2","text":"一不可見則兩之用息。","sortOrder":122},
  {"id":"s_work_ttcm_2_123","chapterId":"ch_work_ttcm_2","text":"其合一而為太和者，當其未成乎法象，陰陽之用固息也。","sortOrder":123},
  {"id":"s_work_ttcm_2_124","chapterId":"ch_work_ttcm_2","text":"兩體者，虛實也，動靜也，聚散也，清濁也，其究一而已。","sortOrder":124},
  {"id":"s_work_ttcm_2_125","chapterId":"ch_work_ttcm_2","text":"虛必成實，實中有虛，一也。而來則實於此，虛於彼，往則虛於此，實於彼，其體分矣。止而行之，動動也；行而止之，靜亦動也：一也。而動有動之用，靜有靜之质，其體分矣。聚者聚所散，散者散所聚，一也。而聚則顯，散則微，其體分矣。清以為濁，濁固有清，一也。而清者通，濁者礙，其體分矣。使無一虛一實，一動一靜；一聚一散，一清一濁，則可疑太虛之本無有，而何者為一。惟兩端迭用，遂成對立之象，於是可知所動所靜，所聚所散，為虛為實，為清為濁，皆取給於太和絪缊之實體。一之體立，故兩之用行；如水唯一體，則寒可為冰，熱可為湯，於冰湯之異，足知水之常體。","sortOrder":125},
  {"id":"s_work_ttcm_2_126","chapterId":"ch_work_ttcm_2","text":"感而後有通：不有兩，則無一。","sortOrder":126},
  {"id":"s_work_ttcm_2_127","chapterId":"ch_work_ttcm_2","text":"陰陽合於太和，而性情不能不異；惟異生感，故交相欣合於既感之後，而法象以著。藉令本無陰陽兩體虛實清濁之實，則無所容其感通，而謂未感之先初無太和，亦可矣；今既兩體各立，則溯其所從來，太和之有一實，顯矣。非有一則無兩也。","sortOrder":127},
  {"id":"s_work_ttcm_2_128","chapterId":"ch_work_ttcm_2","text":"故聖人以刚柔立本，《乾》《坤》毀則無以見《易》。","sortOrder":128},
  {"id":"s_work_ttcm_2_129","chapterId":"ch_work_ttcm_2","text":"聖人之存神，本合乎至一之太虛，而立教之本，必因陰陽已分、刚柔成象之體，蓋以由兩而見一也。乾之六陽，坤之六陰，健順之德具足於法象，故相摩相荡，成六十二卦之变易，以盡天下之斖斖。若陰陽不純備乎乾、坤，則六十二象之往來者何所從生邪，其何以見《易》乎，聖人成天下之盛德大業於感通之後，而以合絪缊一氣和合之體，修人事即以肖天德，知生即以知死，存神即以養氣，惟於二氣之實，兼體而以時用之爾。","sortOrder":129},
  {"id":"s_work_ttcm_2_130","chapterId":"ch_work_ttcm_2","text":"遊氣紛扰，合而成质者，生人物之萬殊；","sortOrder":130},
  {"id":"s_work_ttcm_2_131","chapterId":"ch_work_ttcm_2","text":"遊氣，氣之遊行也，即所謂升降飛扬。紛扰者，無心之化，無擇於施，陰陽老少互相遇而無一成之軌，乾、坤立而六子、五十六象多寡消長之無典要，成天下之至赜，乃其象矣。合者，陰陽之始本一也，而因動靜分而為兩，迨其成又合陰陽於一也。如男陽也而非無陰，女陰也而亦非無陽，敔按：如氣血魂魄之屬，男女畢具，是陽必具陰，陰必具陽也以至於草木魚鳥，無孤陽之物，亦無孤陰之物，唯深於格物者知之。時位相得，則為人，為上知；不相得，則為禽獸，為下愚；要其受氣之遊，合兩端於一體，則無有不兼體者也。","sortOrder":131},
  {"id":"s_work_ttcm_2_132","chapterId":"ch_work_ttcm_2","text":"其陰陽兩端，循環不已者，立天地之大義。","sortOrder":132},
  {"id":"s_work_ttcm_2_133","chapterId":"ch_work_ttcm_2","text":"義者，居正有常而不易之謂。陰陽不偏，循環不息，守正以待感，物得其宜，為經常不易之道，此仁義中正之理所從出。曰誠，曰無妄，曰不息，曰敦化，皆謂此也。然則萬殊之生，因乎二氣，二氣之合，行乎萬殊，天地生生之神化，聖人應感之大經，概可知矣。","sortOrder":133},
  {"id":"s_work_ttcm_2_134","chapterId":"ch_work_ttcm_2","text":"“日月相推而明生，寒暑相推而歲成。”","sortOrder":134},
  {"id":"s_work_ttcm_2_135","chapterId":"ch_work_ttcm_2","text":"《易·系傳》文。","sortOrder":135},
  {"id":"s_work_ttcm_2_136","chapterId":"ch_work_ttcm_2","text":"神易無方體，","sortOrder":136},
  {"id":"s_work_ttcm_2_137","chapterId":"ch_work_ttcm_2","text":"《易·系傳》雲：“神無方而易無體。”無方者，無方而非其方，無體者，無體而非其體，屈伸不異明矣。","sortOrder":137},
  {"id":"s_work_ttcm_2_138","chapterId":"ch_work_ttcm_2","text":"一陰一陽，","sortOrder":138},
  {"id":"s_work_ttcm_2_139","chapterId":"ch_work_ttcm_2","text":"《系傳》雲：“一陰一陽之謂道。”一一者，參伍相雜合而有辨也。卦或五陽一陰，或五陰一陽，乃至純乾純坤，而陰陽併建以為《易》之蘊，亦一陰一陽也，則陰陽之不以屈伸而息亦明矣。","sortOrder":139},
  {"id":"s_work_ttcm_2_140","chapterId":"ch_work_ttcm_2","text":"陰陽不测，","sortOrder":140},
  {"id":"s_work_ttcm_2_141","chapterId":"ch_work_ttcm_2","text":"《系傳》雲：“陰陽不测之謂神。”不测者，乘時因变，初無定體，非“幽明異致，陰陽分界”如邵子“四方八段”之說，亦非“死此生彼，各有分段”如浮屠之言明矣。","sortOrder":141},
  {"id":"s_work_ttcm_2_142","chapterId":"ch_work_ttcm_2","text":"皆所謂通乎晝夜之道也。","sortOrder":142},
  {"id":"s_work_ttcm_2_143","chapterId":"ch_work_ttcm_2","text":"晝夜者，非天之有異，乃日月出没，而人之離明有得施不得施之別爾。日月寒暑之兩行，一陰一陽之殊建，人以睹其明，定其歲，而謂之為方體；實則無方無體，陰陽不测，合同於絪缊而任其变化，乃神易陰陽之固然也。晝夜分兩端，而天之運行一；生死分兩端，而神之恒存一；氣有屈伸，神無生滅，通乎其道，兩立而一見，存順没寧之道在矣。","sortOrder":143},
  {"id":"s_work_ttcm_2_144","chapterId":"ch_work_ttcm_2","text":"晝夜者，天之一息乎！寒暑者，天之晝夜乎！","sortOrder":144},
  {"id":"s_work_ttcm_2_145","chapterId":"ch_work_ttcm_2","text":"氣之屈伸往來，一也。","sortOrder":145},
  {"id":"s_work_ttcm_2_146","chapterId":"ch_work_ttcm_2","text":"天道春秋分而氣易，猶人一寤寐而魂交。","sortOrder":146},
  {"id":"s_work_ttcm_2_147","chapterId":"ch_work_ttcm_2","text":"寤則魂交於明，寐則魂交於幽，神固未嘗亡也。","sortOrder":147},
  {"id":"s_work_ttcm_2_148","chapterId":"ch_work_ttcm_2","text":"魂交成夢，百道紛紜，對寤而言，一身之晝夜也；氣交為春，萬物糅错，對秋而言，天之晝夜也。","sortOrder":148},
  {"id":"s_work_ttcm_2_149","chapterId":"ch_work_ttcm_2","text":"魂交者，专指寐而言。身內為幽，身外為明；生物者客形爾，暫而不常，還原而忘其故，故如夢。秋冬斂物之精，適得太虛絪缊之體，故如寐之返於真也。晝為生，夜為死，氣通乎晝夜者，合寤寐而如一，故君子無不正之夢而與寤通理。","sortOrder":149},
  {"id":"s_work_ttcm_2_150","chapterId":"ch_work_ttcm_2","text":"此篇之旨，以存神而全歸其所從生之本體，故以秋配晝寤，以春配夜夢。而下章推物欲之所自出，唯不能通夜於晝，而任魂交之紛紜，故有發無斂，流於濁而丧其清，皆隨氣遷流，神不存而成貞淫交感之势也。","sortOrder":150},
  {"id":"s_work_ttcm_2_151","chapterId":"ch_work_ttcm_2","text":"舊與下通一章，今按文義分為二章。","sortOrder":151},
  {"id":"s_work_ttcm_2_152","chapterId":"ch_work_ttcm_2","text":"氣本之虛，則湛本無形，感而生則聚而有象。","sortOrder":152},
  {"id":"s_work_ttcm_2_153","chapterId":"ch_work_ttcm_2","text":"湛，澄澈而止也。感而生，遊氣交感而人資以生也。言太和絪缊為太虛，以有體無形為性，可以資廣生大生而無所倚，道之本體也。二氣之動，交感而生，凝滯而成物我之萬象，雖即太和不容已之大用，而與本體之虛湛異矣。","sortOrder":153},
  {"id":"s_work_ttcm_2_154","chapterId":"ch_work_ttcm_2","text":"有象斯有對，對必反其為；有反斯有仇，仇必和而解。","sortOrder":154},
  {"id":"s_work_ttcm_2_155","chapterId":"ch_work_ttcm_2","text":"以氣化言之，陰陽各成其象，則相為對，刚柔、寒溫、生殺，必相反而相為仇；乃其究也，互以相成，無終相敵之理，而解散仍返於太虛。以在人之性情言之，已成形則與物為對，而利於物者損於己，利於己者損於物，必相反而仇；然終不能不取物以自益也，和而解矣。氣化性情，其機一也。","sortOrder":155},
  {"id":"s_work_ttcm_2_156","chapterId":"ch_work_ttcm_2","text":"故愛惡之情同出於太虛，而卒歸於物欲，","sortOrder":156},
  {"id":"s_work_ttcm_2_157","chapterId":"ch_work_ttcm_2","text":"相反相仇則惡，和而解則愛。陰陽異用，惡不容已；陰得陽，陽得陰，乃遂其化，愛不容已；太虛一實之氣所必有之幾也，而感於物乃發為欲，情之所自生也。","sortOrder":157},
  {"id":"s_work_ttcm_2_158","chapterId":"ch_work_ttcm_2","text":"倏而生，忽而成，不容有毫發之間，其神矣夫！","sortOrder":158},
  {"id":"s_work_ttcm_2_159","chapterId":"ch_work_ttcm_2","text":"愛惡之情無端而不暫息者，即太虛之氣一動一靜之幾；物無不交，則情無不起，蓋亦不疾而速，不行而至也。存神以合湛，則愛惡無非天理矣。","sortOrder":159},
  {"id":"s_work_ttcm_2_160","chapterId":"ch_work_ttcm_2","text":"造化所成，無一物相肖者，","sortOrder":160},
  {"id":"s_work_ttcm_2_161","chapterId":"ch_work_ttcm_2","text":"大同必有小異。","sortOrder":161},
  {"id":"s_work_ttcm_2_162","chapterId":"ch_work_ttcm_2","text":"以是知萬物雖多，其實一物；無無陰陽者，","sortOrder":162},
  {"id":"s_work_ttcm_2_163","chapterId":"ch_work_ttcm_2","text":"若使但依种性而成，則區別而各相肖；唯聚而成，散而毀，既毀而复聚，一唯陰陽之变合，故物無定情，無定状，相同而必有異。足知陰陽行乎萬物之中，乘時以各效，全具一絪缊之體而特微爾。","sortOrder":163},
  {"id":"s_work_ttcm_2_164","chapterId":"ch_work_ttcm_2","text":"以是知天地变化，二端而已。","sortOrder":164},
  {"id":"s_work_ttcm_2_165","chapterId":"ch_work_ttcm_2","text":"一氣之中，二端既肇，摩之荡之而变化無窮，是以君子體之，仁義立而百王不同法，千聖不同功。","sortOrder":165},
  {"id":"s_work_ttcm_2_166","chapterId":"ch_work_ttcm_2","text":"萬物形色，神之糟粕，","sortOrder":166},
  {"id":"s_work_ttcm_2_167","chapterId":"ch_work_ttcm_2","text":"生而榮，如糟粕之含酒醴；死而槁，如酒醴盡而糟粕存；其究糟粕亦有所歸，歸於神化。","sortOrder":167},
  {"id":"s_work_ttcm_2_168","chapterId":"ch_work_ttcm_2","text":"“性與天道”雲者，易而已矣。","sortOrder":168},
  {"id":"s_work_ttcm_2_169","chapterId":"ch_work_ttcm_2","text":"神之有其理，在天為道，凝於人為性。易，变易也。陰陽摩荡，八卦興，六十四象成，各有時位错綜，而陰陽、刚柔、仁義之體立，皆神之变易也。互相易而萬物各成其形色，变易之妙，健順五常之用為之，故聖人存神以盡性而合天。敔按：神無方，易即其方；易無體，神即其體","sortOrder":169},
  {"id":"s_work_ttcm_2_170","chapterId":"ch_work_ttcm_2","text":"心所以萬殊者，摩外物為不一也，","sortOrder":170},
  {"id":"s_work_ttcm_2_171","chapterId":"ch_work_ttcm_2","text":"心函絪缊之全體而特微爾，其虛靈本一。而情識意見成乎萬殊者，物之相感，有同異，有攻取，時位異而知覺殊，亦猶萬物為陰陽之偶聚而不相肖也。","sortOrder":171},
  {"id":"s_work_ttcm_2_172","chapterId":"ch_work_ttcm_2","text":"天大無外，其為感者，絪缊二端而已。","sortOrder":172},
  {"id":"s_work_ttcm_2_173","chapterId":"ch_work_ttcm_2","text":"絪缊之中，陰陽具足，而变易以出，萬物併育於其中，不相肖而各成形色，隨感而出，無能越此二端。人心萬殊，操縱、取舍、愛惡、慈忍，一唯此陰陽之翕辟，順其理則為聖，從其妄則為狂，聖狂之分，在心幾变易之間，非形色之有善惡也。","sortOrder":173},
  {"id":"s_work_ttcm_2_174","chapterId":"ch_work_ttcm_2","text":"物之所以相感者，利用出入，莫知其乡。一萬物之妙者與！敔按：此節言天人合一之原，故下文以“天與人交勝”發明其感通","sortOrder":174},
  {"id":"s_work_ttcm_2_175","chapterId":"ch_work_ttcm_2","text":"此言聖人存神之妙，物無不相感應之理。其出而加乎物，物入而應乎己，用無不利，有不知其所以然而然之妙。蓋由萬物之生成，俱神為之变易，而各含絪缊太和之一氣，是以聖狂異趣，靈蠢異情，而感之自通，有不测之化焉。萬物之妙，神也；其形色，糟粕也；糟粕異而神用同，感之以神而神應矣。","sortOrder":175},
  {"id":"s_work_ttcm_2_176","chapterId":"ch_work_ttcm_2","text":"氣與志，天與人，有交勝之理。","sortOrder":176},
  {"id":"s_work_ttcm_2_177","chapterId":"ch_work_ttcm_2","text":"氣者，天化之撰；志者，人心之主；勝者，相為有功之謂。唯天生人，天為功於人而人從天治也。人能存神異性以保合太和，而使二氣之得其理，人為功於天而氣因志治也。不然，天生萬殊，质偏而性隱，而因任糟粕之嗜惡攻取以交相競，則濁惡之氣日充塞於兩間，聚散相仍，灾眚凶顽之所由弥長也。","sortOrder":177},
  {"id":"s_work_ttcm_2_178","chapterId":"ch_work_ttcm_2","text":"聖人在上而下民咨，氣壹之動志也；鳳凰儀，志壹之動氣也。","sortOrder":178},
  {"id":"s_work_ttcm_2_179","chapterId":"ch_work_ttcm_2","text":"尧、舜在上而下民有昏墊之咨，其時氣偶不順，於是聖人忧勤以相天之不足，氣专於偏戾，而聖人之志在勝天，不容不動也。地平天成，風凰來儀，則聖人勝天之功用成，而天為之動矣。人物之生，皆絪缊一氣之伸聚，雖聖人不能有所損益於太和；而二氣既分，吉凶、善不善以時位而不齊，聖人貞其大常，存神以御氣，則為功於变化屈伸之际，物無不感而天亦不能违之，此聖道之所自立，而異於異端之徇有以私一己，滅有以忘天下之诐辭也。敔按：此言氣動志，志動氣，猶言天勝人，人勝天也。今《孟子大全集》以此釋本文，失其旨矣","sortOrder":179},
  {"id":"s_work_ttcm_2_180","chapterId":"ch_work_ttcm_2","text":"參兩篇","sortOrder":180},
  {"id":"s_work_ttcm_2_181","chapterId":"ch_work_ttcm_2","text":"此篇備言天地日月五行之理數，理本於一而通極於萬变，以因象數而見理之一原。但所言日月疾遲與歷家之言異，太祖高皇帝嘗譏其非。天象高遠，不能定其孰是，而以二曜南北發斂遲疾例之，則陽疾陰遲之說未可執。據愚謂在天者即為理，不可執理以限天。《正蒙》一書，唯此為可疑，善讀者存之以待論可也。","sortOrder":181},
  {"id":"s_work_ttcm_2_182","chapterId":"ch_work_ttcm_2","text":"地所以兩，分刚柔男女而效之，法也；天所以參，一太極兩儀而象之，性也。","sortOrder":182},
  {"id":"s_work_ttcm_2_183","chapterId":"ch_work_ttcm_2","text":"天一地二，陽之爻函三為一而奇，陰之爻得三之二而偶，偶則分，奇則合。在天者浑淪一氣，凝結為地，則陰陽分矣。植物有刚柔之殊，動物有男女之別。效者，效著以成形也。法者，物形之定則。凡山川、金石、草木、禽虫以至於人，成乎形者皆地之效而物之法則立焉，兩者之分不可強而合矣。若其在天而未成乎形者，但有其象，絪缊浑合，太極之本體，中函陰陽自然必有之實，則於太極之中，不昧陰陽之象而陰陽未判，固即太極之象，合而言之則一，擬而議之則三，象之固然也。性以理言，有其象必有其理，惟其具太和之誠，故太極有兩儀，兩儀合而為太極，而分陰分陽，生萬物之形，皆秉此以為性。象者未聚而清，形者已聚而濁，清者為性為神，濁者為形為法。","sortOrder":183},
  {"id":"s_work_ttcm_2_184","chapterId":"ch_work_ttcm_2","text":"此章引伸《周易》參天兩地之說，而推其所以然之理。而君子因有形之耳目官骸，即物而盡其當然之則，進退、舒卷各有定經，體無形有象之性，以達天而存其清虛一大之神，故存心養性，保合太和，則參兩相倚以起化，而道在其中矣。","sortOrder":184},
  {"id":"s_work_ttcm_2_185","chapterId":"ch_work_ttcm_2","text":"一物兩體，氣也。","sortOrder":185},
  {"id":"s_work_ttcm_2_186","chapterId":"ch_work_ttcm_2","text":"絪缊太和，合於一氣，而陰陽之體具於中矣。","sortOrder":186},
  {"id":"s_work_ttcm_2_187","chapterId":"ch_work_ttcm_2","text":"一故神，張子自註：兩在故不测","sortOrder":187},
  {"id":"s_work_ttcm_2_188","chapterId":"ch_work_ttcm_2","text":"神者，不可测也，不滯則虛，善变則靈，太和之氣，於陰而在，於陽而在。其於人也，含於虛而行於耳目口體膚發之中，皆觸之而靈，不能测其所在。","sortOrder":188},
  {"id":"s_work_ttcm_2_189","chapterId":"ch_work_ttcm_2","text":"兩故化，張子自註：推行於一","sortOrder":189},
  {"id":"s_work_ttcm_2_190","chapterId":"ch_work_ttcm_2","text":"自太和一氣而推之，陰陽之化自此而分，陰中有陽，陽中有陰，原本於太極之一，非陰陽判離，各自孳生其類。故獨陰不成，孤陽不生，既生既成，而陰陽又各殊體。其在於人，刚柔相濟，義利相裁，道器相需，以成酬酢萬变之理，而皆协於一。","sortOrder":190},
  {"id":"s_work_ttcm_2_191","chapterId":"ch_work_ttcm_2","text":"此天之所以參也。","sortOrder":191},
  {"id":"s_work_ttcm_2_192","chapterId":"ch_work_ttcm_2","text":"自其神而言之則一，自其化而言之則兩。神中有化，化不離乎神，則天一而已，而可謂之參。故陽爻奇，一合三於一；陰偶，一分一得二；陽爻具陰，陰爻不能盡有陽也，分則太極不離而離矣。","sortOrder":192},
  {"id":"s_work_ttcm_2_193","chapterId":"ch_work_ttcm_2","text":"地純陰凝聚於中，天浮陽運旋於外，此天地之常體也。","sortOrder":193},
  {"id":"s_work_ttcm_2_194","chapterId":"ch_work_ttcm_2","text":"此言天者，天之體也。聚而成形者謂之陰，動而有象者謂之陽。天包地外，地在天中，浑天之說如此。","sortOrder":194},
  {"id":"s_work_ttcm_2_195","chapterId":"ch_work_ttcm_2","text":"恒星不動，純系乎天，與浮陽運旋而不窮者也。","sortOrder":195},
  {"id":"s_work_ttcm_2_196","chapterId":"ch_work_ttcm_2","text":"恒星，三垣二十八宿之經星。此言不動，謂其左旋者天體也。然以北斗回指言之，抑未可通。","sortOrder":196},
  {"id":"s_work_ttcm_2_197","chapterId":"ch_work_ttcm_2","text":"日月五星逆天而行，併包乎地者也。","sortOrder":197},
  {"id":"s_work_ttcm_2_198","chapterId":"ch_work_ttcm_2","text":"併包乎地，言居地之外，與地為體而同轉。以經星屬天，以七政屬地，乃張子之創說。","sortOrder":198},
  {"id":"s_work_ttcm_2_199","chapterId":"ch_work_ttcm_2","text":"地在氣中，雖順天左旋，其所系辰象隨之，稍遲則反移從而右爾；","sortOrder":199},
  {"id":"s_work_ttcm_2_200","chapterId":"ch_work_ttcm_2","text":"所系辰象，謂日月五星也。七政隨天左旋，以遲而見為右轉。張子盡破歷家之說，未問孰是，而謂地亦動而順天以旋，則地之不旋，明白易見，竊所未安。","sortOrder":200},
  {"id":"s_work_ttcm_2_201","chapterId":"ch_work_ttcm_2","text":"間有缓速不齊者，七政之性殊也。","sortOrder":201},
  {"id":"s_work_ttcm_2_202","chapterId":"ch_work_ttcm_2","text":"如歷家之說，月最速，金、水、日次之，火次之，木次之，土星最遲。此隨天左旋之說反是。七政既隨地而行，又安得自行其性？此亦未安。","sortOrder":202},
  {"id":"s_work_ttcm_2_203","chapterId":"ch_work_ttcm_2","text":"月陰精，反乎陽者也，故其右行最速；","sortOrder":203},
  {"id":"s_work_ttcm_2_204","chapterId":"ch_work_ttcm_2","text":"右行最速，左行最缓也。","sortOrder":204},
  {"id":"s_work_ttcm_2_205","chapterId":"ch_work_ttcm_2","text":"日為陽精，然其质本陰，故其右行雖缓，亦不純系乎天，如恒星不動。","sortOrder":205},
  {"id":"s_work_ttcm_2_206","chapterId":"ch_work_ttcm_2","text":"以外景內暗《離》卦之象推之，故曰其质本陰。不純系乎天者，謂併包乎地也。","sortOrder":206},
  {"id":"s_work_ttcm_2_207","chapterId":"ch_work_ttcm_2","text":"金、水附日前後進退而行者，其理精深，存乎物感可知矣。","sortOrder":207},
  {"id":"s_work_ttcm_2_208","chapterId":"ch_work_ttcm_2","text":"未詳。","sortOrder":208},
  {"id":"s_work_ttcm_2_209","chapterId":"ch_work_ttcm_2","text":"镇星地類，然根本五行，雖其行最缓，亦不純系乎地也。","sortOrder":209},
  {"id":"s_work_ttcm_2_210","chapterId":"ch_work_ttcm_2","text":"謂根本五行者，木、火、水、金皆依土而生者也。行最缓，以不及天而行，如左旋之說，則其行於七政為最速。不純系乎地，二十八歲而其行始不及天一周，幾與天同其健行矣。","sortOrder":210},
  {"id":"s_work_ttcm_2_211","chapterId":"ch_work_ttcm_2","text":"火者亦陰质，為陽萃焉，然其氣比日而微，故其遲倍日。","sortOrder":211},
  {"id":"s_work_ttcm_2_212","chapterId":"ch_work_ttcm_2","text":"陽萃者，陽聚於外而含陰也。其遲差日一倍，二歲而一周天。","sortOrder":212},
  {"id":"s_work_ttcm_2_213","chapterId":"ch_work_ttcm_2","text":"惟木乃歲一盛衰，故歲歷一辰。辰者，日月一交之次，有歲之象也。","sortOrder":213},
  {"id":"s_work_ttcm_2_214","chapterId":"ch_work_ttcm_2","text":"辰，十有二次也；日月交者，一月則易一次而交之。說與歷家異。歷家以象起數，此以理論數，此其所以異乎！","sortOrder":214},
  {"id":"s_work_ttcm_2_215","chapterId":"ch_work_ttcm_2","text":"凡圓轉之物，動必有機；既謂之機，則動非自外也。古今謂天左旋，此直至粗之論爾，不考日月出没，恒星昏晓之变。","sortOrder":215},
  {"id":"s_work_ttcm_2_216","chapterId":"ch_work_ttcm_2","text":"此直謂天體不動，地自內圓轉而見其差，於理未安。","sortOrder":216},
  {"id":"s_work_ttcm_2_217","chapterId":"ch_work_ttcm_2","text":"愚謂在天而運者，唯七曜而已。","sortOrder":217},
  {"id":"s_work_ttcm_2_218","chapterId":"ch_work_ttcm_2","text":"即所謂系乎地而不系乎天也。系乎地，故與地偕動，遲缓但因其性爾。","sortOrder":218},
  {"id":"s_work_ttcm_2_219","chapterId":"ch_work_ttcm_2","text":"恒星所以為晝夜者，直以地氣乘機左旋於中。故使恒星河漢因北為南，日月因天隱見。","sortOrder":219},
  {"id":"s_work_ttcm_2_220","chapterId":"ch_work_ttcm_2","text":"“左”，當作“右”。謂地氣圜轉。與歷家四遊之說異。","sortOrder":220},
  {"id":"s_work_ttcm_2_221","chapterId":"ch_work_ttcm_2","text":"太虛無體，則無以验其遷動於外也。","sortOrder":221},
  {"id":"s_work_ttcm_2_222","chapterId":"ch_work_ttcm_2","text":"太虛，至清之郛郭，固無體而不動；而坱然太虛之中，虛空即氣，氣則動者也。此義未安。","sortOrder":222},
  {"id":"s_work_ttcm_2_223","chapterId":"ch_work_ttcm_2","text":"天左旋，處其中者順之，少遲則反右矣。","sortOrder":223},
  {"id":"s_work_ttcm_2_224","chapterId":"ch_work_ttcm_2","text":"處其中者，謂日月五星。其說謂七曜亦隨天左旋，以行遲而不及天，人見其退，遂謂右轉。與歷家之說異，未詳孰是；而與前地旋而見天之左，抑不相通。","sortOrder":224},
  {"id":"s_work_ttcm_2_225","chapterId":"ch_work_ttcm_2","text":"地，物也；天，神也；物無逾神之理，顧有地斯有天，若其配然爾。","sortOrder":225},
  {"id":"s_work_ttcm_2_226","chapterId":"ch_work_ttcm_2","text":"天無體，太和絪缊之氣，為萬物所資始，屈伸变化，無跡而不可测，萬物之神所資也。聚而為物，地其最大者爾。逾，謂越此而別有也。地不能越天之神而自為物，成地者天，而天且淪浃於地之中，本不可以相配。但人之生也資地以生，有形乃以載神；則就人言之，地之德可以配天爾。知此，則抗方泽之祀於圜丘，伸母斬衰之服以齊於父，徇形重養而不恤義，後世所以淪乎幽而成乎亂也。張子之論韙矣。","sortOrder":226},
  {"id":"s_work_ttcm_2_227","chapterId":"ch_work_ttcm_2","text":"地有升降，日有修短。地雖凝聚不散之物，然二氣升降其間，相從而不已也。","sortOrder":227},
  {"id":"s_work_ttcm_2_228","chapterId":"ch_work_ttcm_2","text":"《月令》言“天氣下降，地氣上升”，謂氣也；此則言形隨氣而升降，未審然否。","sortOrder":228},
  {"id":"s_work_ttcm_2_229","chapterId":"ch_work_ttcm_2","text":"陽日上，地日降而下者，虛也：陽日降，地日進而上者，盈也。","sortOrder":229},
  {"id":"s_work_ttcm_2_230","chapterId":"ch_work_ttcm_2","text":"謂冬至以後，地日漸下，去日漸遠而晝長；夏至以後，地日漸高，去日漸近而晝短；與日行南北二陆之說異。虛，謂天地之間空曠；盈，謂天地相近而氣充滿。","sortOrder":230},
  {"id":"s_work_ttcm_2_231","chapterId":"ch_work_ttcm_2","text":"此一歲寒暑之候也。","sortOrder":231},
  {"id":"s_work_ttcm_2_232","chapterId":"ch_work_ttcm_2","text":"謂地高近日則暑，地下遠日則寒，不用南北二陆遠近之說。","sortOrder":232},
  {"id":"s_work_ttcm_2_233","chapterId":"ch_work_ttcm_2","text":"至於一晝夜之盈虛升降，則以海水潮汐验之為信：","sortOrder":233},
  {"id":"s_work_ttcm_2_234","chapterId":"ch_work_ttcm_2","text":"以潮验地之升降，謂地升則潮落，地降則潮生，地有一歲之大升降，又有一晝夜之小升降也。其謂寒暑因地之升降，皆自此测之。乃水亦地中之一物，故謂土為四行根本，而水必比地以安，則未可以水之盈虛验地之升降矣。","sortOrder":234},
  {"id":"s_work_ttcm_2_235","chapterId":"ch_work_ttcm_2","text":"然其間有小大之差，則系日月朔望，其精相感。","sortOrder":235},
  {"id":"s_work_ttcm_2_236","chapterId":"ch_work_ttcm_2","text":"此說又與上異。水之盈虛與月相感，使誠因乎此，則非地之升降矣。不及专家之學，以浑天质测及潮汐南北異候验之之為實也。敔按：质测之說出近日，歷家謂據法象以质實测之","sortOrder":236},
  {"id":"s_work_ttcm_2_237","chapterId":"ch_work_ttcm_2","text":"日质本陰，月质本陽；","sortOrder":237},
  {"id":"s_work_ttcm_2_238","chapterId":"ch_work_ttcm_2","text":"日，火之精也，火內暗而外明，《離》中陰也；月，水之精也，水內明而外暗，《坎》中陽也。日月不可知，以水火《坎》《離》测之。","sortOrder":238},
  {"id":"s_work_ttcm_2_239","chapterId":"ch_work_ttcm_2","text":"故於朔望之际，精魄反交，則光為之食矣。","sortOrder":239},
  {"id":"s_work_ttcm_2_240","chapterId":"ch_work_ttcm_2","text":"謂日精月魄交射，而易其外見之陰陽，故光為之奪。與歷家之說異，歷說為允。","sortOrder":240},
  {"id":"s_work_ttcm_2_241","chapterId":"ch_work_ttcm_2","text":"虧盈法：","sortOrder":241},
  {"id":"s_work_ttcm_2_242","chapterId":"ch_work_ttcm_2","text":"謂月晦朔絃望虧盈之理。","sortOrder":242},
  {"id":"s_work_ttcm_2_243","chapterId":"ch_work_ttcm_2","text":"月於人為近，日遠在外，故月受日光常在於外，人视其初終如鉤之曲，及其中天也如半璧然，此虧盈之验也。","sortOrder":243},
  {"id":"s_work_ttcm_2_244","chapterId":"ch_work_ttcm_2","text":"此說未詳。虧盈之故，晓然易知，沈存中之說備矣。","sortOrder":244},
  {"id":"s_work_ttcm_2_245","chapterId":"ch_work_ttcm_2","text":"月所位者陽，故受日之光，不受日之精，相望中絃則光為之食，精之不可以二也。","sortOrder":245},
  {"id":"s_work_ttcm_2_246","chapterId":"ch_work_ttcm_2","text":"位，謂定位而成质也。不受日之精，精相食則光亦不受，《坎》外之陰不為陽易也。此以理推度，非其實也。天者理所自出，在天者即為理，執理以测之，必有所窒矣。日月食自以歷家之說為允，但暗虛之說，疑不可從爾。","sortOrder":246},
  {"id":"s_work_ttcm_2_247","chapterId":"ch_work_ttcm_2","text":"日月雖以形相物，","sortOrder":247},
  {"id":"s_work_ttcm_2_248","chapterId":"ch_work_ttcm_2","text":"因其形而各謂之一物。","sortOrder":248},
  {"id":"s_work_ttcm_2_249","chapterId":"ch_work_ttcm_2","text":"考其道則有施受健順之差焉。","sortOrder":249},
  {"id":"s_work_ttcm_2_250","chapterId":"ch_work_ttcm_2","text":"日施光而月受之，施者健，受者順也。所以謂日陽而月陰，道取諸此。","sortOrder":250},
  {"id":"s_work_ttcm_2_251","chapterId":"ch_work_ttcm_2","text":"星月金水受光於火日，陰受而陽施也。","sortOrder":251},
  {"id":"s_work_ttcm_2_252","chapterId":"ch_work_ttcm_2","text":"謂星亦受日光，近天文家亦有雲然者。然以太白晝見验之，與月之在晝而暗者異，則說亦難通。金水受光於日火，以鏡及止水验之，亦物理之一端而已。","sortOrder":252},
  {"id":"s_work_ttcm_2_253","chapterId":"ch_work_ttcm_2","text":"陰陽之精互藏其宅，則各得其所安。","sortOrder":253},
  {"id":"s_work_ttcm_2_254","chapterId":"ch_work_ttcm_2","text":"精者，陰陽有兆而相合，始聚而為清微和粹，含神以為氣母者也。苟非此，則天地之間，一皆遊氣而無實矣。互藏其宅者，陽入陰中，陰麗陽中，坎、離其象也。太和之氣，陰陽浑合，互相容保其精，得太和之純粹，故陽非孤陽，陰非寡陰，相函而成质，乃不失其和而久安。","sortOrder":254},
  {"id":"s_work_ttcm_2_255","chapterId":"ch_work_ttcm_2","text":"故日月之形，萬古不变。","sortOrder":255},
  {"id":"s_work_ttcm_2_256","chapterId":"ch_work_ttcm_2","text":"互藏之精相得而不舍，則其相生也不窮，固與太虛之太和通理。天不变，故日月亦不变。","sortOrder":256},
  {"id":"s_work_ttcm_2_257","chapterId":"ch_work_ttcm_2","text":"若陰陽之氣，則循環迭至，聚散相荡，升降相求，絪缊相揉，蓋相兼相製，欲一之而不能。","sortOrder":257},
  {"id":"s_work_ttcm_2_258","chapterId":"ch_work_ttcm_2","text":"此則就分陰分陽各成其氣以主群動者言也。循環迭至，時有衰王，更相為主也。聚散相荡，聚則成而荡其散者之弱，散則遊而荡其聚者之滯也。升降相求，陰必求陽，陽必求陰，以成生化也。絪缊相揉，數本虛清，可以互入，而主辅多寡之不齊，揉雜無定也。二氣所生，風雷、雨雪、飛潛、動植、靈蠢、善惡皆其所必有，故萬象萬物雖不得太和之妙，而必兼有陰陽以相宰製，形状诡異，性情區分，不能一也；不能一則不能久。","sortOrder":258},
  {"id":"s_work_ttcm_2_259","chapterId":"ch_work_ttcm_2","text":"此其所以屈伸無方，運行不息，莫或使之，不曰性命之理，謂之何哉？","sortOrder":259},
  {"id":"s_work_ttcm_2_260","chapterId":"ch_work_ttcm_2","text":"屈伸無方者，生死之所以不恒，而聚散不能仍复其故也。運行不息，則雖不复其故，而伸者屈，屈者必伸也。鼓動於太虛之中，因氣之純雜，而理之昏明、強柔，性各別矣。故自風雷水火以至犬牛蛇虎，各成其性而自為理，变化數遷，無一成之法則也。以此論之，太和未分之前，初得其精者，日月也；陰陽成质以後，而能全其精者，人也。人之所以繼天立極，與日月之貞明同其誠而不息；能無丧焉，斯聖矣。","sortOrder":260},
  {"id":"s_work_ttcm_2_261","chapterId":"ch_work_ttcm_2","text":"“日月得天”，得自然之理也，非蒼蒼之形也。","sortOrder":261},
  {"id":"s_work_ttcm_2_262","chapterId":"ch_work_ttcm_2","text":"此上二節，皆因《易》“日月得天而能久照”之義而推言之。自然者，有自而然也。陰陽合而各有良能，神氣凝而為精，此日月之所自而能久照者，與太虛保合太和於無聲無臭之中者同其理，故日“得天”。","sortOrder":262},
  {"id":"s_work_ttcm_2_263","chapterId":"ch_work_ttcm_2","text":"閏餘生於朔，不盡周天之氣。","sortOrder":263},
  {"id":"s_work_ttcm_2_264","chapterId":"ch_work_ttcm_2","text":"三百六十五日有奇而天氣一周，一歲之朔十二，止得三百五十四日有奇。不盡者，氣盈朔虛也。置閏者，所以合月於日。","sortOrder":264},
  {"id":"s_work_ttcm_2_265","chapterId":"ch_work_ttcm_2","text":"而世傳交食法，與閏異術，蓋有不知而作者爾。","sortOrder":265},
  {"id":"s_work_ttcm_2_266","chapterId":"ch_work_ttcm_2","text":"合朔之法，以日月為朔望之准，用推閏餘，乃使分秒之積不差，如穀梁子晦食食既朔之說，及《四分》《三統》諸歷有經朔無定朔，皆不知而作也。此法今歷為密。","sortOrder":266},
  {"id":"s_work_ttcm_2_267","chapterId":"ch_work_ttcm_2","text":"陽之德主於遂，陰之德主於閉。","sortOrder":267},
  {"id":"s_work_ttcm_2_268","chapterId":"ch_work_ttcm_2","text":"德，謂性情功效；性情者其所自據之德，功效者見德於物也。遂，發生成物；閉，收藏自成。凡發生暘遂，皆陽之為而用夫陰；收斂成形，皆陰之為而保其陽。天地、水火、四時、百物、仁義、禮樂無不然者。","sortOrder":268},
  {"id":"s_work_ttcm_2_269","chapterId":"ch_work_ttcm_2","text":"陰性凝聚，陽性發散；陰聚之，陽必散之，其势均散。","sortOrder":269},
  {"id":"s_work_ttcm_2_270","chapterId":"ch_work_ttcm_2","text":"天地之化，人物之生，皆具陰陽二氣。其中陽之性散，陰之性聚，陰抱陽而聚，陽不能安於聚必散，其散也陰亦與之均散而返於太虛。","sortOrder":270},
  {"id":"s_work_ttcm_2_271","chapterId":"ch_work_ttcm_2","text":"陽為陰累，則相持為雨而降；陰為陽得，則飄扬為雲而升。","sortOrder":271},
  {"id":"s_work_ttcm_2_272","chapterId":"ch_work_ttcm_2","text":"雨雲皆陰也，陰氣迫聚於空虛而陽不得下交，陽為陰累矣。然陽不久困，持於上而使陰不升，陰势終抑而雨降，陽乃通矣。陰氣缓聚而欲升，與陽不相亢，而相入以相得也，則陽因其缓而受之。以其從容漸散輕清不聚者為陽，雖含陰氣亦陽也；其聚於地中與地為體者為陰，雖含陽氣亦陰也。凡陰陽之名義不一，陰亦有陰陽，陽亦有陰陽，非判然二物，終不相雜之謂。","sortOrder":272},
  {"id":"s_work_ttcm_2_273","chapterId":"ch_work_ttcm_2","text":"故雲物班布太虛者，陰為風驅，斂聚而未散者也。","sortOrder":273},
  {"id":"s_work_ttcm_2_274","chapterId":"ch_work_ttcm_2","text":"陰氣上升，初尚輕微，無形無象，陽氣欲散之，而驅之太骤，則陰弗能即與相得，而相保以聚，有為雨之势，故曰斂聚；然多不雨，弥久而後交於陽，故曰未散。前言飄扬而升者，倏起旋滅之雲；此言班布太虛者，弥亘不散之雲也。","sortOrder":274},
  {"id":"s_work_ttcm_2_275","chapterId":"ch_work_ttcm_2","text":"凡陰氣凝聚，","sortOrder":275},
  {"id":"s_work_ttcm_2_276","chapterId":"ch_work_ttcm_2","text":"凝聚於地上也。地天之际，人物之區，陰陽往來之冲，氣為尤厚。天氣浑淪，入有入無，一也，而入有者以有礙而難散，則氣聚於其間，輪屯紛遝，天氣舒缓以入，地氣得之相挟以聚，因互相凝結，即陽氣亦以聚而成陰矣。陰陽有定性而無定质也，故獨言陰而不言陽。","sortOrder":276},
  {"id":"s_work_ttcm_2_277","chapterId":"ch_work_ttcm_2","text":"陽在內者不得出，則奋击而為雷霆；","sortOrder":277},
  {"id":"s_work_ttcm_2_278","chapterId":"ch_work_ttcm_2","text":"內，地中也。陰氣在外錮之，迫而怒發。《震》，二陰錮一陽於內，雷從地出之象。","sortOrder":278},
  {"id":"s_work_ttcm_2_279","chapterId":"ch_work_ttcm_2","text":"陽在外者不得入，則周旋不舍而為風。","sortOrder":279},
  {"id":"s_work_ttcm_2_280","chapterId":"ch_work_ttcm_2","text":"外，地上空界也。空而無礙，可恣其遊衍周旋。不舍，八風相報也。《巽》，二陽在一陰之上，風行地上之象。","sortOrder":280},
  {"id":"s_work_ttcm_2_281","chapterId":"ch_work_ttcm_2","text":"其聚有遠近、虛實，故雷風有小大、暴缓。","sortOrder":281},
  {"id":"s_work_ttcm_2_282","chapterId":"ch_work_ttcm_2","text":"聚，陰聚也。陰之所聚，陽所不得而出入也。遠則風大而缓，近則風小而暴，虛則雷易出而小，實則雷難出而暴。","sortOrder":282},
  {"id":"s_work_ttcm_2_283","chapterId":"ch_work_ttcm_2","text":"和而散則為霜雪雨露，","sortOrder":283},
  {"id":"s_work_ttcm_2_284","chapterId":"ch_work_ttcm_2","text":"雨雪則陰降入地中而任陽之出入，和而散其聚矣；霜露又其微而缓者。","sortOrder":284},
  {"id":"s_work_ttcm_2_285","chapterId":"ch_work_ttcm_2","text":"不和而散則為戾氣曀霾；","sortOrder":285},
  {"id":"s_work_ttcm_2_286","chapterId":"ch_work_ttcm_2","text":"陽急欲散而陰之凝結益固，然其势必不能久聚，激為戾氣曀霾而後散焉。戾氣，雹類。","sortOrder":286},
  {"id":"s_work_ttcm_2_287","chapterId":"ch_work_ttcm_2","text":"陰常散缓，受交於陽，則風雨調，寒暑正。","sortOrder":287},
  {"id":"s_work_ttcm_2_288","chapterId":"ch_work_ttcm_2","text":"陰之必聚，其性然也。聚之缓而不惜散，則風雨應候，而不怙結以成戾，風雨時，則寒暑有節而正矣。","sortOrder":288},
  {"id":"s_work_ttcm_2_289","chapterId":"ch_work_ttcm_2","text":"此章言雷風雲雨之化，精極理势，於篇中尤醇矣。","sortOrder":289},
  {"id":"s_work_ttcm_2_290","chapterId":"ch_work_ttcm_2","text":"天象者，陽中之陰；風霆者，陰中之陽。","sortOrder":290},
  {"id":"s_work_ttcm_2_291","chapterId":"ch_work_ttcm_2","text":"輕清上浮者陽也，而有象有形，聚者為陰：出地而有實者陰也，而形無固形，究歸於散為陽。故曰“立天之道，曰陰與陽，立地之道，曰柔與刚”，非判然兩分而不相合也。","sortOrder":291},
  {"id":"s_work_ttcm_2_292","chapterId":"ch_work_ttcm_2","text":"雷霆感動雖速，然其所由來亦漸爾。","sortOrder":292},
  {"id":"s_work_ttcm_2_293","chapterId":"ch_work_ttcm_2","text":"陽氣積習於地中，盈而後奋。","sortOrder":293},
  {"id":"s_work_ttcm_2_294","chapterId":"ch_work_ttcm_2","text":"能窮神化所從來，德之盛者與？","sortOrder":294},
  {"id":"s_work_ttcm_2_295","chapterId":"ch_work_ttcm_2","text":"德盛於中，故神化疾速，於雷霆可验：如伊尹樂尧舜之道，一介無非道義，故一出而伐夏救民，莫之能御，其所從來者盛也。","sortOrder":295},
  {"id":"s_work_ttcm_2_296","chapterId":"ch_work_ttcm_2","text":"火日外光，能直而施；金水內光，能辟而受。受者隨材各得，","sortOrder":296},
  {"id":"s_work_ttcm_2_297","chapterId":"ch_work_ttcm_2","text":"大小、昏明各如其量而止。","sortOrder":297},
  {"id":"s_work_ttcm_2_298","chapterId":"ch_work_ttcm_2","text":"施者所應無窮。","sortOrder":298},
  {"id":"s_work_ttcm_2_299","chapterId":"ch_work_ttcm_2","text":"容光必照，遠而不御。","sortOrder":299},
  {"id":"s_work_ttcm_2_300","chapterId":"ch_work_ttcm_2","text":"神與形，天與地之道與？","sortOrder":300},
  {"id":"s_work_ttcm_2_301","chapterId":"ch_work_ttcm_2","text":"形則限於其材，故耳目雖靈，而目不能聽，耳不能视。且見聞之知，止於已見已聞，而窮於所以然之理。神則內周貫於五官，外泛應於萬物，不可見聞之理無不燭焉，天以神施，地以形應，道如是也。地順乎天，則行無疆；耳目從心，則大而能化；施者為主，受者為役。明乎此，則窮神合天之學得其要矣。","sortOrder":301},
  {"id":"s_work_ttcm_2_302","chapterId":"ch_work_ttcm_2","text":"此上二章，因天化以推心德之主宰，尤學者所宜盡心也。","sortOrder":302},
  {"id":"s_work_ttcm_2_303","chapterId":"ch_work_ttcm_2","text":"“木曰曲直”，能即曲而反伸也；","sortOrder":303},
  {"id":"s_work_ttcm_2_304","chapterId":"ch_work_ttcm_2","text":"既曲可伸，伸抑可曲。","sortOrder":304},
  {"id":"s_work_ttcm_2_305","chapterId":"ch_work_ttcm_2","text":"“金曰從革”，一從革而不能自反也。","sortOrder":305},
  {"id":"s_work_ttcm_2_306","chapterId":"ch_work_ttcm_2","text":"從者，不易其质，革者，其形可变。能從能革，具斯二德，此雲不能自反，於義未安。","sortOrder":306},
  {"id":"s_work_ttcm_2_307","chapterId":"ch_work_ttcm_2","text":"水火，氣也，故炎上润下，與陰陽升降，土不得而製焉。","sortOrder":307},
  {"id":"s_work_ttcm_2_308","chapterId":"ch_work_ttcm_2","text":"水火，有质而勝用在氣，氣，故可旁達，與金木之用止於形中異矣。與陰陽升降者，以陰陽升降為體也。土不得製者，不受命於土也。炎以散寒，润以解燥，與上升下燥各為二德，此獨就上下釋之。","sortOrder":308},
  {"id":"s_work_ttcm_2_309","chapterId":"ch_work_ttcm_2","text":"木金者，土之華實也，","sortOrder":309},
  {"id":"s_work_ttcm_2_310","chapterId":"ch_work_ttcm_2","text":"木者，土之敷榮；金，土之結而堅者爾。","sortOrder":310},
  {"id":"s_work_ttcm_2_311","chapterId":"ch_work_ttcm_2","text":"其性有水火之雜。故水之為物，水渍則生，火然而不離也，蓋得土之浮華於水火之交也。金之為物，得火之精於土之燥，得水之精於水當作土之濡，故水火相待而不相害，烁之反流而不耗，蓋得土之精實於水火之际也。","sortOrder":311},
  {"id":"s_work_ttcm_2_312","chapterId":"ch_work_ttcm_2","text":"渍而生，然而不離，惟其中有水火之性也。水火之交，謂水火之氣與陰陽升降，融彻土中，故土感其氣，合同而化，以發生浮華，以此知土中具有燥濡之性，為水火所資生，雖不能製，自包函之。燥者，土函火；濡者，土函水，木受水火之氣，故浮；金乃水火之精所結，故實。相待，謂金有津润還可生水，燧鏡還可生火，交相待以生，不相害，謂水火不能毀金，火雖烁金而金反流。流者，生動之機。火既去仍無所耗，若水則終不損金也。际者，兩相接而成之謂。水濡之，火燥之，土堅實而成金。","sortOrder":312},
  {"id":"s_work_ttcm_2_313","chapterId":"ch_work_ttcm_2","text":"土者，物之所以成始而成終也。","sortOrder":313},
  {"id":"s_work_ttcm_2_314","chapterId":"ch_work_ttcm_2","text":"始生於土，終歸於土，神有往來，土受之而成形。","sortOrder":314},
  {"id":"s_work_ttcm_2_315","chapterId":"ch_work_ttcm_2","text":"地之质也，","sortOrder":315},
  {"id":"s_work_ttcm_2_316","chapterId":"ch_work_ttcm_2","text":"地一土而已，木金皆其所生，水火依之而成。","sortOrder":316},
  {"id":"s_work_ttcm_2_317","chapterId":"ch_work_ttcm_2","text":"化之終也。","sortOrder":317},
  {"id":"s_work_ttcm_2_318","chapterId":"ch_work_ttcm_2","text":"二氣变化，至形成而止矣。","sortOrder":318},
  {"id":"s_work_ttcm_2_319","chapterId":"ch_work_ttcm_2","text":"水火之所以升降，","sortOrder":319},
  {"id":"s_work_ttcm_2_320","chapterId":"ch_work_ttcm_2","text":"火依地而升，水依地而降，下彻黃壚，炎润之性在焉。故無依空之水，火離土依空則息。","sortOrder":320},
  {"id":"s_work_ttcm_2_321","chapterId":"ch_work_ttcm_2","text":"物兼體而不遺者也。","sortOrder":321},
  {"id":"s_work_ttcm_2_322","chapterId":"ch_work_ttcm_2","text":"水、火、木、金皆與土為體，則萬匯之生，有形有质，土皆兼體而不遺矣。《洪范》之言五行，以人事言，利用厚生之資，故於土但曰稼穡。若自天化而言，即地也，四行所不得抗也。周子太極第一圖，太極之本體；第二圖，陰陽二氣，天之蘊也；第三圖，五行順布，地之撰也。第二圖陰陽分左右，而中有太極，陰陽分體太極，而太極自不雜，在天之極也；第三圖位土於中，周行水、火、木、金而別無太極，明上為在地之極也。土不待水火而生，而水火依土；木金、土之華實，非土外之有木金。張子此論，究極物理，與周子吻合。而術家之言謂火生土、木克土者，其陋明矣。蓋嘗論之，天以神御氣，地以氣成形，形成而後五行各著其體用。故在天唯有五星之象，在地乃有五行之形。五氣布者，就地而言。若七曜以上之天，極於無窮之高，入於無窮之深，不特五行之所不至，且無有所謂四時者。然則四時之行，亦地天之际氣應所感，非天體之固然矣。人生於天地之际，資地以成形而得天以為性，性麗於形而仁、義、禮、智著焉，斯盡人道之所必察也。若聖人存神以合天，則浑然一誠，仁、義、禮、智初無分用，又豈有惻隱、羞惡、恭敬、是非之因感而隨應者。然下學上達，必循其有跡以盡所得為，而豁然貫通之後，以至誠合天德，固未可躐等求也。","sortOrder":322},
  {"id":"s_work_ttcm_2_323","chapterId":"ch_work_ttcm_2","text":"冰者，陰凝而陽未勝也；","sortOrder":323},
  {"id":"s_work_ttcm_2_324","chapterId":"ch_work_ttcm_2","text":"“冰”當作“水”。水本以陽為质，而依於土之至陰，比而不離，一陽在陷而不能勝陰，終與地為體而成乎陰。","sortOrder":324},
  {"id":"s_work_ttcm_2_325","chapterId":"ch_work_ttcm_2","text":"火者，陽麗而陰未盡也。","sortOrder":325},
  {"id":"s_work_ttcm_2_326","chapterId":"ch_work_ttcm_2","text":"火本以陰為质，而麗於陽木以發，其光焰然，其中含陰暗，終不盡失其性，則固系乎地而不屬乎天。","sortOrder":326},
  {"id":"s_work_ttcm_2_327","chapterId":"ch_work_ttcm_2","text":"火之炎，人之蒸，有影無形，能散而不能受光者，其氣陽也。","sortOrder":327},
  {"id":"s_work_ttcm_2_328","chapterId":"ch_work_ttcm_2","text":"蒸，謂身之暖氣。陽散陰聚，陽施陰受，精含於內，氣發於外，故人知日火之炎明而不知其中之暗，知暖氣之蒸為炅熱而不知其中之寒。《素問》曰“陽虛故外熱”，得此旨矣。君子之自居德務保其精，而知人之明不取其外浮之氣，悉此理也。陽陷於陰為水，附於陰為火。","sortOrder":328},
  {"id":"s_work_ttcm_2_329","chapterId":"ch_work_ttcm_2","text":"《坎》《離》其象也，皆以陽為主，君子詞也。","sortOrder":329},
  {"id":"s_work_ttcm_3_1","chapterId":"ch_work_ttcm_3","text":"張子正蒙註卷二","sortOrder":1},
  {"id":"s_work_ttcm_3_2","chapterId":"ch_work_ttcm_3","text":"天道篇","sortOrder":2},
  {"id":"s_work_ttcm_3_3","chapterId":"ch_work_ttcm_3","text":"前二篇具明天道，此篇因天道以推聖德，而見聖人之學，惟求合於所自來之天而無所損益；其言雖若高遠，而原生之所自，則非此抑無以為人。周子曰：“賢希聖，聖希天。”希聖者，亦希其希天者也。大本不立而欲以學聖，非異端則曲學而已。學者不可以為若登天而別求企及之道也。","sortOrder":3},
  {"id":"s_work_ttcm_3_4","chapterId":"ch_work_ttcm_3","text":"天道四時行，百物生，無非至教；聖人之動，無非至德，夫何言哉！敔按：四時行，百物生，大德之敦化也；聖人之動，至斁之人神也；參互言之","sortOrder":4},
  {"id":"s_work_ttcm_3_5","chapterId":"ch_work_ttcm_3","text":"天言教者，天之曲成萬物，各正性命，非以自成其德也。聖言德者，聖人動無非善，非為立教而設，只以自成其德，然而學者之所學在此也。聖者，極乎善之謂。夫何言哉，知天知聖者於此學之，自不待言而至，非聖人之有秘密，求之於言語道斷間也。“夫”何言哉，舊本作“天”，今正之","sortOrder":5},
  {"id":"s_work_ttcm_3_6","chapterId":"ch_work_ttcm_3","text":"天體物不遺，猶仁體事無不在也。","sortOrder":6},
  {"id":"s_work_ttcm_3_7","chapterId":"ch_work_ttcm_3","text":"天以太虛為體，而太和之絪缊充滿焉，故無物不體之以為性命。仁以無欲為體，而视聽言動之節文生焉，故無事不體之以為心理之安。天者仁之全體，仁者天之心，一也。敔按：仁之全體即天，於心見天，故曰天之心，天人一矣","sortOrder":7},
  {"id":"s_work_ttcm_3_8","chapterId":"ch_work_ttcm_3","text":"“禮儀三百，威儀三千”，無一物而非仁也。","sortOrder":8},
  {"id":"s_work_ttcm_3_9","chapterId":"ch_work_ttcm_3","text":"心所不容已而禮不容已矣，故复禮斯為仁矣。禮者，复吾心之動而求安，以與事物相順者也。敔按：复吾心之動而求安，所謂“复其見天地之心”也","sortOrder":9},
  {"id":"s_work_ttcm_3_10","chapterId":"ch_work_ttcm_3","text":"“昊天曰明。及爾出王；昊天曰旦，及爾遊衍。”無一物之不體也。敔按：禮者，天理之節文也，曰明，曰旦，節文於斯顯矣","sortOrder":10},
  {"id":"s_work_ttcm_3_11","chapterId":"ch_work_ttcm_3","text":"無一事之不有體，則無一物之可與天违也。","sortOrder":11},
  {"id":"s_work_ttcm_3_12","chapterId":"ch_work_ttcm_3","text":"此章合天與仁而言，其全體切近人心，朱子謂其從赤心流出，允矣。而顯仁於體，俾學者有所持循，尤求仁者之實務，非凭虛以言存養而與異端相似之比。張子之學，以禮為鵠，此章其枢要也。","sortOrder":12},
  {"id":"s_work_ttcm_3_13","chapterId":"ch_work_ttcm_3","text":"上天之載，有感必通；","sortOrder":13},
  {"id":"s_work_ttcm_3_14","chapterId":"ch_work_ttcm_3","text":"百物之生，情動氣興，天命即授以成其形性，蓋浑淪流動，有可受斯應之。","sortOrder":14},
  {"id":"s_work_ttcm_3_15","chapterId":"ch_work_ttcm_3","text":"聖人之為，得為而為之應。敔按：得為而為之，是以以時製禮","sortOrder":15},
  {"id":"s_work_ttcm_3_16","chapterId":"ch_work_ttcm_3","text":"浑然一仁，道無不足，時可為則如其理而為之。","sortOrder":16},
  {"id":"s_work_ttcm_3_17","chapterId":"ch_work_ttcm_3","text":"天不言而四時行，聖人神道設教而天下服，誠於此，通於彼，神之道與？","sortOrder":17},
  {"id":"s_work_ttcm_3_18","chapterId":"ch_work_ttcm_3","text":"《觀》之象曰“神道設教”，非假鬼神以誣民也，不言而誠盡於己，與天之行四時者順理而自然感動，天下服矣。天以化為德，聖人以德為化，惟太和在中，充實誠篤而已。","sortOrder":18},
  {"id":"s_work_ttcm_3_19","chapterId":"ch_work_ttcm_3","text":"天不言而信，","sortOrder":19},
  {"id":"s_work_ttcm_3_20","chapterId":"ch_work_ttcm_3","text":"四時不忒，萬物各肖其類之謂信。","sortOrder":20},
  {"id":"s_work_ttcm_3_21","chapterId":"ch_work_ttcm_3","text":"神不怒而威。","sortOrder":21},
  {"id":"s_work_ttcm_3_22","chapterId":"ch_work_ttcm_3","text":"聖人神道設教而天下服。","sortOrder":22},
  {"id":"s_work_ttcm_3_23","chapterId":"ch_work_ttcm_3","text":"誠，故信；","sortOrder":23},
  {"id":"s_work_ttcm_3_24","chapterId":"ch_work_ttcm_3","text":"天惟健順之理，充足於太虛而氣無妄動；無妄動，故寒暑化育無不給足，而何有於爽忒。敔按：氣無妄動，理之誠也，無妄，信也","sortOrder":24},
  {"id":"s_work_ttcm_3_25","chapterId":"ch_work_ttcm_3","text":"無私，故威。","sortOrder":25},
  {"id":"s_work_ttcm_3_26","chapterId":"ch_work_ttcm_3","text":"聖人得理之全，無所偏則無所用其私，刑賞皆如其理而隨應之，故天下自服。","sortOrder":26},
  {"id":"s_work_ttcm_3_27","chapterId":"ch_work_ttcm_3","text":"此章申明上章誠此通彼之理而著其所以然之實，蓋人惟托於義理之跡而無實，則據所托以為己私而思以诎天下。聖人喜怒恩威，至虛而靈，備萬物生殺之理，至足而無所缺陷，何私之有？天之誠，聖人之無私，一也。御六氣，用陰陽，非人之所能测矣，此神之大用也。","sortOrder":27},
  {"id":"s_work_ttcm_3_28","chapterId":"ch_work_ttcm_3","text":"天之不测謂神，神而有常謂天。敔按：天之不测，天之神也；神而有常，人之天也","sortOrder":28},
  {"id":"s_work_ttcm_3_29","chapterId":"ch_work_ttcm_3","text":"天自有其至常，人以私意度之則不可测。神，非变幻無恒也，天自不可以情識計度，據之為常，誠而已矣。","sortOrder":29},
  {"id":"s_work_ttcm_3_30","chapterId":"ch_work_ttcm_3","text":"運於無形之謂道，形而下者不足以言之。敔按：運於無形，兼天道人道而言","sortOrder":30},
  {"id":"s_work_ttcm_3_31","chapterId":"ch_work_ttcm_3","text":"形有定而運之無方，運之者得其所以然之理而盡其能然之用。惟誠則體其所以然，惟無私則盡其能然；所以然者不可以言顯，能然者言所不能盡。言者，但言其有形之器而已，故言教有窮，而至德之感通，萬物皆受其裁成。","sortOrder":31},
  {"id":"s_work_ttcm_3_32","chapterId":"ch_work_ttcm_3","text":"鼓萬物而不與聖人同忧，天道也。","sortOrder":32},
  {"id":"s_work_ttcm_3_33","chapterId":"ch_work_ttcm_3","text":"化之有灾祥，物之有善惡靈蠢，聖人忧之而天不以為忧，在天者無不誠，則無不可成其至教也。","sortOrder":33},
  {"id":"s_work_ttcm_3_34","chapterId":"ch_work_ttcm_3","text":"聖不可知也，無心之妙，非有心所及也。","sortOrder":34},
  {"id":"s_work_ttcm_3_35","chapterId":"ch_work_ttcm_3","text":"聖人雖與民同其忧患，而不役心於治教政刑以求勝之，唯反身而誠，身正而天下平，故不親不洽不答，皆以無心應之。彼迫於治物者，皆心以應物而物不感，見聖人之舞幹而苗格，因壘而崇降，不测其所以然之理，則固不能知之。","sortOrder":35},
  {"id":"s_work_ttcm_3_36","chapterId":"ch_work_ttcm_3","text":"“不見而章”，已誠而明也；","sortOrder":36},
  {"id":"s_work_ttcm_3_37","chapterId":"ch_work_ttcm_3","text":"“見”，如字。誠有其理，則自知之，如耳目口鼻之在面，暗中自知其處，不假聞見之知。","sortOrder":37},
  {"id":"s_work_ttcm_3_38","chapterId":"ch_work_ttcm_3","text":"“不動而变”，神而化也；","sortOrder":38},
  {"id":"s_work_ttcm_3_39","chapterId":"ch_work_ttcm_3","text":"有言有教皆動也。神者以誠有之太和感動萬物，而因材各得，物自变矣。","sortOrder":39},
  {"id":"s_work_ttcm_3_40","chapterId":"ch_work_ttcm_3","text":"“無為而成”，物不貳也。","sortOrder":40},
  {"id":"s_work_ttcm_3_41","chapterId":"ch_work_ttcm_3","text":"誠不息，神無間，盡誠合神，純於至善，而德盛化神，無不成矣。有為者以己聞見之知，倚於名法，設立政教，於事愈繁，於道愈缺，終身役役而不能成，惡足以知其妙哉！","sortOrder":41},
  {"id":"s_work_ttcm_3_42","chapterId":"ch_work_ttcm_3","text":"已誠而明，故能“不見而章，不動而变，無為而成”。","sortOrder":42},
  {"id":"s_work_ttcm_3_43","chapterId":"ch_work_ttcm_3","text":"承上章而括之以誠。神，非变幻不测之謂，實得其鼓動萬物之理也；不貳，非固執其聞見之知，終始盡誠於己也。此至誠存神之實也。","sortOrder":43},
  {"id":"s_work_ttcm_3_44","chapterId":"ch_work_ttcm_3","text":"“富有”，廣大不御之盛與！“日新”，悠久無疆之道與！","sortOrder":44},
  {"id":"s_work_ttcm_3_45","chapterId":"ch_work_ttcm_3","text":"富有，非積聞見之知也，通天地萬物之理而用其神化，則廣大不御矣。日新，非數变其道之謂，體神之誠，終始不間，則極乎悠久無疆矣。釋《易·系傳》，而示學者勿侈博以為廣大，勿逐物以為日新。","sortOrder":45},
  {"id":"s_work_ttcm_3_46","chapterId":"ch_work_ttcm_3","text":"天之知物，不以耳目心思，然知之之理，過於耳目心思。","sortOrder":46},
  {"id":"s_work_ttcm_3_47","chapterId":"ch_work_ttcm_3","text":"心思倚耳目以知者，人為之私也；心思寓於神化者，天德也。","sortOrder":47},
  {"id":"s_work_ttcm_3_48","chapterId":"ch_work_ttcm_3","text":"天视聽以民，明威以民，故《詩》《書》所謂帝天之命，主於民心而已焉。","sortOrder":48},
  {"id":"s_work_ttcm_3_49","chapterId":"ch_work_ttcm_3","text":"天無特立之體，即其神化以為體；民之视聽明威，皆天之神也。故民心之大同者，理在是，天即在是，而吉凶應之。若民私心之恩怨，則祁寒暑雨之怨咨，徇耳目之利害以與天相忤，理所不在，君子勿恤。故流放竄殛，不避其怨而逢其欲，己私不可徇，民之私亦不可徇也。","sortOrder":49},
  {"id":"s_work_ttcm_3_50","chapterId":"ch_work_ttcm_3","text":"“化而裁之存乎变。”存四時之变，則周歲之化可裁；存晝夜之变，則百刻之化可裁。","sortOrder":50},
  {"id":"s_work_ttcm_3_51","chapterId":"ch_work_ttcm_3","text":"存，謂識其理於心而不忘也。变者，陰陽順逆事物得失之數，盡知其必可之变而存之於心，則物化無恒，而皆豫知其情状而裁之。存四時之溫凉生殺，則節宣之裁審矣；存百刻之風雨晦明，則作息之裁定矣。化雖異而不驚，裁因時而不逆，天道且惟其所裁，而况人事乎！","sortOrder":51},
  {"id":"s_work_ttcm_3_52","chapterId":"ch_work_ttcm_3","text":"“推而行之存乎通。”推四時而行，則能存周歲之通；推晝夜而行，則能存百刻之通。","sortOrder":52},
  {"id":"s_work_ttcm_3_53","chapterId":"ch_work_ttcm_3","text":"通者，化雖变而吉凶相倚，喜怒相因，得失相互，可會通於一也。推其情之所必至，势之所必反，行於此者可通於彼而不滯於一隅之識，則夏之葛可通於冬之裘，晝之作可通於夜之息，要歸於得其和平，而变皆常矣。故或仕或止，或語或嘿，或刑或賞，皆协一而不相悖害。惟豫有以知其相通之理而存之，故行於此而不礙於彼；當其变必存其通，當其通必存其变，推行之大用，合於一心之所存，此之謂神。","sortOrder":53},
  {"id":"s_work_ttcm_3_54","chapterId":"ch_work_ttcm_3","text":"“神而明之，存乎其人。”不知上天之載，當存文王。","sortOrder":54},
  {"id":"s_work_ttcm_3_55","chapterId":"ch_work_ttcm_3","text":"文王之德“不顯亦臨，不聞亦式”，能常存此於心，則天載之神，化育亭毒於聲臭之外者，無不明矣。","sortOrder":55},
  {"id":"s_work_ttcm_3_56","chapterId":"ch_work_ttcm_3","text":"“默而成之，存乎德行。”學者常存德性，則自然默成而信矣。","sortOrder":56},
  {"id":"s_work_ttcm_3_57","chapterId":"ch_work_ttcm_3","text":"德性者，非耳目口體之性，乃仁義禮智之根心而具足者也。常存之於心，而靜不忘，動不迷，不倚見聞言論而德皆實矣。","sortOrder":57},
  {"id":"s_work_ttcm_3_58","chapterId":"ch_work_ttcm_3","text":"存文王則知天載之神，存眾人則知物性之神。","sortOrder":58},
  {"id":"s_work_ttcm_3_59","chapterId":"ch_work_ttcm_3","text":"眾人之聰明明威，皆天之所降神也。故既存聖人藏密之神，抑必存眾人昭著之神。天載者，所以推行於物性，而物性莫非天載也。天之神理，無乎不察，於聖人得其微，於眾人得其顯，無往而不用其體验也。","sortOrder":59},
  {"id":"s_work_ttcm_3_60","chapterId":"ch_work_ttcm_3","text":"穀之神也有限，故不能通天下之聲；","sortOrder":60},
  {"id":"s_work_ttcm_3_61","chapterId":"ch_work_ttcm_3","text":"老氏以穀神為眾妙之門，然就其心量之所及而空之，以待物而應，則天下之理不得者多矣，猶穀之應聲不能遠。","sortOrder":61},
  {"id":"s_work_ttcm_3_62","chapterId":"ch_work_ttcm_3","text":"聖人之神惟天，故能周萬物而知。","sortOrder":62},
  {"id":"s_work_ttcm_3_63","chapterId":"ch_work_ttcm_3","text":"聖人通天載而達物性，不立一私意而無一物之滯者，惟其萬物之理皆得而知四達也。蓋神運於虛，而老氏以虛為神，暫止其躁動窒塞之情，亦能以機應物而物或應；惟其虛擬聖人之天載而遺乎物性，則與太虛之絪缊一實者相離，而天下之不能通必矣。","sortOrder":63},
  {"id":"s_work_ttcm_3_64","chapterId":"ch_work_ttcm_3","text":"聖人有感無隱，正猶天道之神。","sortOrder":64},
  {"id":"s_work_ttcm_3_65","chapterId":"ch_work_ttcm_3","text":"仁義、禮樂、刑賞、進退之理無倚，而皆備於虛靜之中，感之者各得所欲而無不給，與天之絪缊不息，物感之而各成者，同其肆應不勞，人所不能测也。","sortOrder":65},
  {"id":"s_work_ttcm_3_66","chapterId":"ch_work_ttcm_3","text":"形而上者，得意斯得名，得名斯得象；","sortOrder":66},
  {"id":"s_work_ttcm_3_67","chapterId":"ch_work_ttcm_3","text":"形而上者，道也。形之所從生與其所用，皆有理焉，仁義中正之化裁所生也。仁義中正，可心喻而為之名者也。得惻隱之意，則可自名為仁，得羞惡之意，則可自名為義，因而征之於事為，以愛人製事，而仁義之象著矣。","sortOrder":67},
  {"id":"s_work_ttcm_3_68","chapterId":"ch_work_ttcm_3","text":"不得名，非得象者也。","sortOrder":68},
  {"id":"s_work_ttcm_3_69","chapterId":"ch_work_ttcm_3","text":"若夫神也者，含仁義中正之理而不倚於跡，為道之所從生，不能以一德名之。而成乎德者亦不著其象，不得已而謂之曰誠。誠，以言其實有爾，非有一象可名之為誠也。","sortOrder":69},
  {"id":"s_work_ttcm_3_70","chapterId":"ch_work_ttcm_3","text":"故語道至於不能象，則名言亡矣。","sortOrder":70},
  {"id":"s_work_ttcm_3_71","chapterId":"ch_work_ttcm_3","text":"存之於心者得之爾。","sortOrder":71},
  {"id":"s_work_ttcm_3_72","chapterId":"ch_work_ttcm_3","text":"世人知道之自然，未始識自然之為體爾。","sortOrder":72},
  {"id":"s_work_ttcm_3_73","chapterId":"ch_work_ttcm_3","text":"孩提愛親，長而敬兄，天高地下，迪吉逆凶，皆人以為自然者也。自然者，絪缊之體，健順之誠，為其然之所自，識之者鮮矣。","sortOrder":73},
  {"id":"s_work_ttcm_3_74","chapterId":"ch_work_ttcm_3","text":"有天德，然後天地之道可一言而盡。","sortOrder":74},
  {"id":"s_work_ttcm_3_75","chapterId":"ch_work_ttcm_3","text":"存神以存誠，知天地之道唯此爾，故可一言而盡。","sortOrder":75},
  {"id":"s_work_ttcm_3_76","chapterId":"ch_work_ttcm_3","text":"正明不為日月所眩，正觀不為天地所遷。","sortOrder":76},
  {"id":"s_work_ttcm_3_77","chapterId":"ch_work_ttcm_3","text":"“正”，《易》作“貞”，宋避廟讳作“正”。貞者，正而恒也。自誠而明，非目之倚，日月為明，還為所眩也。觀者，盡於己而示物也。天地，以氣化之变言。治亂吉凶，天地無常數，而至誠有常理，不為所变也。","sortOrder":77},
  {"id":"s_work_ttcm_3_78","chapterId":"ch_work_ttcm_3","text":"神化篇","sortOrder":78},
  {"id":"s_work_ttcm_3_79","chapterId":"ch_work_ttcm_3","text":"此篇備言神化，而歸其存神敦化之本於義，上達無窮而下學有實。張子之學所以別於異端而為學者之所宜守，蓋與孟子相發明焉。","sortOrder":79},
  {"id":"s_work_ttcm_3_80","chapterId":"ch_work_ttcm_3","text":"神，天德；","sortOrder":80},
  {"id":"s_work_ttcm_3_81","chapterId":"ch_work_ttcm_3","text":"絪缊不息，為敦化之本。","sortOrder":81},
  {"id":"s_work_ttcm_3_82","chapterId":"ch_work_ttcm_3","text":"化，天道；","sortOrder":82},
  {"id":"s_work_ttcm_3_83","chapterId":"ch_work_ttcm_3","text":"四時百物各正其秩序，為古今不易之道。","sortOrder":83},
  {"id":"s_work_ttcm_3_84","chapterId":"ch_work_ttcm_3","text":"德其體，道其用，","sortOrder":84},
  {"id":"s_work_ttcm_3_85","chapterId":"ch_work_ttcm_3","text":"體者所以用，用者即用其體。","sortOrder":85},
  {"id":"s_work_ttcm_3_86","chapterId":"ch_work_ttcm_3","text":"一於氣而已。敔按：此言德者健順之體，道者陰陽之用，健順陰陽，一太和之氣也","sortOrder":86},
  {"id":"s_work_ttcm_3_87","chapterId":"ch_work_ttcm_3","text":"氣，其所有之實也。其絪缊而含健順之性，以升降屈伸，條理必信者，神也。神之所為聚而成象成形以生萬变者，化也。故神，氣之神；化，氣之化也。","sortOrder":87},
  {"id":"s_work_ttcm_3_88","chapterId":"ch_work_ttcm_3","text":"神無方，易無體。","sortOrder":88},
  {"id":"s_work_ttcm_3_89","chapterId":"ch_work_ttcm_3","text":"神行氣而無不可成之化，凡方皆方，無一隅之方。易六位错綜，因時成象，凡體皆體，無一定之體。","sortOrder":89},
  {"id":"s_work_ttcm_3_90","chapterId":"ch_work_ttcm_3","text":"大且一而已爾。","sortOrder":90},
  {"id":"s_work_ttcm_3_91","chapterId":"ch_work_ttcm_3","text":"無所遺之謂大，無不貫之謂一，故易簡而天下之理得。體斯道也，仁義中正扩充無外，而進退、存亡、刑賞、禮樂、清和、安勉，道皆隨時而得中；若夷之清，惠之和，有方有體，不足以合神而體易矣。宽以居之，仁以行之，學以聚之，問以辨之，則所由至於大且一也。","sortOrder":91},
  {"id":"s_work_ttcm_3_92","chapterId":"ch_work_ttcm_3","text":"虛明照鑒，神之明也；","sortOrder":92},
  {"id":"s_work_ttcm_3_93","chapterId":"ch_work_ttcm_3","text":"太虛不滯於形，故大明而秩序不紊；君子不滯於意，故貞明而事理不迷。照鑒者，不假審察而自知之謂。","sortOrder":93},
  {"id":"s_work_ttcm_3_94","chapterId":"ch_work_ttcm_3","text":"無遠近幽深，利用出入，神之充塞無間也。","sortOrder":94},
  {"id":"s_work_ttcm_3_95","chapterId":"ch_work_ttcm_3","text":"氣之所至，神皆至焉。氣充塞而無間，神亦無間，明無不彻，用無不利，神之為德莫有盛焉矣。","sortOrder":95},
  {"id":"s_work_ttcm_3_96","chapterId":"ch_work_ttcm_3","text":"天下之動，神鼓之也；","sortOrder":96},
  {"id":"s_work_ttcm_3_97","chapterId":"ch_work_ttcm_3","text":"天以神御氣而時行物生，人以神感物而移風易俗。神者，所以感物之神而類應者也。","sortOrder":97},
  {"id":"s_work_ttcm_3_98","chapterId":"ch_work_ttcm_3","text":"辭不鼓舞，則不足以盡神。","sortOrder":98},
  {"id":"s_work_ttcm_3_99","chapterId":"ch_work_ttcm_3","text":"君子之有辭，不徇聞見，不立標榜，盡其心，专其氣，言皆心之所出而氣無浮沮，則神著於辭，雖愚不肖不能不興起焉。若袭取剿說，則仁義忠孝之言，人且迂视之而漠然不應，不足以鼓舞，唯其神不存也。","sortOrder":99},
  {"id":"s_work_ttcm_3_100","chapterId":"ch_work_ttcm_3","text":"鬼神，往來屈伸之義；張子自註：神示者，歸之始；歸往者，來之終","sortOrder":100},
  {"id":"s_work_ttcm_3_101","chapterId":"ch_work_ttcm_3","text":"始終循環一氣也，往來者屈伸而已。","sortOrder":101},
  {"id":"s_work_ttcm_3_102","chapterId":"ch_work_ttcm_3","text":"故天曰神，地曰示，人曰鬼。","sortOrder":102},
  {"id":"s_work_ttcm_3_103","chapterId":"ch_work_ttcm_3","text":"天之氣伸於人物而行其化者曰神，人之生理盡而氣屈反歸曰鬼；地順天生物，而人由以歸者也，屈伸往來之利用，皆於是而昭著焉，故曰示。示居神鬼之間，以昭示夫鬼神之功效者也。","sortOrder":103},
  {"id":"s_work_ttcm_3_104","chapterId":"ch_work_ttcm_3","text":"形而上者，得辭斯得象矣。","sortOrder":104},
  {"id":"s_work_ttcm_3_105","chapterId":"ch_work_ttcm_3","text":"神化，形而上者也，跡不顯；而由辭以想其象，則得其實。","sortOrder":105},
  {"id":"s_work_ttcm_3_106","chapterId":"ch_work_ttcm_3","text":"神為不测，故缓辭不足以盡神；","sortOrder":106},
  {"id":"s_work_ttcm_3_107","chapterId":"ch_work_ttcm_3","text":"不测者，有其象，無其形，非可以比類廣引而擬之。指其本體，曰誠，曰天，曰仁，一言而盡之矣。","sortOrder":107},
  {"id":"s_work_ttcm_3_108","chapterId":"ch_work_ttcm_3","text":"化為難知。故急辭不足以盡化。","sortOrder":108},
  {"id":"s_work_ttcm_3_109","chapterId":"ch_work_ttcm_3","text":"化無定體，萬有不窮，難指其所在，故四時百物萬事皆所必察，不可以要略言之，從容博引，乃可以體其功用之廣。辭之缓急如其本然，所以盡神，然後能鼓舞天下，使眾著於神化之象，此讀《易》窮理者所當知也。","sortOrder":109},
  {"id":"s_work_ttcm_3_110","chapterId":"ch_work_ttcm_3","text":"氣有陰陽，","sortOrder":110},
  {"id":"s_work_ttcm_3_111","chapterId":"ch_work_ttcm_3","text":"陰陽之實，情才各異，故其致用，功效亦殊。若其以動靜、屈伸、聚散分陰陽為言者，又此二氣之合而因時以效動，則陽之靜屈而散，亦謂之陰，陰之動伸而聚，亦謂之陽，假陰阻之象以名之爾，非氣本無陰陽，因動靜屈伸聚散而始有也。故直言氣有陰陽，以明太虛之中雖無形之可執，而溫肅、生殺、清濁之體性俱有於一氣之中，同為固有之實也。","sortOrder":111},
  {"id":"s_work_ttcm_3_112","chapterId":"ch_work_ttcm_3","text":"推行有漸為化，合一不测為神。","sortOrder":112},
  {"id":"s_work_ttcm_3_113","chapterId":"ch_work_ttcm_3","text":"其發而為陰陽，各以序為主辅，而時行物生，不窮於生，化也。其推行之本，則固合為一氣，和而不相悖害。陰陽實有之性，名不能施，象不能別，則所謂神也。","sortOrder":113},
  {"id":"s_work_ttcm_3_114","chapterId":"ch_work_ttcm_3","text":"其在人也，知義用利，則神化之事備矣。","sortOrder":114},
  {"id":"s_work_ttcm_3_115","chapterId":"ch_work_ttcm_3","text":"知者，洞見事物之所以然，未效於跡而不昧其實，神之所自發也。義者，因事製宜，刚柔有序，化之所自行也。以知知義，以義行知，存於心而推行於物，神化之事也。","sortOrder":115},
  {"id":"s_work_ttcm_3_116","chapterId":"ch_work_ttcm_3","text":"德盛者，窮神則知不足道，知化則義不足雲。","sortOrder":116},
  {"id":"s_work_ttcm_3_117","chapterId":"ch_work_ttcm_3","text":"知所以求窮乎神，義所以求善其化。知之盡，義之精，大明終始，無事審察，隨時處中而不立矩則。惟純體陰陽之全德，則可陰，可陽，可陽而陰，可陰而陽，如春溫而不無涼雨，秋肅而不废和風，不待知知，不求合義矣。然使非全體天地陰陽之德，則弃知外義以遁於空感，洸洋自恣，又奚可哉！","sortOrder":117},
  {"id":"s_work_ttcm_3_118","chapterId":"ch_work_ttcm_3","text":"天之化也運諸氣，人之化也順夫時；非氣非時，則化之名何有，化之實何施！","sortOrder":118},
  {"id":"s_work_ttcm_3_119","chapterId":"ch_work_ttcm_3","text":"惟其有氣，乃運之而成化；理足於己，則隨時應物以利用，而物皆受化矣。非氣則物自生自死，不資於天，何雲天化；非時則己之氣與物氣相忤，而施亦窮。乃所以為時者，喜怒、生殺、泰否、損益，皆陰陽之氣一阖一辟之幾也。以陰交陽，以陽濟陰，以陰應陰，以陽應陽，以吾性之健順應固有之陰陽，則出處、語默、刑賞、治教，道運於心，自感通於天下。聖人化成天下，其枢機之要，唯善用其氣而已。","sortOrder":119},
  {"id":"s_work_ttcm_3_120","chapterId":"ch_work_ttcm_3","text":"中庸曰“至誠為能化”，《孟子》曰“大而化之”，皆以其德合陰陽，與天地同流而無不通也。","sortOrder":120},
  {"id":"s_work_ttcm_3_121","chapterId":"ch_work_ttcm_3","text":"至誠，實有天道之謂；大者，充實於內，化之本也。惟其健順之德，凝五常而無間，合二氣之阖辟，備之無遺，存之不失，故因天地之時，與之同流，有實體則有實用，化之所以鹹通也。陰陽合為一德，不测之神也；存神以御氣，則誠至而聖德成矣。","sortOrder":121},
  {"id":"s_work_ttcm_3_122","chapterId":"ch_work_ttcm_3","text":"所謂氣也者，非待其鬱蒸凝聚，接於目而後知之；","sortOrder":122},
  {"id":"s_work_ttcm_3_123","chapterId":"ch_work_ttcm_3","text":"陽為陰累則鬱蒸，陰為陽迫則凝聚，此氣之將成乎形者。養生家用此氣，非太和絪缊、有體性、無成形之氣也。","sortOrder":123},
  {"id":"s_work_ttcm_3_124","chapterId":"ch_work_ttcm_3","text":"苟健順、動止、浩然、湛然之得言，皆可名之象爾。","sortOrder":124},
  {"id":"s_work_ttcm_3_125","chapterId":"ch_work_ttcm_3","text":"健而動，其發浩然，陽之體性也；順而止，其情湛然，陰之體性也。清虛之中自有此分致之條理，此仁義禮知之神也，皆可名之為氣而著其象。蓋氣之未分而能变合者即神，自其合一不测而謂之神爾，非氣之外有神也。","sortOrder":125},
  {"id":"s_work_ttcm_3_126","chapterId":"ch_work_ttcm_3","text":"然則象若非氣，指何為象？","sortOrder":126},
  {"id":"s_work_ttcm_3_127","chapterId":"ch_work_ttcm_3","text":"健順、動止、浩、湛之象，為《乾》《坤》六子者皆氣也，氣有此象也。","sortOrder":127},
  {"id":"s_work_ttcm_3_128","chapterId":"ch_work_ttcm_3","text":"時若非象，指何為時？","sortOrder":128},
  {"id":"s_work_ttcm_3_129","chapterId":"ch_work_ttcm_3","text":"隨時而起化者，必以健順、動止、浩、湛之幾為與陰陽、翕辟、生殺之候相應以起用，不然，又將何以應乎時哉？","sortOrder":129},
  {"id":"s_work_ttcm_3_130","chapterId":"ch_work_ttcm_3","text":"世人取釋氏銷礙入空，學者舍惡趨善以為化，此直可為始學遺累者薄乎雲爾，豈天道神化所同語也哉！","sortOrder":130},
  {"id":"s_work_ttcm_3_131","chapterId":"ch_work_ttcm_3","text":"釋氏以真空為如來藏，謂太虛之中本無一物，而氣從幻起以成諸惡，為障礙真如之根本，故斥七識乾健之性、六識坤順之性為流轉染污之害源。此在下愚，挟其鬱蒸凝聚之濁氣以陷溺於惡者，聞其滅盡之說，則或可稍懲其狂悖；而仁義無质，忠信無本，於天以太和一氣含神起化之顯道，固非其所及知也。昧其所以生，則不知其所以死，妄欲銷陨世界以為大涅盤，彼亦乌能銷陨之哉，徒有妄想以惑世誣民而已。敔按：釋氏謂第七識為“末那識”，華雲“我識”，第六識為“紇哩耶識”，華雲“意識”。此言乾健之性、坤順之性者，為仁由己，乾道也；主敬行恕，要在誠意慎獨，坤道也","sortOrder":131},
  {"id":"s_work_ttcm_3_132","chapterId":"ch_work_ttcm_3","text":"“变則化”，由粗入精也；","sortOrder":132},
  {"id":"s_work_ttcm_3_133","chapterId":"ch_work_ttcm_3","text":"变者，自我变之，有跡為粗；化者，推行有漸而物自化，不可知為精，此一義也。","sortOrder":133},
  {"id":"s_work_ttcm_3_134","chapterId":"ch_work_ttcm_3","text":"“化而裁之謂之变”，以著顯微也。","sortOrder":134},
  {"id":"s_work_ttcm_3_135","chapterId":"ch_work_ttcm_3","text":"“謂之”，當作“存乎”。化之所自裁，存乎变易不测，不失其常之神。化見於物，著也，裁之者存乎己，微也，此又一義也。中庸变先於化，《易·傳》化先於变，取義不同；凡言陰陽動靜，不可執一義以該之，類如此。中庸之言变，知義之事，化則神之效也。《易·傳》之言化，德盛之事，变則神之用也。变者，化之體；化之體，神也。精微之蘊，神而已矣。","sortOrder":135},
  {"id":"s_work_ttcm_3_136","chapterId":"ch_work_ttcm_3","text":"穀神不死，故能微顯而不掩。","sortOrder":136},
  {"id":"s_work_ttcm_3_137","chapterId":"ch_work_ttcm_3","text":"“穀”，當作“鬼”，傳寫之訛也。神陽，鬼陰，而神非無陰，鬼非無陽，祭禮有求陰求陽之義，明鬼之有陽矣。二氣合而體物，一屈一伸，神鬼分焉；而同此氣則同此理，神非無自而彰，鬼非無所往而滅，故君子言往來，異於釋氏之言生滅。屈伸一指也，死生一物也，無間斷之死滅，則常流動於化中；而察乎人心，微者必顯，孰能掩之邪！","sortOrder":137},
  {"id":"s_work_ttcm_3_138","chapterId":"ch_work_ttcm_3","text":"鬼神常不死，故誠不可掩；人有是心，在隱微必乘間而見。","sortOrder":138},
  {"id":"s_work_ttcm_3_139","chapterId":"ch_work_ttcm_3","text":"鬼神無形聲而必昭著於物，則苟有其實，有不待形而見，不待聲而聞。一念之善惡動於不及覺之地，若或使之發露，蓋氣機之流行，有則必著之也。","sortOrder":139},
  {"id":"s_work_ttcm_3_140","chapterId":"ch_work_ttcm_3","text":"故君子雖處幽獨，防亦不懈。","sortOrder":140},
  {"id":"s_work_ttcm_3_141","chapterId":"ch_work_ttcm_3","text":"非畏其著見，畏其實有之而不能遏也。一念之邪不審，雖或製之不發，而神氣既為之累，見於事為，不覺而成乎非僻，不自测其所從來而不可遏抑。蓋神氣者，始終相貫，無遽生遽滅之理势，念之於數十年之前，而形之也忽成於一旦，故防之也不可不早，不得謂此念忘而後遂無忧，如釋氏心忘罪滅之說也。敔按：此所謂“天奪其魄”也。天者神也，魄者形也，神氣既累，必動乎四體而莫掩其形","sortOrder":141},
  {"id":"s_work_ttcm_3_142","chapterId":"ch_work_ttcm_3","text":"神化者，天之良能，非人能，","sortOrder":142},
  {"id":"s_work_ttcm_3_143","chapterId":"ch_work_ttcm_3","text":"見聞之所推测，名法之所循行，人能也。","sortOrder":143},
  {"id":"s_work_ttcm_3_144","chapterId":"ch_work_ttcm_3","text":"故大而位天德，然後能窮神知化。","sortOrder":144},
  {"id":"s_work_ttcm_3_145","chapterId":"ch_work_ttcm_3","text":"位，猶至也。盡心以盡性，性盡而與時偕行，合陰陽之化，乃位天德，實體之則實知之矣。","sortOrder":145},
  {"id":"s_work_ttcm_3_146","chapterId":"ch_work_ttcm_3","text":"大可為也，大而化不可為也，","sortOrder":146},
  {"id":"s_work_ttcm_3_147","chapterId":"ch_work_ttcm_3","text":"扩充其善以備乎理之用，則大矣，與時偕行而物無不順，非恃其大而可至也。","sortOrder":147},
  {"id":"s_work_ttcm_3_148","chapterId":"ch_work_ttcm_3","text":"在熟而已。","sortOrder":148},
  {"id":"s_work_ttcm_3_149","chapterId":"ch_work_ttcm_3","text":"一其心於道而漸積以自然，則資深居安而順乎時，故學莫妙於熟，人之所以皆可為尧舜也。","sortOrder":149},
  {"id":"s_work_ttcm_3_150","chapterId":"ch_work_ttcm_3","text":"《易》謂“窮神知化”，乃德盛仁熟之致，非智力能強也。","sortOrder":150},
  {"id":"s_work_ttcm_3_151","chapterId":"ch_work_ttcm_3","text":"張子之言，神化極矣，至此引而歸之於仁之熟，乃示學者易簡之功，學聖之奧也。擇善固執，熟之始功，終食不违則熟矣。","sortOrder":151},
  {"id":"s_work_ttcm_3_152","chapterId":"ch_work_ttcm_3","text":"“大而化之”，能不勉而大也；","sortOrder":152},
  {"id":"s_work_ttcm_3_153","chapterId":"ch_work_ttcm_3","text":"熟則不勉。","sortOrder":153},
  {"id":"s_work_ttcm_3_154","chapterId":"ch_work_ttcm_3","text":"不已而天，則不测而神矣。","sortOrder":154},
  {"id":"s_work_ttcm_3_155","chapterId":"ch_work_ttcm_3","text":"天之神化惟不已，故萬变而不易其常。伯夷、伊尹不勉而大，而止於其道，有所止則不能極其变；唯若孔子與時偕行而神應無方，道在則誠，道变則化，化而一合於誠，不能以所止测之。","sortOrder":155},
  {"id":"s_work_ttcm_3_156","chapterId":"ch_work_ttcm_3","text":"先後天而不违，順至理以推行，知無不合也。","sortOrder":156},
  {"id":"s_work_ttcm_3_157","chapterId":"ch_work_ttcm_3","text":"心之所存，推而行之，無不合於理，則天不能违矣。理者，天之所必然者也。","sortOrder":157},
  {"id":"s_work_ttcm_3_158","chapterId":"ch_work_ttcm_3","text":"雖然，得聖人之任者，皆可勉而至，猶不害於未化爾。大幾聖矣，","sortOrder":158},
  {"id":"s_work_ttcm_3_159","chapterId":"ch_work_ttcm_3","text":"伊尹自耕莘以來，集義而純乎道，故以覺民為志，伐夏而天下服，放君而太甲悔過，雖所為有跡，矯時以立德，未幾於化，而天理順則亦幾於聖矣。","sortOrder":159},
  {"id":"s_work_ttcm_3_160","chapterId":"ch_work_ttcm_3","text":"化則位乎天德矣。","sortOrder":160},
  {"id":"s_work_ttcm_3_161","chapterId":"ch_work_ttcm_3","text":"仁熟而神無不存，則與時偕行，萬物自正其性命；故鳳鳥不至，河不出圖，而孔子之道自參天地，贊化育，不待取必於天也。","sortOrder":161},
  {"id":"s_work_ttcm_3_162","chapterId":"ch_work_ttcm_3","text":"大則不驕，化則不吝。","sortOrder":162},
  {"id":"s_work_ttcm_3_163","chapterId":"ch_work_ttcm_3","text":"成物皆成己之事，而後驕心永釋；因物順應而己不勞，而後吝心不生：此廣大高明之極也。學者欲至於大，當勿以小有得而驕；欲幾於化，當勿以私有得而吝。若顏子之勿伐善、勿施勞，竭才以思企及，則得矣。","sortOrder":163},
  {"id":"s_work_ttcm_3_164","chapterId":"ch_work_ttcm_3","text":"無我而後大，","sortOrder":164},
  {"id":"s_work_ttcm_3_165","chapterId":"ch_work_ttcm_3","text":"誠者，成身也，非我則何有於道？而雲無我者，我，謂私意私欲也。欲之害理，善人、信人幾於無矣；唯意徇聞見，倚於理而執之，不通天地之变，不盡萬物之理，同我者從之，異我者违之，則意即欲矣。無我者，德全於心，天下之務皆可成，天下之志皆可通，萬物備於我，安土而無不樂，斯乃以為大人。","sortOrder":165},
  {"id":"s_work_ttcm_3_166","chapterId":"ch_work_ttcm_3","text":"大成性而後聖，","sortOrder":166},
  {"id":"s_work_ttcm_3_167","chapterId":"ch_work_ttcm_3","text":"德盛仁熟，不求備物而萬物備焉，與時偕行，成乎性而無待推扩，斯聖矣。聖者，大之熟也。","sortOrder":167},
  {"id":"s_work_ttcm_3_168","chapterId":"ch_work_ttcm_3","text":"聖位天德不可致知謂神，故神也者，聖而不可知。敔按：致知，猶言指测而知","sortOrder":168},
  {"id":"s_work_ttcm_3_169","chapterId":"ch_work_ttcm_3","text":"聖不可知，則從心所欲，皆合陰陽健順之理氣，其存於中者無仁義之跡，見於外者無治教政刑之勞，非大人以降所可致知，斯其運化之妙與太虛之神一矣。自大人而上，熟之則聖，聖熟而神矣，非果有不可知者為幻異也。“尧、舜之道，孝弟而已矣”，不雜乎人而一於天也。","sortOrder":169},
  {"id":"s_work_ttcm_3_170","chapterId":"ch_work_ttcm_3","text":"見幾則義明，","sortOrder":170},
  {"id":"s_work_ttcm_3_171","chapterId":"ch_work_ttcm_3","text":"事物既至，則不但引我以欲者多端，且可托於義者不一，初心之發，善惡兩端而已，於此分析不苟，則義明而不為非義所冒。","sortOrder":171},
  {"id":"s_work_ttcm_3_172","chapterId":"ch_work_ttcm_3","text":"動而不括則用利，","sortOrder":172},
  {"id":"s_work_ttcm_3_173","chapterId":"ch_work_ttcm_3","text":"括，收也，滯也。放義而行，一如其初心，推之天下，無中止之機，則用無不利矣。","sortOrder":173},
  {"id":"s_work_ttcm_3_174","chapterId":"ch_work_ttcm_3","text":"屈伸順理則身安而德滋。","sortOrder":174},
  {"id":"s_work_ttcm_3_175","chapterId":"ch_work_ttcm_3","text":"滋，漸長而盛也。義明而推行之無所撓止，或屈或伸，無非理矣。時有否泰而身安，恒一於義，而心日廣，德日润矣。此言學聖之始功在於見幾。蓋幾者，形未著，物欲未雜，思慮未分，乃天德之良所發見，唯神能見之，不倚於聞見也。","sortOrder":175},
  {"id":"s_work_ttcm_3_176","chapterId":"ch_work_ttcm_3","text":"“窮神知化”，與天為一，豈有我所能勉哉？乃德盛而自致爾。","sortOrder":176},
  {"id":"s_work_ttcm_3_177","chapterId":"ch_work_ttcm_3","text":"存神以知幾，德滋而熟，所用皆神，化物而不為物化，此作聖希天之實學也。幾者，動之微；微者必著，故聞見之習俗一入於中以成乎私意，則欲利用安身而不可得，况望其德之滋乎！","sortOrder":177},
  {"id":"s_work_ttcm_3_178","chapterId":"ch_work_ttcm_3","text":"“精義入神”，事豫吾內，求利吾外也；","sortOrder":178},
  {"id":"s_work_ttcm_3_179","chapterId":"ch_work_ttcm_3","text":"察事物所以然之理，察之精而盡其变，此在事变未起之先，見幾而决，故行焉而無不利。","sortOrder":179},
  {"id":"s_work_ttcm_3_180","chapterId":"ch_work_ttcm_3","text":"“利用安身”，素利吾外，致養吾內也；","sortOrder":180},
  {"id":"s_work_ttcm_3_181","chapterId":"ch_work_ttcm_3","text":"義已明則推而行之不括，無所撓止。用利身安，則心亦安於理而不亂，故吉凶生死百变而心恒泰。如其行義不果，悔吝生於所不豫，雖欲養其心以靜正，而忧惑相扰，善惡與吉凶交爭於胸中，未有能養者也。","sortOrder":181},
  {"id":"s_work_ttcm_3_182","chapterId":"ch_work_ttcm_3","text":"“窮神知化”，乃養盛自致，非思勉之能強，故崇德而外，君子未或致知也。","sortOrder":182},
  {"id":"s_work_ttcm_3_183","chapterId":"ch_work_ttcm_3","text":"外利內養，身心率循乎義，逮其熟也，物不能遷，形不能累，惟神與理合而與天為一矣。故君子欲窮神而不索之於虛，欲知化而不亿测其变，惟一於精義而已。義精而德崇矣，所由與佛老之強致者異也。蓋作聖之一於豫養，不使其心有須臾之外馳，以為形之所累，物之所遷，而求精於義，則即此以達天德。是聖狂分於歧路，人禽判於幾希，閒邪存誠，與私意私欲不容有毫發之差也。","sortOrder":183},
  {"id":"s_work_ttcm_3_184","chapterId":"ch_work_ttcm_3","text":"神不可致思，存焉可也；","sortOrder":184},
  {"id":"s_work_ttcm_3_185","chapterId":"ch_work_ttcm_3","text":"心思之貞明貞觀，即神之動幾也，存之則神存矣。舍此而索之於虛無不测之中，役其神以從，妄矣。","sortOrder":185},
  {"id":"s_work_ttcm_3_186","chapterId":"ch_work_ttcm_3","text":"化不可助長，順焉可也。","sortOrder":186},
  {"id":"s_work_ttcm_3_187","chapterId":"ch_work_ttcm_3","text":"德未盛而欲变化以趨時，為诡而已矣。順者修身以俟命，正己而物正。","sortOrder":187},
  {"id":"s_work_ttcm_3_188","chapterId":"ch_work_ttcm_3","text":"存虛明，久至德，","sortOrder":188},
  {"id":"s_work_ttcm_3_189","chapterId":"ch_work_ttcm_3","text":"澄心攝氣，莊敬以養之，則意欲不生，虛而自啟其明；以涵泳義理而熟之，不使間斷，心得恒存而久矣。此二者，所以存神也。","sortOrder":189},
  {"id":"s_work_ttcm_3_190","chapterId":"ch_work_ttcm_3","text":"順变化，達時中，","sortOrder":190},
  {"id":"s_work_ttcm_3_191","chapterId":"ch_work_ttcm_3","text":"貞觀立而天地萬物之变不忧不逆；行法以俟命，隨時皆有必中之節，放義以行而不括。此二者，所以順化也。","sortOrder":191},
  {"id":"s_work_ttcm_3_192","chapterId":"ch_work_ttcm_3","text":"仁之至，義之盡也。","sortOrder":192},
  {"id":"s_work_ttcm_3_193","chapterId":"ch_work_ttcm_3","text":"存神順化，則仁無不至，義無不盡。","sortOrder":193},
  {"id":"s_work_ttcm_3_194","chapterId":"ch_work_ttcm_3","text":"知微知彰，不舍而繼其善，然後可以成人性矣。","sortOrder":194},
  {"id":"s_work_ttcm_3_195","chapterId":"ch_work_ttcm_3","text":"知微知彰，虛明而知幾也。不舍而繼其善，久至德而達時中也。成性者，成乎所性之善，性焉安焉之聖也。成乎性而神化在我，豈致思助長者之所可擬哉！言人性者，天之神篤於生而為性，其化則動植之物，故曰“唯人也得其秀而最靈”。","sortOrder":195},
  {"id":"s_work_ttcm_3_196","chapterId":"ch_work_ttcm_3","text":"聖不可知者，乃天德良能；立心求之，則不可得而知之。","sortOrder":196},
  {"id":"s_work_ttcm_3_197","chapterId":"ch_work_ttcm_3","text":"天德良能，太和之氣健順，動止時行而為理之所自出也，熟則自知之。大人以下，立心求之，則不知其從心不逾之矩爾，非有变幻不测，絕乎人而不可测，如致思助長者之詫神異也。","sortOrder":197},
  {"id":"s_work_ttcm_3_198","chapterId":"ch_work_ttcm_3","text":"聖不可知謂神，莊生缪妄，又謂有神人焉。","sortOrder":198},
  {"id":"s_work_ttcm_3_199","chapterId":"ch_work_ttcm_3","text":"聖而不已，合一於神。神者，聖之化也。莊生欲蔑聖功，以清虛無累之至為神人，妄矣。","sortOrder":199},
  {"id":"s_work_ttcm_3_200","chapterId":"ch_work_ttcm_3","text":"惟神為能变化，以其一天下之動也。","sortOrder":200},
  {"id":"s_work_ttcm_3_201","chapterId":"ch_work_ttcm_3","text":"德之獨至者，為清，為任，為和，皆止於量，猶萬物之動者因其质也。天之神，萬化該焉，而統之以太和之升降屈伸；聖人之神，達天下之亹亹，而統之以虛明至德，故動皆协一。子曰“吾道一以貫之”，存神於心之謂也。","sortOrder":201},
  {"id":"s_work_ttcm_3_202","chapterId":"ch_work_ttcm_3","text":"人能知变化之道，其必知神之所為也。","sortOrder":202},
  {"id":"s_work_ttcm_3_203","chapterId":"ch_work_ttcm_3","text":"变化者，因天下之動也。其道則不私於形，不執一於道，不孤其德，神存而順化以协其至常，六龍皆可乘以御天，特在時位移易之間爾，可於此以征神之所為。","sortOrder":203},
  {"id":"s_work_ttcm_3_204","chapterId":"ch_work_ttcm_3","text":"見《易》則神其幾矣。","sortOrder":204},
  {"id":"s_work_ttcm_3_205","chapterId":"ch_work_ttcm_3","text":"《易》有六十四象，三百八十四变，变化極矣，而唯《乾》之六陽、《坤》之六陰错綜往來，摩荡以成其变化爾，此神之所為也，故易簡而行乎天下之险阻。於此而知神之為用，純一不息，隨其屈伸消長皆成乎化。聖不可知，唯以至一貞天下之動，而隨時處中，在運動之間而已。","sortOrder":205},
  {"id":"s_work_ttcm_3_206","chapterId":"ch_work_ttcm_3","text":"知幾其神，由經正以貫之，則寧用終日，斷可識矣。","sortOrder":206},
  {"id":"s_work_ttcm_3_207","chapterId":"ch_work_ttcm_3","text":"經，即所謂義也。事理之宜吾心，有自然之則，大經素正，則一念初起，其為善惡吉凶，判然分為兩途而無可疑，不待終日思索而可識矣。張子之言，神化盡矣，要歸於一；而奉義為大正之經以貫乎事物，則又至嚴而至簡。蓋義之所自立，即健順動止，陰陽必然之則；敔按：此所謂立天地之大義正其義則协乎神之理，凝神专氣以守吾心之義，動存靜養一於此，則存神以順化，皆有實之可守，而知幾合神，化無不順。此《正蒙》要歸之旨，所以與往聖合轍，而非賢知之過也。","sortOrder":207},
  {"id":"s_work_ttcm_3_208","chapterId":"ch_work_ttcm_3","text":"幾者，象見而未形也；","sortOrder":208},
  {"id":"s_work_ttcm_3_209","chapterId":"ch_work_ttcm_3","text":"事無其形，心有其象。","sortOrder":209},
  {"id":"s_work_ttcm_3_210","chapterId":"ch_work_ttcm_3","text":"形則涉乎明，不待神而後知也。","sortOrder":210},
  {"id":"s_work_ttcm_3_211","chapterId":"ch_work_ttcm_3","text":"已形則耳目之聰明可以知其得失，不待神也。然而知之已晚，時過而失其中，物变起而悔吾生矣。","sortOrder":211},
  {"id":"s_work_ttcm_3_212","chapterId":"ch_work_ttcm_3","text":"“吉之先見”雲者，順性命則所先皆吉也。","sortOrder":212},
  {"id":"s_work_ttcm_3_213","chapterId":"ch_work_ttcm_3","text":"精義而存之不息，則所守之大經，固性命各正之理，於此閒邪存誠，一念之動罔非吉矣。故《易》曰：“介於石”，正其經也；“不終日，貞吉”，今一起而即與吉為徒也；順天地之至常，变化而不渝矣。","sortOrder":213},
  {"id":"s_work_ttcm_3_214","chapterId":"ch_work_ttcm_3","text":"知神而後能饗帝饗親，","sortOrder":214},
  {"id":"s_work_ttcm_3_215","chapterId":"ch_work_ttcm_3","text":"不知神而以為無，是不得已而姑向之也，則亡乎愛；以為有，是以山妖木魅饗之也，則亡乎敬。","sortOrder":215},
  {"id":"s_work_ttcm_3_216","chapterId":"ch_work_ttcm_3","text":"見《易》而後能知神。","sortOrder":216},
  {"id":"s_work_ttcm_3_217","chapterId":"ch_work_ttcm_3","text":"《易》卦非错則綜，互相往來。神伸而生，生則饗於鬼；神屈而死，死則返於神；错綜往來不息之道也。","sortOrder":217},
  {"id":"s_work_ttcm_3_218","chapterId":"ch_work_ttcm_3","text":"是故不聞性與天道而能製禮作樂者，末矣。","sortOrder":218},
  {"id":"s_work_ttcm_3_219","chapterId":"ch_work_ttcm_3","text":"天以神為道，性者神之撰，性與天道，神而已也。禮樂所自生，一順乎陰陽不容已之序而导其和，得其精意於進反屈伸之間，而顯著無聲無臭之中，和於形聲，乃以立萬事之節而動人心之豫。不知而作者，玉帛鐘鼓而已。此好言明有禮樂，幽有鬼神，皆自無而肇有；唯窮神者兩得其精意，以鼓舞天下而不倦，故以鬼神興禮樂，以禮樂求鬼神者，從其類也。","sortOrder":219},
  {"id":"s_work_ttcm_3_220","chapterId":"ch_work_ttcm_3","text":"“精義入神”，豫之至也。","sortOrder":220},
  {"id":"s_work_ttcm_3_221","chapterId":"ch_work_ttcm_3","text":"義精則與神同其動止，以神治物，冒天下之道，不待事至而幾先吉，非立一義以待一事，期必之豫也，故中庸以明善為誠身之豫道。","sortOrder":221},
  {"id":"s_work_ttcm_3_222","chapterId":"ch_work_ttcm_3","text":"徇物丧心，人化物而滅天理者乎！存神過化，忘物累而順性命者乎！","sortOrder":222},
  {"id":"s_work_ttcm_3_223","chapterId":"ch_work_ttcm_3","text":"陰陽之糟粕，聚而成形，故內而為耳目口體，外而為聲色臭味，雖皆神之所為，而神不存焉矣，兩相攻取而喜怒生焉。心本神之舍也，馳神外徇，以從小體而趨合於外物，則神去心而心丧其主。知道者凝心之靈以存神，不溢喜，不遷怒，外物之順逆，如其分以應之，乃不留滯以為心累，則物過吾前而吾已化之，性命之理不失而神恒為主。舜之飯糗茹草與為天於無以異，存神之至也。","sortOrder":223},
  {"id":"s_work_ttcm_3_224","chapterId":"ch_work_ttcm_3","text":"敦厚而不化，有體而無用也；","sortOrder":224},
  {"id":"s_work_ttcm_3_225","chapterId":"ch_work_ttcm_3","text":"敦厚，敬持以凝其神也；化，因物治之而不累也。君子之於物，雖不徇之，而當其應之也必順其理，則事已靖，物已安，可以忘之而不為累。若有體而無用，則欲却物而物不我釋，神亦終為之不寧，用非所用而體亦失其體矣。敔按：莊子所謂“其神凝而物不疵厲”者，蓋有體而無用也","sortOrder":225},
  {"id":"s_work_ttcm_3_226","chapterId":"ch_work_ttcm_3","text":"化而自失焉，徇物而丧已也。","sortOrder":226},
  {"id":"s_work_ttcm_3_227","chapterId":"ch_work_ttcm_3","text":"必欲事之靖，物之安，則事求可，功求成，馳情外徇，而己以丧矣。敔按：此言管、晏之學","sortOrder":227},
  {"id":"s_work_ttcm_3_228","chapterId":"ch_work_ttcm_3","text":"大德敦化，然後仁智一而聖人之事備。","sortOrder":228},
  {"id":"s_work_ttcm_3_229","chapterId":"ch_work_ttcm_3","text":"大德，天德也。敦，誠以存神而隨時以應；化，則大而化之矣。敦者仁之體，化者智之用。","sortOrder":229},
  {"id":"s_work_ttcm_3_230","chapterId":"ch_work_ttcm_3","text":"性性為能存神，物物為能過化。","sortOrder":230},
  {"id":"s_work_ttcm_3_231","chapterId":"ch_work_ttcm_3","text":"性性，於所性之理安焉而成乎性，不為習遷也。物物，因物之至，順其理以應之也。性性，則全體天德而神自存；物物，則應物各得其理，雖有违順，而無留滯自累以與物競，感通自順而無不化矣；此聖人之天德也。學聖者見幾精義以不违於仁，動而不括以利用其智，立體以致用，庶幾別於異端之虛寂、流俗之功名矣。","sortOrder":231},
  {"id":"s_work_ttcm_3_232","chapterId":"ch_work_ttcm_3","text":"無我然後得正己之盡，存神然後妙應物之感。","sortOrder":232},
  {"id":"s_work_ttcm_3_233","chapterId":"ch_work_ttcm_3","text":"此言存神過化相為體用也。徇物丧己者，拘耳目以取聲色，唯我私之自累，役於形而不以神用，則物有所不通，而應之失其理。故惟無我，則因物治物，過者化，而己以無所累而恒正；存神，則貫通萬理而曲盡其過化之用。過化之用即用存神之體，而存神者即所以善過化之用，非存神，未有能過化者也。","sortOrder":233},
  {"id":"s_work_ttcm_3_234","chapterId":"ch_work_ttcm_3","text":"“范围天地之化而不過”，過則溺於空，淪於靜，既不能存夫神，又不能知夫化矣。","sortOrder":234},
  {"id":"s_work_ttcm_3_235","chapterId":"ch_work_ttcm_3","text":"范围天地者，神也，必存之以盡其誠，而不可舍二氣健順之實，以却物而遁於物理之外。釋言“真空”，老言“守靜”，皆以神化為無有而思超越之。非神則化何從生，非化則神何所存，非精義以人神，則存非存，知非知，丧己而不能感物，此二氏之愚也。","sortOrder":235},
  {"id":"s_work_ttcm_3_236","chapterId":"ch_work_ttcm_3","text":"“旁行不流”，圓神不倚也。","sortOrder":236},
  {"id":"s_work_ttcm_3_237","chapterId":"ch_work_ttcm_3","text":"圓者，天之道也。屈伸順感而各得，神之圓也。不倚於形器，則不徇物而流。","sortOrder":237},
  {"id":"s_work_ttcm_3_238","chapterId":"ch_work_ttcm_3","text":"“百姓日用而不知”，溺於流也。","sortOrder":238},
  {"id":"s_work_ttcm_3_239","chapterId":"ch_work_ttcm_3","text":"作息飲食，何莫非神之所為，氣動而理即在其中。百姓日所用者皆神，而徇物以忘其理，故如水之流而不止，违於神而趨於鬼，終屈而莫能伸也。","sortOrder":239},
  {"id":"s_work_ttcm_3_240","chapterId":"ch_work_ttcm_3","text":"義以反經為本，經正則精；","sortOrder":240},
  {"id":"s_work_ttcm_3_241","chapterId":"ch_work_ttcm_3","text":"經者，人物事理之大本；反者，反而求乎心之安也。止此倫物，而差之毫厘則失其正，無不正則無不精，非隨事察察之為精也。","sortOrder":241},
  {"id":"s_work_ttcm_3_242","chapterId":"ch_work_ttcm_3","text":"仁以敦化為深，化行則顯。","sortOrder":242},
  {"id":"s_work_ttcm_3_243","chapterId":"ch_work_ttcm_3","text":"敦厚以體萬物之化，乃盡物性而合天行，而仁之用顯，顯者，顯其所敦也，故《易》曰“顯諸仁”。","sortOrder":243},
  {"id":"s_work_ttcm_3_244","chapterId":"ch_work_ttcm_3","text":"義入神，動一靜也；仁敦化，靜一動也。","sortOrder":244},
  {"id":"s_work_ttcm_3_245","chapterId":"ch_work_ttcm_3","text":"存諸中者為靜，見諸行者為動。義精而入神，則所動而施行者皆中存之天德，非因事求義而专於動也；仁敦化，則寂然不動之中，萬化之理密運於心而無一念之息，非虛寂為仁而专於靜也。敦化者豈豫設一变化以紛吾思哉？存大體以精其義而敦之不息爾。動靜合一於仁而義為之幹，以此，張子之學以義為本。","sortOrder":245},
  {"id":"s_work_ttcm_3_246","chapterId":"ch_work_ttcm_3","text":"仁敦化則無體，義入神則無方。","sortOrder":246},
  {"id":"s_work_ttcm_3_247","chapterId":"ch_work_ttcm_3","text":"《易》曰：“神無方而易無體。”仁函萬物以敦其全體，則隨所顯而皆仁，六位時成，《易》之所以冒天下之道者此也。義之精者，體陰陽、屈伸、高下之秩序而盡其神用，義非外袭而圓行以不流，神之所以藏諸用者此也。無體，無孤立之體，異於老、釋之靜；無方，無滯於一隅之方，異於名、法之動。無體者，所以妙合無方之神，精義之德至矣哉！","sortOrder":247},
  {"id":"s_work_ttcm_4_1","chapterId":"ch_work_ttcm_4","text":"張子正蒙註卷三","sortOrder":1},
  {"id":"s_work_ttcm_4_2","chapterId":"ch_work_ttcm_4","text":"動物篇","sortOrder":2},
  {"id":"s_work_ttcm_4_3","chapterId":"ch_work_ttcm_4","text":"此篇論人物生化之理，神氣往來應感之幾，以明天人相繼之妙，形器相資之用，蓋所以發知化之旨，而存神亦寓其間，其言皆體验而得之，非邵子執象數以觀物之可比也。","sortOrder":3},
  {"id":"s_work_ttcm_4_4","chapterId":"ch_work_ttcm_4","text":"動物本諸天，以呼吸為聚散之漸；","sortOrder":4},
  {"id":"s_work_ttcm_4_5","chapterId":"ch_work_ttcm_4","text":"動物皆出地上，而受五行未成形之氣以生。氣之往來在呼吸，自稚至壮，呼吸盛而日聚，自壮至老，呼吸衰而日散。形以神而成，故各含其性。","sortOrder":5},
  {"id":"s_work_ttcm_4_6","chapterId":"ch_work_ttcm_4","text":"植物本諸地，以陰陽升降為聚散之漸。","sortOrder":6},
  {"id":"s_work_ttcm_4_7","chapterId":"ch_work_ttcm_4","text":"植物根於地，而受五行已成形之氣以長。陽降而陰升，則聚而榮；陽升而陰降，則散而槁。以形而受氣，故但自质而無性。","sortOrder":7},
  {"id":"s_work_ttcm_4_8","chapterId":"ch_work_ttcm_4","text":"物之初生，氣日至而滋息；物生既盈，氣日反而遊散。","sortOrder":8},
  {"id":"s_work_ttcm_4_9","chapterId":"ch_work_ttcm_4","text":"有形則有量，盈其量，則氣至而不能受，以漸而散矣。方來之神，無頓受於初生之理；非畏、厭、溺，非疫厲，非獵殺、斬艾，則亦無頓滅之理，日生者神，而性亦日生；反歸者鬼，而未死之前為鬼者亦多矣。所行之清濁善惡，與氣俱而遊散於兩間，為祥為善，為眚為孽，皆人物之氣所結，不待死而為鬼以滅盡無餘也。敔按：此論顯然有征，人特未之體貼耳","sortOrder":9},
  {"id":"s_work_ttcm_4_10","chapterId":"ch_work_ttcm_4","text":"至之謂神，以其伸也；反之為鬼，以其歸也。","sortOrder":10},
  {"id":"s_work_ttcm_4_11","chapterId":"ch_work_ttcm_4","text":"用則伸，不用則不伸，鬼而歸之，仍乎神矣。死生同條，而善吾生者即善吾死。伸者天之化，歸者人之能，君子盡人以合天，所以為功於神也。敔按：全而歸之者，必全而後可謂之歸也，故曰歸者人之能","sortOrder":11},
  {"id":"s_work_ttcm_4_12","chapterId":"ch_work_ttcm_4","text":"氣於人，生而不離，死而遊散者謂魂；聚成形质，雖死而不散者謂魄。","sortOrder":12},
  {"id":"s_work_ttcm_4_13","chapterId":"ch_work_ttcm_4","text":"可以受聰明覺了之靈者，魄也；其不可受者，形也。嗜欲之性，皆魄之所攻取也。但魄離之則不能發其用爾。魄雖不遽散，而久亦歸於土，其餘氣上蒸，亦返於虛，莫非氣之聚。則亦無不歸於氣也。敔按：本文所謂不散者，非終不散也","sortOrder":13},
  {"id":"s_work_ttcm_4_14","chapterId":"ch_work_ttcm_4","text":"海水凝則冰，浮則漚；然冰之才，漚之性，其存其亡，海不得而與焉。推是足以究死生之說。","sortOrder":14},
  {"id":"s_work_ttcm_4_15","chapterId":"ch_work_ttcm_4","text":"冰有质，故言才；漚含虛，敵言性。不得而與，謂因乎氣之凝浮，海不能有心為之也。凝聚而生，才性成焉；散而亡，則才性仍反於水之神。此以喻死生同於太虛之中，君子俟命而不以死為忧，盡其才，養其性，以不失其常爾。伊川程子改“與”為“有’，義未詳。","sortOrder":15},
  {"id":"s_work_ttcm_4_16","chapterId":"ch_work_ttcm_4","text":"有息者根於天，","sortOrder":16},
  {"id":"s_work_ttcm_4_17","chapterId":"ch_work_ttcm_4","text":"息，呼吸也，動物受天氣之動幾。","sortOrder":17},
  {"id":"s_work_ttcm_4_18","chapterId":"ch_work_ttcm_4","text":"不息者根於地。","sortOrder":18},
  {"id":"s_work_ttcm_4_19","chapterId":"ch_work_ttcm_4","text":"植物受地氣之靜化。","sortOrder":19},
  {"id":"s_work_ttcm_4_20","chapterId":"ch_work_ttcm_4","text":"根於天者不滯於用，","sortOrder":20},
  {"id":"s_work_ttcm_4_21","chapterId":"ch_work_ttcm_4","text":"视聽持行可以多所為。天氣載神，故靈。","sortOrder":21},
  {"id":"s_work_ttcm_4_22","chapterId":"ch_work_ttcm_4","text":"根於地者滯於方，","sortOrder":22},
  {"id":"s_work_ttcm_4_23","chapterId":"ch_work_ttcm_4","text":"離土則槁矣。地氣化形，故顽。","sortOrder":23},
  {"id":"s_work_ttcm_4_24","chapterId":"ch_work_ttcm_4","text":"此動植之分也。","sortOrder":24},
  {"id":"s_work_ttcm_4_25","chapterId":"ch_work_ttcm_4","text":"人者動物，得天之最秀者也，其體愈靈，其用愈廣。","sortOrder":25},
  {"id":"s_work_ttcm_4_26","chapterId":"ch_work_ttcm_4","text":"生有先後，所以為天序；小大高下相併而相形焉，是謂天秩。","sortOrder":26},
  {"id":"s_work_ttcm_4_27","chapterId":"ch_work_ttcm_4","text":"少長有等，老稚殊用，別於生之先後也。高下，以位言；小大，以才量言；相形而自著者也。秩序，物皆有之而不能喻；人之良知良能，自知長長、尊尊、賢賢，因天而無所逆。","sortOrder":27},
  {"id":"s_work_ttcm_4_28","chapterId":"ch_work_ttcm_4","text":"天之生物也有序，","sortOrder":28},
  {"id":"s_work_ttcm_4_29","chapterId":"ch_work_ttcm_4","text":"其序之也亦無先設之定理，而序之在天者即為理。","sortOrder":29},
  {"id":"s_work_ttcm_4_30","chapterId":"ch_work_ttcm_4","text":"物之既形也有秩。","sortOrder":30},
  {"id":"s_work_ttcm_4_31","chapterId":"ch_work_ttcm_4","text":"小大高下分矣，欲逾越而不能。","sortOrder":31},
  {"id":"s_work_ttcm_4_32","chapterId":"ch_work_ttcm_4","text":"知序然後經正，","sortOrder":32},
  {"id":"s_work_ttcm_4_33","chapterId":"ch_work_ttcm_4","text":"經即義也。敬長為義之實，推而行之，義不可勝用矣。","sortOrder":33},
  {"id":"s_work_ttcm_4_34","chapterId":"ch_work_ttcm_4","text":"知秩然後禮行。","sortOrder":34},
  {"id":"s_work_ttcm_4_35","chapterId":"ch_work_ttcm_4","text":"尊尊、賢賢之等殺，皆天理自然，達之而禮無不中矣。秩序人所必由，而推之使通，辨之使精，則存乎學問，故博文約禮為希天之始教。","sortOrder":35},
  {"id":"s_work_ttcm_4_36","chapterId":"ch_work_ttcm_4","text":"凡物能相感者，鬼神施受之性也；","sortOrder":36},
  {"id":"s_work_ttcm_4_37","chapterId":"ch_work_ttcm_4","text":"魄麗於形，鬼之屬；魂營於氣，神之屬，此鬼神之在物者也。魄主受，魂主施，鬼神之性情也。物各為一物，而神氣之往來於虛者，原通一於絪缊之氣，故施者不吝施，受者樂得其受，所以同聲相應，同氣相求，琥珀抬芥，磁石引鐵，不知其所以然而感。聖人感人心而天下和平，亦惟其固有可感之性也。","sortOrder":37},
  {"id":"s_work_ttcm_4_38","chapterId":"ch_work_ttcm_4","text":"不能感者，鬼神亦體之而化矣。","sortOrder":38},
  {"id":"s_work_ttcm_4_39","chapterId":"ch_work_ttcm_4","text":"成形成质有殊異而不相逾者，亦形氣偶然之偏戾爾。及其誠之已盡，亦無不同歸之理。蓋其始也皆一氣之伸，其終也屈而歸於虛，不相悖害，此鬼神合萬匯之往來於一致也。存神者與鬼神合其德，則舞幹而苗格，因壘而崇降，不已於誠，物無不體矣。如其驕吝未化，以善惡、聖顽相治而相亢，誠息而神不存，則可感者且相疑貳，而况不能相感者乎！","sortOrder":39},
  {"id":"s_work_ttcm_4_40","chapterId":"ch_work_ttcm_4","text":"物無孤立之理，非同異、屈伸、終始以發明之，則雖物非物也。","sortOrder":40},
  {"id":"s_work_ttcm_4_41","chapterId":"ch_work_ttcm_4","text":"凡物，非相類則相反。《易》之為象，《乾》《坤》《坎》《離》《颐》《大過》《中孚》《小過》之相错，餘卦二十八象之相綜，物象備矣。错者，同異也；綜者，屈伸也。萬物之成，以错綜而成用。或同者，如金鑠而肖水，術灰而肖土之類；或異者，如水之寒、火之熱、鳥之飛、魚之潛之類。或屈而鬼，或伸而神，或屈而小，或伸而大，或始同而終異，或始異而終同，比類相觀，乃知此物所以成彼物之利。金得火而成器，木受鑽而生火，惟於天下之物知之明，而合之、離之，消之、長之，乃成吾用。不然，物各自物，而非我所得用，非物矣。","sortOrder":41},
  {"id":"s_work_ttcm_4_42","chapterId":"ch_work_ttcm_4","text":"事有始卒乃成，非同異有無相感，則不見其成；不見其成，則雖物非物。","sortOrder":42},
  {"id":"s_work_ttcm_4_43","chapterId":"ch_work_ttcm_4","text":"事之所由成，非直行速獲而可以永終。始於勞者終於逸，始於難者終於易，始於博者終於約，歷险阻而後易簡之德業興焉。故非異則不能同，而百慮歸於一致；非同則不能異，而一理散為萬事。能有者乃能無，積之厚而後散之廣；能無者乃能有，不讳屈而後可允伸。故曰“尺蠖之屈以求伸，龍蛇之蟄以全身”。若不互相資以相濟，事雖幸成，且不知其何以成，而居之不安，未能自得，物非其物矣。","sortOrder":43},
  {"id":"s_work_ttcm_4_44","chapterId":"ch_work_ttcm_4","text":"故曰“屈伸相感而利生焉”。","sortOrder":44},
  {"id":"s_work_ttcm_4_45","chapterId":"ch_work_ttcm_4","text":"凡天下之物，一皆陰陽往來之神所变化。物物有陰陽，事亦如之。其小大、吉凶、善惡之形，知其所屈，而屈此者可以伸彼，知其所伸，而伸者必有其屈；以同相辅，以異相治，以製器而利天下之用，以應事而利攸往之用，以俟命而利修身之用，存乎神之感而已。神者，不滯於物而善用物者也。","sortOrder":45},
  {"id":"s_work_ttcm_4_46","chapterId":"ch_work_ttcm_4","text":"獨見獨聞，雖小異，怪也。出於疾與妄也；共見共聞，雖大異，誠也，出陰陽之正也。","sortOrder":46},
  {"id":"s_work_ttcm_4_47","chapterId":"ch_work_ttcm_4","text":"目眚則空中生華，風眩則蝉鳴於耳，雖事所可有，而以無為有，非其實也。妄人之說，不仰觀俯察，鑒古知今，而唯挟偶然意見所弋獲，而據為道教與之同也。疾風迅雷，非常之甚矣。而共見共聞，陰陽之正，運於太虛，人不能察爾，放君伐暴，成非常之事；製禮作樂，極非常之觀，皆體陰陽必然之撰，晓然與天下後世正告之而無思不服。","sortOrder":47},
  {"id":"s_work_ttcm_4_48","chapterId":"ch_work_ttcm_4","text":"賢才出，國將昌；子孫才，族將大。","sortOrder":48},
  {"id":"s_work_ttcm_4_49","chapterId":"ch_work_ttcm_4","text":"神氣先應之也。於此可征鬼神之不掩。","sortOrder":49},
  {"id":"s_work_ttcm_4_50","chapterId":"ch_work_ttcm_4","text":"人之有息，蓋刚柔相摩、乾坤阖辟之象也。","sortOrder":50},
  {"id":"s_work_ttcm_4_51","chapterId":"ch_work_ttcm_4","text":"一屈一伸，交相為感，人以之生，天地以之生人物而不息，此陰陽之動幾也。動而成乎一動一靜，然必先有乾坤刚柔之體，而後阖辟相摩，猶有氣而後有呼吸。","sortOrder":51},
  {"id":"s_work_ttcm_4_52","chapterId":"ch_work_ttcm_4","text":"寤，形开而志交諸外也；夢，形閉而氣专乎內也。","sortOrder":52},
  {"id":"s_work_ttcm_4_53","chapterId":"ch_work_ttcm_4","text":"开者，伸也，閉者，屈也。志交諸外而氣舒，氣专於內而志隱，則神亦藏而不靈。神隨志而動止者也。","sortOrder":53},
  {"id":"s_work_ttcm_4_54","chapterId":"ch_work_ttcm_4","text":"寤，所以知新於耳目；夢，所以緣舊於習心。","sortOrder":54},
  {"id":"s_work_ttcm_4_55","chapterId":"ch_work_ttcm_4","text":"开則與神化相接，耳自為心效日新之用；閉則守耳目之知而困於形中，習為主而性不能持權。故習心之累，烈矣哉！","sortOrder":55},
  {"id":"s_work_ttcm_4_56","chapterId":"ch_work_ttcm_4","text":"医謂飢夢取，飽夢與，凡寤夢所感，专語氣於五藏之变，容有取蔫爾。","sortOrder":56},
  {"id":"s_work_ttcm_4_57","chapterId":"ch_work_ttcm_4","text":"形閉而神退聽於形，故五臟之形有欣厭，心亦隨之而結為妄，形滯而私故也。形為神用則靈，神為形用則妄。","sortOrder":57},
  {"id":"s_work_ttcm_4_58","chapterId":"ch_work_ttcm_4","text":"聲者，形氣相軋而成。","sortOrder":58},
  {"id":"s_work_ttcm_4_59","chapterId":"ch_work_ttcm_4","text":"觸而相迫曰軋。","sortOrder":59},
  {"id":"s_work_ttcm_4_60","chapterId":"ch_work_ttcm_4","text":"兩氣者，穀响雷聲之類；","sortOrder":60},
  {"id":"s_work_ttcm_4_61","chapterId":"ch_work_ttcm_4","text":"銳往之氣與空中固有之氣相觸而成也。","sortOrder":61},
  {"id":"s_work_ttcm_4_62","chapterId":"ch_work_ttcm_4","text":"兩形者，桴鼓叩击之類。","sortOrder":62},
  {"id":"s_work_ttcm_4_63","chapterId":"ch_work_ttcm_4","text":"兩形相觸也。然運桴而氣亦隨之，迫於鼓而發聲，則亦無非氣也。聲之洪纖者，形之厚薄疏密，其氣亦殊感。","sortOrder":63},
  {"id":"s_work_ttcm_4_64","chapterId":"ch_work_ttcm_4","text":"形軋氣，羽、扇、敲矢之類；","sortOrder":64},
  {"id":"s_work_ttcm_4_65","chapterId":"ch_work_ttcm_4","text":"敲，音雹，鳴鏑也。三者形破氣，氣為之鳴。","sortOrder":65},
  {"id":"s_work_ttcm_4_66","chapterId":"ch_work_ttcm_4","text":"氣軋形，人聲笙簧之類。","sortOrder":66},
  {"id":"s_work_ttcm_4_67","chapterId":"ch_work_ttcm_4","text":"氣出而唇舌、匏竹斂之縱之以激成响，氣發有洪纖，體有通塞之異，而氣之舒疾宣鬱亦異。","sortOrder":67},
  {"id":"s_work_ttcm_4_68","chapterId":"ch_work_ttcm_4","text":"是皆物感之良能，人皆習之而不察者爾。","sortOrder":68},
  {"id":"s_work_ttcm_4_69","chapterId":"ch_work_ttcm_4","text":"不感則寂，感則鳴，本有可鳴之理，待動而應之必速。良能，自然之動幾也。","sortOrder":69},
  {"id":"s_work_ttcm_4_70","chapterId":"ch_work_ttcm_4","text":"形也，聲也，臭也，味也，溫涼也，動靜也，六者莫不有五行之別，同異之变，皆帝則之必察者與！","sortOrder":70},
  {"id":"s_work_ttcm_4_71","chapterId":"ch_work_ttcm_4","text":"溫涼，體之覺；動靜，體之用。五行之神未成乎形者，散寄於聲色臭味氣體之中，人資以生而為人用；精而察之，條理具，秩序分焉，帝載之所以信而通也。知天之化，則於六者皆得其所以然之理而精吾義，然亦得其意而利用，而天理之當然得矣。若一一分析以配合於法象，則多泥而不通。張子約言之而邵子博辨之，察帝則以用物，以本御末也，觀物象以推道，循末以测本也，此格物窮理之異於術數也。","sortOrder":71},
  {"id":"s_work_ttcm_4_72","chapterId":"ch_work_ttcm_4","text":"誠明篇","sortOrder":72},
  {"id":"s_work_ttcm_4_73","chapterId":"ch_work_ttcm_4","text":"前篇統人物而言，原天所降之命也。此篇专就人而發，性之蘊於人所受而切言之也。《中庸》曰“天命之謂性”，為人言而物在其中，則謂統人物而言之可也。又曰“率性之謂道”，則专乎人而不兼乎物矣。物不可謂無性，而不可謂有道，道者人物之辨，所謂人之所以異於禽獸也。故孟子曰“人無有不善”，专乎人而言之，善而後謂之道；泛言性，則犬之性，牛之性，其不相類久矣。盡物之性者，盡物之理而已。虎狼噬人以飼其子，而謂盡父子之道，亦率虎狼之性為得其道而可哉？禽獸，無道者也；草水，無性者也；唯命，則天無心無擇之良能，因材而篤，物得與人而共者也。張子推本神化，統動植於人而謂萬物之一源，切指人性，而謂盡性者不以天能為能，同歸殊途，兩盡其義，乃此篇之要旨。其视程子以率性之道為人物之偕焉者，得失自晓然易見；而抉性之藏，該之以誠明，為良知之實，則近世竊釋氏之沈，以無善無惡為良知者，其妄亦不待辨而自辟。學者欲知性以存養，所宜服膺也。","sortOrder":73},
  {"id":"s_work_ttcm_4_74","chapterId":"ch_work_ttcm_4","text":"誠明所知，乃天德良知，","sortOrder":74},
  {"id":"s_work_ttcm_4_75","chapterId":"ch_work_ttcm_4","text":"仁義，天德也。性中固有之而自知之，無不善之謂良。","sortOrder":75},
  {"id":"s_work_ttcm_4_76","chapterId":"ch_work_ttcm_4","text":"非聞見小知而已。","sortOrder":76},
  {"id":"s_work_ttcm_4_77","chapterId":"ch_work_ttcm_4","text":"行所不逮，身所不體，心所不喻，偶然聞一師之言，見一物之機，遂自以為妙悟，小知之所以賊道。","sortOrder":77},
  {"id":"s_work_ttcm_4_78","chapterId":"ch_work_ttcm_4","text":"天人異用，不足以言誠；","sortOrder":78},
  {"id":"s_work_ttcm_4_79","chapterId":"ch_work_ttcm_4","text":"理，天也；意欲，人也。理不行於意欲之中，意欲有時而逾乎理，天人異用也。","sortOrder":79},
  {"id":"s_work_ttcm_4_80","chapterId":"ch_work_ttcm_4","text":"天人異知，不足以盡明。","sortOrder":80},
  {"id":"s_work_ttcm_4_81","chapterId":"ch_work_ttcm_4","text":"因理而體其所以然，知以天也；事物至而以所聞所見者證之，知以人也。通學識之知於德性之所喻而體用一源，則其明自誠而明也。","sortOrder":81},
  {"id":"s_work_ttcm_4_82","chapterId":"ch_work_ttcm_4","text":"所謂誠明者，性與天道，不見乎小大之別也。","sortOrder":82},
  {"id":"s_work_ttcm_4_83","chapterId":"ch_work_ttcm_4","text":"通事物之理、聞見之知與所性合符，達所性之德與天合德，則物無小大，一性中皆備之理。性雖在人而小，道雖在天而大，以人知天，休天於人，則天在我而無小大之別矣。","sortOrder":83},
  {"id":"s_work_ttcm_4_84","chapterId":"ch_work_ttcm_4","text":"義命合一存乎理，","sortOrder":84},
  {"id":"s_work_ttcm_4_85","chapterId":"ch_work_ttcm_4","text":"義之所在即安之為命，唯貞其常理而已。","sortOrder":85},
  {"id":"s_work_ttcm_4_86","chapterId":"ch_work_ttcm_4","text":"仁智合一存乎聖，","sortOrder":86},
  {"id":"s_work_ttcm_4_87","chapterId":"ch_work_ttcm_4","text":"天德本合，徇其跡者或相妨也。聖人與時偕行，至仁非柔，大智非察，兼體仁智而無仁智之名。如舜好問好察，智也；隱惡扬善，仁也，合於一矣。","sortOrder":87},
  {"id":"s_work_ttcm_4_88","chapterId":"ch_work_ttcm_4","text":"動靜合一存乎神，","sortOrder":88},
  {"id":"s_work_ttcm_4_89","chapterId":"ch_work_ttcm_4","text":"靜動異而神之不息者無間。聖能存神，則動而不離乎靜之存，靜而皆備其動之理，敦誠不息，則化不可测。","sortOrder":89},
  {"id":"s_work_ttcm_4_90","chapterId":"ch_work_ttcm_4","text":"陰陽合一存乎道，","sortOrder":90},
  {"id":"s_work_ttcm_4_91","chapterId":"ch_work_ttcm_4","text":"太和所謂道，陰陽具而無倚也。","sortOrder":91},
  {"id":"s_work_ttcm_4_92","chapterId":"ch_work_ttcm_4","text":"性與天道合一存乎誠。","sortOrder":92},
  {"id":"s_work_ttcm_4_93","chapterId":"ch_work_ttcm_4","text":"誠者，神之實體，氣之實用，在天為道，命於人為性，知其合之謂明，體其合之謂誠。","sortOrder":93},
  {"id":"s_work_ttcm_4_94","chapterId":"ch_work_ttcm_4","text":"天所以長久不已之道，乃所謂誠。","sortOrder":94},
  {"id":"s_work_ttcm_4_95","chapterId":"ch_work_ttcm_4","text":"氣化有序而亘古不息，惟其實有此理也。","sortOrder":95},
  {"id":"s_work_ttcm_4_96","chapterId":"ch_work_ttcm_4","text":"仁人孝子所以事夭成身，不過不已於仁孝而已。","sortOrder":96},
  {"id":"s_work_ttcm_4_97","chapterId":"ch_work_ttcm_4","text":"實知之，實行之，必欲得其心所不忍不安，終身之慕，終食之無违，信之篤也。","sortOrder":97},
  {"id":"s_work_ttcm_4_98","chapterId":"ch_work_ttcm_4","text":"故君子誠之為貴。","sortOrder":98},
  {"id":"s_work_ttcm_4_99","chapterId":"ch_work_ttcm_4","text":"有不誠，則乍勇於為而必息矣；至誠則自不容已，而欲致其誠者，惟在於操存勿使間斷，己百己千，勉強之熟而自無不誠矣。","sortOrder":99},
  {"id":"s_work_ttcm_4_100","chapterId":"ch_work_ttcm_4","text":"此章直指立誠之功，特為深切著明，尤學者之所宜加勉。","sortOrder":100},
  {"id":"s_work_ttcm_4_101","chapterId":"ch_work_ttcm_4","text":"誠有是物，則有終有始；","sortOrder":101},
  {"id":"s_work_ttcm_4_102","chapterId":"ch_work_ttcm_4","text":"天道然也，生之必成之，四時序而百物成。","sortOrder":102},
  {"id":"s_work_ttcm_4_103","chapterId":"ch_work_ttcm_4","text":"伪實不有，何終始之有，故曰“不誠無物”。","sortOrder":103},
  {"id":"s_work_ttcm_4_104","chapterId":"ch_work_ttcm_4","text":"人為之伪，意起而為之，意盡而止，其始無本，其終必忒。物，謂事也；事不成之謂無物。","sortOrder":104},
  {"id":"s_work_ttcm_4_105","chapterId":"ch_work_ttcm_4","text":"“自明誠”，由窮理而盡性也；“自誠明”，由盡性而窮理也。","sortOrder":105},
  {"id":"s_work_ttcm_4_106","chapterId":"ch_work_ttcm_4","text":"存養以盡性，學思以窮理。","sortOrder":106},
  {"id":"s_work_ttcm_4_107","chapterId":"ch_work_ttcm_4","text":"性者，萬物之一源，非有我之得私也。","sortOrder":107},
  {"id":"s_work_ttcm_4_108","chapterId":"ch_work_ttcm_4","text":"性以健順為體，本太虛和同而化之理也，由是而仁義立焉，隨形质而發其靈明之知，則彼此不相知而各為一體，如源之分流矣；恃靈明之知發於耳目者為己私智，以求勝於物，逐流而忘源矣。","sortOrder":108},
  {"id":"s_work_ttcm_4_109","chapterId":"ch_work_ttcm_4","text":"惟大人為能盡其道，是故立必俱立，知必周知，愛必兼愛，成不獨成。","sortOrder":109},
  {"id":"s_work_ttcm_4_110","chapterId":"ch_work_ttcm_4","text":"能安其所處為立，各效其材以有用為成。","sortOrder":110},
  {"id":"s_work_ttcm_4_111","chapterId":"ch_work_ttcm_4","text":"彼自蔽塞而不知順吾理者，則亦末如之何矣？","sortOrder":111},
  {"id":"s_work_ttcm_4_112","chapterId":"ch_work_ttcm_4","text":"己私成，則雖有至教，不能移矣。","sortOrder":112},
  {"id":"s_work_ttcm_4_113","chapterId":"ch_work_ttcm_4","text":"此章統萬物於一源，溯其始而言之，固合人物而言；而曰立，曰成，則专乎人之辭爾。知之必有詳略，愛之必有區別，理一分殊，亦存乎其中矣。親疏貴賤之不同，所謂順理也；雖周知博愛而必順其理，蓋自天命以來，秩序分焉，知其一源，則必知其分流。故窮理盡性，交相為功，異於墨、釋之教，漫滅天理之節文而謂會萬物於一己也。","sortOrder":113},
  {"id":"s_work_ttcm_4_114","chapterId":"ch_work_ttcm_4","text":"天能為性；人謀為能。","sortOrder":114},
  {"id":"s_work_ttcm_4_115","chapterId":"ch_work_ttcm_4","text":"天能者，健順五常之體；人謀者，察識扩充之用也。","sortOrder":115},
  {"id":"s_work_ttcm_4_116","chapterId":"ch_work_ttcm_4","text":"大人盡性，不以天能為能，而以人謀為能，","sortOrder":116},
  {"id":"s_work_ttcm_4_117","chapterId":"ch_work_ttcm_4","text":"大人不失其赤子之心，而非孤守其惻隱、羞惡、恭敬、自然之覺，必扩而充之以盡其致，一如天之陰陽有實，而必於阖辟動止神運以成化，則道弘而性之量盡矣，蓋盡心為盡性之實功也。","sortOrder":117},
  {"id":"s_work_ttcm_4_118","chapterId":"ch_work_ttcm_4","text":"故曰“天地設位，聖人成能”。","sortOrder":118},
  {"id":"s_work_ttcm_4_119","chapterId":"ch_work_ttcm_4","text":"天地有其理，誠也；聖人盡其心，誠之者也。","sortOrder":119},
  {"id":"s_work_ttcm_4_120","chapterId":"ch_work_ttcm_4","text":"盡性，然後知生無所得，","sortOrder":120},
  {"id":"s_work_ttcm_4_121","chapterId":"ch_work_ttcm_4","text":"非己之私得。","sortOrder":121},
  {"id":"s_work_ttcm_4_122","chapterId":"ch_work_ttcm_4","text":"則死無所丧。","sortOrder":122},
  {"id":"s_work_ttcm_4_123","chapterId":"ch_work_ttcm_4","text":"理明義正而道不缺，氣正神清而全歸於天，故君子之生，明道焉爾，行道焉爾，為天效動，死則寧焉。丧者，丧其耳目口體，而神無損也。","sortOrder":123},
  {"id":"s_work_ttcm_4_124","chapterId":"ch_work_ttcm_4","text":"未嘗無之謂體，體之謂性。","sortOrder":124},
  {"id":"s_work_ttcm_4_125","chapterId":"ch_work_ttcm_4","text":"無則不可為體矣。人有立人之體，百姓日用而不知爾，雖無形跡而非無實；使其無也，則生理以何為體而得存邪？仁之於父子，義之於君臣，用也；用者必有體而後可用，以此體為仁義之性。","sortOrder":125},
  {"id":"s_work_ttcm_4_126","chapterId":"ch_work_ttcm_4","text":"天所性者通極於道，","sortOrder":126},
  {"id":"s_work_ttcm_4_127","chapterId":"ch_work_ttcm_4","text":"天所命人而為性者，即以其一陰一陽之道成之。即一非二曰通，此外無雜曰極。人生莫不有性，皆天道也，故仁義禮智與元亨利貞無二道。","sortOrder":127},
  {"id":"s_work_ttcm_4_128","chapterId":"ch_work_ttcm_4","text":"氣之昏明不足以蔽之；","sortOrder":128},
  {"id":"s_work_ttcm_4_129","chapterId":"ch_work_ttcm_4","text":"禀氣有昏明，則知能有偏全，而一曲之誠即天之誠，故“乍見孺子”之仁，“無受爾汝”之義，必發於情，莫能終蔽也。","sortOrder":129},
  {"id":"s_work_ttcm_4_130","chapterId":"ch_work_ttcm_4","text":"天所命者通極於性，","sortOrder":130},
  {"id":"s_work_ttcm_4_131","chapterId":"ch_work_ttcm_4","text":"命以吉凶寿夭言。以人情度之，則有厚於性而薄於命者，而富貴、貧賤、夷狄、患難，皆理之所察。予之以性，即予之以順受之道，命不齊，性無不可盡也。","sortOrder":131},
  {"id":"s_work_ttcm_4_132","chapterId":"ch_work_ttcm_4","text":"遇之吉凶不足以戕之；","sortOrder":132},
  {"id":"s_work_ttcm_4_133","chapterId":"ch_work_ttcm_4","text":"性存而道義出，窮通夭寿，何至戕其生理？","sortOrder":133},
  {"id":"s_work_ttcm_4_134","chapterId":"ch_work_ttcm_4","text":"不免乎蔽之戕之者，未之學也。","sortOrder":134},
  {"id":"s_work_ttcm_4_135","chapterId":"ch_work_ttcm_4","text":"任其质而不通其变，惟學有未至，故其端發見而不充，吉凶雜至而失其素。","sortOrder":135},
  {"id":"s_work_ttcm_4_136","chapterId":"ch_work_ttcm_4","text":"性通乎氣之外，命行乎氣之內。氣無內外，假有形而言爾。","sortOrder":136},
  {"id":"s_work_ttcm_4_137","chapterId":"ch_work_ttcm_4","text":"人各有形，形以內為吾氣之區宇，形以外吾之氣不至焉，故可立內外之名。性命乎神，天地萬物函之於虛靈而皆備，仁可以無不達，義可以無不行，氣域於形，吉凶禍福止乎其身爾。然則命者私也，性者公也，性本無蔽，而命之戕性，惟不知其通極於性也。","sortOrder":137},
  {"id":"s_work_ttcm_4_138","chapterId":"ch_work_ttcm_4","text":"故思知人不可不知天，盡其性然後能至於命。","sortOrder":138},
  {"id":"s_work_ttcm_4_139","chapterId":"ch_work_ttcm_4","text":"知人，知人道也；知天，知天性也。知性之合於天德，乃知人性之善，明者可誠而昏皆可明；性盡，則無所遇而不可盡吾性之道。由是而知命之通極於性，與天之命我，吉凶無心而無非順正者同其化矣。","sortOrder":139},
  {"id":"s_work_ttcm_4_140","chapterId":"ch_work_ttcm_4","text":"知性知天，則陰陽鬼神皆吾分內爾。","sortOrder":140},
  {"id":"s_work_ttcm_4_141","chapterId":"ch_work_ttcm_4","text":"知性者，知天道之成乎性；知天者，即性而知天之神理。知性知天，則性與天道通極於一，健順相資，屈伸相感，陰陽鬼神之性情，皆吾所有事，而為吾職分之所當修者矣。","sortOrder":141},
  {"id":"s_work_ttcm_4_142","chapterId":"ch_work_ttcm_4","text":"天性在人，正猶水性之在冰，凝釋雖異，為物一也；","sortOrder":142},
  {"id":"s_work_ttcm_4_143","chapterId":"ch_work_ttcm_4","text":"未生則此理在太虛為天之體性，已生則此理聚於形中為人之性，死則此理氣仍返於太虛，形有凝釋，氣不損益，理亦不雜，此所謂通極於道也。敔按：朱子謂冰水之喻近釋，以朱、張論聚散之本體不同也。說詳《太和篇》註中","sortOrder":143},
  {"id":"s_work_ttcm_4_144","chapterId":"ch_work_ttcm_4","text":"受光有小大昏明，其照納不二也。","sortOrder":144},
  {"id":"s_work_ttcm_4_145","chapterId":"ch_work_ttcm_4","text":"此亦以水喻性。形之受性，猶水之受光。水以受光為性，人以通理為性，有小大、昏明者，氣禀爾；而曲者可致，濁者可澄，其性本能受也，在學以明善而复初爾。此所謂氣有昏明不足以蔽之。","sortOrder":145},
  {"id":"s_work_ttcm_4_146","chapterId":"ch_work_ttcm_4","text":"天良能本吾良能，顧為有我所丧爾。張子自註：明天人之本無二","sortOrder":146},
  {"id":"s_work_ttcm_4_147","chapterId":"ch_work_ttcm_4","text":"體天之神化，存誠盡性，則可備萬物於我。有我者，以心從小體，而執功利聲色為己得，則迷而丧之爾。孟子言良知良能，而張子重言良能。蓋天地以神化運行為德，非但恃其空晶之體；聖人以盡倫成物為道，抑非但恃其虛靈之悟。故知雖良而能不逮，猶之乎弗知。近世王氏之學，舍能而孤言知，宜其疾入於異端也。","sortOrder":147},
  {"id":"s_work_ttcm_4_148","chapterId":"ch_work_ttcm_4","text":"上達反天理，下達徇人欲者與！","sortOrder":148},
  {"id":"s_work_ttcm_4_149","chapterId":"ch_work_ttcm_4","text":"反天理，則與天同其神化；徇人欲，則其违禽獸不遠矣。","sortOrder":149},
  {"id":"s_work_ttcm_4_150","chapterId":"ch_work_ttcm_4","text":"性其總，合兩也；","sortOrder":150},
  {"id":"s_work_ttcm_4_151","chapterId":"ch_work_ttcm_4","text":"天以其陰陽五行之氣生人，理即寓焉而凝之為性。故有聲色臭味以厚其生，有仁義禮智以正其德，莫非理之所宜。聲色臭味，順其道則與仁義禮智不相悖害，合兩者而互為體也。","sortOrder":151},
  {"id":"s_work_ttcm_4_152","chapterId":"ch_work_ttcm_4","text":"命其受，有則也；","sortOrder":152},
  {"id":"s_work_ttcm_4_153","chapterId":"ch_work_ttcm_4","text":"厚生之用，有盈有诎，吉凶生死因之，此時位之不齊，人各因所遇之氣而受之。百年之內，七尺之形，所受者止此，有則而不能過。","sortOrder":153},
  {"id":"s_work_ttcm_4_154","chapterId":"ch_work_ttcm_4","text":"不極總之要，則不至受之分。","sortOrder":154},
  {"id":"s_work_ttcm_4_155","chapterId":"ch_work_ttcm_4","text":"極總之要者，知聲色臭味之則與仁義禮智之體合一於當然之理。當然而然，則正德非以傷生，而厚生者期於正德。心與理一，而知吾時位之所值，道即在是，旁通寿夭，皆樂天而安土矣。若不能合一於理，而吉凶相感，則怨尤之所以生也。","sortOrder":155},
  {"id":"s_work_ttcm_4_156","chapterId":"ch_work_ttcm_4","text":"盡性窮理而不可变，乃吾則也。","sortOrder":156},
  {"id":"s_work_ttcm_4_157","chapterId":"ch_work_ttcm_4","text":"性無所不可盡，故舜之於父子，文王之於君臣，極乎仁義而無不可盡。唯其於理無不窮，故吉凶生死，道皆行焉，所遇者变而誠不变，吾之則無往而非天則，非若命之有則，唯所受而不能越也。","sortOrder":157},
  {"id":"s_work_ttcm_4_158","chapterId":"ch_work_ttcm_4","text":"天所自不能已者謂命，不能無感者謂性。","sortOrder":158},
  {"id":"s_work_ttcm_4_159","chapterId":"ch_work_ttcm_4","text":"萬類靈顽之不齊，氣運否泰之相乘，天之神化廣大，不能擇其善者而已其不善者；故君子或窮，小人或泰，各因其時而受之。然其所受之中，自有使人各得其正之理，則生理之良能自感於倫物而必動，性貫乎所受不齊之中而皆可盡，此君子之所以有事於性，無事於命也。","sortOrder":159},
  {"id":"s_work_ttcm_4_160","chapterId":"ch_work_ttcm_4","text":"雖然，聖人猶不以所可忧而同其無忧者，有相之道存乎我也。","sortOrder":160},
  {"id":"s_work_ttcm_4_161","chapterId":"ch_work_ttcm_4","text":"君子有事於性，無事於命，而聖人盡性以至於命，則於命不能無事焉。天廣大而無忧，聖人盡人道，不可同其無忧，故顽嚣必格，知其不可而必為。是以受人之天下而不為泰，匹夫行天子之事而不恤罪我，相天之不足，以與萬物合其吉凶，又存乎盡性之極功，而合兩所以协一也。","sortOrder":161},
  {"id":"s_work_ttcm_4_162","chapterId":"ch_work_ttcm_4","text":"湛一，氣之本；","sortOrder":162},
  {"id":"s_work_ttcm_4_163","chapterId":"ch_work_ttcm_4","text":"太虛之氣，無同無異，妙合而為一，人之所受即此氣也。故其為體，湛定而合一，湛則物無可撓，一則無不可受。學者苟能凝然靜存，則湛一之氣象自見，非可以聞見测知也。","sortOrder":163},
  {"id":"s_work_ttcm_4_164","chapterId":"ch_work_ttcm_4","text":"攻取，氣之欲。","sortOrder":164},
  {"id":"s_work_ttcm_4_165","chapterId":"ch_work_ttcm_4","text":"物而交於物，則有同有異而攻取生矣。","sortOrder":165},
  {"id":"s_work_ttcm_4_166","chapterId":"ch_work_ttcm_4","text":"口腹於飲食，鼻舌於臭味，皆攻取之性也。","sortOrder":166},
  {"id":"s_work_ttcm_4_167","chapterId":"ch_work_ttcm_4","text":"氣之與神合者，固湛一也，因形而發，則有攻取，以其皆為生氣自然之有，故皆謂之性。生以食為重，故言飲食臭味以該聲色货利。","sortOrder":167},
  {"id":"s_work_ttcm_4_168","chapterId":"ch_work_ttcm_4","text":"知德者屬厭而已，","sortOrder":168},
  {"id":"s_work_ttcm_4_169","chapterId":"ch_work_ttcm_4","text":"性有之，不容絕也。知德者知吾所得於天之不专系於此，則如其量以安其氣而攻取息。","sortOrder":169},
  {"id":"s_work_ttcm_4_170","chapterId":"ch_work_ttcm_4","text":"不以嗜欲累其心，不以小害大、以末丧本焉爾。","sortOrder":170},
  {"id":"s_work_ttcm_4_171","chapterId":"ch_work_ttcm_4","text":"心者，湛一之氣所含。湛一之氣，統氣體而合於一，故大；耳目口體成形而分有司，故小。是以鼻不知味，口不聞香，非其所取則攻之；而一體之間，性情相隔，愛惡相违，况外物乎。小體，末也；大體，本也。","sortOrder":171},
  {"id":"s_work_ttcm_4_172","chapterId":"ch_work_ttcm_4","text":"心能盡性，“人能弘道”也；性不知檢其心，“非道弘人”也。","sortOrder":172},
  {"id":"s_work_ttcm_4_173","chapterId":"ch_work_ttcm_4","text":"天理之自然，為太和之氣所體物不遺者為性；凝之於人而函於形中，因形發用以起知能者為心。性者天道，心者人道，天道隱而人道顯；顯，故充惻隱之心而仁盡，推羞惡之心而義盡。弘道者，資心以效其能也。性則與天同其無為，不知製其心也；故心放而不存，不可以咎性之不善。","sortOrder":173},
  {"id":"s_work_ttcm_4_174","chapterId":"ch_work_ttcm_4","text":"盡其性，能盡人物之性；至於命者，亦能至人物之命；","sortOrder":174},
  {"id":"s_work_ttcm_4_175","chapterId":"ch_work_ttcm_4","text":"牛之穿而耕，馬之絡而乘，蠶之繅而絲，木之伐而薪，小人之勞力以養君子，效死以報君國，豈其性然哉？其命然爾。至於命，則知命以樂天，取於人物者有節不淫，而殺生皆敦乎仁，立命以相天治。夫人物者，裁成有道，而茂對鹹若其化，人物之命皆自我而順正矣。","sortOrder":175},
  {"id":"s_work_ttcm_4_176","chapterId":"ch_work_ttcm_4","text":"莫不性諸道，命諸天。敔按：性諸道，言人物之性莫非道；命諸天，言人物之命莫非天","sortOrder":176},
  {"id":"s_work_ttcm_4_177","chapterId":"ch_work_ttcm_4","text":"上智下愚，有昏明而無得丧；禽獸於人，有偏全而無违離。知其皆性諸道，故取諸人以為善，聖不弃愚；觀於物以得理，人不弃物。知其皆命諸天，則秩叙審而親疏、上下各得其理，節宣時而生育、肅殺各如其量。聖人所以體物不遺，與鬼神合其吉凶，能至人物之命也。","sortOrder":177},
  {"id":"s_work_ttcm_4_178","chapterId":"ch_work_ttcm_4","text":"我體物未嘗遺，物體我知其不遺也。敔按：物體我，猶言物以我為體","sortOrder":178},
  {"id":"s_work_ttcm_4_179","chapterId":"ch_work_ttcm_4","text":"能體物，則人物皆以我為體，不能離我以為道，必依我之綏以為來，動以為和，九族睦，百姓昭，黎民变，鳥獸草木鹹若，物無有能遺我者。","sortOrder":179},
  {"id":"s_work_ttcm_4_180","chapterId":"ch_work_ttcm_4","text":"至於命，然後能成己成物，不失其道。","sortOrder":180},
  {"id":"s_work_ttcm_4_181","chapterId":"ch_work_ttcm_4","text":"己無不誠，則循物無违而與天同化，以人治人，以物治物，各順其受命之正，雖不能知者皆可使由，萬物之命自我立矣。所以然者，我與人物莫不性諸道，命諸天，無異理也。","sortOrder":181},
  {"id":"s_work_ttcm_4_182","chapterId":"ch_work_ttcm_4","text":"以生為性，既不通晝夜之道，且人與物等，故告子之妄不可不詆。","sortOrder":182},
  {"id":"s_work_ttcm_4_183","chapterId":"ch_work_ttcm_4","text":"知覺運動，生則盛，死則無能焉。性者，天理流行，氣聚則凝於人，氣散則合於太虛，晝夜異而天之運行不息，無所謂生滅也。如告子之說，則性隨彤而生滅，是性因形發，形不自性成矣。曰性善者，专言人也，故曰“人無有不善”；犬牛之性，天道廣大之变化也，人以為性，則無所不為矣。","sortOrder":183},
  {"id":"s_work_ttcm_4_184","chapterId":"ch_work_ttcm_4","text":"性於人無不善，","sortOrder":184},
  {"id":"s_work_ttcm_4_185","chapterId":"ch_work_ttcm_4","text":"乾道变化，各正性命，理氣一源而各有所合於天，無非善也。而就一物言之，則不善者多矣，唯人則全具健順五常之理。善者，人之獨也。","sortOrder":185},
  {"id":"s_work_ttcm_4_186","chapterId":"ch_work_ttcm_4","text":"系其善反不善反而已；","sortOrder":186},
  {"id":"s_work_ttcm_4_187","chapterId":"ch_work_ttcm_4","text":"攻取之氣，逐物而往，恒不知反。善反者，應物之感，不為物引以去，而斂之以體其湛一，則天理著矣。此操存舍亡之幾也。","sortOrder":187},
  {"id":"s_work_ttcm_4_188","chapterId":"ch_work_ttcm_4","text":"過天地之化，不善反者也。","sortOrder":188},
  {"id":"s_work_ttcm_4_189","chapterId":"ch_work_ttcm_4","text":"食色以滋生，天地之化也，如其受命之則而已。恃其攻取之能而求盈，則湛一之本，迷而不复。","sortOrder":189},
  {"id":"s_work_ttcm_4_190","chapterId":"ch_work_ttcm_4","text":"命於人無不正，","sortOrder":190},
  {"id":"s_work_ttcm_4_191","chapterId":"ch_work_ttcm_4","text":"天有生殺之時，有否泰之運，而人以人道受命，則窮通禍福，皆足以成仁取義，無不正也。","sortOrder":191},
  {"id":"s_work_ttcm_4_192","chapterId":"ch_work_ttcm_4","text":"系其順與不順而已；","sortOrder":192},
  {"id":"s_work_ttcm_4_193","chapterId":"ch_work_ttcm_4","text":"盡其道而生死皆順也，是以舜受尧之天下，若固有之；孔子围於匡，厄於陳、蔡而無忧。","sortOrder":193},
  {"id":"s_work_ttcm_4_194","chapterId":"ch_work_ttcm_4","text":"行险以僥幸，不順命者也。","sortOrder":194},
  {"id":"s_work_ttcm_4_195","chapterId":"ch_work_ttcm_4","text":"故必盡性而後可至於命。","sortOrder":195},
  {"id":"s_work_ttcm_4_196","chapterId":"ch_work_ttcm_4","text":"形而後有氣质之性，","sortOrder":196},
  {"id":"s_work_ttcm_4_197","chapterId":"ch_work_ttcm_4","text":"氣质者，氣成质而质還生氣也。氣成质，則氣凝滯而局於形，取資於物以滋其质；质生氣，則同異攻取各從其類。故耳目鼻口之氣與聲色臭味相取，亦自然而不可拂违，此有彤而始然，非太和絪緼之氣、健順之常所固有也。舊說以氣质之性為昏明強柔不齊之品，與程子之說合。今按張子以昏明強柔得氣之偏者，系之才而不系之性，故下章詳言之，而此言氣质之性，蓋孟子所謂口耳目鼻之於聲色臭味者爾。蓋性者，生之理也。均是人也，則此與生俱有之理，未嘗或異；故仁義禮知之理，下愚所不能滅，而聲色臭味之欲，上智所不能废，俱可謂之為性。而或受於形而上，或受於形而下，在天以其至仁滋人之生，成人之善，初無二理。但形而上者為形之所自生，則動以清而事近乎天；形而後有者資形起用，則靜以濁而事近乎地。形而上者，亘生死、通晝夜而常伸，事近乎神；形而後有者，困於形而固將竭，事近乎鬼；則一屈一伸之际，理與欲皆自然而非由人為。故告子謂食色為性，亦不可謂為非性，而特不知有天命之良能爾。若夫才之不齊，則均是人而差等萬殊，非合兩而為天下所大總之性，性則統乎人而無異之謂。","sortOrder":197},
  {"id":"s_work_ttcm_4_198","chapterId":"ch_work_ttcm_4","text":"善反之，則天地之性存焉。","sortOrder":198},
  {"id":"s_work_ttcm_4_199","chapterId":"ch_work_ttcm_4","text":"天地之性，太和絪緼之神，健順合而無倚者也。即此氣质之性，如其受命之則而不過，勿放其心以徇小體之攻取，而仁義之良能自不可掩。蓋仁義禮智之丧於己者，類為聲色臭味之所奪，不則其安佚而惰於成能者也。製之有節，不以從道而奚從乎！天地之性原存而未去，氣质之性亦初不相悖害，屈伸之間，理欲分馳，君子察此而已。","sortOrder":199},
  {"id":"s_work_ttcm_4_200","chapterId":"ch_work_ttcm_4","text":"故氣质之性，君子有弗性者焉。","sortOrder":200},
  {"id":"s_work_ttcm_4_201","chapterId":"ch_work_ttcm_4","text":"弗性，不據為己性而安之也。","sortOrder":201},
  {"id":"s_work_ttcm_4_202","chapterId":"ch_work_ttcm_4","text":"此章與孟子之言相為發明，而深切顯著，乃張子探本窮歸之要旨，與程子之言自別，讀者審之。","sortOrder":202},
  {"id":"s_work_ttcm_4_203","chapterId":"ch_work_ttcm_4","text":"人之刚柔、缓急，有才與不才氣之偏也。","sortOrder":203},
  {"id":"s_work_ttcm_4_204","chapterId":"ch_work_ttcm_4","text":"昏明、強柔、敏钝、靜躁，因氣之刚柔、缓急而分，於是而智愚、賢不肖若自性成，故荀悅、韓愈有三品之說，其實才也，非性也。性者，氣順理而生人，自未有形而有形，成乎其人，則固無惡而一於善，陰陽健順之德本善也。才者，成形於一時升降之氣，則耳目口體不能如一，而聰明幹力因之而有通塞、精粗之別，乃動靜、阖辟偶然之機所成也。性借才以成用，才有不善，遂累其性，而不知者遂咎性之惡，此古今言性者，皆不知才性各有從來，而以才為性爾。商臣之蜂目豺聲，才也，象之傲而見舜則忸怩，性也；舜能養象，楚頵不能養商臣爾。居移氣，養移體，氣體移則才化，若性則不待移者也。才之美者未必可以作聖，才之偏者不迷其性，雖不速合於聖，而固舜之徒矣。程子謂天命之性與氣质之性為二，其所謂氣质之性，才也，非性也。張子以耳目口體之必資物而安者為氣质之性，合於孟子；而別刚柔缓急之殊质者為才，性之為性乃獨立而不為人所亂。蓋命於天之謂性，成於人之謂才；靜而無為之謂性，動而有為之謂才。性不易見而才則著，是以言性者但言其才而性隱。張子辨性之功大矣哉！敔按：動而有為之謂才，才，所謂心之官。心之體為性，心之用為情，心之官為才","sortOrder":204},
  {"id":"s_work_ttcm_4_205","chapterId":"ch_work_ttcm_4","text":"天本參和不偏。養其氣，反之本而不偏，則盡性而天矣。","sortOrder":205},
  {"id":"s_work_ttcm_4_206","chapterId":"ch_work_ttcm_4","text":"天與性一也，天無體，即其資始而成人之性者為體。參和，太極、陰、陽，三而一也。氣本參和，雖因形而發，有偏而不善，而養之以反其本，則即此一曲之才，盡其性而與天合矣。養之，則性現而才為用；不養，則性隱而惟以才為性，性終不能复也。養之之道，沈潛柔友刚克，高明強弗友柔克，教者，所以裁成而矯其偏。若學者之自養，則惟盡其才於仁義中正，以求其熟而扩充之，非待有所矯而後可正。故教能止惡，而誠明不倚於教，人皆可以為尧、舜，人皆可以合於天也。","sortOrder":206},
  {"id":"s_work_ttcm_4_207","chapterId":"ch_work_ttcm_4","text":"性未成則善惡混，故亹亹而繼善者，斯為善矣。","sortOrder":207},
  {"id":"s_work_ttcm_4_208","chapterId":"ch_work_ttcm_4","text":"成，猶定也，謂一以性為體而達其用也。善端見而繼之不息，則終始一於善而性定矣。蓋才雖或偏，而性之善者不能盡掩，有時而自見；惟不能分別善者以歸性，偏者以歸才，則善惡混之說所以疑性之雜而迷其真。繼善者，因性之不容掩者察識而扩充之，才從性而純善之體現矣，何善惡混之有乎？","sortOrder":208},
  {"id":"s_work_ttcm_4_209","chapterId":"ch_work_ttcm_4","text":"惡盡去則善因以亡，故舍曰“善”，而曰“成之者性”。","sortOrder":209},
  {"id":"s_work_ttcm_4_210","chapterId":"ch_work_ttcm_4","text":"惡盡去，謂知性之本無惡，而不以才之偏而未丧者誣其性也。善惡相形而著，無惡以相形，則善之名不立，故《易》言“繼之者善，成之者性。”分言之而不曰性善，反才之偏而恰合於人，以其可欲而謂之善矣。善者，因事而見，非可以盡太和之妙也。抑考孟子言天之降才不殊，而張子以才為有偏，似與孟子異矣。蓋陷溺深，則習氣重而併屈其才，陷溺未深而不知存養則才伸而屈其性。故孟子又言“為不善非才之罪”，則為善亦非才之功可見。是才者性之役，全者不足以為善，偏者不足以為害。故困勉之成功，均於生安。學者當专於盡性，勿恃才之有餘，勿諉才之不足也","sortOrder":210},
  {"id":"s_work_ttcm_4_211","chapterId":"ch_work_ttcm_4","text":"德不勝氣，性命於氣；德勝其氣，性命於德。","sortOrder":211},
  {"id":"s_work_ttcm_4_212","chapterId":"ch_work_ttcm_4","text":"繼善而得其性之所固有曰德。此言氣者，謂偏氣成形，而氣即從偏發用者也。勝氣者，反本而化其偏也。德不至而聽才氣之所為，則任其一偏之為，而或迪或逆，善惡混而吉凶亦無據矣。以善之純養才於不偏，則性焉安焉於德而吉無不利，則皆德之所固有，此至於命而立命也。","sortOrder":212},
  {"id":"s_work_ttcm_4_213","chapterId":"ch_work_ttcm_4","text":"窮理盡性，則性天德，命天理。","sortOrder":213},
  {"id":"s_work_ttcm_4_214","chapterId":"ch_work_ttcm_4","text":"與天同德，則天之化理在我矣。","sortOrder":214},
  {"id":"s_work_ttcm_4_215","chapterId":"ch_work_ttcm_4","text":"氣之不可变者，獨死生修夭而已。","sortOrder":215},
  {"id":"s_work_ttcm_4_216","chapterId":"ch_work_ttcm_4","text":"氣成乎形，體之強弱形，則凝滯而不可变，故跖寿而顏夭。","sortOrder":216},
  {"id":"s_work_ttcm_4_217","chapterId":"ch_work_ttcm_4","text":"故論死生則曰“有命”，以言其氣也；","sortOrder":217},
  {"id":"s_work_ttcm_4_218","chapterId":"ch_work_ttcm_4","text":"形氣之厚薄不可变也。","sortOrder":218},
  {"id":"s_work_ttcm_4_219","chapterId":"ch_work_ttcm_4","text":"語富貴則曰“在天”，以言其理也。","sortOrder":219},
  {"id":"s_work_ttcm_4_220","chapterId":"ch_work_ttcm_4","text":"理御氣而可变者也。","sortOrder":220},
  {"id":"s_work_ttcm_4_221","chapterId":"ch_work_ttcm_4","text":"此大德所以必受命，易簡理得而成位乎天地之中也。","sortOrder":221},
  {"id":"s_work_ttcm_4_222","chapterId":"ch_work_ttcm_4","text":"易簡，乾、坤之德，所謂天德。成位乎中者，君師天下而參贊天地。","sortOrder":222},
  {"id":"s_work_ttcm_4_223","chapterId":"ch_work_ttcm_4","text":"所謂天理也者，能悅諸心，能通天下之志之理也。能使天下悅且通，則天下必歸焉。","sortOrder":223},
  {"id":"s_work_ttcm_4_224","chapterId":"ch_work_ttcm_4","text":"天之聰明，自民能通天下之志而悅之，人歸即天與，此天命之實，理固然也。","sortOrder":224},
  {"id":"s_work_ttcm_4_225","chapterId":"ch_work_ttcm_4","text":"不歸焉者，所乘所遇之不同，如仲尼與繼世之君也。","sortOrder":225},
  {"id":"s_work_ttcm_4_226","chapterId":"ch_work_ttcm_4","text":"仲尼不遇尧、舜之荐，無可乘之權，故德不加於天下，民不知歸；而繼世之君，非桀、紂之無道，尚能有其位。","sortOrder":226},
  {"id":"s_work_ttcm_4_227","chapterId":"ch_work_ttcm_4","text":"“舜、禹有天下而不與焉”者，正謂天理馴致，非氣禀當然，非志意所與也。","sortOrder":227},
  {"id":"s_work_ttcm_4_228","chapterId":"ch_work_ttcm_4","text":"舜、禹未嘗受天子之命於初生之氣禀，唯以德馴致之，窮理盡性而命即理，於斯著矣。然理至而命自至，固無欲得之心，自無或爽之命，理則然也。","sortOrder":228},
  {"id":"s_work_ttcm_4_229","chapterId":"ch_work_ttcm_4","text":"“必曰舜、禹”雲者，非乘势則求焉者也。","sortOrder":229},
  {"id":"s_work_ttcm_4_230","chapterId":"ch_work_ttcm_4","text":"繼世之君乘势而有天下，命乎氣也。湯、武則未嘗無求之之心，非與天通理，故可曰俟命而不可曰至於命。有天下而不與，則以德馴致而無心，所以合一於神化。此明天子之位，舜、禹能以其德馴致，則吉凶、禍福何不自我推移，而特非有心為善以徼福者之所能與也。","sortOrder":230},
  {"id":"s_work_ttcm_4_231","chapterId":"ch_work_ttcm_4","text":"利者為神，滯者為物。","sortOrder":231},
  {"id":"s_work_ttcm_4_232","chapterId":"ch_work_ttcm_4","text":"皆氣之為也。其本體之清微者，無性而不通，不疾而速；及其聚而成象，又聚而成形，則凝滯而難於推致矣。","sortOrder":232},
  {"id":"s_work_ttcm_4_233","chapterId":"ch_work_ttcm_4","text":"是故風雷有象，不速於心；心御見聞，不弘於性。","sortOrder":233},
  {"id":"s_work_ttcm_4_234","chapterId":"ch_work_ttcm_4","text":"風雷無形而有象，心無象而有覺，故一舉念而千里之境事現於俄頃，速於風雷矣。心之情状雖無形無象，而必依所嘗見聞者以為影质，見聞所不習者，心不能現其象。性則純乎神理，凡理之所有，皆性之所函，寂然不動之中，萬象賅存，無能御也。是以天之命，物之性，本非志意所與；而能盡其性，則物性盡，天命至，有不知其所以然者而無不通。蓋心者，翕辟之幾，無定者也；性者，合一之誠，皆備者也。","sortOrder":234},
  {"id":"s_work_ttcm_4_235","chapterId":"ch_work_ttcm_4","text":"上智下愚，習與性相遠既甚而不可变者也。","sortOrder":235},
  {"id":"s_work_ttcm_4_236","chapterId":"ch_work_ttcm_4","text":"氣之偏者，才與不才之分而已；無有人生而下愚，以終不知有君臣父子之倫及穿窬之可羞者。世教衰，風俗坏，才不逮者染於習尤易，遂日遠於性而後不可变，象可格而商臣終於大惡，習遠甚而成乎不移，非性之有不移也。","sortOrder":236},
  {"id":"s_work_ttcm_4_237","chapterId":"ch_work_ttcm_4","text":"纖惡必除，善斯成性矣；察惡未盡，雖善必粗矣。","sortOrder":237},
  {"id":"s_work_ttcm_4_238","chapterId":"ch_work_ttcm_4","text":"性無不善，有纖芥之惡，則性即為蔽，故德之已盛，猶加察於幾微；此《虞書》於精一執中之餘，尤以無稽、弗詢為戒，為邦於禮明樂備之後，必於鄭聲、佞人致謹也。心無過而身猶有之，則不能純粹以精，以成乎性焉安焉之聖德也。","sortOrder":238},
  {"id":"s_work_ttcm_4_239","chapterId":"ch_work_ttcm_4","text":"“不識不知，順帝之則”，有思慮識知，則丧其天矣。","sortOrder":239},
  {"id":"s_work_ttcm_4_240","chapterId":"ch_work_ttcm_4","text":"思慮者，逆诈、亿不信之小慧；識知者，专己保殘之曲學。天即理也，私意雖或足以知人而成事，而不能通於天理之廣大，與天則相违者多矣。張子此言，與老、釋相近而所指者不同，學者辨之。","sortOrder":240},
  {"id":"s_work_ttcm_4_241","chapterId":"ch_work_ttcm_4","text":"“君子所性”，與天地同流，異行而已焉。","sortOrder":241},
  {"id":"s_work_ttcm_4_242","chapterId":"ch_work_ttcm_4","text":"一於天理之自然，則因時合義，無非帝則矣。異行者，裁成天地之道，辅相天地之宜，自成其能也。","sortOrder":242},
  {"id":"s_work_ttcm_4_243","chapterId":"ch_work_ttcm_4","text":"“在帝左右”，察天理而左右也。","sortOrder":243},
  {"id":"s_work_ttcm_4_244","chapterId":"ch_work_ttcm_4","text":"無不在之謂察。左右者，與時偕行而無所執也。","sortOrder":244},
  {"id":"s_work_ttcm_4_245","chapterId":"ch_work_ttcm_4","text":"天理者，時義而已。","sortOrder":245},
  {"id":"s_work_ttcm_4_246","chapterId":"ch_work_ttcm_4","text":"理者，天所昭著之秩序也。時以通乎变化，義以貞其大常，風雨露雷無一成之期，而寒暑生殺終於大信。君子之行藏刑賞，因時变通而协於大，中左宜右有，皆理也，所以在帝左右也。","sortOrder":246},
  {"id":"s_work_ttcm_4_247","chapterId":"ch_work_ttcm_4","text":"君子教人，舉天理以示之而已；其行己也，述天理而時措之也。","sortOrder":247},
  {"id":"s_work_ttcm_4_248","chapterId":"ch_work_ttcm_4","text":"小慧所测，記問所得，不恃以為學誨，所明者一以其誠而已。誠者，天理之實然，無人為之伪也。","sortOrder":248},
  {"id":"s_work_ttcm_4_249","chapterId":"ch_work_ttcm_4","text":"和樂，道之端乎！","sortOrder":249},
  {"id":"s_work_ttcm_4_250","chapterId":"ch_work_ttcm_4","text":"和者於物不逆，樂者於心不厭，端，所自出之始也。道本人物之同得而得我心之悅者，故君子學以致道，必平其氣，而欣於有得，乃可與適道；若操一求勝於物之心而视為苦難，早與道離矣。下章言誠言敬，而此以和樂先之。非和樂，則誠敬局隘而易於厭倦，故能和能樂，為誠敬所自出之端。","sortOrder":250},
  {"id":"s_work_ttcm_4_251","chapterId":"ch_work_ttcm_4","text":"和則可大，樂則可久；天地之性，久大而已矣。","sortOrder":251},
  {"id":"s_work_ttcm_4_252","chapterId":"ch_work_ttcm_4","text":"不氣矜以立異，則時無不可行，物無不可受；不疲形以厭苦，則終食無违，終身不去。和樂者，適道之初心，而及其至也，則與天地同其久大矣。性體性也；太虛之體，絪緼大和，是以聚散無恒而不窮於運。孔子之學不厭，教不倦，人皆可學而不能歲，唯其用情異也。","sortOrder":252},
  {"id":"s_work_ttcm_4_253","chapterId":"ch_work_ttcm_4","text":"莫非天也，","sortOrder":253},
  {"id":"s_work_ttcm_4_254","chapterId":"ch_work_ttcm_4","text":"耳目口體之攻取，仁義禮智之存發，皆自然之理，天以厚人之生而立人之道者也。","sortOrder":254},
  {"id":"s_work_ttcm_4_255","chapterId":"ch_work_ttcm_4","text":"陽明勝則德性用，陰濁勝則物欲行。","sortOrder":255},
  {"id":"s_work_ttcm_4_256","chapterId":"ch_work_ttcm_4","text":"陽動而運乎神，陰靜而成乎形，神成性，形資養，凡物欲之需，皆地產之陰德，與形相滋益者也。氣動而不凝滯於物，則怵惕惻隱之心無所礙而不窮於生；貪養不已，馳逐物欲，而心之動幾息矣。","sortOrder":256},
  {"id":"s_work_ttcm_4_257","chapterId":"ch_work_ttcm_4","text":"領惡而全好者，其必由學乎！","sortOrder":257},
  {"id":"s_work_ttcm_4_258","chapterId":"ch_work_ttcm_4","text":"好善惡惡，德性也；領者，順其理而挈之也。陽明之德，刚健而和樂，陰濁則荏苒而賊害以攻取於物，欲澄其濁而動以清刚，則不可以不學。學者用神而以忘形之累，日習於理而欲自遏，此道問學之所以尊德性也。","sortOrder":258},
  {"id":"s_work_ttcm_4_259","chapterId":"ch_work_ttcm_4","text":"不誠不莊，可謂之盡性窮理乎？","sortOrder":259},
  {"id":"s_work_ttcm_4_260","chapterId":"ch_work_ttcm_4","text":"釋氏以天理為幻妄，則不誠；莊生以逍遙為天遊，則不莊；皆自謂窮理盡性，所以賊道。","sortOrder":260},
  {"id":"s_work_ttcm_4_261","chapterId":"ch_work_ttcm_4","text":"性之德也未嘗伪且慢，故知不免乎伪慢者，來嘗知其性也。","sortOrder":261},
  {"id":"s_work_ttcm_4_262","chapterId":"ch_work_ttcm_4","text":"性受於天理之實然，何伪之有？雖居靜而函萬化以不息，何慢之有？若王介甫之雜機朽，蘇子瞻之好驕樂，皆自言知性，所知者釋氏、莊生之所謂性也，恍忽無實而徜徉自废之浮氣也。居處恭，執事敬，與人忠，乃以體性之誠；心恒存而性顯，則不待推求而知之真矣。","sortOrder":262},
  {"id":"s_work_ttcm_4_263","chapterId":"ch_work_ttcm_4","text":"勉而後誠莊，非性也。","sortOrder":263},
  {"id":"s_work_ttcm_4_264","chapterId":"ch_work_ttcm_4","text":"勉強則志困而氣疲，求其性焉安焉，未能也。","sortOrder":264},
  {"id":"s_work_ttcm_4_265","chapterId":"ch_work_ttcm_4","text":"不勉而誠莊，所謂“不言而信，不怒而威”者與！","sortOrder":265},
  {"id":"s_work_ttcm_4_266","chapterId":"ch_work_ttcm_4","text":"勉者存其跡，不勉者存其神；存神之至，與天地同其信威。中庸言勉強則成功一，而張子以勉為非性，似過高而不切於學者。乃釋此篇之旨，先言和樂而後言誠莊，則學者適道之始，必以和樂之情存誠而莊莅，然後其為誠莊也可繼，馴而致之，聖人之至善合天，不越乎此。蓋中庸所言勉強者，學問思辨篤行之功，固不容已於勉強；而誠莊乃靜存之事，勉強則居之不安而涉於人為之偏。且勉強之功，亦非和樂則終不能勉；養蒙之道，通於聖功，苟非其本心之樂為，強之而不能以終日。故學者在先定其情，而教者导之以順。古人為教，先以勺、象，其此意欤！","sortOrder":266},
  {"id":"s_work_ttcm_4_267","chapterId":"ch_work_ttcm_4","text":"生直理順，則吉凶莫非正也。","sortOrder":267},
  {"id":"s_work_ttcm_4_268","chapterId":"ch_work_ttcm_4","text":"義不當死，則慎以全身，義不可生，則决於致命，直也。氣常伸而理不可屈，天所命人之正者此也。","sortOrder":268},
  {"id":"s_work_ttcm_4_269","chapterId":"ch_work_ttcm_4","text":"不直其生者，非幸福於回，則免難於苟也。","sortOrder":269},
  {"id":"s_work_ttcm_4_270","chapterId":"ch_work_ttcm_4","text":"處安平而枉以幸福，必臨難而苟於求免。凭氣數之偶然，幸而得福者有矣；以正言之，刑戮之民爾。","sortOrder":270},
  {"id":"s_work_ttcm_4_271","chapterId":"ch_work_ttcm_4","text":"“屈伸相感而利生”，感以誠也；","sortOrder":271},
  {"id":"s_work_ttcm_4_272","chapterId":"ch_work_ttcm_4","text":"屈則必伸，伸則必屈，善其屈以裕其伸，節其伸所以安其屈，天地不息之誠，太和不偏之妙也。人能以屈感伸，斂華就實，而德自著；以伸感屈，善其得者善其丧，皆體天地自然之實理，修身俟命而富貴不淫，貧賤不屈，夭寿不貳，用無不利矣。","sortOrder":272},
  {"id":"s_work_ttcm_4_273","chapterId":"ch_work_ttcm_4","text":"“情伪相感而利害生”，雜之伪也。","sortOrder":273},
  {"id":"s_work_ttcm_4_274","chapterId":"ch_work_ttcm_4","text":"情，實也。事之所有為情，理之所無為伪。事可為而即為，而不恤其非理之實，以事起事，以名邀名，以利計利，則雖事或實然，而雜之以妄，幸而得利，害亦伏焉。","sortOrder":274},
  {"id":"s_work_ttcm_4_275","chapterId":"ch_work_ttcm_4","text":"至誠則順理而利，伪則不循理而害，順性命之理，則所謂吉凶，莫非正也；逆理則凶為自取，吉其险幸也。","sortOrder":275},
  {"id":"s_work_ttcm_4_276","chapterId":"ch_work_ttcm_4","text":"誠者，吾性之所必盡，天命之大常也。順之則雖凶而為必受之命，逆則雖幸而得吉，险道也，险則末有不危者。故比幹死而不與惡來同其誅，曹丕、司馬昭雖竊大位而禍延於世。不可以屈伸之數，幸事之或有而不恤理之本無也。","sortOrder":276},
  {"id":"s_work_ttcm_4_277","chapterId":"ch_work_ttcm_4","text":"此章釋《易傳》之旨而决之於義利之分，為天道物理之恒，人禽存去之防，其言深切。學者近取而验吾心應感之端，决之於幾微，善惡得失，判為兩途，當無所疑矣。","sortOrder":277},
  {"id":"s_work_ttcm_4_278","chapterId":"ch_work_ttcm_4","text":"“莫非命也，順受其正”。順性命之理，則得性命之正；滅理窮欲，人為之招也。","sortOrder":278},
  {"id":"s_work_ttcm_4_279","chapterId":"ch_work_ttcm_4","text":"性命之理本無不正，順之，則當其伸而自天佑之，當其屈而不愧於天。若滅理窮欲以徼幸者，非其性之本然，命之當受，為利害之感所搖惑而致爾。","sortOrder":279},
  {"id":"s_work_ttcm_5_1","chapterId":"ch_work_ttcm_5","text":"張子正蒙註卷四","sortOrder":1},
  {"id":"s_work_ttcm_5_2","chapterId":"ch_work_ttcm_5","text":"大心篇","sortOrder":2},
  {"id":"s_work_ttcm_5_3","chapterId":"ch_work_ttcm_5","text":"此上六篇，極言天人神化性命之理；自此以下三篇，乃言學者窮理精義之功。明乎道之所自出，則功不妄；反諸學之所必務，則理不差。君子之道所以大而有實也。此篇乃致知之要，下二篇乃篤行之實，知之至而後行無不得，又學者知止之先資也。","sortOrder":3},
  {"id":"s_work_ttcm_5_4","chapterId":"ch_work_ttcm_5","text":"大其心，則能體天下之物，物有未體，則心為有外。","sortOrder":4},
  {"id":"s_work_ttcm_5_5","chapterId":"ch_work_ttcm_5","text":"大其心，非故扩之使遊於荒遠也；天下之物相感而可通者，吾心皆有其理，唯意欲蔽之則小爾。由其法象，推其神化，達之於萬物一源之本，則所以知明處當者，條理無不見矣。天下之物皆用也，吾心之理其體也；盡心以循之，則體立而用自無窮。","sortOrder":5},
  {"id":"s_work_ttcm_5_6","chapterId":"ch_work_ttcm_5","text":"世人之心，止於聞見之狹；聖人盡性，不以見聞梏其心。其视天下，無一物非我，","sortOrder":6},
  {"id":"s_work_ttcm_5_7","chapterId":"ch_work_ttcm_5","text":"聞見，習也；習之所知者，善且有窮，况不善乎！盡性者，極吾心虛靈不昧之良能，舉而與天地萬物所從出之理合而知其大始，則天下之物與我同源，而待我以應而成。故盡孝而後父為吾父，盡忠而後君為吾君，無一物之不自我成也；非感於聞見，觸名思義，觸事求通之得謂之知能也。","sortOrder":7},
  {"id":"s_work_ttcm_5_8","chapterId":"ch_work_ttcm_5","text":"孟子謂盡心則知性知天以此。","sortOrder":8},
  {"id":"s_work_ttcm_5_9","chapterId":"ch_work_ttcm_5","text":"朱子謂知性乃能盡心，而張子以盡心為知性之功，其說小異，然性處於靜而未成法象，非盡其心以體認之，則偶有見聞，遂據為性之實然，此天下之言性者所以凿也。","sortOrder":9},
  {"id":"s_work_ttcm_5_10","chapterId":"ch_work_ttcm_5","text":"天大無外，故有外之心，不足以合天心。","sortOrder":10},
  {"id":"s_work_ttcm_5_11","chapterId":"ch_work_ttcm_5","text":"心不盡則有外，一曲乍得之知，未嘗非天理变化之端，而所遺者多矣。","sortOrder":11},
  {"id":"s_work_ttcm_5_12","chapterId":"ch_work_ttcm_5","text":"見聞之知，乃物交而知，非德性所知；","sortOrder":12},
  {"id":"s_work_ttcm_5_13","chapterId":"ch_work_ttcm_5","text":"天下有其事而見聞乃可及之，故有尧，有象，有瞽瞍，有舜，有文王，幽、厲，有三代之民，事跡已著之餘，傳聞而後知，遂挟以證性，知為之梏矣。德性之知，循理而及其原，廓然於天地萬物大始之理，乃吾所得於天而即所得以自喻者也。","sortOrder":13},
  {"id":"s_work_ttcm_5_14","chapterId":"ch_work_ttcm_5","text":"德性所知，不萌於見聞。","sortOrder":14},
  {"id":"s_work_ttcm_5_15","chapterId":"ch_work_ttcm_5","text":"萌者，所從生之始也。見聞可以證於知已知之後，而知不因見聞而發。德性誠有而自喻，如暗中自指其口鼻，不待鏡而悉。","sortOrder":15},
  {"id":"s_work_ttcm_5_16","chapterId":"ch_work_ttcm_5","text":"由象識心，徇象丧心。","sortOrder":16},
  {"id":"s_work_ttcm_5_17","chapterId":"ch_work_ttcm_5","text":"物之有象，理即在焉。心有其理，取象而證之，無不通矣。若心所不喻，一由於象，而以之識心，則徇象之一曲而丧心之大全矣。故乍見孺子入井，可識惻隱之心，然必察識此心所從生之實而後仁可喻。若但據此以自信，則象在而顯，象去而隱，且有如齊王全牛之心，反求而不得者矣。","sortOrder":17},
  {"id":"s_work_ttcm_5_18","chapterId":"ch_work_ttcm_5","text":"知象者心，存象之心，亦象而已，謂之心，可乎？","sortOrder":18},
  {"id":"s_work_ttcm_5_19","chapterId":"ch_work_ttcm_5","text":"知象者本心也，非識心者象也。存象於心而據之為知，則其知者象而已；象化其心而心唯有象，不可謂此為吾心之知也明矣。見聞所得者象也，知其器，知其數，知其名爾。若吾心所以製之之義，豈彼之所能昭著乎！","sortOrder":19},
  {"id":"s_work_ttcm_5_20","chapterId":"ch_work_ttcm_5","text":"人謂己有知，由耳目有受也；","sortOrder":20},
  {"id":"s_work_ttcm_5_21","chapterId":"ch_work_ttcm_5","text":"受聲色而能知其固然，因恃為己知，而不察知所從生，陋矣。","sortOrder":21},
  {"id":"s_work_ttcm_5_22","chapterId":"ch_work_ttcm_5","text":"人之有受，由內外之合也。","sortOrder":22},
  {"id":"s_work_ttcm_5_23","chapterId":"ch_work_ttcm_5","text":"耳與聲合，目與色合，皆心所翕辟之牖也，合，故相知；乃其所以合之故，則豈耳目聲色之力哉！故舆薪過前，群言雜至，而非意所屬，則見如不見，聞如不聞，其非耳目之受而即合，明矣。","sortOrder":23},
  {"id":"s_work_ttcm_5_24","chapterId":"ch_work_ttcm_5","text":"知合內外於耳目之外，則其知也過人遠矣。","sortOrder":24},
  {"id":"s_work_ttcm_5_25","chapterId":"ch_work_ttcm_5","text":"合內外者，化之神也，誠之幾也。以此為知，則聞之見之而知之審，不聞不見而理不亡，事即不隱，此存神之妙也。","sortOrder":25},
  {"id":"s_work_ttcm_5_26","chapterId":"ch_work_ttcm_5","text":"天之明莫大於日，故有目接之，不知其幾萬里之高也；天之聲莫大於雷霆，故有耳屬之，莫知其幾萬里之遠也；天之不御莫大於太虛，故心知廓之，莫究其極也。敔按：“幾萬里之遠也”，“萬’當作“百”","sortOrder":26},
  {"id":"s_work_ttcm_5_27","chapterId":"ch_work_ttcm_5","text":"言道體之無涯，以耳目心知测度之，終不能究其所至，故雖日之明，雷霆之聲，為耳目所可聽睹，而無能窮其高遠；太虛寥廓，分明可見，而心知固不能度，况其变化難知者乎！是知耳目心知之不足以盡道，而徒累之使疑爾。心知者，緣見聞而生，其知非真知也。","sortOrder":27},
  {"id":"s_work_ttcm_5_28","chapterId":"ch_work_ttcm_5","text":"人病其以耳目見聞累其心，而不務盡其心，","sortOrder":28},
  {"id":"s_work_ttcm_5_29","chapterId":"ch_work_ttcm_5","text":"盡其心者，盡心之本知。","sortOrder":29},
  {"id":"s_work_ttcm_5_30","chapterId":"ch_work_ttcm_5","text":"故思盡其心者，必知心所從來而後能。","sortOrder":30},
  {"id":"s_work_ttcm_5_31","chapterId":"ch_work_ttcm_5","text":"心所從來者，日得之以為明，雷霆得之以為聲，太虛絪緼之氣升降之幾也。於人，則誠有其性即誠有其理，自誠有之而自喻之，故靈明發焉；耳目見聞皆其所發之一曲，而函其全於心以為四應之真知。知此，則見聞不足以累其心，而適為獲心之助，廣大不测之神化，無不達矣。此盡性知天之要也。","sortOrder":31},
  {"id":"s_work_ttcm_5_32","chapterId":"ch_work_ttcm_5","text":"耳目雖為性累，然合內外之德，知其為啟之要也。","sortOrder":32},
  {"id":"s_work_ttcm_5_33","chapterId":"ch_work_ttcm_5","text":"累者，累之使御於見聞之小爾，非欲空之而後無累也。內者，心之神，外者，物之法象。法象非神不立，神非法象不顯。多聞而擇，多見而識，乃以啟發其心思而會歸於一，又非徒恃存神而置格物窮理之學也。此篇力辨見聞之小而要歸於此，張子之學所以異於陆、王之孤僻也。","sortOrder":33},
  {"id":"s_work_ttcm_5_34","chapterId":"ch_work_ttcm_5","text":"成吾身者，天之神也。不知以性成身，而自謂因身發智，貪天功為己力，吾不知其知也。","sortOrder":34},
  {"id":"s_work_ttcm_5_35","chapterId":"ch_work_ttcm_5","text":"身，謂耳目之聰明也。形色莫非天性，故天性之知，由形色而發。知者引聞見之知以窮理而要歸於盡性；愚者限於見聞而不反諸心，據所窥测恃為真知。徇欲者以欲為性，耽空者以空為性，皆聞見之所测也。","sortOrder":35},
  {"id":"s_work_ttcm_5_36","chapterId":"ch_work_ttcm_5","text":"民何知哉？因物同異相形，萬变相感，耳目內外之合，貪天功而自謂己知爾。","sortOrder":36},
  {"id":"s_work_ttcm_5_37","chapterId":"ch_work_ttcm_5","text":"形之所發，莫非天也；物变之不齊，亦莫非天也；兩相攻取而順逆之見生焉。若能知性知天，則一理之所貫通有真是，而無待是非之兩立以相比擬，因天理之固然而不因乎聞見，則無恃以自矜其察矣。待有幽、厲而始知文武之民善，待乌喙之毒而始知菽粟之養乎？同異萬变，佹得佹失，不足為知也，明矣。","sortOrder":37},
  {"id":"s_work_ttcm_5_38","chapterId":"ch_work_ttcm_5","text":"體物體身，道之本也；","sortOrder":38},
  {"id":"s_work_ttcm_5_39","chapterId":"ch_work_ttcm_5","text":"萬物之所自生，萬事之所自立，耳目之有見聞，心思之能覺察，皆與道為體，知道而後外能盡物，內能成身；不然，則徇其末而忘其本矣。","sortOrder":39},
  {"id":"s_work_ttcm_5_40","chapterId":"ch_work_ttcm_5","text":"身而體道，其為人也大矣。","sortOrder":40},
  {"id":"s_work_ttcm_5_41","chapterId":"ch_work_ttcm_5","text":"视聽言動，無非道也，則耳目口體全為道用，而道外無徇物自恣之身，合天德而廣大肆應矣。","sortOrder":41},
  {"id":"s_work_ttcm_5_42","chapterId":"ch_work_ttcm_5","text":"道能物身，故大；不能物身而累於身，則藐乎其卑矣。","sortOrder":42},
  {"id":"s_work_ttcm_5_43","chapterId":"ch_work_ttcm_5","text":"物身者，以身為物而為道所用，所謂以小體從大體而為大人也，不以道用其耳目口體之能，而從嗜欲以沈溺不反，從記誦以玩物丧志，心盡於形器之中，小人之所以卑也。","sortOrder":43},
  {"id":"s_work_ttcm_5_44","chapterId":"ch_work_ttcm_5","text":"能以天體身，則能體物也不疑。","sortOrder":44},
  {"id":"s_work_ttcm_5_45","chapterId":"ch_work_ttcm_5","text":"天不息而大公，一於神，一於理，一於誠也。大人以道為體，耳目口體無非道用，則入萬物之中，推己即以盡物，循物皆得於己，物之情無不盡，物之才無不可成矣。","sortOrder":45},
  {"id":"s_work_ttcm_5_46","chapterId":"ch_work_ttcm_5","text":"成心忘，然後可與進於道。張子自註：成心者，私意也","sortOrder":46},
  {"id":"s_work_ttcm_5_47","chapterId":"ch_work_ttcm_5","text":"成心者，非果一定之理，不可奪之志也。乍然見聞所得，未必非道之一曲，而不能通其感於萬变，徇同毀異，強異求同，成乎己私，违大公之理，恃之而不忘，則執一善以守之，終身不复進矣。萬世不易之常經，通萬变而隨時得中。學者即未能至，而不恃其習成之見，知有未至之境，則可與適道，而所未至者，皆其可至者也。","sortOrder":47},
  {"id":"s_work_ttcm_5_48","chapterId":"ch_work_ttcm_5","text":"化則無成心矣。","sortOrder":48},
  {"id":"s_work_ttcm_5_49","chapterId":"ch_work_ttcm_5","text":"大而化之，則心純乎道。盡無方無體之理，自無成心。","sortOrder":49},
  {"id":"s_work_ttcm_5_50","chapterId":"ch_work_ttcm_5","text":"成心者，意之謂與！","sortOrder":50},
  {"id":"s_work_ttcm_5_51","chapterId":"ch_work_ttcm_5","text":"意者，心所偶發，執之則為成心矣。聖人無意，不以意為成心之謂也。蓋在道為經，在心為志，志者，始於志學而終於從心之矩，一定而不可易者，可成者也。意則因感而生，因見聞而執同異攻取，不可恒而習之為恒，不可成者也。故曰學者當知志意之分。","sortOrder":51},
  {"id":"s_work_ttcm_5_52","chapterId":"ch_work_ttcm_5","text":"無成心者，時中而已矣。","sortOrder":52},
  {"id":"s_work_ttcm_5_53","chapterId":"ch_work_ttcm_5","text":"中無定在，而隨時位之变，皆無過不及之差，意不得而與焉。","sortOrder":53},
  {"id":"s_work_ttcm_5_54","chapterId":"ch_work_ttcm_5","text":"心存，無盡性之理，故聖不可知謂神。張子自註：此章言心者，亦指私心為言也","sortOrder":54},
  {"id":"s_work_ttcm_5_55","chapterId":"ch_work_ttcm_5","text":"心存，謂成心未忘也。性為神之體而統萬善，若以私意為成心，則性之廣大深微不能盡者多矣。楊之義，墨之仁，申之名，韓之法，莫非道之所可，而成乎性之偏，惟挟之以為成心，而不能極道之深、充道之廣也。盡性而無成心，則大人以下，有所執以為善者，皆不测其時行時止、進退勸威之妙，蓋聖人之神，超然知道之本原，以循理因時而已。敔按：不可知者，謂大人以下皆不能测之也","sortOrder":55},
  {"id":"s_work_ttcm_5_56","chapterId":"ch_work_ttcm_5","text":"以我视物，則我大；","sortOrder":56},
  {"id":"s_work_ttcm_5_57","chapterId":"ch_work_ttcm_5","text":"视聽之明，可以攝物，心知之量，可以受物，於是而可以知物之不足而我之有餘，則不徇物以自替其大矣。","sortOrder":57},
  {"id":"s_work_ttcm_5_58","chapterId":"ch_work_ttcm_5","text":"以道體物我，則道大。","sortOrder":58},
  {"id":"s_work_ttcm_5_59","chapterId":"ch_work_ttcm_5","text":"物與我皆氣之所聚，理之所行，受命於一陰一陽之道，而道為其體；不但夫婦、鳶魚為道之所昭著，而我之心思耳目，何莫非道之所凝承，而為道效其用者乎！唯體道者能以道體物我，則大以道而不以我。","sortOrder":59},
  {"id":"s_work_ttcm_5_60","chapterId":"ch_work_ttcm_5","text":"故君子之大也大於道，大於我者，容不免狂而已。","sortOrder":60},
  {"id":"s_work_ttcm_5_61","chapterId":"ch_work_ttcm_5","text":"於道無不體，則充實光辉而大矣。狂者見我之尊而卑萬物，不屑徇物以為功名而自得，乃考其行而不掩，則亦耳目心思之曠達而已。","sortOrder":61},
  {"id":"s_work_ttcm_5_62","chapterId":"ch_work_ttcm_5","text":"燭天理，如向明，萬物無所隱；","sortOrder":62},
  {"id":"s_work_ttcm_5_63","chapterId":"ch_work_ttcm_5","text":"燭天理者，全體而率行之，則條理萬变無不察也。萬象之情状，以理验其合離，則得失吉凶，不待逆亿而先覺。","sortOrder":63},
  {"id":"s_work_ttcm_5_64","chapterId":"ch_work_ttcm_5","text":"窮人欲，如专顧影間，區區一物之中爾。","sortOrder":64},
  {"id":"s_work_ttcm_5_65","chapterId":"ch_work_ttcm_5","text":"形蔽明而成影；人欲者，為耳目口體所蔽而窒其天理者也。耳困於聲，目困於色，口困於味，體困於安，心之靈且從之而困於一物，得則見美，失則見惡，是非之准，吉凶之感，在眉睫而不知；此物大而我小，下愚之所以陷溺也。","sortOrder":65},
  {"id":"s_work_ttcm_5_66","chapterId":"ch_work_ttcm_5","text":"此章直指智愚之辨，窮本推源，最為深切，尤學者之所宜知警也。","sortOrder":66},
  {"id":"s_work_ttcm_5_67","chapterId":"ch_work_ttcm_5","text":"釋氏不知天命，而以心法起滅天地，","sortOrder":67},
  {"id":"s_work_ttcm_5_68","chapterId":"ch_work_ttcm_5","text":"天命，太和絪緼之氣，屈伸而成萬化，氣至而神至，神至而理存者也。釋氏謂“心生种种法生，心滅种种法滅”，置之不見不聞，而即謂之無。天地本無起滅，而以私意起滅之，愚矣哉！","sortOrder":68},
  {"id":"s_work_ttcm_5_69","chapterId":"ch_work_ttcm_5","text":"以小緣大，以末緣本，其不能窮而謂之幻妄，真所謂疑冰者與！張子自註：夏虫疑冰，以其不識","sortOrder":69},
  {"id":"s_work_ttcm_5_70","chapterId":"ch_work_ttcm_5","text":"小，謂耳目心知見聞覺知之限量：大者，清虛一大之道體；末者，散而之無，疑於滅，聚而成有，疑於相緣以起而本無生。惟不能窮夫屈伸往來於太虛之中者，實有絪緼太和之元氣，函健順五常之體性，故直斥為幻妄。己所不見而謂之幻妄，真夏虫不可語冰也。蓋太虛之中，無極而太極，充滿兩間，皆一實之府，特视不可見，聽不可聞爾。存神以窮之，則其富有而非無者自見。緣小體视聽之知，則但見聲色俱泯之為無極，而不知無極之為太極。其雲“但願空諸所有”，既雲有矣，我乌得而空之？“不願實諸所無”，若其本無，又何從可得而實之？惟其乍離人欲而未見夫天理，故以人欲之妄概天理之真，而非果有賢知之過，亦愚不肖之不及而已。","sortOrder":70},
  {"id":"s_work_ttcm_5_71","chapterId":"ch_work_ttcm_5","text":"釋氏妄意天性，而不知范围天用，","sortOrder":71},
  {"id":"s_work_ttcm_5_72","chapterId":"ch_work_ttcm_5","text":"其直指人心見性，妄意天性，不知道心，而以惟危之人心為性也。天用者，升降之恒，屈伸之化，皆太虛一實之理氣成乎大用也。天無體，用即其體。范围者，大心以廣運之，則天之用顯而天體可知矣。敔按：《中庸》雲“天地之道，博也厚也，高也明也，悠也久也”，正所謂“天無體，用即其體”也","sortOrder":72},
  {"id":"s_work_ttcm_5_73","chapterId":"ch_work_ttcm_5","text":"反以六根之微因緣天地。明不能盡，則誣天地日月為幻妄，蔽其用於一身之小，溺其志於虛空之大，","sortOrder":73},
  {"id":"s_work_ttcm_5_74","chapterId":"ch_work_ttcm_5","text":"萬化之屈伸，無屈不伸，無伸不屈。耳目心知之微明，驚其所自生以為漚合，疑其屈而歸於無，則謂凡有者畢竟歸空，而天地亦本無實有之理氣，但從見病而成眚。其雲“同一雨而天仙見為寶，羅刹見為刀”，乃盜賊惡月明、行人惡雨濘之偷心爾，是蔽其用於耳目口體之私情，以己之利害為天地之得丧，因欲一空而銷陨之，遂謂“一真法界本無一物”，則溺其志以求合，而君父可滅，形體可毀，皆其所不恤已。","sortOrder":74},
  {"id":"s_work_ttcm_5_75","chapterId":"ch_work_ttcm_5","text":"此所以語大語小，流遁失中。其過於大也，尘芥六合；其蔽於小也，夢幻人世。","sortOrder":75},
  {"id":"s_work_ttcm_5_76","chapterId":"ch_work_ttcm_5","text":"以虛空為無盡藏，故尘芥六合；以見聞覺知所不能及為無有，故夢幻人世。","sortOrder":76},
  {"id":"s_work_ttcm_5_77","chapterId":"ch_work_ttcm_5","text":"謂之窮理，可乎？不知窮理而謂盡性，可乎？謂之無不知，可乎？","sortOrder":77},
  {"id":"s_work_ttcm_5_78","chapterId":"ch_work_ttcm_5","text":"夢幻無理，故人無有窮究夢幻者；以人世為夢幻，則富有日新之理皆可置之不思不議矣，君可非吾君矣，父可非吾父矣。天理者，性之撰，此之不恤、是無性矣。故其究竟，以無生為宗，而欲斷言語，絕心行，茫然一無所知，而妄謂無不知，流遁以護其愚悍，無所不至矣。","sortOrder":78},
  {"id":"s_work_ttcm_5_79","chapterId":"ch_work_ttcm_5","text":"尘芥六合，謂天地為有窮也；","sortOrder":79},
  {"id":"s_work_ttcm_5_80","chapterId":"ch_work_ttcm_5","text":"如華藏世界等說是也。不知法界安立於何所，其愚蚩適足哂而已。","sortOrder":80},
  {"id":"s_work_ttcm_5_81","chapterId":"ch_work_ttcm_5","text":"夢幻人世，明不能究所從也。","sortOrder":81},
  {"id":"s_work_ttcm_5_82","chapterId":"ch_work_ttcm_5","text":"不能究所從者，不知太和絪緼之實為聚散之府，則疑無所從生而惟心法起滅，故立十二因緣之說，以無明為生死之本。統而論之，流俗之徇欲者，以見聞域其所知也；釋氏之邪妄者，據見聞之所窮而遂謂無也。致知之道，惟在遠此二愚，大其心以體物體身而已。","sortOrder":82},
  {"id":"s_work_ttcm_5_83","chapterId":"ch_work_ttcm_5","text":"中正篇","sortOrder":83},
  {"id":"s_work_ttcm_5_84","chapterId":"ch_work_ttcm_5","text":"此篇博引《論語》《孟子》之言以著作聖之功，而終之以教者善誘之道。其雲中道者，即尧、舜以來相傳之極致，《大學》所謂至善也。學者下學立心之始，即以此為知止之要而求得焉，不可疑存神精義為不可企及而自小其志量也。","sortOrder":84},
  {"id":"s_work_ttcm_5_85","chapterId":"ch_work_ttcm_5","text":"中正然後貫天下之道，","sortOrder":85},
  {"id":"s_work_ttcm_5_86","chapterId":"ch_work_ttcm_5","text":"不倚之謂中，得其理而守之、不為物遷之謂正。中正，則奉天下之大本以臨事物，大經審而物不能外，天下之道貫於一矣。有成心者有所倚，徇見聞者必屢遷；唯其非存大中而守至正，故與道多违。","sortOrder":86},
  {"id":"s_work_ttcm_5_87","chapterId":"ch_work_ttcm_5","text":"此君子之所以大居正也。","sortOrder":87},
  {"id":"s_work_ttcm_5_88","chapterId":"ch_work_ttcm_5","text":"居者，存之於心，待物之來而應之。","sortOrder":88},
  {"id":"s_work_ttcm_5_89","chapterId":"ch_work_ttcm_5","text":"蓋得正則得所止，得所止則可以弘而至於大。","sortOrder":89},
  {"id":"s_work_ttcm_5_90","chapterId":"ch_work_ttcm_5","text":"所止者，至善也；事物所以然之實，成乎當然之則者也。以健順之大常為五常之大經，扩之，則萬事萬物皆效法焉而至於大矣。","sortOrder":90},
  {"id":"s_work_ttcm_5_91","chapterId":"ch_work_ttcm_5","text":"樂正子、顏淵，知欲仁矣。","sortOrder":91},
  {"id":"s_work_ttcm_5_92","chapterId":"ch_work_ttcm_5","text":"仁者，生物之理。以此，生則各凝之為性，而終身率由，條理畅遂，無不弘焉；是性命之正，不倚見聞之私，不為物欲所遷者也。知欲仁，則志於仁矣。","sortOrder":92},
  {"id":"s_work_ttcm_5_93","chapterId":"ch_work_ttcm_5","text":"樂正子不致其學，足以為善人信人，志於仁，無惡而已。","sortOrder":93},
  {"id":"s_work_ttcm_5_94","chapterId":"ch_work_ttcm_5","text":"學，所以扩其中正之用而弘之者也；學雖未弘而志於仁，抑可以無惡者。蓋夫人之心，善則欲，惡則惡，情之所然，即二氣之和，大順而不可逆者也。惻然有動之心，發生於太和之氣，故苟有諸己，人必欲之，合天下之公欲，不遠二氣之正，乖戾之所以化也。","sortOrder":94},
  {"id":"s_work_ttcm_5_95","chapterId":"ch_work_ttcm_5","text":"顏子好學不倦，合仁與智，具體聖人，獨未至聖人之止爾。","sortOrder":95},
  {"id":"s_work_ttcm_5_96","chapterId":"ch_work_ttcm_5","text":"顏子之好學，不遷怒，不貳過，養其心以求化於跡，則既志於仁，抑能通物理之变而周知之，具聖人之體矣。未極乎高明廣大至善之境，以貞萬氣於一原，故未造聖人之極致。","sortOrder":96},
  {"id":"s_work_ttcm_5_97","chapterId":"ch_work_ttcm_5","text":"學者中道而立，則有仁以弘之。","sortOrder":97},
  {"id":"s_work_ttcm_5_98","chapterId":"ch_work_ttcm_5","text":"中道者，大中之矩，陰陽合一，周流於屈伸之萬象而無偏倚者，合陰陽、健順、動靜於一而皆和，故周子曰“中也者和也”。《中庸》自其存中而後發之和言之，則中其體也，和其用也。自學者奉之為大本以立於四達之道言之，本乎太和而成無過不及之節，則和又體而中其用也。仁者，中道之所顯也；靜而能涵吾性之中，則天理來复，自然發起而生惻隱之心，以成天下之用，道自弘矣。","sortOrder":98},
  {"id":"s_work_ttcm_5_99","chapterId":"ch_work_ttcm_5","text":"無中道而弘，則窮大而失其居，","sortOrder":99},
  {"id":"s_work_ttcm_5_100","chapterId":"ch_work_ttcm_5","text":"老之虛，釋之空，莊生之逍遙，皆自欲弘者；無一實之中道，則心滅而不能貫萬化矣。","sortOrder":100},
  {"id":"s_work_ttcm_5_101","chapterId":"ch_work_ttcm_5","text":"失其居則無地以崇其德，與不及者同；","sortOrder":101},
  {"id":"s_work_ttcm_5_102","chapterId":"ch_work_ttcm_5","text":"苟欲弘而失其居，則视天下皆非吾所安之土，故其極至於恤私而蔑君親，縱欲而習放誕，以為不系不留，理事皆無礙，而是非不立，與不肖者之偷污等矣。","sortOrder":102},
  {"id":"s_work_ttcm_5_103","chapterId":"ch_work_ttcm_5","text":"此顏子所以克己研幾，必欲用其極也。","sortOrder":103},
  {"id":"s_work_ttcm_5_104","chapterId":"ch_work_ttcm_5","text":"極，中道也。克己，則不徇耳目之見聞而為所錮蔽；研幾，則審乎是非之微，知動靜之因微成著而見天地之心。顏子知用中道之極以求仁，故仁將來复。","sortOrder":104},
  {"id":"s_work_ttcm_5_105","chapterId":"ch_work_ttcm_5","text":"未至聖而不已，故仲尼賢其進；未得中而不居，故惜夫未見其止也。","sortOrder":105},
  {"id":"s_work_ttcm_5_106","chapterId":"ch_work_ttcm_5","text":"不居，未能居也；居之安，則不思不勉而與天同其化矣。未見其止者，顏子早夭，故不及止於至善也。","sortOrder":106},
  {"id":"s_work_ttcm_5_107","chapterId":"ch_work_ttcm_5","text":"大中至正之文極，必能致其用，約必能感而通。","sortOrder":107},
  {"id":"s_work_ttcm_5_108","chapterId":"ch_work_ttcm_5","text":"大中者，無所不中；至止者，無所不正：貫天下之道者也。文有古今质文之異，而用之皆宜，非博辯而不適於用；約以禮，修之於已，無心於物，物無不應。蓋文與禮，一皆神化所顯著之跡，陰陽、刚柔、仁義自然之秩序，不倚於一事一物而各正其性命者也。、","sortOrder":108},
  {"id":"s_work_ttcm_5_109","chapterId":"ch_work_ttcm_5","text":"未至於此，其视聖人，恍惚前後，不可為像，此顏子之叹乎！","sortOrder":109},
  {"id":"s_work_ttcm_5_110","chapterId":"ch_work_ttcm_5","text":"神化之理，散為萬殊而為文，麗於事物而為禮，故聖人教人，使之熟習之而知其所由；生乃所以成乎文與禮者，人心不自已之幾，神之所流行也。聖人存神，隨時而處中，其所用以感天下者，以大本行乎達道，故错綜变化，人莫能测，顏子之叹以此。如《禮記》所載“拱而尚左”之類，亦文與禮之易知易從者，得其時中而人且不知，亦可以思聖人義精仁熟、熟而入化之妙矣。","sortOrder":110},
  {"id":"s_work_ttcm_5_111","chapterId":"ch_work_ttcm_5","text":"可欲之謂善，志仁則無惡也，","sortOrder":111},
  {"id":"s_work_ttcm_5_112","chapterId":"ch_work_ttcm_5","text":"無惡，則不拂人之性而見可欲。","sortOrder":112},
  {"id":"s_work_ttcm_5_113","chapterId":"ch_work_ttcm_5","text":"誠善於心之謂信，","sortOrder":113},
  {"id":"s_work_ttcm_5_114","chapterId":"ch_work_ttcm_5","text":"有諸己者，誠自信於心也。","sortOrder":114},
  {"id":"s_work_ttcm_5_115","chapterId":"ch_work_ttcm_5","text":"充內形外之謂美，","sortOrder":115},
  {"id":"s_work_ttcm_5_116","chapterId":"ch_work_ttcm_5","text":"義理足乎日用，德純一致無疵颣曰美。","sortOrder":116},
  {"id":"s_work_ttcm_5_117","chapterId":"ch_work_ttcm_5","text":"塞乎天地之謂大，","sortOrder":117},
  {"id":"s_work_ttcm_5_118","chapterId":"ch_work_ttcm_5","text":"天地之間事物变化，得其神理，無不可弥纶者。能以神御氣，則神足以存，氣無不勝矣。","sortOrder":118},
  {"id":"s_work_ttcm_5_119","chapterId":"ch_work_ttcm_5","text":"大能成性之謂聖，","sortOrder":119},
  {"id":"s_work_ttcm_5_120","chapterId":"ch_work_ttcm_5","text":"大則無以加矣，熟之而不待扩充，全其性之所能，而安之以成乎固然，不待思勉矣。","sortOrder":120},
  {"id":"s_work_ttcm_5_121","chapterId":"ch_work_ttcm_5","text":"天地同流，陰陽不测之謂神。","sortOrder":121},
  {"id":"s_work_ttcm_5_122","chapterId":"ch_work_ttcm_5","text":"神者，聖之大用也。合陰陽於一致，進退生殺乘乎時，而無非天理之自然，人不得以動靜、刚柔、仁義之跡测之，聖之神也。六者，以正志為入德之門，以存心立誠為所學之實，以中道貫萬理為至善之止，聖與神則其熟而馴致者也。故學者以大心正志為本。","sortOrder":122},
  {"id":"s_work_ttcm_5_123","chapterId":"ch_work_ttcm_5","text":"高明不可窮，博厚不可極，則中道不可識，蓋顏子之叹也。","sortOrder":123},
  {"id":"s_work_ttcm_5_124","chapterId":"ch_work_ttcm_5","text":"窮高明者，達太虛至和之妙，而理之所從出無不知也；極博厚者，盡人物之逆順险阻，皆能載之而無所拒也。窮高明則文皆致用，極博厚則禮能感通，而後天下之富有，皆得其大中之矩以貫萬理。顏子弥高弥堅之叹，非侈心於高堅，所以求中道爾。不窮高明，不極博厚，而欲識中道，非偏則妄矣。","sortOrder":124},
  {"id":"s_work_ttcm_5_125","chapterId":"ch_work_ttcm_5","text":"君子之道，成身成性以為功者也。","sortOrder":125},
  {"id":"s_work_ttcm_5_126","chapterId":"ch_work_ttcm_5","text":"身者道之用，性者道之體。合氣质攻取之性，一為道用，則以道體身而身成；大其心以盡性，熟而安焉，則性成。身與性之所自成者，天也，人為蔽之而不成；以道體天，而後其所本成者安之而皆順。君子精義研幾而化其成心，所以為作聖之實功也。","sortOrder":126},
  {"id":"s_work_ttcm_5_127","chapterId":"ch_work_ttcm_5","text":"未至於聖，皆行而未成之地爾。","sortOrder":127},
  {"id":"s_work_ttcm_5_128","chapterId":"ch_work_ttcm_5","text":"欲罢不能而未熟，私意或間之也；行而不息，則成矣。","sortOrder":128},
  {"id":"s_work_ttcm_5_129","chapterId":"ch_work_ttcm_5","text":"大而未化，未能有其大，化而後能有其大。","sortOrder":129},
  {"id":"s_work_ttcm_5_130","chapterId":"ch_work_ttcm_5","text":"與時偕行而無不安，然後大無所御；以天地萬物一體為量而有任之之意存，則動止進退必有所礙，不能全其大矣。任之之意，即有思勉、有方體也。","sortOrder":130},
  {"id":"s_work_ttcm_5_131","chapterId":"ch_work_ttcm_5","text":"知德以大中為期，可謂知至矣。","sortOrder":131},
  {"id":"s_work_ttcm_5_132","chapterId":"ch_work_ttcm_5","text":"大中者，陰陽合德，屈伸合機，萬事萬理之大本也。知之而必至於是以為止，知乃至其極也。","sortOrder":132},
  {"id":"s_work_ttcm_5_133","chapterId":"ch_work_ttcm_5","text":"擇中庸而固執之，乃至之之漸也。","sortOrder":133},
  {"id":"s_work_ttcm_5_134","chapterId":"ch_work_ttcm_5","text":"中庸，中之用也。擇者，擇道心於人心之中，而不以見聞之人為雜天理之自然也。固執，動靜恒依而不失也。擇之精，執之固，熟則至矣。","sortOrder":134},
  {"id":"s_work_ttcm_5_135","chapterId":"ch_work_ttcm_5","text":"惟知學然後能勉，能勉然後日進而不息可期矣。","sortOrder":135},
  {"id":"s_work_ttcm_5_136","chapterId":"ch_work_ttcm_5","text":"知學，知擇執以至於中也；不息，則成性而自能化矣。不知學者，俗儒以人為為事功，異端以窮大失居為神化；故或事求可，功求成，而遂生其驕吝，或謂知有是事便休，皆放其心而不能勉；雖小有得，以間斷而失之。","sortOrder":136},
  {"id":"s_work_ttcm_5_137","chapterId":"ch_work_ttcm_5","text":"體正則不待矯而弘，","sortOrder":137},
  {"id":"s_work_ttcm_5_138","chapterId":"ch_work_ttcm_5","text":"體，才也；才足以成性曰正。聰明強固，知能及而行能守，則自弘矣。","sortOrder":138},
  {"id":"s_work_ttcm_5_139","chapterId":"ch_work_ttcm_5","text":"不正必矯，矯而得中，然後可大。","sortOrder":139},
  {"id":"s_work_ttcm_5_140","chapterId":"ch_work_ttcm_5","text":"得中道之一實以體天德，然後可備萬物之理。才既偏矣，不矯而欲弘，則窮大失居，弘非其弘矣。蓋才與習相狎，則性不可得而見，習之所以溺人者，皆乘其才之相近而遂相得。故矯習以复性者，必矯其才之所利；不然，陷於一曲之知能，雖善而隘，不但人欲之局促也。","sortOrder":140},
  {"id":"s_work_ttcm_5_141","chapterId":"ch_work_ttcm_5","text":"故致曲於誠者，必变而後化。敔按：此言变化，與朱子《中庸章句》異，詳後《致曲不貳》章","sortOrder":141},
  {"id":"s_work_ttcm_5_142","chapterId":"ch_work_ttcm_5","text":"变，謂变其才质之偏；化，則弘大而無滯也。","sortOrder":142},
  {"id":"s_work_ttcm_5_143","chapterId":"ch_work_ttcm_5","text":"極其大而後中可求，止其中而後大可有。","sortOrder":143},
  {"id":"s_work_ttcm_5_144","chapterId":"ch_work_ttcm_5","text":"大者，中之撰也；中者，大之實也。盡體天地萬物之化理，而後得大本以隨時而處中，得中道而不遷，則萬化皆由之以弘，而用無不備矣。","sortOrder":144},
  {"id":"s_work_ttcm_5_145","chapterId":"ch_work_ttcm_5","text":"大亦聖之任，","sortOrder":145},
  {"id":"s_work_ttcm_5_146","chapterId":"ch_work_ttcm_5","text":"聖之任，亦大之至爾。","sortOrder":146},
  {"id":"s_work_ttcm_5_147","chapterId":"ch_work_ttcm_5","text":"雖非清和一體之偏，猶未忘於勉而大爾。","sortOrder":147},
  {"id":"s_work_ttcm_5_148","chapterId":"ch_work_ttcm_5","text":"伊尹耕於有莘，亦夷之清；出而五就湯、五就桀，亦惠之和；可兼二子，而執義已嚴，圖功已亟，皆勉也。","sortOrder":148},
  {"id":"s_work_ttcm_5_149","chapterId":"ch_work_ttcm_5","text":"若聖人，則性與天道無所勉焉。","sortOrder":149},
  {"id":"s_work_ttcm_5_150","chapterId":"ch_work_ttcm_5","text":"聖人，謂孔子。順性而自止於大中，因天道而自合其時中，不以道自任，故化不可测，伊尹之道疑於孔子，而大與聖分焉，故辨之。","sortOrder":150},
  {"id":"s_work_ttcm_5_151","chapterId":"ch_work_ttcm_5","text":"無所雜者清之極，無所異者和之極。勉而清，非聖人之清；勉而和，非聖人之和。所謂聖者，不勉不思而至焉者也。","sortOrder":151},
  {"id":"s_work_ttcm_5_152","chapterId":"ch_work_ttcm_5","text":"伯夷、柳下惠體清和而熟之，故孟子謂之為聖，化於清和也；伊尹大矣，而有所勉；夷、惠忘乎思勉，而未極其大。清和未極其大，故中不能止；任者未止於中，故大不能化。唯孔子存神而忘跡，有事於天，無事於人，聖功不已，故臻時中之妙，以大中貫萬理而皆安也。","sortOrder":152},
  {"id":"s_work_ttcm_5_153","chapterId":"ch_work_ttcm_5","text":"勉，蓋未能安也；思，蓋未能有也。","sortOrder":153},
  {"id":"s_work_ttcm_5_154","chapterId":"ch_work_ttcm_5","text":"未能安，則見難而必勉；未能有，必待思而得之。見道於外，則非己所固有而不安；存神以居德，則雖未即至而日與道合，作聖之功，其入德之門，審矣。","sortOrder":154},
  {"id":"s_work_ttcm_5_155","chapterId":"ch_work_ttcm_5","text":"不尊德性，則學問從而不道；","sortOrder":155},
  {"id":"s_work_ttcm_5_156","chapterId":"ch_work_ttcm_5","text":"道謂順道而行。不尊德性，徇聞見而已。","sortOrder":156},
  {"id":"s_work_ttcm_5_157","chapterId":"ch_work_ttcm_5","text":"不致廣大，則精微無所立其誠；","sortOrder":157},
  {"id":"s_work_ttcm_5_158","chapterId":"ch_work_ttcm_5","text":"不弘不大，區限於一己而不備天地萬物之實，則窮微察幽，且流於幻妄。","sortOrder":158},
  {"id":"s_work_ttcm_5_159","chapterId":"ch_work_ttcm_5","text":"不極高明，則擇乎中庸，失時措之宜矣。","sortOrder":159},
  {"id":"s_work_ttcm_5_160","chapterId":"ch_work_ttcm_5","text":"不極乎形而上之道以燭天理之自然，則雖動必遵道而與時违。張子此說，與陆子靜之學相近，然所謂廣大高明者，皆體物不遺之實，而非以空虛為高廣。此聖學異端之大辨，學者慎之。","sortOrder":160},
  {"id":"s_work_ttcm_5_161","chapterId":"ch_work_ttcm_5","text":"絕四之外，心可存處，蓋必有事焉，而聖不可知也。","sortOrder":161},
  {"id":"s_work_ttcm_5_162","chapterId":"ch_work_ttcm_5","text":"凡人之心，離此四者則無所用心；異端欲空此四者而寄其心於虛寂惝恍，皆未能有事，聖人豈其然哉？“成性存存，道義之門”，非人所易知爾。","sortOrder":162},
  {"id":"s_work_ttcm_5_163","chapterId":"ch_work_ttcm_5","text":"不得已，當為而為之，雖殺人，皆義也；","sortOrder":163},
  {"id":"s_work_ttcm_5_164","chapterId":"ch_work_ttcm_5","text":"不得已者，理所必行，乘乎時位，已之則失義也。","sortOrder":164},
  {"id":"s_work_ttcm_5_165","chapterId":"ch_work_ttcm_5","text":"有心為之，雖善，皆意也。","sortOrder":165},
  {"id":"s_work_ttcm_5_166","chapterId":"ch_work_ttcm_5","text":"有心為者，立意以求功也。","sortOrder":166},
  {"id":"s_work_ttcm_5_167","chapterId":"ch_work_ttcm_5","text":"正己而物正，大人也；","sortOrder":167},
  {"id":"s_work_ttcm_5_168","chapterId":"ch_work_ttcm_5","text":"大人正己而已，居大正以臨物，皆為己也。得萬物理氣之大同，感物必通矣。","sortOrder":168},
  {"id":"s_work_ttcm_5_169","chapterId":"ch_work_ttcm_5","text":"正己而正物，猶不免有意之累也。","sortOrder":169},
  {"id":"s_work_ttcm_5_170","chapterId":"ch_work_ttcm_5","text":"以欲正物，故正己以正之，賢於藏身不恕者爾，而政教督责，有賢智臨人之意，物不感而忧患積矣。","sortOrder":170},
  {"id":"s_work_ttcm_5_171","chapterId":"ch_work_ttcm_5","text":"有意為善，利之也，假之也；","sortOrder":171},
  {"id":"s_work_ttcm_5_172","chapterId":"ch_work_ttcm_5","text":"利者利其功，假者假其名，非義也。","sortOrder":172},
  {"id":"s_work_ttcm_5_173","chapterId":"ch_work_ttcm_5","text":"無意為善，性之也，由之也。","sortOrder":173},
  {"id":"s_work_ttcm_5_174","chapterId":"ch_work_ttcm_5","text":"性成乎必然，故無意而必為。由者，以其存於中者率而行之也，《孟子》曰：“由仁義行。”","sortOrder":174},
  {"id":"s_work_ttcm_5_175","chapterId":"ch_work_ttcm_5","text":"有意在善，且為未盡，况有意於未善邪！","sortOrder":175},
  {"id":"s_work_ttcm_5_176","chapterId":"ch_work_ttcm_5","text":"意者，人心偶動之機，類因見聞所觸，非天理自然之誠，故不足以盡善。而意不能恒，則為善為惡，皆未可保。故志於仁者，聖功之始；有意為善者，非辟之原。志大而虛含眾理，意小而滯於一隅也。","sortOrder":176},
  {"id":"s_work_ttcm_5_177","chapterId":"ch_work_ttcm_5","text":"仲尼絕四，自始學至成德，竭兩端之教也。","sortOrder":177},
  {"id":"s_work_ttcm_5_178","chapterId":"ch_work_ttcm_5","text":"意、必、固、我，以意為根；必、固、我者，皆其意也，無意而後三者可絕也。初學之始，正義而不謀利，明道而不計功；及其至也，義精仁熟，當為而為，與時偕行，而所過者化矣。聖功之始基，即天德之極致，下學上達，一於此也。","sortOrder":178},
  {"id":"s_work_ttcm_5_179","chapterId":"ch_work_ttcm_5","text":"不得已而後為，至於不得為而止。斯智矣夫！","sortOrder":179},
  {"id":"s_work_ttcm_5_180","chapterId":"ch_work_ttcm_5","text":"不得已，理所不可止，義也；不得為，時所未可為，命也。義命合一存乎理，順理以屈伸動靜，智斯大矣。","sortOrder":180},
  {"id":"s_work_ttcm_5_181","chapterId":"ch_work_ttcm_5","text":"意，有思也；","sortOrder":181},
  {"id":"s_work_ttcm_5_182","chapterId":"ch_work_ttcm_5","text":"未能有諸己而思及之。","sortOrder":182},
  {"id":"s_work_ttcm_5_183","chapterId":"ch_work_ttcm_5","text":"必，有待也；","sortOrder":183},
  {"id":"s_work_ttcm_5_184","chapterId":"ch_work_ttcm_5","text":"期待其必得。","sortOrder":184},
  {"id":"s_work_ttcm_5_185","chapterId":"ch_work_ttcm_5","text":"固，不化也；","sortOrder":185},
  {"id":"s_work_ttcm_5_186","chapterId":"ch_work_ttcm_5","text":"事已過而不忘。","sortOrder":186},
  {"id":"s_work_ttcm_5_187","chapterId":"ch_work_ttcm_5","text":"我，有方也。","sortOrder":187},
  {"id":"s_work_ttcm_5_188","chapterId":"ch_work_ttcm_5","text":"一方之善可據而據之。","sortOrder":188},
  {"id":"s_work_ttcm_5_189","chapterId":"ch_work_ttcm_5","text":"四者有一焉，則與天地為不相似。","sortOrder":189},
  {"id":"s_work_ttcm_5_190","chapterId":"ch_work_ttcm_5","text":"天地誠有而化行，不待有心以應物無意；施生無方，栽培傾覆，無待於物以成德無必；四時運行，成功而不居無固；併育併行，無所擇以為方體無我；四者忘，則體天矣。此言成德之極致，四者絕也。","sortOrder":190},
  {"id":"s_work_ttcm_5_191","chapterId":"ch_work_ttcm_5","text":"天理一貫，則無意、必、固、我之凿。","sortOrder":191},
  {"id":"s_work_ttcm_5_192","chapterId":"ch_work_ttcm_5","text":"隨時循理而自相貫通，順其固然，不凿聰明以自用。","sortOrder":192},
  {"id":"s_work_ttcm_5_193","chapterId":"ch_work_ttcm_5","text":"意、必，固、我，一物存焉，非誠也。","sortOrder":193},
  {"id":"s_work_ttcm_5_194","chapterId":"ch_work_ttcm_5","text":"凿者，理所本無，妄而不誠。","sortOrder":194},
  {"id":"s_work_ttcm_5_195","chapterId":"ch_work_ttcm_5","text":"四者盡去，則直養而無害矣。","sortOrder":195},
  {"id":"s_work_ttcm_5_196","chapterId":"ch_work_ttcm_5","text":"順義以直行，養其中道，無私妄以為之害矣。此始學之存心當絕四者也。","sortOrder":196},
  {"id":"s_work_ttcm_5_197","chapterId":"ch_work_ttcm_5","text":"妄去然後得所止，","sortOrder":197},
  {"id":"s_work_ttcm_5_198","chapterId":"ch_work_ttcm_5","text":"意、必、固、我皆妄也，絕之，則心一於天理流行之實而不妄動。","sortOrder":198},
  {"id":"s_work_ttcm_5_199","chapterId":"ch_work_ttcm_5","text":"得所止，然後得所養而進於大矣。","sortOrder":199},
  {"id":"s_work_ttcm_5_200","chapterId":"ch_work_ttcm_5","text":"養其所止之至善，則知此心與天地同其無方而進於大。","sortOrder":200},
  {"id":"s_work_ttcm_5_201","chapterId":"ch_work_ttcm_5","text":"無所感而起，妄也；","sortOrder":201},
  {"id":"s_work_ttcm_5_202","chapterId":"ch_work_ttcm_5","text":"天下無其事而意忽欲為之，非妄而何？必、固、我皆緣之以成也。","sortOrder":202},
  {"id":"s_work_ttcm_5_203","chapterId":"ch_work_ttcm_5","text":"感而通，誠也；","sortOrder":203},
  {"id":"s_work_ttcm_5_204","chapterId":"ch_work_ttcm_5","text":"神存而誠立，誠則理可肆應，感之而遂通。","sortOrder":204},
  {"id":"s_work_ttcm_5_205","chapterId":"ch_work_ttcm_5","text":"計度而知，昏也；不思而得，素也。","sortOrder":205},
  {"id":"s_work_ttcm_5_206","chapterId":"ch_work_ttcm_5","text":"萬事萬物之不齊，善惡得失二端而已。大經正，大義精，則可否應违，截然分辨，皆素也。計度而知，設未有之形以料其然，是非之理不察者多矣。","sortOrder":206},
  {"id":"s_work_ttcm_5_207","chapterId":"ch_work_ttcm_5","text":"事豫則立，必有教以先之；","sortOrder":207},
  {"id":"s_work_ttcm_5_208","chapterId":"ch_work_ttcm_5","text":"明善乃所以立誠，教者所以明也。","sortOrder":208},
  {"id":"s_work_ttcm_5_209","chapterId":"ch_work_ttcm_5","text":"盡教之善，必精義以研之；","sortOrder":209},
  {"id":"s_work_ttcm_5_210","chapterId":"ch_work_ttcm_5","text":"以義為大經，研其所以然，則物理無不察，所立之教皆誠明矣。","sortOrder":210},
  {"id":"s_work_ttcm_5_211","chapterId":"ch_work_ttcm_5","text":"精義入神，然後立斯立，動斯和矣。敔按：此言“斯立、斯和”，與《論語》本文小異，後《以能問不能章》解“私淑艾”亦然。凡此類註皆如張子之意而通之，不袭程、朱之旨。說見下卷《作者》篇","sortOrder":211},
  {"id":"s_work_ttcm_5_212","chapterId":"ch_work_ttcm_5","text":"得物情事理屈伸相感之義以教人，而審其才质刚柔之所自別，則矯其偏而立斯立，動其天而自和樂以受裁，竭兩端之教，所以中道而立，無貶道以徇人之理。","sortOrder":212},
  {"id":"s_work_ttcm_5_213","chapterId":"ch_work_ttcm_5","text":"志道則進據者不止矣，依仁則小者可遊而不失和矣。","sortOrder":213},
  {"id":"s_work_ttcm_5_214","chapterId":"ch_work_ttcm_5","text":"進而據者，德也；志道，則壹其志於性天之理，其得為真得，愈進而愈可據。小，謂藝也。和者，萬事一致之理。依仁，則藝皆仁之散見，而知合於一貫，明非據事以為德，遊小而忘大也。","sortOrder":214},
  {"id":"s_work_ttcm_5_215","chapterId":"ch_work_ttcm_5","text":"志學然後可以適道，","sortOrder":215},
  {"id":"s_work_ttcm_5_216","chapterId":"ch_work_ttcm_5","text":"志學者大其心以求肖夫道，則無窮之體皆可由之而至。","sortOrder":216},
  {"id":"s_work_ttcm_5_217","chapterId":"ch_work_ttcm_5","text":"強禮然後可與立，","sortOrder":217},
  {"id":"s_work_ttcm_5_218","chapterId":"ch_work_ttcm_5","text":"強者力製其妄，敦行其節，動無非禮，則立身固矣。","sortOrder":218},
  {"id":"s_work_ttcm_5_219","chapterId":"ch_work_ttcm_5","text":"不惑然後可與權。","sortOrder":219},
  {"id":"s_work_ttcm_5_220","chapterId":"ch_work_ttcm_5","text":"理一而有象，有數，有時，有位，數赜而不亂，象变而不驚，時变而行之有素，位殊而處之有常，輕重、大小、屈伸通一而皆齊，可與權也。","sortOrder":220},
  {"id":"s_work_ttcm_5_221","chapterId":"ch_work_ttcm_5","text":"博文以集義，集義以正經，正經然後一以貫天下之道。","sortOrder":221},
  {"id":"s_work_ttcm_5_222","chapterId":"ch_work_ttcm_5","text":"申明不惑可權之義。言博文而集義之，蕃变無所疑惑，則無往而不得其經之正。此強禮之後，立本以親用之學。經正則萬物皆備，而天下之道貫於經之一，故其趨不同而皆仁也。權者，以銖兩而定無方之重輕，一以貫之之象，隨時移易而皆得其平也。明此，則權即經之所自定，而反經合權之邪說愈不足立矣。抑張子以博文之功在能立之後，與朱子以格物為始教之說有異，而《大學》之序，以知止為始，修身為本，朱子謂本始所先，則志道強禮為學之始基，而非志未大，立未定，徒恃博文以幾明善，明矣。","sortOrder":222},
  {"id":"s_work_ttcm_5_223","chapterId":"ch_work_ttcm_5","text":"將窮理而不順理，將精義而不徙義，欲資深且習察，吾不知其智也。","sortOrder":223},
  {"id":"s_work_ttcm_5_224","chapterId":"ch_work_ttcm_5","text":"理者，合萬化於一源；即其固然而研窮以求其至極，則理明。乃舍其屈伸相因之條理而別求之，則恍惚幻妄之見立而理逆矣。義者，一事有一事之宜，因乎時位者也。徙而不執，乃得其隨時處中之大常；若執一義而求盡其微，則楊之為我，墨之兼愛，所以執一而賊道。資深自得，則本立而應無窮；若即耳目所習見習聞者察之，則蔽於所不及見聞，言僻而易窮，如釋氏生滅之說，足以惑愚民而已，奚其智！","sortOrder":224},
  {"id":"s_work_ttcm_5_225","chapterId":"ch_work_ttcm_5","text":"知、仁、勇天下之達德，雖本之有差，及所以知之成之則一也。蓋謂仁者以生知、以安行此五者，智者以學知、以利行此五者，勇者以困知、以勉行此五者。","sortOrder":225},
  {"id":"s_work_ttcm_5_226","chapterId":"ch_work_ttcm_5","text":"朱子之說本此，而以生安為知，學利為仁，則有小異，其說可通參，各有所本。要之，知、仁、勇各有生安、學利、困勉之差，非必分屬三品也。","sortOrder":226},
  {"id":"s_work_ttcm_5_227","chapterId":"ch_work_ttcm_5","text":"中心安仁，無欲而好仁，無畏而惡不仁。天下一人而已，惟责己一身當然爾。","sortOrder":227},
  {"id":"s_work_ttcm_5_228","chapterId":"ch_work_ttcm_5","text":"為天下之一人，豈可概望之天下哉！治天下，以天下而责一人之獨至於己，故養先於教，禮先於刑，所為易從而能化也。","sortOrder":228},
  {"id":"s_work_ttcm_5_229","chapterId":"ch_work_ttcm_5","text":"行之篤者，敦篤雲乎哉！如天道不已而然，篤之至也。","sortOrder":229},
  {"id":"s_work_ttcm_5_230","chapterId":"ch_work_ttcm_5","text":"敦篤者，奋發自強於必為，勇之次者也。如天道不已而然，則仁者之終身無违也。以天體身，以身體道，知其不容已，而何已之有！","sortOrder":230},
  {"id":"s_work_ttcm_5_231","chapterId":"ch_work_ttcm_5","text":"君子於天下，達善達不善，無物我之私。","sortOrder":231},
  {"id":"s_work_ttcm_5_232","chapterId":"ch_work_ttcm_5","text":"達者，通物我於一也。君子所欲者，純乎善而無不善爾。若善則专美於己，不善則聽諸物，是拒物私我而善窮於己，不善矣。","sortOrder":232},
  {"id":"s_work_ttcm_5_233","chapterId":"ch_work_ttcm_5","text":"循理者共悅之，","sortOrder":233},
  {"id":"s_work_ttcm_5_234","chapterId":"ch_work_ttcm_5","text":"己有善則悅，人有善，视之無異於己，是達善也。","sortOrder":234},
  {"id":"s_work_ttcm_5_235","chapterId":"ch_work_ttcm_5","text":"不循理者共改之。","sortOrder":235},
  {"id":"s_work_ttcm_5_236","chapterId":"ch_work_ttcm_5","text":"己有過則改，人有惡，則反求自訟而化之，是達不善也。","sortOrder":236},
  {"id":"s_work_ttcm_5_237","chapterId":"ch_work_ttcm_5","text":"改之者，過雖在人如在己，不忘自訟；","sortOrder":237},
  {"id":"s_work_ttcm_5_238","chapterId":"ch_work_ttcm_5","text":"“萬方有罪，罪在朕躬”，非但天子為然。橫逆不改而三自反，所以盡己而感人也。","sortOrder":238},
  {"id":"s_work_ttcm_5_239","chapterId":"ch_work_ttcm_5","text":"共悅者，善雖在己，蓋取諸人而為，必以與人焉。","sortOrder":239},
  {"id":"s_work_ttcm_5_240","chapterId":"ch_work_ttcm_5","text":"己知之，待人言而行之，歸其功於人，不自有也。","sortOrder":240},
  {"id":"s_work_ttcm_5_241","chapterId":"ch_work_ttcm_5","text":"善以天下，不善以天下，是謂達善達不善。","sortOrder":241},
  {"id":"s_work_ttcm_5_242","chapterId":"ch_work_ttcm_5","text":"形跡化而天理流行，神化之事也。然學者克去己私以存心，則亦何遠之有哉！","sortOrder":242},
  {"id":"s_work_ttcm_5_243","chapterId":"ch_work_ttcm_5","text":"善人雲者，志於仁而未致其學，能無惡而已，“君子名之必可言也”如是。","sortOrder":243},
  {"id":"s_work_ttcm_5_244","chapterId":"ch_work_ttcm_5","text":"學，謂窮理精義以盡性之功，名之曰善人，則其實也。無惡之謂善。","sortOrder":244},
  {"id":"s_work_ttcm_5_245","chapterId":"ch_work_ttcm_5","text":"善人，欲仁而未致其學者也。欲仁，故雖不踐成法，亦不陷於惡，有諸己也。","sortOrder":245},
  {"id":"s_work_ttcm_5_246","chapterId":"ch_work_ttcm_5","text":"仁者心之安，心所不安則不欲，故不陷於惡。乡原則踐成法以自文，而不恤其心之安，故自以為善者皆惡人，雖欲之相似而實相反。","sortOrder":246},
  {"id":"s_work_ttcm_5_247","chapterId":"ch_work_ttcm_5","text":"“不入於室”由不學，故無自而入聖人之室也。","sortOrder":247},
  {"id":"s_work_ttcm_5_248","chapterId":"ch_work_ttcm_5","text":"善人而學，則洗心藏密而入聖人之室矣，聖非不可學而至也。","sortOrder":248},
  {"id":"s_work_ttcm_5_249","chapterId":"ch_work_ttcm_5","text":"惡不仁，故不善未嘗不知；","sortOrder":249},
  {"id":"s_work_ttcm_5_250","chapterId":"ch_work_ttcm_5","text":"惡之誠則知之明，不善當前而與己相拂，如惡惡臭，過前而即知之。","sortOrder":250},
  {"id":"s_work_ttcm_5_251","chapterId":"ch_work_ttcm_5","text":"徒好仁而不惡不仁，則習不察，行不著。","sortOrder":251},
  {"id":"s_work_ttcm_5_252","chapterId":"ch_work_ttcm_5","text":"未嘗取不仁之惡而决擇之，則或見為當然，狎習之而不知惡。故窮異端之妄，必知其不仁之所在，然後別天理之幾微；不然，且有如遊、謝諸子暗淫於其說者矣。司馬君實好善篤而惡惡未精，故蘇子瞻與遊而不知擇。道雖廣而義不得不嚴，君子所以反經而消邪慝也。","sortOrder":252},
  {"id":"s_work_ttcm_5_253","chapterId":"ch_work_ttcm_5","text":"是故徒善未必盡義，徒是未必盡仁；","sortOrder":253},
  {"id":"s_work_ttcm_5_254","chapterId":"ch_work_ttcm_5","text":"徒欲善而不辨其惡以去之，則義有所不正；徒行其是而不防是之或非，則仁有所不純。","sortOrder":254},
  {"id":"s_work_ttcm_5_255","chapterId":"ch_work_ttcm_5","text":"好仁而惡不仁，然後盡仁義之道。","sortOrder":255},
  {"id":"s_work_ttcm_5_256","chapterId":"ch_work_ttcm_5","text":"嚴以拒不仁而辨之於微，然後所好者純粹以精之理行，習之似是而非者不能亂也。故坤之初六，履霜而辨堅冰之至。荀彧唯不知此，是以陷於亂臣賊子之党而不自知。","sortOrder":256},
  {"id":"s_work_ttcm_5_257","chapterId":"ch_work_ttcm_5","text":"“篤信好學”，篤信不好學，不越為善人信士而已。","sortOrder":257},
  {"id":"s_work_ttcm_5_258","chapterId":"ch_work_ttcm_5","text":"越，過也。學以充實其所以然之理，作聖之功也。","sortOrder":258},
  {"id":"s_work_ttcm_5_259","chapterId":"ch_work_ttcm_5","text":"此節舊連下章，傳寫之訛，今別之。","sortOrder":259},
  {"id":"s_work_ttcm_5_260","chapterId":"ch_work_ttcm_5","text":"“好德如好色”，好仁為甚矣。","sortOrder":260},
  {"id":"s_work_ttcm_5_261","chapterId":"ch_work_ttcm_5","text":"求必得也。","sortOrder":261},
  {"id":"s_work_ttcm_5_262","chapterId":"ch_work_ttcm_5","text":"見過而內自訟，惡不仁而不使加乎其身，惡不仁為甚矣。","sortOrder":262},
  {"id":"s_work_ttcm_5_263","chapterId":"ch_work_ttcm_5","text":"不容有纖芥之留也。","sortOrder":263},
  {"id":"s_work_ttcm_5_264","chapterId":"ch_work_ttcm_5","text":"學者不如是，不足以成身，","sortOrder":264},
  {"id":"s_work_ttcm_5_265","chapterId":"ch_work_ttcm_5","text":"成身者，卓然成位乎中，直方刚大而無愧怍於天人也。","sortOrder":265},
  {"id":"s_work_ttcm_5_266","chapterId":"ch_work_ttcm_5","text":"故孔子未見其人，必叹曰“已矣乎”，思之甚也。","sortOrder":266},
  {"id":"s_work_ttcm_5_267","chapterId":"ch_work_ttcm_5","text":"君子之好惡用諸己，小人之好惡用諸物，涵泳孔子之言而重叹之，張子之學所為壁立千仞，而不假人以遊溢之便。先儒或病其已迫，乃誠伪之分，善惡之介，必如此謹嚴而後可與立。彼托於春風沂水之狂而陶然自遂者，未足以开來學、立人道也。","sortOrder":267},
  {"id":"s_work_ttcm_5_268","chapterId":"ch_work_ttcm_5","text":"孫其志於仁則得仁，孫其志於義則得義，惟其敏而已。","sortOrder":268},
  {"id":"s_work_ttcm_5_269","chapterId":"ch_work_ttcm_5","text":"孫，順也，順其志也；志於仁義而不违。志與相依而不违，則不能自已而進於德矣。此釋說命“孫志時敏”之義，明孫非柔缓之謂，乃動與相依，靜與相守，敏求而無須臾之违也。","sortOrder":269},
  {"id":"s_work_ttcm_5_270","chapterId":"ch_work_ttcm_5","text":"博文約禮，由至著入至簡，故可使不得叛而去。","sortOrder":270},
  {"id":"s_work_ttcm_5_271","chapterId":"ch_work_ttcm_5","text":"文者，禮之著見者也。會通於典札，以服身而製心，所謂至簡也。不博考於至著之文，而专有事於心，則虛寂恍惚以為簡，叛道而之於邪矣。","sortOrder":271},
  {"id":"s_work_ttcm_5_272","chapterId":"ch_work_ttcm_5","text":"溫故知新，多識前言往行以畜德，","sortOrder":272},
  {"id":"s_work_ttcm_5_273","chapterId":"ch_work_ttcm_5","text":"溫故知新，非以侈見聞之博；多識而力行之，皆可據之以為德。","sortOrder":273},
  {"id":"s_work_ttcm_5_274","chapterId":"ch_work_ttcm_5","text":"繹舊業而知新益，思昔未至而今至，","sortOrder":274},
  {"id":"s_work_ttcm_5_275","chapterId":"ch_work_ttcm_5","text":"即所聞以验所進。","sortOrder":275},
  {"id":"s_work_ttcm_5_276","chapterId":"ch_work_ttcm_5","text":"緣舊所見聞而察來，","sortOrder":276},
  {"id":"s_work_ttcm_5_277","chapterId":"ch_work_ttcm_5","text":"據所聞，以義類推之。","sortOrder":277},
  {"id":"s_work_ttcm_5_278","chapterId":"ch_work_ttcm_5","text":"皆其義也。","sortOrder":278},
  {"id":"s_work_ttcm_5_279","chapterId":"ch_work_ttcm_5","text":"皆博文之益也。存神以立本，博文以盡其蕃变，道相辅而不可偏废。","sortOrder":279},
  {"id":"s_work_ttcm_5_280","chapterId":"ch_work_ttcm_5","text":"责己者當知天下國家無皆非之理，","sortOrder":280},
  {"id":"s_work_ttcm_5_281","chapterId":"ch_work_ttcm_5","text":"人雖窮凶極惡，亦必有所挟以為名，其所挟之名則亦是也。尧以天下與人而丹朱之傲不爭，若殷之顽民稱亂不止，亦有情理之可谅。倘挟吾之是以摘彼之非，庸詎不可！而己亦有歉矣。大其心以體之，則唯有责己而已。","sortOrder":281},
  {"id":"s_work_ttcm_5_282","chapterId":"ch_work_ttcm_5","text":"故學至於不尤人，學之至也。","sortOrder":282},
  {"id":"s_work_ttcm_5_283","chapterId":"ch_work_ttcm_5","text":"學以窮理而成身，察理於橫逆之中，則義精而仁弘，求己以必盡之善，則誠至而化行，乃聖學之極致。","sortOrder":283},
  {"id":"s_work_ttcm_5_284","chapterId":"ch_work_ttcm_5","text":"聞而不疑則傳言之，見而不殆則學行之，中人之德也。","sortOrder":284},
  {"id":"s_work_ttcm_5_285","chapterId":"ch_work_ttcm_5","text":"傳言，述之為教也；學行，模仿以飾其行也。資聞見以求合於道，可以寡過，非心得也，故夫子亦但以為可以得祿之學。","sortOrder":285},
  {"id":"s_work_ttcm_5_286","chapterId":"ch_work_ttcm_5","text":"聞斯行，好學之徒也；","sortOrder":286},
  {"id":"s_work_ttcm_5_287","chapterId":"ch_work_ttcm_5","text":"不闕疑殆而急於行，好學而不知道。","sortOrder":287},
  {"id":"s_work_ttcm_5_288","chapterId":"ch_work_ttcm_5","text":"見而識其善而未果於行，愈於不知者爾。","sortOrder":288},
  {"id":"s_work_ttcm_5_289","chapterId":"ch_work_ttcm_5","text":"此尤不足有為者，愈於不知而妄作者爾。","sortOrder":289},
  {"id":"s_work_ttcm_5_290","chapterId":"ch_work_ttcm_5","text":"世有不知而作者，蓋凿也，妄也；","sortOrder":290},
  {"id":"s_work_ttcm_5_291","chapterId":"ch_work_ttcm_5","text":"慧巧者則為凿，粗肆者則為妄。","sortOrder":291},
  {"id":"s_work_ttcm_5_292","chapterId":"ch_work_ttcm_5","text":"夫子所不敢也，故曰“我無是也”。","sortOrder":292},
  {"id":"s_work_ttcm_5_293","chapterId":"ch_work_ttcm_5","text":"聖人且不敢，而况未至於聖者乎！","sortOrder":293},
  {"id":"s_work_ttcm_5_294","chapterId":"ch_work_ttcm_5","text":"此章言恃聞見以求合，雖博識而仅為中人之德，若急於行、怠於行者，尤無德之可稱，則聞見之不足恃明矣。然废聞見而以私意测理，則為妄為凿，陷於大惡，乃聖人之所深懼。蓋存神以燭理，則聞見廣而知日新，故學不废博，而必以存神盡心為至善，其立志之規模不同，而後養聖之功以正。大學之道，以格物為先務，而必欲明明德於天下，知止至善以為本始，則見聞不叛而德日充。志不大則所成者小，學者所宜審也。","sortOrder":294},
  {"id":"s_work_ttcm_5_295","chapterId":"ch_work_ttcm_5","text":"以能問不能，以多問寡，私淑艾以教人，隱而未見之仁也。","sortOrder":295},
  {"id":"s_work_ttcm_5_296","chapterId":"ch_work_ttcm_5","text":"私淑艾，謂取人之善以自淑，非以教人，而所以奖進愚不肖者，則教行乎其間矣。蓋以多能下問，則苟有一得者，因問而思所疑，堅所信，則亦求深於道而不自已，其曲成萬物之仁，隱於求益自成之中，教思無窮，愈隱而愈至矣。此大舜之德而顏子學之也。","sortOrder":296},
  {"id":"s_work_ttcm_5_297","chapterId":"ch_work_ttcm_5","text":"為山平地，此仲尼所以惜顏回未至，蓋與互乡之進也。","sortOrder":297},
  {"id":"s_work_ttcm_5_298","chapterId":"ch_work_ttcm_5","text":"志於善則不可量，故不拒童子。顏子殆聖而聖功未成，一簣之差也。聖人望人無已之心如是。","sortOrder":298},
  {"id":"s_work_ttcm_5_299","chapterId":"ch_work_ttcm_5","text":"學者四失：為人則失多，好高則失寡，不察則易，苦難則止。","sortOrder":299},
  {"id":"s_work_ttcm_5_300","chapterId":"ch_work_ttcm_5","text":"為人，求諸人也。失多者，聞見雜而不精；好高者，目困而不能取益於眾；易於為者，不察而為之則妄；知其難者，憚難而置之則怠。四者，才之偏於刚柔者也。知其失而矯之，為人而反求諸己，志高而樂取善，易於為而知慎，知其難而勇於為，然後可與共學。","sortOrder":300},
  {"id":"s_work_ttcm_5_301","chapterId":"ch_work_ttcm_5","text":"學者舍禮義，則飽食終日，無所猷為，與下民一致，所事不逾衣食之間，燕遊之樂爾。","sortOrder":301},
  {"id":"s_work_ttcm_5_302","chapterId":"ch_work_ttcm_5","text":"甚言其賤也。困其心於衣食之計，暇則燕遊，自謂恬淡寡過，不知其為賤丈夫而已。學者讀陶靖節、邵康節之詩，無其志與識而效之，則其违禽獸不遠矣，莊周所謂人莫悲於心死也。","sortOrder":302},
  {"id":"s_work_ttcm_5_303","chapterId":"ch_work_ttcm_5","text":"以心求道，正猶以己知人，終不若彼自立彼為不思而得也。","sortOrder":303},
  {"id":"s_work_ttcm_5_304","chapterId":"ch_work_ttcm_5","text":"以心求道者，見義在外，而以覺了能知之心為心也，性函於心而理備焉，即心而盡其量，則天地萬物之理，皆於吾心之良能而著：心所不及，則道亦不在矣。以己知人，飢飽寒暑得其仿佛爾。若彼自立彼，人各有所自喻，如飢而食、渴而飲，豈待思理之當然哉！吾有父而吾孝之，非求合於大舜；吾有君而吾忠之，非求合於周公；求合者終不得合，用力易而盡心難也。","sortOrder":304},
  {"id":"s_work_ttcm_5_305","chapterId":"ch_work_ttcm_5","text":"考求跡合以免罪戾者，畏罪之人也。故曰考道以為無失。","sortOrder":305},
  {"id":"s_work_ttcm_5_306","chapterId":"ch_work_ttcm_5","text":"以誠心體誠理，則光明刚大，行於忧患生死而自得，何畏之有！無欠者，仅免於罪。","sortOrder":306},
  {"id":"s_work_ttcm_5_307","chapterId":"ch_work_ttcm_5","text":"儒者窮理，故率性可以謂之道。","sortOrder":307},
  {"id":"s_work_ttcm_5_308","chapterId":"ch_work_ttcm_5","text":"窮仁義中正之所自出，皆浑淪太和之固有，而人得之以為性，故率循其性而道即在是。","sortOrder":308},
  {"id":"s_work_ttcm_5_309","chapterId":"ch_work_ttcm_5","text":"浮圖不知窮理而自謂之性，故其說不可推而行。","sortOrder":309},
  {"id":"s_work_ttcm_5_310","chapterId":"ch_work_ttcm_5","text":"釋氏緣見聞之所不及而遂謂之無，故以真空為圓成實性，乃於物理之必感者，無理以處之而欲滅之；滅之而終不可滅，又為“化身無礙”之遁辭，乃至雲“淫坊酒肆皆菩提道場”，其窮見矣。性不可率之以為道，其為幻誕可知；而近世王畿之流，中其邪而不寤，悲夫！","sortOrder":310},
  {"id":"s_work_ttcm_5_311","chapterId":"ch_work_ttcm_5","text":"致曲不貳，則德有定體；","sortOrder":311},
  {"id":"s_work_ttcm_5_312","chapterId":"ch_work_ttcm_5","text":"不貳，無間雜也。定體，成其一曲之善而不失。","sortOrder":312},
  {"id":"s_work_ttcm_5_313","chapterId":"ch_work_ttcm_5","text":"體象誠定，則文節著見；","sortOrder":313},
  {"id":"s_work_ttcm_5_314","chapterId":"ch_work_ttcm_5","text":"體象，體成而可象也。誠定者，實有此理而定於心也。所行者一，因其定立之誠，則成章而條理不紊。","sortOrder":314},
  {"id":"s_work_ttcm_5_315","chapterId":"ch_work_ttcm_5","text":"一曲致文，則餘善兼照；","sortOrder":315},
  {"id":"s_work_ttcm_5_316","chapterId":"ch_work_ttcm_5","text":"餘善，未至之善也。心實有善而推行之，則物理之當然，推之而通，行至而明達矣。","sortOrder":316},
  {"id":"s_work_ttcm_5_317","chapterId":"ch_work_ttcm_5","text":"明能兼照，則必將徒義；","sortOrder":317},
  {"id":"s_work_ttcm_5_318","chapterId":"ch_work_ttcm_5","text":"知及之則行必逮之，蓋所知者以誠而明，自不獨知而已爾。動而曰徙義者，行而不止之謂動。","sortOrder":318},
  {"id":"s_work_ttcm_5_319","chapterId":"ch_work_ttcm_5","text":"誠能徙義，則德自通变；","sortOrder":319},
  {"id":"s_work_ttcm_5_320","chapterId":"ch_work_ttcm_5","text":"徙義以誠，其明益廣，其義益精，变無不通矣。","sortOrder":320},
  {"id":"s_work_ttcm_5_321","chapterId":"ch_work_ttcm_5","text":"能通其变，則圓神無滯。","sortOrder":321},
  {"id":"s_work_ttcm_5_322","chapterId":"ch_work_ttcm_5","text":"至变與大常合而不相悖，以神用而不以跡合，與時偕行，大經常正而协乎時中之道矣。此釋《中庸》之義，而歷序其日進之德，蓋張子自道其致曲之學所自得者，脈絡次序，唯實有其德者喻之，非可以意為想像也。","sortOrder":322},
  {"id":"s_work_ttcm_5_323","chapterId":"ch_work_ttcm_5","text":"有不知則有知，無不知則無知；","sortOrder":323},
  {"id":"s_work_ttcm_5_324","chapterId":"ch_work_ttcm_5","text":"有知者，挟所見以為是，而不知有其不知者在也。聖人無不知，故因時，因位，因物，無先立之成見，而動靜、刚柔皆統乎中道。其曰“吾道一以貫之”，豈聖人之獨知者哉！","sortOrder":324},
  {"id":"s_work_ttcm_5_325","chapterId":"ch_work_ttcm_5","text":"是以鄙夫有問，仲尼竭兩端而空空。","sortOrder":325},
  {"id":"s_work_ttcm_5_326","chapterId":"ch_work_ttcm_5","text":"若有秘密獨知之法，則必不可以語鄙夫矣。竭兩端者，夫子以之而聖，鄙夫以之而寡過，一也。空空，無成心，無定則也，事理皆如其意得爾。","sortOrder":326},
  {"id":"s_work_ttcm_5_327","chapterId":"ch_work_ttcm_5","text":"《易》無思無為，受命乃如响。","sortOrder":327},
  {"id":"s_work_ttcm_5_328","chapterId":"ch_work_ttcm_5","text":"全體乎吉凶悔吝之理，以待物至而應之，故曰“《易》廣矣”。大矣聖人之知無不通，所以合於鬼神。","sortOrder":328},
  {"id":"s_work_ttcm_5_329","chapterId":"ch_work_ttcm_5","text":"聖人一言盡天下之道，雖鄙夫有問，必竭兩端而告之。","sortOrder":329},
  {"id":"s_work_ttcm_5_330","chapterId":"ch_work_ttcm_5","text":"凡事之理，皆一源之变化屈伸也；存神忘跡，則天道物理之廣大皆协於一，而一言可盡，非以己所知之一言強括天下之理也。","sortOrder":330},
  {"id":"s_work_ttcm_5_331","chapterId":"ch_work_ttcm_5","text":"然問者隨才分各足，未必能兩端之盡也。","sortOrder":331},
  {"id":"s_work_ttcm_5_332","chapterId":"ch_work_ttcm_5","text":"非獨鄙夫為然，顏、闵以下，亦各不能體其言之所盡，有所受益而自據為知，所以受教於聖人而不能至於聖。","sortOrder":332},
  {"id":"s_work_ttcm_5_333","chapterId":"ch_work_ttcm_5","text":"教人者必知至學之難易。","sortOrder":333},
  {"id":"s_work_ttcm_5_334","chapterId":"ch_work_ttcm_5","text":"有初學難而後易者，有初學易而後難者，因其序則皆可使之易。","sortOrder":334},
  {"id":"s_work_ttcm_5_335","chapterId":"ch_work_ttcm_5","text":"知人之美惡，","sortOrder":335},
  {"id":"s_work_ttcm_5_336","chapterId":"ch_work_ttcm_5","text":"刚柔、敏純之異。","sortOrder":336},
  {"id":"s_work_ttcm_5_337","chapterId":"ch_work_ttcm_5","text":"當知誰可先傳此，誰將後倦此。","sortOrder":337},
  {"id":"s_work_ttcm_5_338","chapterId":"ch_work_ttcm_5","text":"年強氣盛則樂趨高遠；而使循近小，雖強習必倦。","sortOrder":338},
  {"id":"s_work_ttcm_5_339","chapterId":"ch_work_ttcm_5","text":"若洒扫應對，乃幼而遜弟之事；長後教之，人必倦弊。惟聖人於大德有始有卒，故事無大小，莫非處極。","sortOrder":339},
  {"id":"s_work_ttcm_5_340","chapterId":"ch_work_ttcm_5","text":"聖人合精粗、大小於一致，故幼而志於大道，老而不遺下學。","sortOrder":340},
  {"id":"s_work_ttcm_5_341","chapterId":"ch_work_ttcm_5","text":"今始學之人，未必能繼，妄以大道教之，是誣也。","sortOrder":341},
  {"id":"s_work_ttcm_5_342","chapterId":"ch_work_ttcm_5","text":"繼，謂純其念於道而不間也。若洒扫應對，則可相繼而不倦；故產其志於专謹，且以畢小德而不俟其倦。","sortOrder":342},
  {"id":"s_work_ttcm_5_343","chapterId":"ch_work_ttcm_5","text":"知至學之難易，知德也；","sortOrder":343},
  {"id":"s_work_ttcm_5_344","chapterId":"ch_work_ttcm_5","text":"行焉而皆有得於心，乃可以知其中甘苦之數。","sortOrder":344},
  {"id":"s_work_ttcm_5_345","chapterId":"ch_work_ttcm_5","text":"知其美惡，知人也。","sortOrder":345},
  {"id":"s_work_ttcm_5_346","chapterId":"ch_work_ttcm_5","text":"曲盡人才，知之悉也。","sortOrder":346},
  {"id":"s_work_ttcm_5_347","chapterId":"ch_work_ttcm_5","text":"知其人且知德，故能教人使入德。","sortOrder":347},
  {"id":"s_work_ttcm_5_348","chapterId":"ch_work_ttcm_5","text":"順其所易，矯其所難，成其美，变其惡，教非一也。","sortOrder":348},
  {"id":"s_work_ttcm_5_349","chapterId":"ch_work_ttcm_5","text":"仲尼所以問同而答異，以此。","sortOrder":349},
  {"id":"s_work_ttcm_5_350","chapterId":"ch_work_ttcm_5","text":"理一也，從人者異爾。","sortOrder":350},
  {"id":"s_work_ttcm_5_351","chapterId":"ch_work_ttcm_5","text":"“蒙以養正”，使蒙者不失其正，教人者之功也；盡其道，其唯聖人乎！","sortOrder":351},
  {"id":"s_work_ttcm_5_352","chapterId":"ch_work_ttcm_5","text":"才之偏，蒙也；養之者因所可施可受而使安習之。聖人全體天德之條理，以知人而大明其終始，故教道不一而盡。","sortOrder":352},
  {"id":"s_work_ttcm_5_353","chapterId":"ch_work_ttcm_5","text":"洪鐘未嘗有聲，由扣乃有聲；聖人未嘗有知，由問乃有知。","sortOrder":353},
  {"id":"s_work_ttcm_5_354","chapterId":"ch_work_ttcm_5","text":"洪鐘具大聲之理，聖人統眾理之神，扣焉而無不應，問焉而無不竭。","sortOrder":354},
  {"id":"s_work_ttcm_5_355","chapterId":"ch_work_ttcm_5","text":"“有如時雨化之者”。當其可，乘其間而施之，","sortOrder":355},
  {"id":"s_work_ttcm_5_356","chapterId":"ch_work_ttcm_5","text":"可者，當其時也；間者，可受之機也。","sortOrder":356},
  {"id":"s_work_ttcm_5_357","chapterId":"ch_work_ttcm_5","text":"不待彼有求有為而後教之也。","sortOrder":357},
  {"id":"s_work_ttcm_5_358","chapterId":"ch_work_ttcm_5","text":"有求則疑，有為則成乎過而不易救。","sortOrder":358},
  {"id":"s_work_ttcm_5_359","chapterId":"ch_work_ttcm_5","text":"志常繼則罕譬而喻，言易入則微而臧。","sortOrder":359},
  {"id":"s_work_ttcm_5_360","chapterId":"ch_work_ttcm_5","text":"學者志正而不息，則熟於天理，雖有未知，聞言即喻，不待廣譬也。遜志而敏求，則言易相人，但微言告之而無不盡善。此言教者在養人以善，使之自得，而不在於詳說。","sortOrder":360},
  {"id":"s_work_ttcm_5_361","chapterId":"ch_work_ttcm_5","text":"“凡學，官先事，士先志”，謂有官者先教之事，未官者使正其志焉。","sortOrder":361},
  {"id":"s_work_ttcm_5_362","chapterId":"ch_work_ttcm_5","text":"所謂當其可也。即事以正志，即志以通事，徐引之以達於道。","sortOrder":362},
  {"id":"s_work_ttcm_5_363","chapterId":"ch_work_ttcm_5","text":"志者，教之大倫而言也。","sortOrder":363},
  {"id":"s_work_ttcm_5_364","chapterId":"ch_work_ttcm_5","text":"大倫，可以統眾事者。正其志於道，則事理皆得，故教者尤以正志為本。","sortOrder":364},
  {"id":"s_work_ttcm_5_365","chapterId":"ch_work_ttcm_5","text":"道以德者，運於物外，使自化也。","sortOrder":365},
  {"id":"s_work_ttcm_5_366","chapterId":"ch_work_ttcm_5","text":"物者，政刑之跡。","sortOrder":366},
  {"id":"s_work_ttcm_5_367","chapterId":"ch_work_ttcm_5","text":"故諭人者，先其意而遜其志可也。","sortOrder":367},
  {"id":"s_work_ttcm_5_368","chapterId":"ch_work_ttcm_5","text":"意之所發，或善或惡，因一時之感動而成乎私；志則未有事而豫定者也。意發必見諸事，則非政刑不能正之；豫養於先，使其志馴習乎正，悅而安焉，則志定而意雖不純，亦自覺而思改矣。","sortOrder":368},
  {"id":"s_work_ttcm_5_369","chapterId":"ch_work_ttcm_5","text":"蓋志意兩言，則志公而意私爾。","sortOrder":369},
  {"id":"s_work_ttcm_5_370","chapterId":"ch_work_ttcm_5","text":"未有事，則理無所倚而易明。惟庸人無志爾，苟有志，自合天下之公是。意則見己為是，不恤天下之公是，故志正而後可治其意，無志而唯意之所為，雖善不固，惡則無不為矣。故大學之先誠意，為欲正其心者言也，非不問志之正否而但责之意也。教人者知志意公私之別，不爭於私之已成，而唯養其虛公之心，所謂“禁於未發之謂豫”也。","sortOrder":370},
  {"id":"s_work_ttcm_5_371","chapterId":"ch_work_ttcm_5","text":"能使不仁者仁，仁之施厚矣；故聖人併答仁智以“舉直错諸枉”。","sortOrder":371},
  {"id":"s_work_ttcm_5_372","chapterId":"ch_work_ttcm_5","text":"“仁智合一”之說本此。","sortOrder":372},
  {"id":"s_work_ttcm_5_373","chapterId":"ch_work_ttcm_5","text":"以责人之心责己則盡道，所謂“君子之道四，丘未能一焉”者也；","sortOrder":373},
  {"id":"s_work_ttcm_5_374","chapterId":"ch_work_ttcm_5","text":"责人則明，责己或暗，私利蔽之也。去其蔽，责己自嚴。","sortOrder":374},
  {"id":"s_work_ttcm_5_375","chapterId":"ch_work_ttcm_5","text":"以愛己之心愛人則盡仁，所謂“施諸己而不願亦勿施於人”者也；君子之自愛，無徇私之欲惡，無不可推以及人。","sortOrder":375},
  {"id":"s_work_ttcm_5_376","chapterId":"ch_work_ttcm_5","text":"以眾人望人則易從，所謂“以人治人改而止”者也；","sortOrder":376},
  {"id":"s_work_ttcm_5_377","chapterId":"ch_work_ttcm_5","text":"大倫大經，民可使由之，雖不可使知之而勿過求焉。","sortOrder":377},
  {"id":"s_work_ttcm_5_378","chapterId":"ch_work_ttcm_5","text":"此君子所以责己、责人、愛人之三術也。","sortOrder":378},
  {"id":"s_work_ttcm_5_379","chapterId":"ch_work_ttcm_5","text":"術者，道之神妙。","sortOrder":379},
  {"id":"s_work_ttcm_5_380","chapterId":"ch_work_ttcm_5","text":"有受教之心，雖蠻貊可教；為道既異，雖党類難相為類。","sortOrder":380},
  {"id":"s_work_ttcm_5_381","chapterId":"ch_work_ttcm_5","text":"君子道大教弘而不為異端所辱者，當其可，乘其間而已。","sortOrder":381},
  {"id":"s_work_ttcm_5_382","chapterId":"ch_work_ttcm_5","text":"大人所存，蓋必以天下為度。","sortOrder":382},
  {"id":"s_work_ttcm_5_383","chapterId":"ch_work_ttcm_5","text":"念之所存，萬物一源之太和，天下常在其度內。","sortOrder":383},
  {"id":"s_work_ttcm_5_384","chapterId":"ch_work_ttcm_5","text":"故孟子教人，雖货色之欲，親長之私，達諸天下而後已。","sortOrder":384},
  {"id":"s_work_ttcm_5_385","chapterId":"ch_work_ttcm_5","text":"天下之公欲，即理也；人人之獨得，即公也。道本可達，故無所不可，達之於天下。","sortOrder":385},
  {"id":"s_work_ttcm_5_386","chapterId":"ch_work_ttcm_5","text":"子而孚化之，","sortOrder":386},
  {"id":"s_work_ttcm_5_387","chapterId":"ch_work_ttcm_5","text":"子，禽鳥卵也；孚，抱也。有其质而未成者，養之以和以变其氣质，猶鳥之伏子。","sortOrder":387},
  {"id":"s_work_ttcm_5_388","chapterId":"ch_work_ttcm_5","text":"“眾好者”翼飛之，","sortOrder":388},
  {"id":"s_work_ttcm_5_389","chapterId":"ch_work_ttcm_5","text":"眾好，喻禽鳥之少好者；翼飛，喻哺而長其翼，教之習飛也。志學已正而引之以達，使盡其才，猶鳥之教習飛。","sortOrder":389},
  {"id":"s_work_ttcm_5_390","chapterId":"ch_work_ttcm_5","text":"則吾道行矣。","sortOrder":390},
  {"id":"s_work_ttcm_5_391","chapterId":"ch_work_ttcm_5","text":"師道立，善人多，道明則行。","sortOrder":391},
  {"id":"s_work_ttcm_6_1","chapterId":"ch_work_ttcm_6","text":"張子正蒙註卷五","sortOrder":1},
  {"id":"s_work_ttcm_6_2","chapterId":"ch_work_ttcm_6","text":"至當篇","sortOrder":2},
  {"id":"s_work_ttcm_6_3","chapterId":"ch_work_ttcm_6","text":"此篇推前篇未盡之旨而征之於日用，尤為切近。然皆存神知化之理所一以貫之者，所謂易簡而天下之理得也。篇內言易簡、知幾而歸本於大經之正，學者反而求之於父子君臣之間，以察吾性之所不容已，則天之所以為天，人之所以為人，聖之所以為聖，無待他求之矣。","sortOrder":3},
  {"id":"s_work_ttcm_6_4","chapterId":"ch_work_ttcm_6","text":"至當之謂德，百順之謂福。","sortOrder":4},
  {"id":"s_work_ttcm_6_5","chapterId":"ch_work_ttcm_6","text":"當於理則順。於事至當，則善协於一，無不順矣。事無所逆之謂福。","sortOrder":5},
  {"id":"s_work_ttcm_6_6","chapterId":"ch_work_ttcm_6","text":"德者福之基，福者德之致，無入而非百順，故君子樂得其道。","sortOrder":6},
  {"id":"s_work_ttcm_6_7","chapterId":"ch_work_ttcm_6","text":"以德致福，因其理之所宜，乃順也。無入不順，故尧水、湯旱而天下安，文王囚、孔子厄而心志適，皆樂也，樂則福莫大蔫。小人以得其欲為樂，非福也。","sortOrder":7},
  {"id":"s_work_ttcm_6_8","chapterId":"ch_work_ttcm_6","text":"循天下之理之謂道，得天下之理之謂德，","sortOrder":8},
  {"id":"s_work_ttcm_6_9","chapterId":"ch_work_ttcm_6","text":"理者，物之同然，事之所以然也。顯著於天下，循而得之，非若異端孤守一己之微明，離理氣以為道德。","sortOrder":9},
  {"id":"s_work_ttcm_6_10","chapterId":"ch_work_ttcm_6","text":"故曰“易簡之善配至德”。","sortOrder":10},
  {"id":"s_work_ttcm_6_11","chapterId":"ch_work_ttcm_6","text":"至德，天之德也。順天下之理而不凿，五倫百行晓然易知而簡能，天之所以行四時、生百物之理在此矣。","sortOrder":11},
  {"id":"s_work_ttcm_6_12","chapterId":"ch_work_ttcm_6","text":"“大德敦化”，仁智合一，厚且化也；","sortOrder":12},
  {"id":"s_work_ttcm_6_13","chapterId":"ch_work_ttcm_6","text":"敦，存仁之體也；化，廣知之用也。大德存仁於神而化無不行，智皆因仁而發，仁至而智無不明。化者，厚之化也，故化而不傷其厚，舉错而枉者直，此理也。","sortOrder":13},
  {"id":"s_work_ttcm_6_14","chapterId":"ch_work_ttcm_6","text":"“小德川流”，淵泉時出之也。敔按：此言用涵於體，體著於用，小德大德，一誠而已","sortOrder":14},
  {"id":"s_work_ttcm_6_15","chapterId":"ch_work_ttcm_6","text":"淵泉則無不流，惟其時而已，故德以敦仁為本。","sortOrder":15},
  {"id":"s_work_ttcm_6_16","chapterId":"ch_work_ttcm_6","text":"“大德不逾閒，小德出入可也”，大者器，則小者不器矣。","sortOrder":16},
  {"id":"s_work_ttcm_6_17","chapterId":"ch_work_ttcm_6","text":"器者，有成之謂。仁成而純乎至善，為不逾之矩則。小德如川之流，禮有損益，義有变通，運而不滯，而皆协於至一，故任讓、進退、质文、刑賞，隨施而可。","sortOrder":17},
  {"id":"s_work_ttcm_6_18","chapterId":"ch_work_ttcm_6","text":"德者，得也，凡有性质而可有者也。","sortOrder":18},
  {"id":"s_work_ttcm_6_19","chapterId":"ch_work_ttcm_6","text":"得，謂得之於天也。凡物皆太和氤氲之氣所成，有质則有性，有性則有德，草木鳥獸非無性無德，而质與人殊，則性亦殊，德亦殊爾。若均是人也，所得者皆一陰一陽繼善之理氣，才雖或偏而德必同，故曰“人無有不善”。","sortOrder":19},
  {"id":"s_work_ttcm_6_20","chapterId":"ch_work_ttcm_6","text":"“日新之謂盛德”，過而不有，不凝滯於心知之細也。","sortOrder":20},
  {"id":"s_work_ttcm_6_21","chapterId":"ch_work_ttcm_6","text":"日新盛德，乾之道，天之化也。人能體之，所知所能，皆以行乎不得不然而不居，則後日之德非倚前日之德，而德日盛矣。時已過而猶執者，必非自然之理，乃心知緣於耳目一曲之明爾，未嘗不為道所散見，而不足以盡道體之弘。","sortOrder":21},
  {"id":"s_work_ttcm_6_22","chapterId":"ch_work_ttcm_6","text":"浩然無害，則天地合德；","sortOrder":22},
  {"id":"s_work_ttcm_6_23","chapterId":"ch_work_ttcm_6","text":"以理御氣，周遍於萬事萬物，而不以己私自屈撓，天之健，地之順也。","sortOrder":23},
  {"id":"s_work_ttcm_6_24","chapterId":"ch_work_ttcm_6","text":"照無偏系，則日月合明；","sortOrder":24},
  {"id":"s_work_ttcm_6_25","chapterId":"ch_work_ttcm_6","text":"以理燭物，則順逆、美惡皆容光必照，好而知惡，惡而知美，無所私也，如日月之明矣。","sortOrder":25},
  {"id":"s_work_ttcm_6_26","chapterId":"ch_work_ttcm_6","text":"天地同流，則四時合序；","sortOrder":26},
  {"id":"s_work_ttcm_6_27","chapterId":"ch_work_ttcm_6","text":"因天之時，順地之理，時行則行，時止則止，一四時之過化而日新也。","sortOrder":27},
  {"id":"s_work_ttcm_6_28","chapterId":"ch_work_ttcm_6","text":"酬酢不倚，則鬼神合吉凶。","sortOrder":28},
  {"id":"s_work_ttcm_6_29","chapterId":"ch_work_ttcm_6","text":"應天下以喜怒刑賞，善善惡惡各如其理，鬼神之福善禍淫無成心者，此爾。故鬼神不可以淫祀祷，君子不可以非道悅。","sortOrder":29},
  {"id":"s_work_ttcm_6_30","chapterId":"ch_work_ttcm_6","text":"天地合德，日月合明，然後能無方體；能無方體，然後能無我。","sortOrder":30},
  {"id":"s_work_ttcm_6_31","chapterId":"ch_work_ttcm_6","text":"方體，以用言；我，以體言。凡方而皆其可行之方，凡體而皆其可立之體，則私意盡而廓然大公，與天同化矣。無方體者，神之妙；無我者，聖之純。","sortOrder":31},
  {"id":"s_work_ttcm_6_32","chapterId":"ch_work_ttcm_6","text":"禮器則藏諸身，用無不利。","sortOrder":32},
  {"id":"s_work_ttcm_6_33","chapterId":"ch_work_ttcm_6","text":"禮器，禮運曲禮之要。禮器於多寡、大小、高下、质文，因其理之當然，隨時位而变易，度數無方而不立所尚以為體，故曰“禮器是故大備”，言盡其变以合於大常也。全乎不一之器，藏於心以為斟酌之用，故無不协其宜，而至當以成百順。","sortOrder":33},
  {"id":"s_work_ttcm_6_34","chapterId":"ch_work_ttcm_6","text":"禮運雲者，語其達也；禮器雲者，語其成也。","sortOrder":34},
  {"id":"s_work_ttcm_6_35","chapterId":"ch_work_ttcm_6","text":"運雲者，運行於器之中，所以為體天地日月之化而酬酢於人事者也。達，謂通理而為萬事之本；成者，見於事物而各成其事也。","sortOrder":35},
  {"id":"s_work_ttcm_6_36","chapterId":"ch_work_ttcm_6","text":"達與成，體與用之道合。","sortOrder":36},
  {"id":"s_work_ttcm_6_37","chapterId":"ch_work_ttcm_6","text":"禮運，體也；禮器，用也。達則無不可成，成者成其達也。體必有用，顯諸仁也。用即用其體，藏諸用也。達以成而成其所達，則體用合矣。","sortOrder":37},
  {"id":"s_work_ttcm_6_38","chapterId":"ch_work_ttcm_6","text":"體與用，大人之事備矣。","sortOrder":38},
  {"id":"s_work_ttcm_6_39","chapterId":"ch_work_ttcm_6","text":"體無不成，用無不達，大人宰製萬物、役使群動之事備矣。","sortOrder":39},
  {"id":"s_work_ttcm_6_40","chapterId":"ch_work_ttcm_6","text":"禮器不泥於小者，則無非禮之禮，非義之義。蓋大者器，則出入小者，莫非時中也。","sortOrder":40},
  {"id":"s_work_ttcm_6_41","chapterId":"ch_work_ttcm_6","text":"禮器備而斟酌合乎時位，無所泥矣；不備，則貴多有時而侈，貴寡有時而陋，貴高有時而亢，貴下有時而屈，自以為禮義，而非天理之節文，吾心之裁製矣。達乎禮之運，而合吉凶、高下以不逾於大中之矩，故度數之小，可出可入，用無不利。","sortOrder":41},
  {"id":"s_work_ttcm_6_42","chapterId":"ch_work_ttcm_6","text":"子夏謂“大德不逾閒，小德出入可也”，斯之謂爾。","sortOrder":42},
  {"id":"s_work_ttcm_6_43","chapterId":"ch_work_ttcm_6","text":"出入，損益也。雖有損益，不逾天地日月運行各正之矩，非謂小節之可以自恣也。","sortOrder":43},
  {"id":"s_work_ttcm_6_44","chapterId":"ch_work_ttcm_6","text":"禮器則大矣，","sortOrder":44},
  {"id":"s_work_ttcm_6_45","chapterId":"ch_work_ttcm_6","text":"能備知禮器而用之，大人之事備矣。蓋禮器雲者，以天理之節文合而為大器，不倚於一偏者也。","sortOrder":45},
  {"id":"s_work_ttcm_6_46","chapterId":"ch_work_ttcm_6","text":"修性而非小成者與！","sortOrder":46},
  {"id":"s_work_ttcm_6_47","chapterId":"ch_work_ttcm_6","text":"性，謂理之具於心者；修，如修道之修，修著其品節也。修性而不小成，所以盡吾性之能而非獨明其器數。","sortOrder":47},
  {"id":"s_work_ttcm_6_48","chapterId":"ch_work_ttcm_6","text":"運則化矣，","sortOrder":48},
  {"id":"s_work_ttcm_6_49","chapterId":"ch_work_ttcm_6","text":"禮運本天地日月之化而推行於節文，非知化者不能體。","sortOrder":49},
  {"id":"s_work_ttcm_6_50","chapterId":"ch_work_ttcm_6","text":"達順而樂亦至焉爾。","sortOrder":50},
  {"id":"s_work_ttcm_6_51","chapterId":"ch_work_ttcm_6","text":"通達大順，得中而無不和，則於多寡、大小、高下、质文之損益，曲畅人情之安矣。律呂之高下，人心之豫悅，此理而已。蓋中和一致，中本於和而中則和，著於聲容，原於神化，陰陽均而動靜以時，所謂“明則有禮樂”也。故禮器以運為本。敔按：中本於和，謂時中本於太和","sortOrder":51},
  {"id":"s_work_ttcm_6_52","chapterId":"ch_work_ttcm_6","text":"“萬物皆備於我”，言萬物皆有素於我也；","sortOrder":52},
  {"id":"s_work_ttcm_6_53","chapterId":"ch_work_ttcm_6","text":"素，猶豫也，言豫知其理而無不得。此孟子自言其所得之辭。","sortOrder":53},
  {"id":"s_work_ttcm_6_54","chapterId":"ch_work_ttcm_6","text":"“反身而誠”，謂行無不慊於心，則樂莫大焉。","sortOrder":54},
  {"id":"s_work_ttcm_6_55","chapterId":"ch_work_ttcm_6","text":"知之盡，則實踐之而已。實踐之，乃心所素知，行焉皆順，故樂莫大焉。","sortOrder":55},
  {"id":"s_work_ttcm_6_56","chapterId":"ch_work_ttcm_6","text":"未能如玉，不足以成德；未能成德，不足以孚天下。","sortOrder":56},
  {"id":"s_work_ttcm_6_57","chapterId":"ch_work_ttcm_6","text":"如玉，表里純善而無疵也。放道而行，非誠有其得於心者，雖善，不足以感人。","sortOrder":57},
  {"id":"s_work_ttcm_6_58","chapterId":"ch_work_ttcm_6","text":"“修己以安人。”修己而不安人，不行乎妻子，况可愾於天下？","sortOrder":58},
  {"id":"s_work_ttcm_6_59","chapterId":"ch_work_ttcm_6","text":"愾，氣相感也。修己之盡者，成如玉之德，無私無欲而通天下之志；如其不然，刻意尚行，矯物以為高，妻子不可行也。德至則感通自神，豈以己之是臨物之非哉！","sortOrder":59},
  {"id":"s_work_ttcm_6_60","chapterId":"ch_work_ttcm_6","text":"“正己而不求於人”，不願乎外之盛者與！","sortOrder":60},
  {"id":"s_work_ttcm_6_61","chapterId":"ch_work_ttcm_6","text":"君子之不願乎外，非恬淡寡欲而已，隨所處而必居正，則自無外願也。盛，謂道之大者。","sortOrder":61},
  {"id":"s_work_ttcm_6_62","chapterId":"ch_work_ttcm_6","text":"仁道有本，近譬諸身，推以及人，乃其方也。","sortOrder":62},
  {"id":"s_work_ttcm_6_63","chapterId":"ch_work_ttcm_6","text":"心備萬物之理，愛之本也。推以及人，於此求之而已。","sortOrder":63},
  {"id":"s_work_ttcm_6_64","chapterId":"ch_work_ttcm_6","text":"必欲博施濟眾，扩之天下，施之無窮，必有聖人之才，能弘其道。","sortOrder":64},
  {"id":"s_work_ttcm_6_65","chapterId":"ch_work_ttcm_6","text":"用之大者因其才，性其本也，性全而才或不足，故聖人不易及。然心日盡則才亦日生；故求仁者但求之心，不以才之不足為患。","sortOrder":65},
  {"id":"s_work_ttcm_6_66","chapterId":"ch_work_ttcm_6","text":"製行以己，非所以同乎人。必物之同者，己則異矣；必物之是者，己則非矣。","sortOrder":66},
  {"id":"s_work_ttcm_6_67","chapterId":"ch_work_ttcm_6","text":"製行必極於至善，非人之所能企及也。德盛則物自化，己有善而必人之己若，則立異而成乎過。君子不忍人之不善，唯嚴於责己而已。","sortOrder":67},
  {"id":"s_work_ttcm_6_68","chapterId":"ch_work_ttcm_6","text":"此節舊分為二，今合之。","sortOrder":68},
  {"id":"s_work_ttcm_6_69","chapterId":"ch_work_ttcm_6","text":"能通天下之志者，為能感人心。聖人同乎人而無我，故和平天下，莫盛於感人心。","sortOrder":69},
  {"id":"s_work_ttcm_6_70","chapterId":"ch_work_ttcm_6","text":"天下之人，嗜好習尚移其志者無所不有，而推其本原，莫非道之所許。故不但兵農禮樂為所必務，即私親、私長、好货、好色，亦可以其情之正者為性之所弘。聖人達於太和氤氲之化，不執己之是以臨人之非，則君子樂得其道，小人樂得其欲，無不可感也，所以天下共化於和。敔按：《易》鹹卦彖曰：“聖人感人心而天下和平。”張子引伸其義，見聖人之化天下，唯無朋從而光大故也。","sortOrder":70},
  {"id":"s_work_ttcm_6_71","chapterId":"ch_work_ttcm_6","text":"道遠人則不仁。","sortOrder":71},
  {"id":"s_work_ttcm_6_72","chapterId":"ch_work_ttcm_6","text":"仁者，己與萬物所同得之生理。倚其偏至之識才，可為人所不能為者，老、釋是已。己與天下殊異而不相通，則一身以外皆痿痹也；發焉而為己甚之行，必惨薄而寡恩。","sortOrder":72},
  {"id":"s_work_ttcm_6_73","chapterId":"ch_work_ttcm_6","text":"易簡理得則知幾，知幾然後經可正。","sortOrder":73},
  {"id":"s_work_ttcm_6_74","chapterId":"ch_work_ttcm_6","text":"易簡，乾、坤之至德，萬物同原之理。知此，則吾所自生微動之幾，為萬化所自始，皆知矣。即此而見君臣、父子、崑弟、夫婦、朋友天叙天秩不容已之愛敬，則親、義、序、別、信，皆原本德性以盡其誠，而無出入、過不及於大經之中。蓋惟盡性者為能盡倫，非獨行之士，一往孤行之忠孝也。","sortOrder":74},
  {"id":"s_work_ttcm_6_75","chapterId":"ch_work_ttcm_6","text":"天下達道五，其生民之大經乎！經正則道前定，事豫立，不疑其所行，利用安身之要莫先焉。","sortOrder":75},
  {"id":"s_work_ttcm_6_76","chapterId":"ch_work_ttcm_6","text":"終身所行，自此五者而外無事，仁民、愛物、製禮、作樂，全此五者而已。五者豫立，則推行萬事，無不安利；舍此則妄揣冥行，事赜而志亂，吉凶悔吝莫知所從。張子推天道人性变化之極而歸之於正經，則窮神知化，要以反求大正之中道，此由博反約之實學，《西銘》一此意廣言之也。","sortOrder":76},
  {"id":"s_work_ttcm_6_77","chapterId":"ch_work_ttcm_6","text":"性天經，然後仁義行，故曰“有父子、君臣、上下，然後禮義有所错。”","sortOrder":77},
  {"id":"s_work_ttcm_6_78","chapterId":"ch_work_ttcm_6","text":"性天經者，知大倫之秩叙自天，本吾性自然之理，成之為性，安焉而無所勉強也。能然，則愛敬之用扩充而無不行矣。禮義，仁義之用也，舍五者而泛施之，禮伪而義私，冥行而鮮當，刑名、法術之所以违天、拂人、戕仁義也。","sortOrder":78},
  {"id":"s_work_ttcm_6_79","chapterId":"ch_work_ttcm_6","text":"仁通極其性，故能致養而靜以安；","sortOrder":79},
  {"id":"s_work_ttcm_6_80","chapterId":"ch_work_ttcm_6","text":"仁者，生理之函於心者也；感於物而發，而不待感而始有，性之藏也。人能心依於仁，則不為物欲所遷以致養於性，靜存不失。","sortOrder":80},
  {"id":"s_work_ttcm_6_81","chapterId":"ch_work_ttcm_6","text":"義致行其知，故能盡文而動以变。","sortOrder":81},
  {"id":"s_work_ttcm_6_82","chapterId":"ch_work_ttcm_6","text":"義者，心所喻之物則也；知者，仁所發見之覺也。誠之明，知之良，因而行之，則仁之節文具而变動不居，無所往而非仁矣。","sortOrder":82},
  {"id":"s_work_ttcm_6_83","chapterId":"ch_work_ttcm_6","text":"此章言義所以成仁之用，行無非義，則盡仁而复性矣。","sortOrder":83},
  {"id":"s_work_ttcm_6_84","chapterId":"ch_work_ttcm_6","text":"義，仁之動也；流於義者於仁或傷。","sortOrder":84},
  {"id":"s_work_ttcm_6_85","chapterId":"ch_work_ttcm_6","text":"仁存而必動，以加於物，則因物之宜而製之。然因物審處，則於本體之所存有相悖害者矣。故處物必不忘其靜之所函，而屢顧以求安。","sortOrder":85},
  {"id":"s_work_ttcm_6_86","chapterId":"ch_work_ttcm_6","text":"仁，體之常也；過於仁者於義或害。","sortOrder":86},
  {"id":"s_work_ttcm_6_87","chapterId":"ch_work_ttcm_6","text":"體之常者，貫動靜而恒也。乃方動而過持以靜，則於事幾之变失矣。故必靜存萬里、化裁不滯之圓神，曲成萬物而不遺。","sortOrder":87},
  {"id":"s_work_ttcm_6_88","chapterId":"ch_work_ttcm_6","text":"此章言仁義之相為體用，動靜、刚柔以相濟而不可偏也。","sortOrder":88},
  {"id":"s_work_ttcm_6_89","chapterId":"ch_work_ttcm_6","text":"立不易方，安於仁而已乎！","sortOrder":89},
  {"id":"s_work_ttcm_6_90","chapterId":"ch_work_ttcm_6","text":"乎，叹美之辭。隨所立而不易其方，義也。然唯安於仁者，動而不失其靜之理，故雖遇变而恒貞。","sortOrder":90},
  {"id":"s_work_ttcm_6_91","chapterId":"ch_work_ttcm_6","text":"此章言仁所以立義之體，仁熟則義自正矣。以上三章，互相發明仁義合一之理。蓋道之所自行，德之所自立，原其所本，則陰陽也，刚柔也，仁義也，當其氤氲而太和，初未嘗分而為兩；盡性合天者，得其合一、兩在之神，則義不流，仁不過，而天下之理無不得。若徒袭仁義之跡，則或致兩妨，故學者以存神為要。《易》以仁配陰，以義配陽，釋者紛紜，唯此以一靜一動為言，發明特切。然在天，在地，在人，理同而撰異，初不可畫然分屬，讀者得意而舍跡可也。","sortOrder":91},
  {"id":"s_work_ttcm_6_92","chapterId":"ch_work_ttcm_6","text":"安所遇而敦仁，故其愛有常心，有常心則物被常愛也。","sortOrder":92},
  {"id":"s_work_ttcm_6_93","chapterId":"ch_work_ttcm_6","text":"安遇所以自處，敦仁則必及物。然人之所以不能常其愛者，境遇不齊而心為之变；心為境遷，則雖欲敦愛，而利於物者恐傷於己，仁不容不薄矣。若得丧安危，無遇不安，則苟可以愛而仁無所吝，一言一介，無遷就規避之心，不必泽及天下而後為仁也。","sortOrder":93},
  {"id":"s_work_ttcm_6_94","chapterId":"ch_work_ttcm_6","text":"大海無润，因暍者有润；至仁無恩，因不足者有恩。樂天安土，所居而安，不累於物也。","sortOrder":94},
  {"id":"s_work_ttcm_6_95","chapterId":"ch_work_ttcm_6","text":"無恩者，非以為恩於物而施之，愛猶大海，非為润人之渴而有水也。君子自存其仁，不為境遷，則物不能累己，而己亦不致為物之累，則因物之利而利之而已。若沾沾然以為恩於物為功，則必需势位以行愛而愛窮。","sortOrder":95},
  {"id":"s_work_ttcm_6_96","chapterId":"ch_work_ttcm_6","text":"愛人然後能保其身，張子自註：寡助則親戚畔之能保其身則不擇地而安；自註：不能有其身，則資安處以置之不擇地而安，蓋所達者大矣；","sortOrder":96},
  {"id":"s_work_ttcm_6_97","chapterId":"ch_work_ttcm_6","text":"四海之廣，古今之变，順逆险阻，無不可行矣。","sortOrder":97},
  {"id":"s_work_ttcm_6_98","chapterId":"ch_work_ttcm_6","text":"大達於天，則成性成身矣。","sortOrder":98},
  {"id":"s_work_ttcm_6_99","chapterId":"ch_work_ttcm_6","text":"大而化之，仁熟而無土不安，合於天德之無不覆，聖矣。無所遇而不安於性，以成身也。故舜之飯糗茹草，與為天子一也；孔子之困厄，與尧、舜一也。通乎屈伸而安身利用，下學而上達矣。","sortOrder":99},
  {"id":"s_work_ttcm_6_100","chapterId":"ch_work_ttcm_6","text":"此章之指，言近而指遠，尤學者所宜加省。","sortOrder":100},
  {"id":"s_work_ttcm_6_101","chapterId":"ch_work_ttcm_6","text":"上達則樂天，樂天則不怨；下學則治己，治己則不無尤。","sortOrder":101},
  {"id":"s_work_ttcm_6_102","chapterId":"ch_work_ttcm_6","text":"上達於天，屈伸之理合一，而不疑時位之不齊，皆天理之自然，富貴厚吾生，貧賤玉吾成，何怨乎！治己則去物之累，以责人之心责己，愛己之心愛人，不見人之可尤矣。聖之所以合天安土，敦仁而已。","sortOrder":102},
  {"id":"s_work_ttcm_6_103","chapterId":"ch_work_ttcm_6","text":"不知來物，不足以利用；","sortOrder":103},
  {"id":"s_work_ttcm_6_104","chapterId":"ch_work_ttcm_6","text":"來物，方來之事也。人之所以不利用者，據現在之境遇而執之也，若知將來之变不可测而守其中道，則無不利矣。","sortOrder":104},
  {"id":"s_work_ttcm_6_105","chapterId":"ch_work_ttcm_6","text":"不通晝夜，未足以樂天。","sortOrder":105},
  {"id":"s_work_ttcm_6_106","chapterId":"ch_work_ttcm_6","text":"屈伸往來之理，莫著於晝夜。晝必夜，夜必晝，晝以成夜，夜以息晝，故尧、舜之伸必有孔子之屈，一時之屈所以善萬世之伸，天之所命無不可樂也。","sortOrder":106},
  {"id":"s_work_ttcm_6_107","chapterId":"ch_work_ttcm_6","text":"聖人成其德，不私其身，故乾乾自強，所以成之於天爾。","sortOrder":107},
  {"id":"s_work_ttcm_6_108","chapterId":"ch_work_ttcm_6","text":"身者，天之化也；德者，身之職也。乾乾自強，以成其德。以共天職，而歸健順之理氣於天地，則生事畢而無累於太虛，非以聖智之功名私有於其身，所遇之通塞何足以系其念哉！","sortOrder":108},
  {"id":"s_work_ttcm_6_109","chapterId":"ch_work_ttcm_6","text":"君子於仁聖，為不厭，誨不倦，然且自謂不能，蓋所以為能也。","sortOrder":109},
  {"id":"s_work_ttcm_6_110","chapterId":"ch_work_ttcm_6","text":"仁聖之道，乾乾不息而已。","sortOrder":110},
  {"id":"s_work_ttcm_6_111","chapterId":"ch_work_ttcm_6","text":"能不過人，故與人爭能，以能病人；","sortOrder":111},
  {"id":"s_work_ttcm_6_112","chapterId":"ch_work_ttcm_6","text":"少有所得，則其氣驕；廣大無涯，則其志遜。","sortOrder":112},
  {"id":"s_work_ttcm_6_113","chapterId":"ch_work_ttcm_6","text":"大則天地合德，自不見其能也。","sortOrder":113},
  {"id":"s_work_ttcm_6_114","chapterId":"ch_work_ttcm_6","text":"時行物生，豈以今歲之成功自居，而息其將來之化哉！","sortOrder":114},
  {"id":"s_work_ttcm_6_115","chapterId":"ch_work_ttcm_6","text":"君子之道達諸夭，故聖人有所不能；","sortOrder":115},
  {"id":"s_work_ttcm_6_116","chapterId":"ch_work_ttcm_6","text":"道通於天之化，君子之所必為著明；而天之盛德大業，古今互成而不迫，生殺併行而不悖，聖人能因時裁成，而不能效其廣大。","sortOrder":116},
  {"id":"s_work_ttcm_6_117","chapterId":"ch_work_ttcm_6","text":"夫婦之智淆諸物，故大人有所不與。","sortOrder":117},
  {"id":"s_work_ttcm_6_118","chapterId":"ch_work_ttcm_6","text":"夫婦之智偶合於道，而天明孤發，幾與蜂蚁之君臣、虎狼之父子相雜，故自經溝渎之信，從井救人之仁，夫婦能之而大人弗為，大人貞一以動也。","sortOrder":118},
  {"id":"s_work_ttcm_6_119","chapterId":"ch_work_ttcm_6","text":"匹夫匹婦，非夭之聰明不成其為人。","sortOrder":119},
  {"id":"s_work_ttcm_6_120","chapterId":"ch_work_ttcm_6","text":"非能自立人道，天使之然爾。","sortOrder":120},
  {"id":"s_work_ttcm_6_121","chapterId":"ch_work_ttcm_6","text":"聖人，天聰明之盡者爾。","sortOrder":121},
  {"id":"s_work_ttcm_6_122","chapterId":"ch_work_ttcm_6","text":"天之聰明，在人者有隱有顯，有变有通，聖人以聖學扩大而誠體之，則盡有天之聰明，而视聽無非理矣。","sortOrder":122},
  {"id":"s_work_ttcm_6_123","chapterId":"ch_work_ttcm_6","text":"大人者，有容物，無去物；有愛物，無徇物，天之道然。","sortOrder":123},
  {"id":"s_work_ttcm_6_124","chapterId":"ch_work_ttcm_6","text":"大人不離物以自高，不絕物以自絜，廣愛以全仁，而不违道以幹譽，皆順天之理以行也。","sortOrder":124},
  {"id":"s_work_ttcm_6_125","chapterId":"ch_work_ttcm_6","text":"天以直養萬物，","sortOrder":125},
  {"id":"s_work_ttcm_6_126","chapterId":"ch_work_ttcm_6","text":"萬物併育於天地之間，天順其理而養之，無所擇於靈蠢、清濁，撓其种性，而後可致其養直也。","sortOrder":126},
  {"id":"s_work_ttcm_6_127","chapterId":"ch_work_ttcm_6","text":"代天而理物者，曲成而不害其直，斯盡道矣。","sortOrder":127},
  {"id":"s_work_ttcm_6_128","chapterId":"ch_work_ttcm_6","text":"道立於廣大而化之以神，則天下之人無不可感，天下之物無不可用，愚明、強柔，治教皆洽焉；聲色、货利，仁義皆行焉，非有所必去，有所或徇也。若老、釋之徒，絕物以孤立，而徇人以示愛，违天自用，不祥久矣。","sortOrder":128},
  {"id":"s_work_ttcm_6_129","chapterId":"ch_work_ttcm_6","text":"志大則才大事業大，故曰“可大”，又曰“富有”；志久則氣久德性久，故曰“可久”，又曰“日新”。","sortOrder":129},
  {"id":"s_work_ttcm_6_130","chapterId":"ch_work_ttcm_6","text":"志立則學思從之，故才日益而聰明盛，成乎富有；志之篤，則氣從其志，以不倦而日新，蓋言學者德業之始終，一以志為大小久暫之區量，故《大學》教人，必以知止為始，孔子之聖，唯志學之異於人也。天載物，則神化感通之事，下學雖所不逮，而志必至焉，不可泥於近小，以苶其氣而弃其才也。","sortOrder":130},
  {"id":"s_work_ttcm_6_131","chapterId":"ch_work_ttcm_6","text":"清為異物，和為徇物。","sortOrder":131},
  {"id":"s_work_ttcm_6_132","chapterId":"ch_work_ttcm_6","text":"清之過，和之流也。","sortOrder":132},
  {"id":"s_work_ttcm_6_133","chapterId":"ch_work_ttcm_6","text":"金和而玉節之則不過，知運而貞一之則不流。","sortOrder":133},
  {"id":"s_work_ttcm_6_134","chapterId":"ch_work_ttcm_6","text":"金堅玉白，而養之以和，節之以润，則至清而不異，智能運物，而恒貞於一，則至和而不徇，孔子之所以聖不可知，其涵養德性者密也。","sortOrder":134},
  {"id":"s_work_ttcm_6_135","chapterId":"ch_work_ttcm_6","text":"此章上二句舊分一章，“金和”以下連下章，今正之。","sortOrder":135},
  {"id":"s_work_ttcm_6_136","chapterId":"ch_work_ttcm_6","text":"道所以可久可大，以其肖天地而不離也；","sortOrder":136},
  {"id":"s_work_ttcm_6_137","chapterId":"ch_work_ttcm_6","text":"肖其化則可大，乾乾不息而不離則可久。","sortOrder":137},
  {"id":"s_work_ttcm_6_138","chapterId":"ch_work_ttcm_6","text":"與天地不相似，其违道也遠矣。","sortOrder":138},
  {"id":"s_work_ttcm_6_139","chapterId":"ch_work_ttcm_6","text":"意欲之私，限於所知而不恒，非天理之自然也。釋、老執一己之生滅，畏死厭難，偷安而苟息，曲學拘聞見之習而不通於神化，以自畫而小成，邪正雖殊，其與道违一也。“道二，仁與不仁而已”，天與人之辨焉耳。","sortOrder":139},
  {"id":"s_work_ttcm_6_140","chapterId":"ch_work_ttcm_6","text":"久者一之純，大者兼之富。","sortOrder":140},
  {"id":"s_work_ttcm_6_141","chapterId":"ch_work_ttcm_6","text":"不雜以私伪，故純；久，非专執不化也。窮天地萬物之理，故富；大，非故為高遠也。兼之富者，合萬於一；一之純者，一以貫萬。一故神，兩在故不测，下學而上達矣。","sortOrder":141},
  {"id":"s_work_ttcm_6_142","chapterId":"ch_work_ttcm_6","text":"大則直不絞，方不刿，故不習而無不利。","sortOrder":142},
  {"id":"s_work_ttcm_6_143","chapterId":"ch_work_ttcm_6","text":"大則通於萬理而無不順，直不傷激，方不矯廉，坤之六二，居中得正，刚柔合德，純一而大，天下之理皆伸而情皆得，故無不利。","sortOrder":143},
  {"id":"s_work_ttcm_6_144","chapterId":"ch_work_ttcm_6","text":"易簡然後能知险阻，","sortOrder":144},
  {"id":"s_work_ttcm_6_145","chapterId":"ch_work_ttcm_6","text":"以险阻之心察险阻，則险阻不在天下而先生於心，心有险阻，天下之险阻愈变矣。以乾之純於健，自強而不恤天下之险，其道易；以坤之純於順，厚載而不忧天下之阻，其道簡。险阻萬变，奉此以臨之，情形自著，而吾有以治之矣。","sortOrder":145},
  {"id":"s_work_ttcm_6_146","chapterId":"ch_work_ttcm_6","text":"易簡理得，然後一以貫天下之道。","sortOrder":146},
  {"id":"s_work_ttcm_6_147","chapterId":"ch_work_ttcm_6","text":"险阻可通，况其大常者乎。","sortOrder":147},
  {"id":"s_work_ttcm_6_148","chapterId":"ch_work_ttcm_6","text":"易簡故能說諸心，知险阻故能研諸慮；","sortOrder":148},
  {"id":"s_work_ttcm_6_149","chapterId":"ch_work_ttcm_6","text":"道在己而無忧，故悅，悅而忧惑不妄起，則所慮者正而自精。不然，在己無大常之理，物至情移，愈变而愈迷矣。","sortOrder":149},
  {"id":"s_work_ttcm_6_150","chapterId":"ch_work_ttcm_6","text":"知幾為能以屈為伸。","sortOrder":150},
  {"id":"s_work_ttcm_6_151","chapterId":"ch_work_ttcm_6","text":"幾者，動靜必然之介，伸必有屈，屈所以伸，動靜之理然也。以屈為伸，則善吾生者善吾死，死生不易其素，一以貫久大之德矣。乾之“知存亡進退而不失其正”，坤之“先迷後得”，所以平天下之险阻也","sortOrder":151},
  {"id":"s_work_ttcm_6_152","chapterId":"ch_work_ttcm_6","text":"“君子無所爭”，彼伸則我屈，知也。","sortOrder":152},
  {"id":"s_work_ttcm_6_153","chapterId":"ch_work_ttcm_6","text":"陰陽、柔刚，迭相為屈伸，君子、小人各乘其時，知者知此，則量自弘矣。","sortOrder":153},
  {"id":"s_work_ttcm_6_154","chapterId":"ch_work_ttcm_6","text":"彼屈則吾不伸而自伸矣。","sortOrder":154},
  {"id":"s_work_ttcm_6_155","chapterId":"ch_work_ttcm_6","text":"彼屈則我自伸，不待鳴其屈以求伸。","sortOrder":155},
  {"id":"s_work_ttcm_6_156","chapterId":"ch_work_ttcm_6","text":"又何爭！","sortOrder":156},
  {"id":"s_work_ttcm_6_157","chapterId":"ch_work_ttcm_6","text":"屈亦無爭，伸亦無爭，保吾大正而已。","sortOrder":157},
  {"id":"s_work_ttcm_6_158","chapterId":"ch_work_ttcm_6","text":"無不容然後盡屈伸之道，至虛則無所不伸矣。","sortOrder":158},
  {"id":"s_work_ttcm_6_159","chapterId":"ch_work_ttcm_6","text":"於人有君子小人，於世有治亂，於己有富貴、貧賤、夷狄、患難，天地之化至大，其屈伸非旦夕之效也。人所以不能盡屈伸之道者，遇屈則不能容也。至虛，則古今如旦暮，人我如影响，交感於太和之中而神不損。龍蛇蟄而全身，尺蠖之伸在屈，浩然之氣，亘古今而常伸。“言忠信，行篤敬，雖之夷狄不可弃也”，利害於我何有焉？","sortOrder":159},
  {"id":"s_work_ttcm_6_160","chapterId":"ch_work_ttcm_6","text":"“君子無所爭”，知幾於屈伸之感而已。","sortOrder":160},
  {"id":"s_work_ttcm_6_161","chapterId":"ch_work_ttcm_6","text":"屈伸必相感者也，無待於求伸，而又何爭！","sortOrder":161},
  {"id":"s_work_ttcm_6_162","chapterId":"ch_work_ttcm_6","text":"“精義入神”，交神於不爭之地，順莫甚焉，利莫大焉。“天下何思何慮”，明屈伸之变，斯盡之矣。","sortOrder":162},
  {"id":"s_work_ttcm_6_163","chapterId":"ch_work_ttcm_6","text":"精義，則伸有伸之義，屈有屈之義，知進退、存亡而不失其正。入神者，否泰消長之機化有变而神不变。故六十四象而乾、坤之德在焉，陰陽之多少，位之得失，因乎屈伸爾。知達於此，理無不順，用無不利矣。彼與物爭者，唯於天下生其思慮，而不自悅其心，研其慮，故憧憧爾思而不寧，唯己小而天下大，異於大人之無不知而無不容也。","sortOrder":163},
  {"id":"s_work_ttcm_6_164","chapterId":"ch_work_ttcm_6","text":"此章舊分為二，今合之。","sortOrder":164},
  {"id":"s_work_ttcm_6_165","chapterId":"ch_work_ttcm_6","text":"勝兵之勝，勝在至柔，明屈伸之神爾。","sortOrder":165},
  {"id":"s_work_ttcm_6_166","chapterId":"ch_work_ttcm_6","text":"兵以求伸者也，而勝以柔，屈伸相感之神，於斯見矣。善為國者不師，至於用兵爭勝，至能全體屈伸之神，窥見其幾而已。老氏遂奉此以為教，欲伸固屈，以柔勝刚，與至虛能容之誠相违遠矣。讀者當分別觀之。","sortOrder":166},
  {"id":"s_work_ttcm_6_167","chapterId":"ch_work_ttcm_6","text":"敬斯有立，有立斯有為。","sortOrder":167},
  {"id":"s_work_ttcm_6_168","chapterId":"ch_work_ttcm_6","text":"莊敬自持，而後耳目口體從心而定其物，則卓然知有我之立於兩間，不因物而遷矣。有我而備萬之誠存焉，奉此以有為而仁義行。","sortOrder":168},
  {"id":"s_work_ttcm_6_169","chapterId":"ch_work_ttcm_6","text":"敬，禮之舆也，不敬則禮不行。","sortOrder":169},
  {"id":"s_work_ttcm_6_170","chapterId":"ch_work_ttcm_6","text":"敬者，禮之神也，神運乎儀文之中，然後安以敏而天下孚之。","sortOrder":170},
  {"id":"s_work_ttcm_6_171","chapterId":"ch_work_ttcm_6","text":"“恭敬、撙節、退讓以明禮”，仁之至也，愛道之極也。","sortOrder":171},
  {"id":"s_work_ttcm_6_172","chapterId":"ch_work_ttcm_6","text":"斂情自約以順愛敬之節，心之不容已而禮行焉；不崇己以替天下，仁愛之心至矣。故复禮為為仁之極致，心之德即愛之理也。","sortOrder":172},
  {"id":"s_work_ttcm_6_173","chapterId":"ch_work_ttcm_6","text":"己不勉明，則人無從倡，道無從弘，教無從成矣。","sortOrder":173},
  {"id":"s_work_ttcm_6_174","chapterId":"ch_work_ttcm_6","text":"既明其理，尤詳其事，君子之所以耄而好學，有餘善以及天下後世也。","sortOrder":174},
  {"id":"s_work_ttcm_6_175","chapterId":"ch_work_ttcm_6","text":"禮，直斯清，撓斯昏，","sortOrder":175},
  {"id":"s_work_ttcm_6_176","chapterId":"ch_work_ttcm_6","text":"順天理自然之節文為直；眾論起而撓之，奉吾直而折之乃不亂。欧陽修、張孚敬皆成乎一說，惟其曲而不直也。敔按：《濮議》及《興獻帝謚說》，行乎一時而理不順乎人心，故曰“曲而不直”","sortOrder":176},
  {"id":"s_work_ttcm_6_177","chapterId":"ch_work_ttcm_6","text":"和斯利，樂斯安。","sortOrder":177},
  {"id":"s_work_ttcm_6_178","chapterId":"ch_work_ttcm_6","text":"順心理而直行，和於人心而己心適矣；安而利，孰得而撓之！退讓為節，直清為守，合斯二者而後可以言禮。","sortOrder":178},
  {"id":"s_work_ttcm_6_179","chapterId":"ch_work_ttcm_6","text":"將致用者，幾不可缓；","sortOrder":179},
  {"id":"s_work_ttcm_6_180","chapterId":"ch_work_ttcm_6","text":"心之初動，善惡分趣之幾，辨之於早，缓則私意起而惑之矣。","sortOrder":180},
  {"id":"s_work_ttcm_6_181","chapterId":"ch_work_ttcm_6","text":"思進德者，徙義必精；","sortOrder":181},
  {"id":"s_work_ttcm_6_182","chapterId":"ch_work_ttcm_6","text":"辨其幾，則已取義矣；而義必精而後盡理之極致，故進此而研之以充類至盡。","sortOrder":182},
  {"id":"s_work_ttcm_6_183","chapterId":"ch_work_ttcm_6","text":"此君子所以立多凶多懼之世，乾乾德業，不少懈於趨時也。","sortOrder":183},
  {"id":"s_work_ttcm_6_184","chapterId":"ch_work_ttcm_6","text":"義精，則有以處凶懼而無不正矣。趨時者，與時行而不息，宵晝瞬息，皆有研幾徙義之功也。","sortOrder":184},
  {"id":"s_work_ttcm_6_185","chapterId":"ch_work_ttcm_6","text":"“動靜不失其時”，義之極也。","sortOrder":185},
  {"id":"s_work_ttcm_6_186","chapterId":"ch_work_ttcm_6","text":"動靜，以事言，謂行止進退也。不失其時者，順天下之大經，合於時之中，研幾速而徙義精，一於正也。","sortOrder":186},
  {"id":"s_work_ttcm_6_187","chapterId":"ch_work_ttcm_6","text":"義極則光明著見，","sortOrder":187},
  {"id":"s_work_ttcm_6_188","chapterId":"ch_work_ttcm_6","text":"晓然可以對於天下後世而無不白之隱。","sortOrder":188},
  {"id":"s_work_ttcm_6_189","chapterId":"ch_work_ttcm_6","text":"唯其時，物前定而不疚。","sortOrder":189},
  {"id":"s_work_ttcm_6_190","chapterId":"ch_work_ttcm_6","text":"物，事也。前定者，義精而誠立，因時必發而皆當。","sortOrder":190},
  {"id":"s_work_ttcm_6_191","chapterId":"ch_work_ttcm_6","text":"有吉凶利害，然後人謀作，大業生；","sortOrder":191},
  {"id":"s_work_ttcm_6_192","chapterId":"ch_work_ttcm_6","text":"此屈伸相感之機也。故尧有不肖之子，舜有不順之親，文王有不仁之君，周公有不軌之兄，孔子有不道之世，皆惟其時而精其義，歸於大正。","sortOrder":192},
  {"id":"s_work_ttcm_6_193","chapterId":"ch_work_ttcm_6","text":"若無施不宜，則何業之有！","sortOrder":193},
  {"id":"s_work_ttcm_6_194","chapterId":"ch_work_ttcm_6","text":"無施不宜，所遇皆順也。知此，則不怨不尤，而樂天敦仁於不息矣。","sortOrder":194},
  {"id":"s_work_ttcm_6_195","chapterId":"ch_work_ttcm_6","text":"“天下何思何慮”，行其所無辜，斯可矣。","sortOrder":195},
  {"id":"s_work_ttcm_6_196","chapterId":"ch_work_ttcm_6","text":"所謂天下有道不與易也。處变則不怨尤，處常則不妄作，皆與時偕行之精義，非以己意思慮之。","sortOrder":196},
  {"id":"s_work_ttcm_6_197","chapterId":"ch_work_ttcm_6","text":"舊本分為二，今合之。","sortOrder":197},
  {"id":"s_work_ttcm_6_198","chapterId":"ch_work_ttcm_6","text":"知崇，天也，形而上也；通晝夜而知，其知崇矣。","sortOrder":198},
  {"id":"s_work_ttcm_6_199","chapterId":"ch_work_ttcm_6","text":"知崇者，知天者也，知形而上之神也。化有晦明而人用為晝夜，神則不息，通晝夜而無異行；略屈伸之跡而知其恒運之理，知合於天，崇矣。時有屈伸而君子之神無間，《易》曰“知崇法天”，法其不息也。","sortOrder":199},
  {"id":"s_work_ttcm_6_200","chapterId":"ch_work_ttcm_6","text":"知及之而不以禮性之，非己有也。","sortOrder":200},
  {"id":"s_work_ttcm_6_201","chapterId":"ch_work_ttcm_6","text":"禮之節文見於事為，形而下之器，地之质也。性，安也。形而上之道，有形而即麗於器，能體禮而安之，然後即此视聽言動之中，天理流行而無不通貫，乃以凝形而上之道於己，否則亦高談性命而無實矣。","sortOrder":201},
  {"id":"s_work_ttcm_6_202","chapterId":"ch_work_ttcm_6","text":"故知禮成性而道義出，如天地位而易行。","sortOrder":202},
  {"id":"s_work_ttcm_6_203","chapterId":"ch_work_ttcm_6","text":"知極於高明，禮不遺於卑下，如天地奠位而变化合一，以成乎乾、坤之德業，聖學所以極高明而道中庸也。","sortOrder":203},
  {"id":"s_work_ttcm_6_204","chapterId":"ch_work_ttcm_6","text":"知德之難言，知之至也。","sortOrder":204},
  {"id":"s_work_ttcm_6_205","chapterId":"ch_work_ttcm_6","text":"天下之所言者，道而已。德則通極於天，存之以神，和之於氣，至虛而誠有，體一而用兩；若倚於一事一念之所得而畅言之，則非德矣。知已至，乃知其言之難。","sortOrder":205},
  {"id":"s_work_ttcm_6_206","chapterId":"ch_work_ttcm_6","text":"孟子謂“我於辭命而不能”，又謂“浩然之氣難言”。《易》謂“不言而信，存乎德行”，又以尚辭為聖人之道，非知德，達乎是哉？","sortOrder":206},
  {"id":"s_work_ttcm_6_207","chapterId":"ch_work_ttcm_6","text":"聖賢知德之難言，然必言之而後自信其知之已至，故以尚辭為道之極致。“性與天道不可得而聞”，“修辭立誠”，言其所自知，非中人以下所可與聞也。","sortOrder":207},
  {"id":"s_work_ttcm_6_208","chapterId":"ch_work_ttcm_6","text":"暗然，修於德也；","sortOrder":208},
  {"id":"s_work_ttcm_6_209","chapterId":"ch_work_ttcm_6","text":"入德以凝道。","sortOrder":209},
  {"id":"s_work_ttcm_6_210","chapterId":"ch_work_ttcm_6","text":"的然，著於外也。","sortOrder":210},
  {"id":"s_work_ttcm_6_211","chapterId":"ch_work_ttcm_6","text":"附托於道而不知德。","sortOrder":211},
  {"id":"s_work_ttcm_6_212","chapterId":"ch_work_ttcm_6","text":"作者篇","sortOrder":212},
  {"id":"s_work_ttcm_6_213","chapterId":"ch_work_ttcm_6","text":"此下四篇，皆釋《論語》《孟子》之義，其說有與程、朱異者。蓋聖賢之微言大義，曲畅旁通，雖立言本有定指，而學者躬行心得，各有契合，要以取益於身心，非如訓詁家拘文之小辨。讀者就其異而察其同，斯得之矣。","sortOrder":213},
  {"id":"s_work_ttcm_6_214","chapterId":"ch_work_ttcm_6","text":"“作者七人”，伏羲、神農、黃帝、尧、舜、禹、湯，製法興王之道，非有述於人者也。","sortOrder":214},
  {"id":"s_work_ttcm_6_215","chapterId":"ch_work_ttcm_6","text":"周監於二代，則亦述而已矣。夫子言此，以明作者既盛，則道在述而不容更作。若嬴秦之坏法亂紀與異端之非聖誣民，皆妄作之過也。","sortOrder":215},
  {"id":"s_work_ttcm_6_216","chapterId":"ch_work_ttcm_6","text":"以知人為難，故不輕去未彰之罪；以安民為難，故不輕变未厭之君。","sortOrder":216},
  {"id":"s_work_ttcm_6_217","chapterId":"ch_work_ttcm_6","text":"謂尧不知誅四凶也。变者，誅其君而別立君，謂三苗也；三苗不服，民猶從之。","sortOrder":217},
  {"id":"s_work_ttcm_6_218","chapterId":"ch_work_ttcm_6","text":"及舜而去之，","sortOrder":218},
  {"id":"s_work_ttcm_6_219","chapterId":"ch_work_ttcm_6","text":"攝位時事。","sortOrder":219},
  {"id":"s_work_ttcm_6_220","chapterId":"ch_work_ttcm_6","text":"尧君德，故得以厚吾終；舜臣德，故不敢不虔其始。","sortOrder":220},
  {"id":"s_work_ttcm_6_221","chapterId":"ch_work_ttcm_6","text":"君以容蓄厚載為德，臣以行法無私為德，所以皆合時中。","sortOrder":221},
  {"id":"s_work_ttcm_6_222","chapterId":"ch_work_ttcm_6","text":"“稽眾舍己”，尧也；“與人為善”，舜也；“聞善言則拜”，禹也；“用人惟己，改過不吝”，湯也；“不聞亦式，不諫亦入”，文王也。","sortOrder":222},
  {"id":"s_work_ttcm_6_223","chapterId":"ch_work_ttcm_6","text":"“惟己”，當作“惟其賢”。不聞、不諫，謂不待聞人之諫而旁求眾論也。聖人之德，一於無我，至虛而受天下之善。","sortOrder":223},
  {"id":"s_work_ttcm_6_224","chapterId":"ch_work_ttcm_6","text":"“別生分類”，孟子所謂“明庶物、察人倫”者與！","sortOrder":224},
  {"id":"s_work_ttcm_6_225","chapterId":"ch_work_ttcm_6","text":"人物同受太和之氣以生，本一也；而資生於父母、根荄，則草木鳥獸之與人，其生別矣。人之有君臣、父子、崑弟、夫婦、朋友，親疏上下各從其類者分矣。於其同而見萬物一體之仁，於其異而見親親、仁民、愛物之義，明察及此，則由仁義行者皆天理之自然，不待思勉矣。","sortOrder":225},
  {"id":"s_work_ttcm_6_226","chapterId":"ch_work_ttcm_6","text":"“象忧亦忧，象喜亦喜”，所過者化也，與人為善也，隱惡也，所覺者先也。敔按：所過者化，謂感人以誠；所覺者先，謂察理獨精","sortOrder":226},
  {"id":"s_work_ttcm_6_227","chapterId":"ch_work_ttcm_6","text":"“象忧亦忧，象喜亦喜”之心，誠信之不可测者也，故必疑其為伪。約略言之，想見其心有此四者。蓋聖人之心，大公無我，唯至仁充足，隨所感通，即沛然若决江河而莫御，於天下且然，而况其弟乎！","sortOrder":227},
  {"id":"s_work_ttcm_6_228","chapterId":"ch_work_ttcm_6","text":"“好問”，“好察邇言”，“隱惡扬善”，“與人為善”，“象忧亦忧，象喜亦喜”，皆行其所無事也，過化也，不藏怒也，不宿怨也。","sortOrder":228},
  {"id":"s_work_ttcm_6_229","chapterId":"ch_work_ttcm_6","text":"聖人之心，純一於善，惡之過於前，知其惡而已，不复留於胸中以累其神明，惡去而忘之矣。善則留，惡則去，如天地雖有不祥之物而不以累其生成。學者知此，則惡稱人之惡而勿攻；若其惡不仁雖至，乃唯以自嚴而不加乎其身；所以養吾心之善氣而泯惡於無跡，善日滋而惡日遠，誠養心之要也。","sortOrder":229},
  {"id":"s_work_ttcm_6_230","chapterId":"ch_work_ttcm_6","text":"舜之孝，湯、武之武，雖順逆不同，其為不幸均矣。","sortOrder":230},
  {"id":"s_work_ttcm_6_231","chapterId":"ch_work_ttcm_6","text":"瞽瞍底豫，順也；桀放、紂誅，逆也。","sortOrder":231},
  {"id":"s_work_ttcm_6_232","chapterId":"ch_work_ttcm_6","text":"明庶物，察人倫，然後能精義致用，性其仁而行。","sortOrder":232},
  {"id":"s_work_ttcm_6_233","chapterId":"ch_work_ttcm_6","text":"舜惟一率其所生之性而審於親疏輕重之辨，故人悅之，天下將歸，皆不足以易其孺慕，而一言一動一舉念之間，無非曲盡其為子之義，故坦然行之，無所忧疑，而終至於底豫，所謂性之也。","sortOrder":233},
  {"id":"s_work_ttcm_6_234","chapterId":"ch_work_ttcm_6","text":"湯放桀，有慚德而不敢赦，執中之難也如是。","sortOrder":234},
  {"id":"s_work_ttcm_6_235","chapterId":"ch_work_ttcm_6","text":"欲赦之則可無慚，而負上帝求莫之心；欲不赦則順乎天，而於己君臣之義有所不安，擇於二者之中，輕重之權衡難定，故雖决於奉天讨罪，而慚終不釋。","sortOrder":235},
  {"id":"s_work_ttcm_6_236","chapterId":"ch_work_ttcm_6","text":"天下有道而已，在人在己不見其有間也，“立賢無方”也如是。","sortOrder":236},
  {"id":"s_work_ttcm_6_237","chapterId":"ch_work_ttcm_6","text":"乃其得天下以後不以己意行爵賞，明其本志唯在化無道為有道，與天下之賢者共治之，而昔之致讨有罪，非己私而可無慚於天下，曲折以合於義，所謂反之也。事至於不幸，雖聖人難之矣。明物察倫以安於仁，此易簡之理所以配至德，非湯、武之所幾及也。","sortOrder":237},
  {"id":"s_work_ttcm_6_238","chapterId":"ch_work_ttcm_6","text":"“立賢無方”，此湯之所以公天下而不疑；","sortOrder":238},
  {"id":"s_work_ttcm_6_239","chapterId":"ch_work_ttcm_6","text":"初行放伐之時，必且疑賢者之效尤，湯唯無求固其位之心，故天下安之。漢誅功臣，宋削藩镇，皆昧屈伸之義而己私勝也。","sortOrder":239},
  {"id":"s_work_ttcm_6_240","chapterId":"ch_work_ttcm_6","text":"周公所以於其身望道而必吾見也。","sortOrder":240},
  {"id":"s_work_ttcm_6_241","chapterId":"ch_work_ttcm_6","text":"舊註：“周公”上疑有“坐以待日”四字。","sortOrder":241},
  {"id":"s_work_ttcm_6_242","chapterId":"ch_work_ttcm_6","text":"“帝臣不蔽”，言桀有罪，己不敢违天縱赦；既已克之，今天下莫非上帝之臣，善惡皆不可掩，惟帝擇而命之，己不敢不聽。","sortOrder":242},
  {"id":"s_work_ttcm_6_243","chapterId":"ch_work_ttcm_6","text":"湯放桀而不即自立，欲唯天所命、民所歸而戴之為君，其公天下之心如是。所以既有天下之後，立賢無方，不倚親臣為藩衛，如周之監殷，張子以此獨稱湯而略武王。","sortOrder":243},
  {"id":"s_work_ttcm_6_244","chapterId":"ch_work_ttcm_6","text":"“虞、芮质厥成”，訟獄者不之紂而之文王。文王之生所以縻系於天下，由於多助於四友之臣故爾。","sortOrder":244},
  {"id":"s_work_ttcm_6_245","chapterId":"ch_work_ttcm_6","text":"縻系，為人所系屬。文王無求天下歸己之心，乃四友之臣宣其德化，而天下慕之爾。","sortOrder":245},
  {"id":"s_work_ttcm_6_246","chapterId":"ch_work_ttcm_6","text":"以杞包瓜，文王事紂之道也。","sortOrder":246},
  {"id":"s_work_ttcm_6_247","chapterId":"ch_work_ttcm_6","text":"杞柳為筐也，瓜易坏者，包椷而藏之，使無急坏。","sortOrder":247},
  {"id":"s_work_ttcm_6_248","chapterId":"ch_work_ttcm_6","text":"厚下以防中潰，盡人謀而聽天命者與！","sortOrder":248},
  {"id":"s_work_ttcm_6_249","chapterId":"ch_work_ttcm_6","text":"紂之無道極矣，周雖不伐，天下必有起而亡之者。文王受西伯之命，以德威镇天下，故文王不興師，天下不敢動，厚集其势，防中潰之变，所為盡人謀以延商者至矣。必天命之不可延而後武王伐之，天之命也，非己所願也，斯其所以為仁至義盡，而執中無難，非湯、武之所可及與！","sortOrder":249},
  {"id":"s_work_ttcm_6_250","chapterId":"ch_work_ttcm_6","text":"上天之載，無聲臭可象，正惟儀刑文王，當冥契天德而萬邦信悅。","sortOrder":250},
  {"id":"s_work_ttcm_6_251","chapterId":"ch_work_ttcm_6","text":"文王之德，天德也，故法文王即合天載，求諸有可效者也。天之聰明，自民聰明，故萬邦作孚為契天之验。","sortOrder":251},
  {"id":"s_work_ttcm_6_252","chapterId":"ch_work_ttcm_6","text":"故《易》曰：“神而明之，存乎其人。”","sortOrder":252},
  {"id":"s_work_ttcm_6_253","chapterId":"ch_work_ttcm_6","text":"心存文王之所以為文，則神明之德在矣。","sortOrder":253},
  {"id":"s_work_ttcm_6_254","chapterId":"ch_work_ttcm_6","text":"不以聲色為政，不革命而有中國，默順帝則而天下自歸者，其惟文王乎！","sortOrder":254},
  {"id":"s_work_ttcm_6_255","chapterId":"ch_work_ttcm_6","text":"不以聲色為政者，非废聲色也；有其心乃有其事，則物無不誠，而不於號令施為求民之從。其順帝則以孚民志者，皆積中發外，因時而出，天下自悅而信之。","sortOrder":255},
  {"id":"s_work_ttcm_6_256","chapterId":"ch_work_ttcm_6","text":"可願可欲，雖聖人之知，不越盡其才以勉焉而已。","sortOrder":256},
  {"id":"s_work_ttcm_6_257","chapterId":"ch_work_ttcm_6","text":"越，過也。聖人之願欲廣大，而不過盡其才之所可為，人道盡而帝則順，屈伸因乎時也。","sortOrder":257},
  {"id":"s_work_ttcm_6_258","chapterId":"ch_work_ttcm_6","text":"故君子之道四，雖孔子自謂未能；博施濟眾，修己安百姓，尧、舜病諸。是知人能有願有欲，不能窮其願欲。","sortOrder":258},
  {"id":"s_work_ttcm_6_259","chapterId":"ch_work_ttcm_6","text":"有願欲而欲窮極之，墨、釋所以妄而淫。","sortOrder":259},
  {"id":"s_work_ttcm_6_260","chapterId":"ch_work_ttcm_6","text":"“周有八士”，記善人之富也。","sortOrder":260},
  {"id":"s_work_ttcm_6_261","chapterId":"ch_work_ttcm_6","text":"富，眾也；賢才出，國所以昌。","sortOrder":261},
  {"id":"s_work_ttcm_6_262","chapterId":"ch_work_ttcm_6","text":"重耳婉而不直，小白直而不婉。","sortOrder":262},
  {"id":"s_work_ttcm_6_263","chapterId":"ch_work_ttcm_6","text":"婉則譎，直則正；故君子之道恒刚，小人之道恒柔；刚以自遂，柔以誘人。","sortOrder":263},
  {"id":"s_work_ttcm_6_264","chapterId":"ch_work_ttcm_6","text":"魯政之弊，馭法者非其人而已；齊而管仲，遂併坏其法，故必再变而後至於道。","sortOrder":264},
  {"id":"s_work_ttcm_6_265","chapterId":"ch_work_ttcm_6","text":"法存則待人以修明之而已；法坏而欲反之於正，條理不熟，既变其法，又待其人，必再变而後習而安之。法者，先王禮樂刑政之大經，如《中庸》所謂“九經”是也。","sortOrder":265},
  {"id":"s_work_ttcm_6_266","chapterId":"ch_work_ttcm_6","text":"孟子以智之於賢者為有命，如晏婴智矣，而獨不智於仲尼，非天命邪！","sortOrder":266},
  {"id":"s_work_ttcm_6_267","chapterId":"ch_work_ttcm_6","text":"性命於天，而才亦命於天，皆命也。晏婴才有所蔽，不足以至於孔子之廣大，若是非之性則無以異也。仁義禮智之體具於性，而其為用必資於才以為小大偏全。唯存神盡性以至於命，則命自我立，才可扩充以副其性，天之降才不足以限之。故君子於此，以性為主而不為命之所限。","sortOrder":267},
  {"id":"s_work_ttcm_6_268","chapterId":"ch_work_ttcm_6","text":"山節藻棁為藏龟之室，祀爰居之義，同歸於不智，宜矣。","sortOrder":268},
  {"id":"s_work_ttcm_6_269","chapterId":"ch_work_ttcm_6","text":"龟雖神物，而神非以其形也；媚其形器，不足以知神之所在，則與祀海鳥之愚同。","sortOrder":269},
  {"id":"s_work_ttcm_6_270","chapterId":"ch_work_ttcm_6","text":"使民義，不害不能教當作“養”；愛猶眾人之母，不害使之義。禮樂不興，侨之病與！義與愛，不相悖而相成，子產庶幾知陰陽屈伸合同而化之道，則禮樂之興達此而行爾。病而未能，故謂其有君子之道，言已得其道而惜其未成也。","sortOrder":270},
  {"id":"s_work_ttcm_6_271","chapterId":"ch_work_ttcm_6","text":"獻子者忘其势，五人者忘人之势；不資其势而利其有，然後能忘人之势。","sortOrder":271},
  {"id":"s_work_ttcm_6_272","chapterId":"ch_work_ttcm_6","text":"人之势於己何有；而不忘之，必其資而利之也。無所求，則見有道而已。","sortOrder":272},
  {"id":"s_work_ttcm_6_273","chapterId":"ch_work_ttcm_6","text":"若五人者有獻子之势，則反為獻子之所賤矣。","sortOrder":273},
  {"id":"s_work_ttcm_6_274","chapterId":"ch_work_ttcm_6","text":"己忘之而人顧不能忘，此流俗之所以可賤也。","sortOrder":274},
  {"id":"s_work_ttcm_6_275","chapterId":"ch_work_ttcm_6","text":"颛臾主事東蒙，既魯地，則是已在邦域之中矣，雖非魯臣，乃吾杜稷之臣也。","sortOrder":275},
  {"id":"s_work_ttcm_6_276","chapterId":"ch_work_ttcm_6","text":"諸侯祀境內山川，而社稷為群祀之主，則颛臾必供祀事於魯。《詩》稱“錫之附庸”，其為供祀之臣可明矣。","sortOrder":276},
  {"id":"s_work_ttcm_7_1","chapterId":"ch_work_ttcm_7","text":"張子正蒙註卷六","sortOrder":1},
  {"id":"s_work_ttcm_7_2","chapterId":"ch_work_ttcm_7","text":"三十篇","sortOrder":2},
  {"id":"s_work_ttcm_7_3","chapterId":"ch_work_ttcm_7","text":"三十器於禮，非強立之謂也。","sortOrder":3},
  {"id":"s_work_ttcm_7_4","chapterId":"ch_work_ttcm_7","text":"盡其用之謂器，無動非禮，則立人之道盡矣。","sortOrder":4},
  {"id":"s_work_ttcm_7_5","chapterId":"ch_work_ttcm_7","text":"四十精義致用，時措而不疑。","sortOrder":5},
  {"id":"s_work_ttcm_7_6","chapterId":"ch_work_ttcm_7","text":"禮之所自出，義之當然也，精之，則盡变矣。","sortOrder":6},
  {"id":"s_work_ttcm_7_7","chapterId":"ch_work_ttcm_7","text":"五十窮理盡性，至天之命，然不可自謂之至，故曰知。","sortOrder":7},
  {"id":"s_work_ttcm_7_8","chapterId":"ch_work_ttcm_7","text":"義者因事而措理，則其合一之原也。理原於天化之神而為吾性之所固有，窮極其至，一本而萬殊，則吾之所受於天者盡，而天之神化，吾皆與其事矣。不可謂至者，聖人自謙之辭。知，猶與聞也。","sortOrder":8},
  {"id":"s_work_ttcm_7_9","chapterId":"ch_work_ttcm_7","text":"六十盡人物之性，聲入心通。","sortOrder":9},
  {"id":"s_work_ttcm_7_10","chapterId":"ch_work_ttcm_7","text":"合天之化而通之於物理，則人物之志欲情理，皆知其所自而隨感即通，處之有道矣。物之相感也莫如聲，聲入心通，不待形見而早有以應之。","sortOrder":10},
  {"id":"s_work_ttcm_7_11","chapterId":"ch_work_ttcm_7","text":"七十與天同德，不思不勉，從容中道。","sortOrder":11},
  {"id":"s_work_ttcm_7_12","chapterId":"ch_work_ttcm_7","text":"窮理盡性之熟也。聖功之極致，與天合德，而其所自成，則以執禮精義為上達之本。蓋禮，器也，義，器與道相為體用之實也；而形而上之道麗於器之中，則即器以精其義，萬事萬物無不會通於至誠之变化，故曰“下學而上達，知我者其天乎！”天之為德，不顯於形色，而成形成色，淪浃貫通於形色之粗，無非氣之所流行，則無非理之所昭著。聖功以存神為至，而不舍形色以盡其誠，此所以異於異端之虛而無實，自謂神靈而實則習不察、行不著也。","sortOrder":12},
  {"id":"s_work_ttcm_7_13","chapterId":"ch_work_ttcm_7","text":"常人之學，日益而不自知也。","sortOrder":13},
  {"id":"s_work_ttcm_7_14","chapterId":"ch_work_ttcm_7","text":"學則必有益矣；聞見之力忽生其心，故不自知其所以益。","sortOrder":14},
  {"id":"s_work_ttcm_7_15","chapterId":"ch_work_ttcm_7","text":"仲尼學行習察，異於他人，","sortOrder":15},
  {"id":"s_work_ttcm_7_16","chapterId":"ch_work_ttcm_7","text":"學則行之而無所待，習則察其所以然，是其聖性之自然合道；而所志者天德，聞見日啟而不恃聞見以知，皆誠於德而明自誠生也。","sortOrder":16},
  {"id":"s_work_ttcm_7_17","chapterId":"ch_work_ttcm_7","text":"故自十五至於七十，化而知裁，其德進之盛者與！","sortOrder":17},
  {"id":"s_work_ttcm_7_18","chapterId":"ch_work_ttcm_7","text":"學而行，無滯於行，則已行者化；習而察，則不執所習，而參伍以盡其变，故不執一德而裁成萬理；德進之盛，殆由此與！蓋循物窮理，待一旦之豁然，賢者之學，得失不能自保，而以天德為志，所學皆要歸焉，則一學一習皆上達之資，則作聖之功當其始而已異。此張、朱學誨之不同，學者辨之。","sortOrder":18},
  {"id":"s_work_ttcm_7_19","chapterId":"ch_work_ttcm_7","text":"窮理盡性，然後至於命；盡人物之性，然後耳順，與天地參；無意、必、固、我，然後范围天地之化，從心而不逾矩；","sortOrder":19},
  {"id":"s_work_ttcm_7_20","chapterId":"ch_work_ttcm_7","text":"知命，從心，不逾矩，聖德之效也。有聖學而後聖德日升，聖學以窮理為之基，而與天地參者，灼見天地之神，窮理之至也。","sortOrder":20},
  {"id":"s_work_ttcm_7_21","chapterId":"ch_work_ttcm_7","text":"老而安死，然後不夢周公。","sortOrder":21},
  {"id":"s_work_ttcm_7_22","chapterId":"ch_work_ttcm_7","text":"此七十後聖心之妙也。范围天地之化，則死而歸化於天，無不安者，屈伸自然無所庸其志也。《詩》曰“文王在上，於昭於天”，此之謂與！","sortOrder":22},
  {"id":"s_work_ttcm_7_23","chapterId":"ch_work_ttcm_7","text":"從心莫如夢。","sortOrder":23},
  {"id":"s_work_ttcm_7_24","chapterId":"ch_work_ttcm_7","text":"物無所感，自然而如其心之所志。","sortOrder":24},
  {"id":"s_work_ttcm_7_25","chapterId":"ch_work_ttcm_7","text":"夢見周公，志也；","sortOrder":25},
  {"id":"s_work_ttcm_7_26","chapterId":"ch_work_ttcm_7","text":"志則非時位所能為而志之。","sortOrder":26},
  {"id":"s_work_ttcm_7_27","chapterId":"ch_work_ttcm_7","text":"不夢，欲不逾矩也，","sortOrder":27},
  {"id":"s_work_ttcm_7_28","chapterId":"ch_work_ttcm_7","text":"矩，天則也。范围天地之化，屈伸行止，無往而不在帝則之中，奚其逾！","sortOrder":28},
  {"id":"s_work_ttcm_7_29","chapterId":"ch_work_ttcm_7","text":"不願乎外也，","sortOrder":29},
  {"id":"s_work_ttcm_7_30","chapterId":"ch_work_ttcm_7","text":"無往而非天理，天理無外，何逾之有！","sortOrder":30},
  {"id":"s_work_ttcm_7_31","chapterId":"ch_work_ttcm_7","text":"顧之至也，","sortOrder":31},
  {"id":"s_work_ttcm_7_32","chapterId":"ch_work_ttcm_7","text":"於天皆合，則於物皆順。","sortOrder":32},
  {"id":"s_work_ttcm_7_33","chapterId":"ch_work_ttcm_7","text":"老而安死也。","sortOrder":33},
  {"id":"s_work_ttcm_7_34","chapterId":"ch_work_ttcm_7","text":"順自然之化，歸太和氤氲之妙，故心以安。","sortOrder":34},
  {"id":"s_work_ttcm_7_35","chapterId":"ch_work_ttcm_7","text":"故曰“吾衰也久矣。”","sortOrder":35},
  {"id":"s_work_ttcm_7_36","chapterId":"ch_work_ttcm_7","text":"形衰將屈，神將伸也。","sortOrder":36},
  {"id":"s_work_ttcm_7_37","chapterId":"ch_work_ttcm_7","text":"困而不知变，民斯為下矣；不待困而喻，賢者之常也。","sortOrder":37},
  {"id":"s_work_ttcm_7_38","chapterId":"ch_work_ttcm_7","text":"未嘗處困而能喻乎道，賢矣。然困常而常，則喻其當然，而屈伸動靜之变有不察者。","sortOrder":38},
  {"id":"s_work_ttcm_7_39","chapterId":"ch_work_ttcm_7","text":"困之進人也，為德辨，為感速，孟子謂“人有德慧術知者存乎疢疾”，以此。","sortOrder":39},
  {"id":"s_work_ttcm_7_40","chapterId":"ch_work_ttcm_7","text":"困之中必有通焉，窮則变，变則通。不執一之道，惟困而後辨之，人情物化变而有常之理，亦惟困而後辨之，故曰其德辨。心極於窮，則觸变而即通，故曰其感速。不待困而喻者，知其大綱，忘其條理，因循故常，雖感亦不能速辨。","sortOrder":40},
  {"id":"s_work_ttcm_7_41","chapterId":"ch_work_ttcm_7","text":"自古困於內無如舜，困於外無如孔子。以孔子之聖而下學於困，則其蒙難正志，聖德日跻，必有人所不及知而天獨知之者矣，故曰“莫我知也夫！”“知我者，其天乎！”","sortOrder":41},
  {"id":"s_work_ttcm_7_42","chapterId":"ch_work_ttcm_7","text":"無生安之可恃而不倚於學，迫其神明以與道合，下學之事也。正志者，正大經也。萬变而反於大經，非賢者以下所知，惟天屈伸聚散，運行於太極之中，具此理爾。義日精，仁日熟，則從心不逾，困之所得者深矣。然則處常而無所困者，將如之何？境雖通而一事一物之感，一情一意之發，嚴持其心。臨深履薄而不使馳驅，以研幾於極深而盡性於至隱，則安利之境，不忘困勉之心，聖功在是。故知不待困而喻者，雖賢於人，終不可至於聖也。","sortOrder":42},
  {"id":"s_work_ttcm_7_43","chapterId":"ch_work_ttcm_7","text":"“立斯立，道斯行，綏斯來，動斯和”，從欲風動，神而化也。","sortOrder":43},
  {"id":"s_work_ttcm_7_44","chapterId":"ch_work_ttcm_7","text":"存禮樂刑政之神而達其用，以盡人物之性，與天之曲成萬物者通理，則民有不自知其所以然，而感動於不容已者矣。","sortOrder":44},
  {"id":"s_work_ttcm_7_45","chapterId":"ch_work_ttcm_7","text":"仲尼生於周，從周禮，故公旦法坏，夢寐不忘為東周之意；使其繼周而王，則其損益可知矣。","sortOrder":45},
  {"id":"s_work_ttcm_7_46","chapterId":"ch_work_ttcm_7","text":"禮隨時為損益，義之所以精也，中道也，大經也。為周人則志周禮，繼周王則且必变通之。","sortOrder":46},
  {"id":"s_work_ttcm_7_47","chapterId":"ch_work_ttcm_7","text":"滔滔忘反者，天下莫不然，如何变易之？","sortOrder":47},
  {"id":"s_work_ttcm_7_48","chapterId":"ch_work_ttcm_7","text":"述桀溺之意，所言亦近是。","sortOrder":48},
  {"id":"s_work_ttcm_7_49","chapterId":"ch_work_ttcm_7","text":"“天下有道，丘不與易。”知天下無道而不隱者，道不遠人；且聖人之仁，不以無道必天下而弃之也。","sortOrder":49},
  {"id":"s_work_ttcm_7_50","chapterId":"ch_work_ttcm_7","text":"道不遠人，有人斯可行道，定公之君，季斯之臣，三月而魯大治，非孔子與以所本無也。即不我用，聖人不忍弃之。天不以嚚訟而奪小人之口體，不以淫邪而奪小人之耳目，自盡其化而已。","sortOrder":50},
  {"id":"s_work_ttcm_7_51","chapterId":"ch_work_ttcm_7","text":"仁者先事後得，先難後獲，故君子事事則得食；不以事事，“雖有粟，吾得而食諸！”仲尼少也國人不知，委吏乘田得而食之矣；及德備道尊，至是邦必聞其政，雖欲仕貧，無從以得之。","sortOrder":51},
  {"id":"s_work_ttcm_7_52","chapterId":"ch_work_ttcm_7","text":"位望既尊，不可复為卑官。","sortOrder":52},
  {"id":"s_work_ttcm_7_53","chapterId":"ch_work_ttcm_7","text":"“今召我者而豈徒哉”，庶幾得以事事矣，而又絕之，是誠系滯如匏瓜不食之物也。","sortOrder":53},
  {"id":"s_work_ttcm_7_54","chapterId":"ch_work_ttcm_7","text":"人不能不食，雖聖人必以事食；不能不食，則不能不事，故急於事，不輕絕人。此言雖淺，而學者以此存心，則飽食終身，為天地民物之累，亦尚知愧乎！","sortOrder":54},
  {"id":"s_work_ttcm_7_55","chapterId":"ch_work_ttcm_7","text":"不待備而勉於禮樂，“先進於禮樂”者也；","sortOrder":55},
  {"id":"s_work_ttcm_7_56","chapterId":"ch_work_ttcm_7","text":"先，謂未備物而急於行；後，謂備物而後行。禮樂不可斯須去身，故急於行者不待物之備。","sortOrder":56},
  {"id":"s_work_ttcm_7_57","chapterId":"ch_work_ttcm_7","text":"備而後至於禮樂，“後進於禮樂”者也。","sortOrder":57},
  {"id":"s_work_ttcm_7_58","chapterId":"ch_work_ttcm_7","text":"治定製禮，功成作樂，聖人而在天子之位，乃建中和之極。君子、野人，以位言。","sortOrder":58},
  {"id":"s_work_ttcm_7_59","chapterId":"ch_work_ttcm_7","text":"仲尼以貧賤者必待文備而後進，則於禮樂終不可得而行矣，故自謂野人而必為，所謂“不願乎其外”也。","sortOrder":59},
  {"id":"s_work_ttcm_7_60","chapterId":"ch_work_ttcm_7","text":"素位行道，而無所待於大行。","sortOrder":60},
  {"id":"s_work_ttcm_7_61","chapterId":"ch_work_ttcm_7","text":"功業不试，則人所見者藝而已。","sortOrder":61},
  {"id":"s_work_ttcm_7_62","chapterId":"ch_work_ttcm_7","text":"藝，六藝也。聖人之德，非人所可测，則人見其功；道不行，則人但見其藝。功與藝有大小，而盛德之光辉不可掩，則一也。","sortOrder":62},
  {"id":"s_work_ttcm_7_63","chapterId":"ch_work_ttcm_7","text":"鳳至圖出，文明之祥，伏羲、舜、文之瑞不至，則夫子之文章知其已矣。","sortOrder":63},
  {"id":"s_work_ttcm_7_64","chapterId":"ch_work_ttcm_7","text":"文章，謂製禮作樂、移風易俗之事。聖德默成萬物，不因隱見而損益，文章則不可見也。","sortOrder":64},
  {"id":"s_work_ttcm_7_65","chapterId":"ch_work_ttcm_7","text":"魯禮文闕失，不以仲尼正之，如有馬者不借人以乘習。","sortOrder":65},
  {"id":"s_work_ttcm_7_66","chapterId":"ch_work_ttcm_7","text":"借，猶請也。謂馬未馴習，必假請善御者調習之乃可乘，喻魯君不能正禮樂，當假夫子修習之。","sortOrder":66},
  {"id":"s_work_ttcm_7_67","chapterId":"ch_work_ttcm_7","text":"不曰禮文而曰“史之闕文”者，祝史所任，儀章器數而已，舉近者而言約也。","sortOrder":67},
  {"id":"s_work_ttcm_7_68","chapterId":"ch_work_ttcm_7","text":"淺近易知者且闕失之，况其大者。“猶及”，謂力能任之；“今亡矣夫”，叹其終不可得而正矣。","sortOrder":68},
  {"id":"s_work_ttcm_7_69","chapterId":"ch_work_ttcm_7","text":"師挚之始，樂失其次，徒洋洋盈耳而已焉。","sortOrder":69},
  {"id":"s_work_ttcm_7_70","chapterId":"ch_work_ttcm_7","text":"有聲無律，則其音濫。","sortOrder":70},
  {"id":"s_work_ttcm_7_71","chapterId":"ch_work_ttcm_7","text":"夫子自衛反魯，一嘗治之，其後伶人賤工識樂之正。及魯益下衰，三桓僭妄，自太師以下，皆知散之四方，逾河蹈海以去亂。聖人俄頃之助，功化如此。“用我者期月而可”，豈虛語哉！","sortOrder":71},
  {"id":"s_work_ttcm_7_72","chapterId":"ch_work_ttcm_7","text":"聖人順大經而存神，故感心之速如此。","sortOrder":72},
  {"id":"s_work_ttcm_7_73","chapterId":"ch_work_ttcm_7","text":"“與與如也”，君或在朝在廟，容色不忘向君也。","sortOrder":73},
  {"id":"s_work_ttcm_7_74","chapterId":"ch_work_ttcm_7","text":"與與，相授貌。心盡乎君，則容色不貳。","sortOrder":74},
  {"id":"s_work_ttcm_7_75","chapterId":"ch_work_ttcm_7","text":"“君召使擯，趨進翼如”；自註：此翼如，左右在君也","sortOrder":75},
  {"id":"s_work_ttcm_7_76","chapterId":"ch_work_ttcm_7","text":"向君而趨，如兩翼之夹身也。知非張拱者，近君不宜自為容。","sortOrder":76},
  {"id":"s_work_ttcm_7_77","chapterId":"ch_work_ttcm_7","text":"“没階，趨進翼如”；自註：張拱如翔。“進”字衍文","sortOrder":77},
  {"id":"s_work_ttcm_7_78","chapterId":"ch_work_ttcm_7","text":"文同而義異，上以向君，下以自飭也。","sortOrder":78},
  {"id":"s_work_ttcm_7_79","chapterId":"ch_work_ttcm_7","text":"“賓不顧矣”，相君送賓，賓去則白曰“賓不顧而去矣”，纾君敬也。","sortOrder":79},
  {"id":"s_work_ttcm_7_80","chapterId":"ch_work_ttcm_7","text":"敬無所施而過於恭，則自辱。","sortOrder":80},
  {"id":"s_work_ttcm_7_81","chapterId":"ch_work_ttcm_7","text":"上堂如揖，恭也；","sortOrder":81},
  {"id":"s_work_ttcm_7_82","chapterId":"ch_work_ttcm_7","text":"致圭於主，君當盡其恭。","sortOrder":82},
  {"id":"s_work_ttcm_7_83","chapterId":"ch_work_ttcm_7","text":"下堂如授，其容纾也。","sortOrder":83},
  {"id":"s_work_ttcm_7_84","chapterId":"ch_work_ttcm_7","text":"受命於君，已執圭而反於次，敬可少纾矣。","sortOrder":84},
  {"id":"s_work_ttcm_7_85","chapterId":"ch_work_ttcm_7","text":"冉子請粟與原思為宰，見聖人之用财也。","sortOrder":85},
  {"id":"s_work_ttcm_7_86","chapterId":"ch_work_ttcm_7","text":"财以成用，當其可則義精矣。","sortOrder":86},
  {"id":"s_work_ttcm_7_87","chapterId":"ch_work_ttcm_7","text":"聖人於物無畔援，雖佛肸、南子，苟以是心至，教之在我爾，不為己甚也如是。","sortOrder":87},
  {"id":"s_work_ttcm_7_88","chapterId":"ch_work_ttcm_7","text":"畔援，君子必與君子為類，交相倚也。聖人盡人物之性，在我者無不誠，不倚於物，故不為己甚，絕惡人以自表異。","sortOrder":88},
  {"id":"s_work_ttcm_7_89","chapterId":"ch_work_ttcm_7","text":"“子欲居九夷”，不遇於中國，庶遇於九夷，中國之陋為可知。","sortOrder":89},
  {"id":"s_work_ttcm_7_90","chapterId":"ch_work_ttcm_7","text":"九夷之陋陋於文，中國之陋陋於心。","sortOrder":90},
  {"id":"s_work_ttcm_7_91","chapterId":"ch_work_ttcm_7","text":"欲居九夷，言忠信，行篤敬，雖蠻貊之邦可行，“何陋之有！”","sortOrder":91},
  {"id":"s_work_ttcm_7_92","chapterId":"ch_work_ttcm_7","text":"聖人之化不可测，而大經之正，立誠而已矣。","sortOrder":92},
  {"id":"s_work_ttcm_7_93","chapterId":"ch_work_ttcm_7","text":"栖栖者，依依其君而不能忘也。","sortOrder":93},
  {"id":"s_work_ttcm_7_94","chapterId":"ch_work_ttcm_7","text":"疑微生畝之言，因孔子遲遲去魯而發。","sortOrder":94},
  {"id":"s_work_ttcm_7_95","chapterId":"ch_work_ttcm_7","text":"固，猶不回也。","sortOrder":95},
  {"id":"s_work_ttcm_7_96","chapterId":"ch_work_ttcm_7","text":"執一必往之念，去則不可止。","sortOrder":96},
  {"id":"s_work_ttcm_7_97","chapterId":"ch_work_ttcm_7","text":"仲尼應問，雖叩兩端而竭。","sortOrder":97},
  {"id":"s_work_ttcm_7_98","chapterId":"ch_work_ttcm_7","text":"即下學之中，具上達之理。","sortOrder":98},
  {"id":"s_work_ttcm_7_99","chapterId":"ch_work_ttcm_7","text":"然言必因人為变化。所貴乎聖人之詞者，以其知变化也。","sortOrder":99},
  {"id":"s_work_ttcm_7_100","chapterId":"ch_work_ttcm_7","text":"盡人之性而知之明，則原於善而成乎偏者，洞知其所自蔽，因其蔽而通之，变化無方而要歸於一，是其因人而施之教，未嘗不竭盡上達之旨矣。","sortOrder":100},
  {"id":"s_work_ttcm_7_101","chapterId":"ch_work_ttcm_7","text":"“富而可求也，雖執鞭之士，吾亦為之”，不憚卑以求富，求之有可致之道也；","sortOrder":101},
  {"id":"s_work_ttcm_7_102","chapterId":"ch_work_ttcm_7","text":"此小人之設心則然。","sortOrder":102},
  {"id":"s_work_ttcm_7_103","chapterId":"ch_work_ttcm_7","text":"然則乃有命，是求無益於得也。","sortOrder":103},
  {"id":"s_work_ttcm_7_104","chapterId":"ch_work_ttcm_7","text":"曲諭小人，使知返而自安於命。","sortOrder":104},
  {"id":"s_work_ttcm_7_105","chapterId":"ch_work_ttcm_7","text":"愛人以德，喻於義者常多，故罕及於利；","sortOrder":105},
  {"id":"s_work_ttcm_7_106","chapterId":"ch_work_ttcm_7","text":"聖人之徒，正義而不謀利，無庸复與言利。","sortOrder":106},
  {"id":"s_work_ttcm_7_107","chapterId":"ch_work_ttcm_7","text":"盡性者方能至命，未達之人，告之無益，故不以亟言；","sortOrder":107},
  {"id":"s_work_ttcm_7_108","chapterId":"ch_work_ttcm_7","text":"求道於天而不求道於己，無益於進德。","sortOrder":108},
  {"id":"s_work_ttcm_7_109","chapterId":"ch_work_ttcm_7","text":"仁大難名，人未易及，故言之亦鮮。","sortOrder":109},
  {"id":"s_work_ttcm_7_110","chapterId":"ch_work_ttcm_7","text":"盡天下之理，皆吾心之惻然而動，不容已者；執事以言之，則倚於一曲而不全。","sortOrder":110},
  {"id":"s_work_ttcm_7_111","chapterId":"ch_work_ttcm_7","text":"顏子於天下，“有不善未嘗不知，知之未嘗复行”。","sortOrder":111},
  {"id":"s_work_ttcm_7_112","chapterId":"ch_work_ttcm_7","text":"誠立而幾明，則自知審，而即以验天下，無不知也；因人之不善以自警，則終身不行。","sortOrder":112},
  {"id":"s_work_ttcm_7_113","chapterId":"ch_work_ttcm_7","text":"故怒於人者，不使加乎其身；愧於己者，不辄貳之於後也。","sortOrder":113},
  {"id":"s_work_ttcm_7_114","chapterId":"ch_work_ttcm_7","text":"人有不善，則怒之矣；己不效尤，不使人將怒己，故曰不遷。貳，猶复也。此顏子力行之功，故夫子許為好學之實。","sortOrder":114},
  {"id":"s_work_ttcm_7_115","chapterId":"ch_work_ttcm_7","text":"顏子之徒，隱而末見，行而未成，","sortOrder":115},
  {"id":"s_work_ttcm_7_116","chapterId":"ch_work_ttcm_7","text":"未仕，故道不達；早亡，所求之志末竟。","sortOrder":116},
  {"id":"s_work_ttcm_7_117","chapterId":"ch_work_ttcm_7","text":"故曰“吾聞其語而未見其人也。”所以知此為顏子之類言者，以用舍行藏知之。","sortOrder":117},
  {"id":"s_work_ttcm_7_118","chapterId":"ch_work_ttcm_7","text":"“用則行，舍則藏，惟我與爾有是夫！“顏子龍德而隱，故遁世不見知而不悔，與聖者同。","sortOrder":118},
  {"id":"s_work_ttcm_7_119","chapterId":"ch_work_ttcm_7","text":"學以聚之，問以辨之，宽以居之，仁以行之，顏子之學，見龍之德也，可以利見，而時在潛則潛，所學者聖學，故道同於聖。","sortOrder":119},
  {"id":"s_work_ttcm_7_120","chapterId":"ch_work_ttcm_7","text":"龍德，聖修之極也；","sortOrder":120},
  {"id":"s_work_ttcm_7_121","chapterId":"ch_work_ttcm_7","text":"修之極而聖德純，則屈伸一致而六龍可御。","sortOrder":121},
  {"id":"s_work_ttcm_7_122","chapterId":"ch_work_ttcm_7","text":"顏子之進，則欲一朝而至焉，“可謂好學也已矣”。","sortOrder":122},
  {"id":"s_work_ttcm_7_123","chapterId":"ch_work_ttcm_7","text":"所謂大其心則能體天下之物也。大學之道，止於至善；近小自期，非學也。","sortOrder":123},
  {"id":"s_work_ttcm_7_124","chapterId":"ch_work_ttcm_7","text":"“回非助我者”，無疑問也；","sortOrder":124},
  {"id":"s_work_ttcm_7_125","chapterId":"ch_work_ttcm_7","text":"大其心而正大經，則雖所未知，而聞言即貫，無疑則無容問矣。","sortOrder":125},
  {"id":"s_work_ttcm_7_126","chapterId":"ch_work_ttcm_7","text":"有疑問，則吾得以感通其故而達夫異同者矣。道有異同，推其異以會其同，學者當自求而得之。待教而喻，雖達異同，其所達者猶有方也。聖人因問而曲盡教思之無窮，然非學者進德之實益。","sortOrder":126},
  {"id":"s_work_ttcm_7_127","chapterId":"ch_work_ttcm_7","text":"“放鄭聲，遠佞人”。顏回為邦，禮樂法度不必教之，惟損益三代，蓋所以告之也。","sortOrder":127},
  {"id":"s_work_ttcm_7_128","chapterId":"ch_work_ttcm_7","text":"“三”，當作“四”。言行，言乘，言服，言韶舞，則皆現成之辭。是其度數文章，顏子皆已知之，不待詳教，但告之損益而已。","sortOrder":128},
  {"id":"s_work_ttcm_7_129","chapterId":"ch_work_ttcm_7","text":"法立而能守，德則可久，業可大；鄭聲、佞人能使為邦者丧所以守，故放遠之。","sortOrder":129},
  {"id":"s_work_ttcm_7_130","chapterId":"ch_work_ttcm_7","text":"德立而業成，於君道無憾矣。以鄭聲、佞人為不足慮而姑置之，終為盛德之累，且潛移風會而不知。唯守之純一，而淫邪之微疵必謹，則居心一，百官正，風俗醇，可久可大之道，純王之德也。","sortOrder":130},
  {"id":"s_work_ttcm_7_131","chapterId":"ch_work_ttcm_7","text":"“天下有道則見，無道則隱”，“君子疾没世而名不稱”，","sortOrder":131},
  {"id":"s_work_ttcm_7_132","chapterId":"ch_work_ttcm_7","text":"二者疑於不相通。","sortOrder":132},
  {"id":"s_work_ttcm_7_133","chapterId":"ch_work_ttcm_7","text":"蓋“士而懷居，不可以為士”，必也去無道，就有道。","sortOrder":133},
  {"id":"s_work_ttcm_7_134","chapterId":"ch_work_ttcm_7","text":"春秋之世，諸侯之國皆可仕，故不當懷土重遷而必去之。","sortOrder":134},
  {"id":"s_work_ttcm_7_135","chapterId":"ch_work_ttcm_7","text":"遇有道而貧且賤，君子恥之。舉天下無道，然後窮居獨善，不見知而不悔，","sortOrder":135},
  {"id":"s_work_ttcm_7_136","chapterId":"ch_work_ttcm_7","text":"夫子所以周流列國而後反魯以老。","sortOrder":136},
  {"id":"s_work_ttcm_7_137","chapterId":"ch_work_ttcm_7","text":"《中庸》所謂“惟聖者能之”，仲尼所以獨許顏回“唯我與爾為有是”也。","sortOrder":137},
  {"id":"s_work_ttcm_7_138","chapterId":"ch_work_ttcm_7","text":"無我之至，龍德而時中，夫子聖而顏子以此為學。","sortOrder":138},
  {"id":"s_work_ttcm_7_139","chapterId":"ch_work_ttcm_7","text":"仲由樂善，故車馬衣裘，喜與賢者共敝；","sortOrder":139},
  {"id":"s_work_ttcm_7_140","chapterId":"ch_work_ttcm_7","text":"子路所友，必其賢也；樂人之善，外見之仁也。","sortOrder":140},
  {"id":"s_work_ttcm_7_141","chapterId":"ch_work_ttcm_7","text":"顏子樂進，故願無伐善施勞；","sortOrder":141},
  {"id":"s_work_ttcm_7_142","chapterId":"ch_work_ttcm_7","text":"進而不已，不見有可伐可施，樂己之進無窮，內修之仁也。","sortOrder":142},
  {"id":"s_work_ttcm_7_143","chapterId":"ch_work_ttcm_7","text":"聖人樂天，故合內外而成其仁。","sortOrder":143},
  {"id":"s_work_ttcm_7_144","chapterId":"ch_work_ttcm_7","text":"天者，理之無間者也。安之，信之，懷之，內盡於己者至；老安，友信，少懷，外及於物者弘。合於己而己無非天，顏子所欲進者此，而未逮爾。","sortOrder":144},
  {"id":"s_work_ttcm_7_145","chapterId":"ch_work_ttcm_7","text":"子路禮樂文章，未足盡為政之道，以其重然诺，言為眾信，故“片言可以折獄”，如《易》所謂“利用折獄”，“利用刑人”，皆非爻卦盛德，適能是而已焉。","sortOrder":145},
  {"id":"s_work_ttcm_7_146","chapterId":"ch_work_ttcm_7","text":"《噬嗑》嚙而合，非天理之自然；《蒙》三未出乎险，聖功不就，皆非盛德事。","sortOrder":146},
  {"id":"s_work_ttcm_7_147","chapterId":"ch_work_ttcm_7","text":"顏淵從師，進德於孔子之門；孟子命世，修業於戰國之际，此所以潛見之不同。","sortOrder":147},
  {"id":"s_work_ttcm_7_148","chapterId":"ch_work_ttcm_7","text":"命世，世無人而己任责於天也。二子皆學孔子，而因時為位，無成心以執一，所以為善學。","sortOrder":148},
  {"id":"s_work_ttcm_7_149","chapterId":"ch_work_ttcm_7","text":"犁牛之子，雖無全純，然使其色骍且角，縱不為大祀所取，","sortOrder":149},
  {"id":"s_work_ttcm_7_150","chapterId":"ch_work_ttcm_7","text":"大祀為郊廟。","sortOrder":150},
  {"id":"s_work_ttcm_7_151","chapterId":"ch_work_ttcm_7","text":"次祀小祀終必取之，言大者苟立，人所不弃也。","sortOrder":151},
  {"id":"s_work_ttcm_7_152","chapterId":"ch_work_ttcm_7","text":"大者，大節不失也。此教仲弓以用人之道，與“先有司、赦小過”意同。","sortOrder":152},
  {"id":"s_work_ttcm_7_153","chapterId":"ch_work_ttcm_7","text":"有德篇","sortOrder":153},
  {"id":"s_work_ttcm_7_154","chapterId":"ch_work_ttcm_7","text":"此篇亦廣釋《論》《孟》之義而开示進修之方，尤切身心之用，誠學者所宜服膺也。","sortOrder":154},
  {"id":"s_work_ttcm_7_155","chapterId":"ch_work_ttcm_7","text":"“有德者必有言”，能為有也；","sortOrder":155},
  {"id":"s_work_ttcm_7_156","chapterId":"ch_work_ttcm_7","text":"言以垂世立教，興起天下而天下賴之，聖賢所以死而不亡。","sortOrder":156},
  {"id":"s_work_ttcm_7_157","chapterId":"ch_work_ttcm_7","text":"“志於仁而無惡”，能為無也。","sortOrder":157},
  {"id":"s_work_ttcm_7_158","chapterId":"ch_work_ttcm_7","text":"不以己私累天下，天下無所損，安而忘之。張子此言，以警學者至矣。縱欲趨利，則天下求無其人而不得，是人類之狼蠆也。","sortOrder":158},
  {"id":"s_work_ttcm_7_159","chapterId":"ch_work_ttcm_7","text":"行修言道，則當為人取。","sortOrder":159},
  {"id":"s_work_ttcm_7_160","chapterId":"ch_work_ttcm_7","text":"道，順於道也。取，取法也。","sortOrder":160},
  {"id":"s_work_ttcm_7_161","chapterId":"ch_work_ttcm_7","text":"不務徇物強施以引取乎人，故往教妄說，皆取人之弊也。","sortOrder":161},
  {"id":"s_work_ttcm_7_162","chapterId":"ch_work_ttcm_7","text":"君子之教，思無窮而道在己，則有志者自來取法；若不可與言而與言，必姑屈其說以誘使企及，成乎妄矣。往教之弊，終於妄說，枉己者未有能正人也。","sortOrder":162},
  {"id":"s_work_ttcm_7_163","chapterId":"ch_work_ttcm_7","text":"“言不必信，行不必果”，志正深遠，不務硁硁信其小者。","sortOrder":163},
  {"id":"s_work_ttcm_7_164","chapterId":"ch_work_ttcm_7","text":"反大經則正，達天德則深，循大常則遠。","sortOrder":164},
  {"id":"s_work_ttcm_7_165","chapterId":"ch_work_ttcm_7","text":"辭取達意則止，多或反害也。","sortOrder":165},
  {"id":"s_work_ttcm_7_166","chapterId":"ch_work_ttcm_7","text":"旁及則害於本意。","sortOrder":166},
  {"id":"s_work_ttcm_7_167","chapterId":"ch_work_ttcm_7","text":"君子寧言之不顧，不規規於非義之信；寧身被困辱，不徇人以非禮之恭；寧孤立無助，不失親於可賤之人。三者知和而能以禮節之也。","sortOrder":167},
  {"id":"s_work_ttcm_7_168","chapterId":"ch_work_ttcm_7","text":"言必於信，恭以免辱。不擇人而與親，所以和天下也。以禮節之者，以禮立身，雖不與世侮而終不枉己，所以節和而不流。","sortOrder":168},
  {"id":"s_work_ttcm_7_169","chapterId":"ch_work_ttcm_7","text":"與上有子之言，文相屬而不相蒙者。凡《論語》《孟子》發明前文，義各未盡者，皆挈之。他皆放此。","sortOrder":169},
  {"id":"s_work_ttcm_7_170","chapterId":"ch_work_ttcm_7","text":"挈，相引而及也。","sortOrder":170},
  {"id":"s_work_ttcm_7_171","chapterId":"ch_work_ttcm_7","text":"德主天下之善，","sortOrder":171},
  {"id":"s_work_ttcm_7_172","chapterId":"ch_work_ttcm_7","text":"主，所要歸也。德得於心，而必以人心之同然者為歸；偏見自得之善，非善也。","sortOrder":172},
  {"id":"s_work_ttcm_7_173","chapterId":"ch_work_ttcm_7","text":"善原天下之一。","sortOrder":173},
  {"id":"s_work_ttcm_7_174","chapterId":"ch_work_ttcm_7","text":"原，所從出也。天下者，萬事萬物之富，而皆原天道自然之化，陰陽相感，刚柔相濟，仁義相成，合同而利用者也。若隨其偶感之幾，立異同以成趨尚，則有不善者矣。","sortOrder":174},
  {"id":"s_work_ttcm_7_175","chapterId":"ch_work_ttcm_7","text":"善同歸治，故王心一；","sortOrder":175},
  {"id":"s_work_ttcm_7_176","chapterId":"ch_work_ttcm_7","text":"期於善天下而已。張弛质文，善不同而同治，王心定也。一者，括萬理而貫通之。","sortOrder":176},
  {"id":"s_work_ttcm_7_177","chapterId":"ch_work_ttcm_7","text":"言必主德，故王言大。","sortOrder":177},
  {"id":"s_work_ttcm_7_178","chapterId":"ch_work_ttcm_7","text":"政教號令，因時因事，而皆主於心之所得以感人心之同得，則言約而可以統博，推之四海，垂之百世，鹹為法則。此言王者之心，本於一原而散於萬有，體天地民物之理，全備而貫通之，故隨時用中，一致而百慮，異於執見聞以為我，私偏尚而流於霸功也。","sortOrder":178},
  {"id":"s_work_ttcm_7_179","chapterId":"ch_work_ttcm_7","text":"言有教，","sortOrder":179},
  {"id":"s_work_ttcm_7_180","chapterId":"ch_work_ttcm_7","text":"言皆心得而可為法則。","sortOrder":180},
  {"id":"s_work_ttcm_7_181","chapterId":"ch_work_ttcm_7","text":"動有法，","sortOrder":181},
  {"id":"s_work_ttcm_7_182","chapterId":"ch_work_ttcm_7","text":"動審乎幾而不逾乎閒。","sortOrder":182},
  {"id":"s_work_ttcm_7_183","chapterId":"ch_work_ttcm_7","text":"晝有為，","sortOrder":183},
  {"id":"s_work_ttcm_7_184","chapterId":"ch_work_ttcm_7","text":"日用皆察著而力行之。","sortOrder":184},
  {"id":"s_work_ttcm_7_185","chapterId":"ch_work_ttcm_7","text":"宵有得，","sortOrder":185},
  {"id":"s_work_ttcm_7_186","chapterId":"ch_work_ttcm_7","text":"靜思以精義。","sortOrder":186},
  {"id":"s_work_ttcm_7_187","chapterId":"ch_work_ttcm_7","text":"息有養，","sortOrder":187},
  {"id":"s_work_ttcm_7_188","chapterId":"ch_work_ttcm_7","text":"物無時不相引，而靜正以養之，勿使牿害。","sortOrder":188},
  {"id":"s_work_ttcm_7_189","chapterId":"ch_work_ttcm_7","text":"瞬有存。","sortOrder":189},
  {"id":"s_work_ttcm_7_190","chapterId":"ch_work_ttcm_7","text":"心易出而外馳，持理勿忘以因時順應。此張子自得之實修，特著之以自考而示學者。其言嚴切，先儒或議其太迫。然苟息心以靜，而不加操持嚴密之功，則且放逸輕安，流入於釋、老之虛寂；逮其下流，則有如近世王畿之徒，汩没誕縱，成乎無忌憚之小人。故有志聖功者，必當以此為法。","sortOrder":190},
  {"id":"s_work_ttcm_7_191","chapterId":"ch_work_ttcm_7","text":"君子於民，导使為德而禁其為非，不大望於愚者之道與禮，謂道民以言，禁民以行，斯之謂爾。","sortOrder":191},
  {"id":"s_work_ttcm_7_192","chapterId":"ch_work_ttcm_7","text":"文義未詳，疑有闕誤。大略謂不過望愚民而嚴為之禁，但修之己者，言可法，行可則，以示民而感之使善。","sortOrder":192},
  {"id":"s_work_ttcm_7_193","chapterId":"ch_work_ttcm_7","text":"無征而言，取不信、啟诈妄之道也。","sortOrder":193},
  {"id":"s_work_ttcm_7_194","chapterId":"ch_work_ttcm_7","text":"以意度之，以理概之，雖其說是而取人不信，且使诈妄者效之，而造伪說以誣世。","sortOrder":194},
  {"id":"s_work_ttcm_7_195","chapterId":"ch_work_ttcm_7","text":"杞、宋不足征吾言則不言，","sortOrder":195},
  {"id":"s_work_ttcm_7_196","chapterId":"ch_work_ttcm_7","text":"得其大指，可以義起，而終不言。","sortOrder":196},
  {"id":"s_work_ttcm_7_197","chapterId":"ch_work_ttcm_7","text":"周足征則從之，故無征不信，君子不言。","sortOrder":197},
  {"id":"s_work_ttcm_7_198","chapterId":"ch_work_ttcm_7","text":"言天者征於人，言心者征於事，言古者征於今，所謂“修辭立其誠”也。","sortOrder":198},
  {"id":"s_work_ttcm_7_199","chapterId":"ch_work_ttcm_7","text":"便僻，足恭；善柔，令色；便佞，巧言。","sortOrder":199},
  {"id":"s_work_ttcm_7_200","chapterId":"ch_work_ttcm_7","text":"無識者取友，取此而已。故君子擇交，莫惡於易與，莫善於勝己。己不逮而惡人之驕，自弃者也。“僻”當作“辟”。","sortOrder":200},
  {"id":"s_work_ttcm_7_201","chapterId":"ch_work_ttcm_7","text":"節禮樂，不使流離相勝，能進反以為文也。","sortOrder":201},
  {"id":"s_work_ttcm_7_202","chapterId":"ch_work_ttcm_7","text":"流於彼，則離於此矣。禮主於减，所以裁抑形神而使不過；然必進以為文者，鼓動其歡欣畅達之情以行禮，則無強製不安而難繼之忧。樂主乎盈，以舒志氣而使樂於為善；然必反以為文者，收斂神情，如其自得者而樂之，則無隨物以靡、往而不复之傷。蓋禮樂互相為節而成章，其數精，其義得，其合同而化之神，斯須不去而節自著，故樂之不厭。","sortOrder":202},
  {"id":"s_work_ttcm_7_203","chapterId":"ch_work_ttcm_7","text":"驕樂，侈靡；宴樂，宴安。","sortOrder":203},
  {"id":"s_work_ttcm_7_204","chapterId":"ch_work_ttcm_7","text":"其氣驕者其用物必侈，侈則愈驕；其心好樂者必偷安，則愈不知戒懼。","sortOrder":204},
  {"id":"s_work_ttcm_7_205","chapterId":"ch_work_ttcm_7","text":"言形則卜如响，","sortOrder":205},
  {"id":"s_work_ttcm_7_206","chapterId":"ch_work_ttcm_7","text":"言形，謂可名言所疑，使卜人正告鬼神，無暗昧不可言之隱。","sortOrder":206},
  {"id":"s_work_ttcm_7_207","chapterId":"ch_work_ttcm_7","text":"以是知蔽固之私心，不能默然以達於性與天道。","sortOrder":207},
  {"id":"s_work_ttcm_7_208","chapterId":"ch_work_ttcm_7","text":"性者，神之凝於人；天道，神之化也。蔽固者為習氣利欲所蔽，雖有测度性天之智而為所固隘，必且有意與天违之隱，不得已而托於默以自匿，是其求明之心，早與性天之廓然大公、昭示無隱者相违，亦猶懷私而不能昌言者，卜而神不告也。陆、王之學多所秘藏，與釋氏握拳、竖拂同其诡閟，蓋弗能洞开心意以通極於天則，故若明若昧，無由测性天之實也。","sortOrder":208},
  {"id":"s_work_ttcm_7_209","chapterId":"ch_work_ttcm_7","text":"人道知所先後，","sortOrder":209},
  {"id":"s_work_ttcm_7_210","chapterId":"ch_work_ttcm_7","text":"謂篤親不遺舊。","sortOrder":210},
  {"id":"s_work_ttcm_7_211","chapterId":"ch_work_ttcm_7","text":"則恭不勞，慎不葸，勇不亂，直不絞，民化而歸厚矣。","sortOrder":211},
  {"id":"s_work_ttcm_7_212","chapterId":"ch_work_ttcm_7","text":"大經正則自得其和矣。合二章為一，亦挈前文之說，而於義未安。蓋聖賢之言，推其極無不可以貫通，而義各有指，不可強合。此則張子之小疵。","sortOrder":212},
  {"id":"s_work_ttcm_7_213","chapterId":"ch_work_ttcm_7","text":"膚受，陽也；其行，陰也。","sortOrder":213},
  {"id":"s_work_ttcm_7_214","chapterId":"ch_work_ttcm_7","text":"以膚受激烈明愬，其跡陽也；险而隱，其情陰也。","sortOrder":214},
  {"id":"s_work_ttcm_7_215","chapterId":"ch_work_ttcm_7","text":"象生，法必效，故君子重夫刚者。","sortOrder":215},
  {"id":"s_work_ttcm_7_216","chapterId":"ch_work_ttcm_7","text":"象者心所設，法者事所著。膚受雖內陰而外陽，然其险譎不能終隱，則其後必苶然而自失，心柔則事必不刚也。刚者無欲而伸，有其心乃有其事，則純乎陽，而千萬人吾往矣。必言象法者，以凡人未有事而心先有其始終規畫之成象，此陰陽之序，善惡之幾，君子所必審察也。","sortOrder":216},
  {"id":"s_work_ttcm_7_217","chapterId":"ch_work_ttcm_7","text":"歸罪為尤，罪己為悔。","sortOrder":217},
  {"id":"s_work_ttcm_7_218","chapterId":"ch_work_ttcm_7","text":"人歸罪於己為尤，己既失而追自咎為悔。","sortOrder":218},
  {"id":"s_work_ttcm_7_219","chapterId":"ch_work_ttcm_7","text":"“言寡尤”者，不以言得罪於人也。","sortOrder":219},
  {"id":"s_work_ttcm_7_220","chapterId":"ch_work_ttcm_7","text":"言必於理之有征，人孰得而罪之。","sortOrder":220},
  {"id":"s_work_ttcm_7_221","chapterId":"ch_work_ttcm_7","text":"“己所不欲，勿施於人”，能恕己以仁人也。","sortOrder":221},
  {"id":"s_work_ttcm_7_222","chapterId":"ch_work_ttcm_7","text":"恕己，猶言如己之心。","sortOrder":222},
  {"id":"s_work_ttcm_7_223","chapterId":"ch_work_ttcm_7","text":"“在邦無怨，在家無怨”，己雖不施不欲於人，然人施於己，能無怨也。","sortOrder":223},
  {"id":"s_work_ttcm_7_224","chapterId":"ch_work_ttcm_7","text":"反仁，反禮而已。此仁者存心之常定也。","sortOrder":224},
  {"id":"s_work_ttcm_7_225","chapterId":"ch_work_ttcm_7","text":"“敬而無失”，與人接而當也；","sortOrder":225},
  {"id":"s_work_ttcm_7_226","chapterId":"ch_work_ttcm_7","text":"親疏尊卑各得其分誼。","sortOrder":226},
  {"id":"s_work_ttcm_7_227","chapterId":"ch_work_ttcm_7","text":"“恭而有禮”，不為非禮之恭也。","sortOrder":227},
  {"id":"s_work_ttcm_7_228","chapterId":"ch_work_ttcm_7","text":"恭以自靖，非徇物也。","sortOrder":228},
  {"id":"s_work_ttcm_7_229","chapterId":"ch_work_ttcm_7","text":"聚百順以事君親，故曰“孝者畜也”，又曰“畜君者好君也”。","sortOrder":229},
  {"id":"s_work_ttcm_7_230","chapterId":"ch_work_ttcm_7","text":"畜之為言聚也。孝子於親，忠臣於君，孤致其心而不假於外，非期聚乎自順也。然其誠之专至，則凡心之所念，身之所為，物之所遇，皆必其順於君親者而後敢為，則不期於事之順而自無不順矣，然後可以養親之志而引君於道。","sortOrder":230},
  {"id":"s_work_ttcm_7_231","chapterId":"ch_work_ttcm_7","text":"事父母“先意承志”，","sortOrder":231},
  {"id":"s_work_ttcm_7_232","chapterId":"ch_work_ttcm_7","text":"意將動而先知之，則順其美而幾諫其失；志之所存，則承之以行而無违。","sortOrder":232},
  {"id":"s_work_ttcm_7_233","chapterId":"ch_work_ttcm_7","text":"故能辨志、意之異，然後能教人。","sortOrder":233},
  {"id":"s_work_ttcm_7_234","chapterId":"ch_work_ttcm_7","text":"因禮文而推廣之，於意言先，於志言承，則可從不可從分矣。意者，乍隨物感而起也；志者，事所自立而不可易者也。庸人有意而無志，中人志立而意亂之，君子持其志以慎其意，聖人純乎志以成德而無意。蓋志一而已，意則無定而不可紀。善教人者，示以至善以亟正其志，志正，則意雖不立，可因事以裁成之。不然，待其意之已發，或趨於善而過奖之，或趨於不善而亟絕之，賢無所就而不肖者莫知所惡，教之所以不行也。","sortOrder":234},
  {"id":"s_work_ttcm_7_235","chapterId":"ch_work_ttcm_7","text":"藝者，日為之分義，涉而不有，","sortOrder":235},
  {"id":"s_work_ttcm_7_236","chapterId":"ch_work_ttcm_7","text":"得不居功。","sortOrder":236},
  {"id":"s_work_ttcm_7_237","chapterId":"ch_work_ttcm_7","text":"過而不存，","sortOrder":237},
  {"id":"s_work_ttcm_7_238","chapterId":"ch_work_ttcm_7","text":"不恃才而數為之。","sortOrder":238},
  {"id":"s_work_ttcm_7_239","chapterId":"ch_work_ttcm_7","text":"故曰“遊”。","sortOrder":239},
  {"id":"s_work_ttcm_7_240","chapterId":"ch_work_ttcm_7","text":"所依者仁而已。藝者，仁之跡。","sortOrder":240},
  {"id":"s_work_ttcm_7_241","chapterId":"ch_work_ttcm_7","text":"天下有道，道隨身出；","sortOrder":241},
  {"id":"s_work_ttcm_7_242","chapterId":"ch_work_ttcm_7","text":"身不徒出，道隨以行。","sortOrder":242},
  {"id":"s_work_ttcm_7_243","chapterId":"ch_work_ttcm_7","text":"天下無道，身隨道屈。","sortOrder":243},
  {"id":"s_work_ttcm_7_244","chapterId":"ch_work_ttcm_7","text":"道不可行，身必隱也。此謂愛身以愛道，見有道而不見有身。","sortOrder":244},
  {"id":"s_work_ttcm_7_245","chapterId":"ch_work_ttcm_7","text":"“安土”，不懷居也；懷則有所從违而不安。","sortOrder":245},
  {"id":"s_work_ttcm_7_246","chapterId":"ch_work_ttcm_7","text":"有為而重遷，無為而輕遷，皆懷居也。","sortOrder":246},
  {"id":"s_work_ttcm_7_247","chapterId":"ch_work_ttcm_7","text":"有為重遷，為利所靡也；無為輕遷，非義所當去，激於一往而去之。","sortOrder":247},
  {"id":"s_work_ttcm_7_248","chapterId":"ch_work_ttcm_7","text":"“老而不死，是為賊。”幼不率教，長無循述，老不安死，三者皆賊生之道也。","sortOrder":248},
  {"id":"s_work_ttcm_7_249","chapterId":"ch_work_ttcm_7","text":"率教、循述，以全生理；安死，以順生氣，老不安死，欲寧神靜氣以幾幸不死。原壤蓋老氏之徒，修久视之術者。屈伸，自然之理，天地生化之道也。欲於天化以偷生，不屈則不伸，故曰賊生。","sortOrder":249},
  {"id":"s_work_ttcm_7_250","chapterId":"ch_work_ttcm_7","text":"“樂驕樂”則佚欲，","sortOrder":250},
  {"id":"s_work_ttcm_7_251","chapterId":"ch_work_ttcm_7","text":"凡侈皆生於驕也。","sortOrder":251},
  {"id":"s_work_ttcm_7_252","chapterId":"ch_work_ttcm_7","text":"“樂宴安”則不能徙義。","sortOrder":252},
  {"id":"s_work_ttcm_7_253","chapterId":"ch_work_ttcm_7","text":"偷安則以義為繁難而外之，莊、告是也。","sortOrder":253},
  {"id":"s_work_ttcm_7_254","chapterId":"ch_work_ttcm_7","text":"“不僭不賊”，其不忮不求之謂乎！","sortOrder":254},
  {"id":"s_work_ttcm_7_255","chapterId":"ch_work_ttcm_7","text":"不忮，則不越分而妄作；不求，則不損物以利己；心平，則動皆無咎。","sortOrder":255},
  {"id":"s_work_ttcm_7_256","chapterId":"ch_work_ttcm_7","text":"不穿窬，義也；謂非其有而取之曰盜，亦義也。惻隱，仁也；如天，亦仁也。故扩而充之，不可勝用。","sortOrder":256},
  {"id":"s_work_ttcm_7_257","chapterId":"ch_work_ttcm_7","text":"仁義之全體具足於性，因推行而有小大爾。小者不遺，知天性之在人；大而無外，知人之可達於天。","sortOrder":257},
  {"id":"s_work_ttcm_7_258","chapterId":"ch_work_ttcm_7","text":"自養，薄於人，私也；","sortOrder":258},
  {"id":"s_work_ttcm_7_259","chapterId":"ch_work_ttcm_7","text":"欲希眾而要譽。","sortOrder":259},
  {"id":"s_work_ttcm_7_260","chapterId":"ch_work_ttcm_7","text":"厚於人，私也。","sortOrder":260},
  {"id":"s_work_ttcm_7_261","chapterId":"ch_work_ttcm_7","text":"有意忘物。","sortOrder":261},
  {"id":"s_work_ttcm_7_262","chapterId":"ch_work_ttcm_7","text":"稱其才，","sortOrder":262},
  {"id":"s_work_ttcm_7_263","chapterId":"ch_work_ttcm_7","text":"當作“财”。","sortOrder":263},
  {"id":"s_work_ttcm_7_264","chapterId":"ch_work_ttcm_7","text":"隨其等，無驕吝之弊，斯得之矣。","sortOrder":264},
  {"id":"s_work_ttcm_7_265","chapterId":"ch_work_ttcm_7","text":"厚人者驕，自厚者吝。君子之用财，稱物平施，心無系焉爾。","sortOrder":265},
  {"id":"s_work_ttcm_7_266","chapterId":"ch_work_ttcm_7","text":"罪己則無尤。","sortOrder":266},
  {"id":"s_work_ttcm_7_267","chapterId":"ch_work_ttcm_7","text":"引過自责，盡仁盡禮，尤之者妄人而已，不足恤也。","sortOrder":267},
  {"id":"s_work_ttcm_7_268","chapterId":"ch_work_ttcm_7","text":"困辱非忧，取困辱為忧；","sortOrder":268},
  {"id":"s_work_ttcm_7_269","chapterId":"ch_work_ttcm_7","text":"以取困辱為忧，則困辱不足忧矣。","sortOrder":269},
  {"id":"s_work_ttcm_7_270","chapterId":"ch_work_ttcm_7","text":"榮利非樂，忘榮利為樂。","sortOrder":270},
  {"id":"s_work_ttcm_7_271","chapterId":"ch_work_ttcm_7","text":"有道則若固有之。","sortOrder":271},
  {"id":"s_work_ttcm_7_272","chapterId":"ch_work_ttcm_7","text":"“勇者不懼”，死且不避而反不安貧，則其勇將何施邪？不足稱也；","sortOrder":272},
  {"id":"s_work_ttcm_7_273","chapterId":"ch_work_ttcm_7","text":"人有氣誼所激，奋不顧身，而不能安貧者，不受嘑蹴以死而受萬鐘。勇之所施，施於所欲而已。勇莫勇於自製其欲。","sortOrder":273},
  {"id":"s_work_ttcm_7_274","chapterId":"ch_work_ttcm_7","text":"“仁者愛人”，彼不仁而疾之深，其仁不足稱也；皆迷谬不思之甚。故仲尼卒歸諸亂雲。","sortOrder":274},
  {"id":"s_work_ttcm_7_275","chapterId":"ch_work_ttcm_7","text":"思死與貧之孰重孰輕，則专致其勇於義矣；思彼之可疾惟其不仁，而我疾之甚，則自薄其愛，人將疾我矣。必內篤其仁而後愛篤以溥。","sortOrder":275},
  {"id":"s_work_ttcm_7_276","chapterId":"ch_work_ttcm_7","text":"挤人者人挤之，侮人者人侮之。“出乎爾者反乎爾”，理也；","sortOrder":276},
  {"id":"s_work_ttcm_7_277","chapterId":"ch_work_ttcm_7","text":"不仁、無禮者所應得。","sortOrder":277},
  {"id":"s_work_ttcm_7_278","chapterId":"ch_work_ttcm_7","text":"势不得反，亦理也。","sortOrder":278},
  {"id":"s_work_ttcm_7_279","chapterId":"ch_work_ttcm_7","text":"反則成乎相報無已之势，自反而無難於妄人，君子自盡容物之理。","sortOrder":279},
  {"id":"s_work_ttcm_7_280","chapterId":"ch_work_ttcm_7","text":"克己行法為賢，","sortOrder":280},
  {"id":"s_work_ttcm_7_281","chapterId":"ch_work_ttcm_7","text":"不已榮利失自守之道，克己之事也。審其宜而進退，行法之事也。","sortOrder":281},
  {"id":"s_work_ttcm_7_282","chapterId":"ch_work_ttcm_7","text":"樂己可法為聖。","sortOrder":282},
  {"id":"s_work_ttcm_7_283","chapterId":"ch_work_ttcm_7","text":"自有其樂，進退屈伸，因時而不累其心，皆得其中，允為行藏之法。","sortOrder":283},
  {"id":"s_work_ttcm_7_284","chapterId":"ch_work_ttcm_7","text":"聖與賢，跡相近而心之所至有差焉。辟世者依乎中庸，没世不遇而無嫌；辟地者不懷居以害仁，辟色者遠恥於將形，辟言者免害於禍辱，此為士清濁淹速之殊也。","sortOrder":284},
  {"id":"s_work_ttcm_7_285","chapterId":"ch_work_ttcm_7","text":"知幾則速，速則純乎清矣。知幾者，非於幾而察之，心純乎道，樂以忘忧，則見幾自明。故曰“知幾其神乎！”","sortOrder":285},
  {"id":"s_work_ttcm_7_286","chapterId":"ch_work_ttcm_7","text":"辟世辟地，雖聖人亦同，然忧樂於中，與賢者、其次者為異，故曰跡相近而心之所至者不同。","sortOrder":286},
  {"id":"s_work_ttcm_7_287","chapterId":"ch_work_ttcm_7","text":"賢者未免於忧，自克而已；聖人樂天，雖忧世而不以為悶。","sortOrder":287},
  {"id":"s_work_ttcm_7_288","chapterId":"ch_work_ttcm_7","text":"“進賢如不得已，將使卑逾尊，疏逾戚”之意，與《表記》所謂“事君難進而易退則位有序，易進而難退則亂也”相表里。","sortOrder":288},
  {"id":"s_work_ttcm_7_289","chapterId":"ch_work_ttcm_7","text":"君慎於進賢，非吝也；士慎於自進，非驕也。天位天職，非己所得私，君臣交慎，則天理順而人能畢效矣。","sortOrder":289},
  {"id":"s_work_ttcm_7_290","chapterId":"ch_work_ttcm_7","text":"“弓調而後求劲焉，馬服而後求良焉，士必悫而後智能焉。”不悫而多能，譬之豺狼不可近。","sortOrder":290},
  {"id":"s_work_ttcm_7_291","chapterId":"ch_work_ttcm_7","text":"君之取士，士之取友，以此求之則不失。悫者，人之恒心也。小人之誤國而賣友者，唯無恒而已。","sortOrder":291},
  {"id":"s_work_ttcm_7_292","chapterId":"ch_work_ttcm_7","text":"穀神能象其聲而應之，","sortOrder":292},
  {"id":"s_work_ttcm_7_293","chapterId":"ch_work_ttcm_7","text":"穀之虛而能應者曰神。象其聲，無異响也。","sortOrder":293},
  {"id":"s_work_ttcm_7_294","chapterId":"ch_work_ttcm_7","text":"非謂能報以律呂之变也，","sortOrder":294},
  {"id":"s_work_ttcm_7_295","chapterId":"ch_work_ttcm_7","text":"以虛應物而能象之，仿佛得其相似者而已。不能窮律呂之变，不能合同於異，盡情理之微也。","sortOrder":295},
  {"id":"s_work_ttcm_7_296","chapterId":"ch_work_ttcm_7","text":"猶卜筮叩以是言則報以是物而已，《易》所謂“同聲相應”是也。","sortOrder":296},
  {"id":"s_work_ttcm_7_297","chapterId":"ch_work_ttcm_7","text":"神之有方者，非能变者也。","sortOrder":297},
  {"id":"s_work_ttcm_7_298","chapterId":"ch_work_ttcm_7","text":"王弼謂“命呂者律”，語聲之变，非此之謂也。","sortOrder":298},
  {"id":"s_work_ttcm_7_299","chapterId":"ch_work_ttcm_7","text":"命，猶倡也。律倡之，呂和之，而聲之变乃備，律呂清濁洪細之不同，合異而同，变乃可盡。故孤陽不生，獨陰不成，至中之理，仁義不倚，君子之道。出處語默之不齊，命官取友之無党，高明沉潛之相濟，中道之矩，神化之所以行也。若應所同而违所異，則小人之道矣。惟其中無主而量不宏，以穀神為妙用而不以誠也。","sortOrder":299},
  {"id":"s_work_ttcm_7_300","chapterId":"ch_work_ttcm_7","text":"行前定而不疚，光明也。","sortOrder":300},
  {"id":"s_work_ttcm_7_301","chapterId":"ch_work_ttcm_7","text":"前定者，非執一而固必之；正大經以應天下，昭然使人喻之。","sortOrder":301},
  {"id":"s_work_ttcm_7_302","chapterId":"ch_work_ttcm_7","text":"大人虎变，夫何疚之有！","sortOrder":302},
  {"id":"s_work_ttcm_7_303","chapterId":"ch_work_ttcm_7","text":"大經正而萬变皆載其威，神行不同而心則一，所以不疚。","sortOrder":303},
  {"id":"s_work_ttcm_7_304","chapterId":"ch_work_ttcm_7","text":"言從作乂，名正，其言易知，人易從。聖人不患為政難，患民難喻。","sortOrder":304},
  {"id":"s_work_ttcm_7_305","chapterId":"ch_work_ttcm_7","text":"德禮之精意，民不能知，挈其要以定大經。故修辭立誠，聖人有其難其慎者，詳則多疑，略則不喻。《春秋》之筆削，遊、夏不能贊一辭，以此。","sortOrder":305},
  {"id":"s_work_ttcm_8_1","chapterId":"ch_work_ttcm_8","text":"張子正蒙註卷七","sortOrder":1},
  {"id":"s_work_ttcm_8_2","chapterId":"ch_work_ttcm_8","text":"有司篇","sortOrder":2},
  {"id":"s_work_ttcm_8_3","chapterId":"ch_work_ttcm_8","text":"有司，政之綱紀也。","sortOrder":3},
  {"id":"s_work_ttcm_8_4","chapterId":"ch_work_ttcm_8","text":"素習其事，則大綱具悉。","sortOrder":4},
  {"id":"s_work_ttcm_8_5","chapterId":"ch_work_ttcm_8","text":"始為政者，未暇論其賢否，必先正之，","sortOrder":5},
  {"id":"s_work_ttcm_8_6","chapterId":"ch_work_ttcm_8","text":"正其職掌。","sortOrder":6},
  {"id":"s_work_ttcm_8_7","chapterId":"ch_work_ttcm_8","text":"求得賢才而後舉之。","sortOrder":7},
  {"id":"s_work_ttcm_8_8","chapterId":"ch_work_ttcm_8","text":"為政者迫於有為，急取有司而更易之以快一時之人心，而新進浮薄之士骤用而不習於綱紀，废事滋甚。惟任有司而徐察之，知其賢不肖而後有所取舍，則事之利病，我既習知，人之賢否，無所混匿，此遠大之規存乎慎缓也。","sortOrder":8},
  {"id":"s_work_ttcm_8_9","chapterId":"ch_work_ttcm_8","text":"為政不以德，人不附且勞。","sortOrder":9},
  {"id":"s_work_ttcm_8_10","chapterId":"ch_work_ttcm_8","text":"勞，為民扰也。不本諸心得之理，非其至當，雖善而拂人之性。","sortOrder":10},
  {"id":"s_work_ttcm_8_11","chapterId":"ch_work_ttcm_8","text":"“子之不欲，雖賞之不竊欲。”生於不足則民盜，能使無欲則民不為盜。假設以子不欲之物賞子，使竊其所不欲，子必不竊。故為政者在乎足民，使無所不足，不見可欲，而盜必息矣。","sortOrder":11},
  {"id":"s_work_ttcm_8_12","chapterId":"ch_work_ttcm_8","text":"田畴易，稅斂薄，則所可欲者已足；食以時，用以禮，已足而無妄欲，即養以寓教，民不知而自化矣。","sortOrder":12},
  {"id":"s_work_ttcm_8_13","chapterId":"ch_work_ttcm_8","text":"為政必身倡之，且不愛其勞，又益之以不倦。","sortOrder":13},
  {"id":"s_work_ttcm_8_14","chapterId":"ch_work_ttcm_8","text":"以乾乾夕惕之心臨民，則民化；以無為清靜自逸，則民偷。","sortOrder":14},
  {"id":"s_work_ttcm_8_15","chapterId":"ch_work_ttcm_8","text":"天子讨而不伐，諸侯伐而不讨；","sortOrder":15},
  {"id":"s_work_ttcm_8_16","chapterId":"ch_work_ttcm_8","text":"自合六師曰讨，奉詞合眾曰伐。","sortOrder":16},
  {"id":"s_work_ttcm_8_17","chapterId":"ch_work_ttcm_8","text":"故雖湯、武之舉，不謂之讨而謂之伐。","sortOrder":17},
  {"id":"s_work_ttcm_8_18","chapterId":"ch_work_ttcm_8","text":"“伐夏救民”，“变伐大商”，皆曰“伐”是也。雖無可奉之命，必正告諸侯，眾允而後連師以伐。","sortOrder":18},
  {"id":"s_work_ttcm_8_19","chapterId":"ch_work_ttcm_8","text":"陳恒弒君，孔子請讨之，","sortOrder":19},
  {"id":"s_work_ttcm_8_20","chapterId":"ch_work_ttcm_8","text":"聖人於名必正，不輕言讨，必有所據。","sortOrder":20},
  {"id":"s_work_ttcm_8_21","chapterId":"ch_work_ttcm_8","text":"此必因周製鄰有弒逆，諸侯當不請而讨。","sortOrder":21},
  {"id":"s_work_ttcm_8_22","chapterId":"ch_work_ttcm_8","text":"胡氏曰：先發後聞可也。","sortOrder":22},
  {"id":"s_work_ttcm_8_23","chapterId":"ch_work_ttcm_8","text":"孟子又謂“征者上伐下，敵國不相征”，然湯十一征，非賜鈇鉞，則征讨之名，至周始定乎！","sortOrder":23},
  {"id":"s_work_ttcm_8_24","chapterId":"ch_work_ttcm_8","text":"疑湯之已賜鈇鉞，又疑夏、商未定征伐之名，皆正名必謹乎微之意。","sortOrder":24},
  {"id":"s_work_ttcm_8_25","chapterId":"ch_work_ttcm_8","text":"“野九一而助”，郊之外助也；“國中什一使自賦”，郊門之內通謂之國中，田不井授，故使什而自賦其一也。","sortOrder":25},
  {"id":"s_work_ttcm_8_26","chapterId":"ch_work_ttcm_8","text":"助九一、賦十一者，助則公田之耕其种馌，皆上給也。郊，近郊。滕地方五十里，三十里外之遠郊，非其境矣。","sortOrder":26},
  {"id":"s_work_ttcm_8_27","chapterId":"ch_work_ttcm_8","text":"“道千乘之國”，不及禮樂刑政，而雲“節用愛人，使民以時”，言能如是則法行，不能如是則法不徒行，禮樂刑政亦製數而己爾。","sortOrder":27},
  {"id":"s_work_ttcm_8_28","chapterId":"ch_work_ttcm_8","text":"節用，禮之本；愛人，樂之本；使民以時，則政簡而刑不濫；製數皆藉此以行慈俭，存心於萬物之原也。","sortOrder":28},
  {"id":"s_work_ttcm_8_29","chapterId":"ch_work_ttcm_8","text":"富而不治，不若貧而治；","sortOrder":29},
  {"id":"s_work_ttcm_8_30","chapterId":"ch_work_ttcm_8","text":"事得其理曰治。國不治，雖富而國必危。","sortOrder":30},
  {"id":"s_work_ttcm_8_31","chapterId":"ch_work_ttcm_8","text":"大而不察，不若小而察。","sortOrder":31},
  {"id":"s_work_ttcm_8_32","chapterId":"ch_work_ttcm_8","text":"盡民之情曰察。地大民眾而不得民之情，民必不附。","sortOrder":32},
  {"id":"s_work_ttcm_8_33","chapterId":"ch_work_ttcm_8","text":"報者，天下之利，率德而致。","sortOrder":33},
  {"id":"s_work_ttcm_8_34","chapterId":"ch_work_ttcm_8","text":"自有德於人，不求報而自致。","sortOrder":34},
  {"id":"s_work_ttcm_8_35","chapterId":"ch_work_ttcm_8","text":"善有勸，不善有沮，皆天下之利也。小人私己，故利於不治；","sortOrder":35},
  {"id":"s_work_ttcm_8_36","chapterId":"ch_work_ttcm_8","text":"治，明辨也。德怨不報，苟利目前而已。","sortOrder":36},
  {"id":"s_work_ttcm_8_37","chapterId":"ch_work_ttcm_8","text":"君子公物，利於治。","sortOrder":37},
  {"id":"s_work_ttcm_8_38","chapterId":"ch_work_ttcm_8","text":"使天下樂於德而憚於怨，與人為善之公也。此明以德報怨為小人之術。","sortOrder":38},
  {"id":"s_work_ttcm_8_39","chapterId":"ch_work_ttcm_8","text":"大易篇","sortOrder":39},
  {"id":"s_work_ttcm_8_40","chapterId":"ch_work_ttcm_8","text":"此篇廣釋《周易》之指，有大義，有微言，旁及於訓詁，而皆必合於道。蓋張子之學，得之《易》者深，與周子相為發明。而窮神達化，开示聖學之奧，不拘於象數之末以流於術數，則與邵子自謂得伏羲之秘授，比擬分合，有鬻術射覆之俑者迥異，切問近思者所宜深究也。","sortOrder":40},
  {"id":"s_work_ttcm_8_41","chapterId":"ch_work_ttcm_8","text":"大《易》不言有無，言有無，諸子之陋也。","sortOrder":41},
  {"id":"s_work_ttcm_8_42","chapterId":"ch_work_ttcm_8","text":"明有所以為明，幽有所以為幽；其在幽者，耳目見聞之力窮，而非理氣之本無也。老、莊之徒，於所不能見聞而决言之曰無，陋甚矣。《易》以乾之六陽、坤之六陰大備，而错綜以成变化為體，故乾非無陰，陰處於幽也；坤非無陽，陽處於幽也；剝、复之陽非少，夬、姤之陰非微，幽以為缊，明以為表也。故曰“《易》有太極”，乾、坤合於太和而富有日新之無所缺也。若周子之言無極者，言道無適主，化無定則，不可名之為極，而實有太極，亦以明夫無所謂無，而人見為無者皆有也。屈伸者，非理氣之生滅也；自明而之幽為屈，自幽而之明為伸；運於兩間者恒伸，而成乎形色者有屈。彼以無名為天地之始，滅盡為真空之藏。猶瞽者不見有物而遂謂無物，其愚不可瘳已。","sortOrder":42},
  {"id":"s_work_ttcm_8_43","chapterId":"ch_work_ttcm_8","text":"《易》語天地陰陽，情伪至隱赜而不可惡也。","sortOrder":43},
  {"id":"s_work_ttcm_8_44","chapterId":"ch_work_ttcm_8","text":"神化雖隱，变合雖赜，而皆本物理之固然，切生人之利用，故不可厭惡。","sortOrder":44},
  {"id":"s_work_ttcm_8_45","chapterId":"ch_work_ttcm_8","text":"諸子馳騁說辭，窮高極幽，而知德者厭其言。","sortOrder":45},
  {"id":"s_work_ttcm_8_46","chapterId":"ch_work_ttcm_8","text":"諸子論天人之理而終於無所行者，必不能與之相應，則又為遁辭以合於流俗，使人丧所守而波靡以浮沉於世。知德者，知其言之止於所不能見聞而非其實，故厭之。","sortOrder":46},
  {"id":"s_work_ttcm_8_47","chapterId":"ch_work_ttcm_8","text":"故言為非難，使君子樂取之為貴。","sortOrder":47},
  {"id":"s_work_ttcm_8_48","chapterId":"ch_work_ttcm_8","text":"可以通天下之志，成天下之務，盛德大業資焉，而有益於學，則君子樂取之。","sortOrder":48},
  {"id":"s_work_ttcm_8_49","chapterId":"ch_work_ttcm_8","text":"《易》一物而三才：陰陽，氣也，而謂之天；刚柔，质也，而謂之地；仁義，德也，而謂之人。","sortOrder":49},
  {"id":"s_work_ttcm_8_50","chapterId":"ch_work_ttcm_8","text":"才以成乎用者也。一物者，太和氤氲合同之體，含德而化光，其在氣則為陰陽，在质則為刚柔，在生人之心，載其神理以善用，則為仁義，皆太極所有之才也。故凡氣之類，可養而不可強之以消長者，皆天也；凡质之類，刚柔具體可以待用，載氣之清濁、柔強而成仁義之用者，皆地也；氣质之中，神理行乎其間，而惻隱羞惡之自動，則人所以體天地而成人道也。《易》備其理，故有見有隱而陰陽分，有奇有偶而刚柔立，有德有失而仁義審，體一物以盡三才之撰也。“謂之”雲者，天、地、人亦皆人為之名，而無實不能有名，無理不能有實，則皆因乎其才也。","sortOrder":50},
  {"id":"s_work_ttcm_8_51","chapterId":"ch_work_ttcm_8","text":"《易》為君子謀，不為小人謀。","sortOrder":51},
  {"id":"s_work_ttcm_8_52","chapterId":"ch_work_ttcm_8","text":"若火珠林之類，有吉凶而無善惡，小人資之謀利，君子取之，竊所未安。","sortOrder":52},
  {"id":"s_work_ttcm_8_53","chapterId":"ch_work_ttcm_8","text":"故撰德於卦，","sortOrder":53},
  {"id":"s_work_ttcm_8_54","chapterId":"ch_work_ttcm_8","text":"不但言吉凶，而必明乎得失之原，乾且曰“利貞”，况其餘乎！貞雖或凶，未有言利而不貞者也。","sortOrder":54},
  {"id":"s_work_ttcm_8_55","chapterId":"ch_work_ttcm_8","text":"雖爻有小大，","sortOrder":55},
  {"id":"s_work_ttcm_8_56","chapterId":"ch_work_ttcm_8","text":"陰過為小，陽勝為大，失其時位，則得失殊矣。","sortOrder":56},
  {"id":"s_work_ttcm_8_57","chapterId":"ch_work_ttcm_8","text":"及系辭其爻，必諭之以君子之義。","sortOrder":57},
  {"id":"s_work_ttcm_8_58","chapterId":"ch_work_ttcm_8","text":"有小人之爻，而聖人必系之以君子之辭。剝之六五，陰僭之極，而告以貫魚之義，或使君子治小人，或使小人知懼，不徇其失而以幸為吉。若火珠林之類，謀利計功，盜賊可以問利害，乃小人僥幸之術，君子所深惡也。","sortOrder":58},
  {"id":"s_work_ttcm_8_59","chapterId":"ch_work_ttcm_8","text":"一物而兩體，其太極之謂與！陰陽天道，象之成也；刚柔地道，法之效也；仁義人道，性之立也。","sortOrder":59},
  {"id":"s_work_ttcm_8_60","chapterId":"ch_work_ttcm_8","text":"成而為象，則有陰有陽；效而為法，則有刚有柔；立而為性，則有仁有義；皆太極本所併有，合同而化之實體也。故謂“太極靜而生陰，動而生陽”。自其動幾已後之化言之，則陰陽因動靜而著；若其本有為所動所靜者，則陰陽各為其體，而動靜者乃陰陽之動靜也。靜則陰氣聚以函陽，動則陽氣伸以荡陰，陰陽之非因動靜而始有，明矣。故曰兩體，不曰兩用。此張子之言所以獨得其實，而非從呼吸之一幾，测理之大全也。","sortOrder":60},
  {"id":"s_work_ttcm_8_61","chapterId":"ch_work_ttcm_8","text":"三才兩之，莫不有乾、坤之道。","sortOrder":61},
  {"id":"s_work_ttcm_8_62","chapterId":"ch_work_ttcm_8","text":"三才各有兩體，陰陽、柔刚、仁義，皆太和之氣，有其至健，又有其至順，併行不悖，相感以互相成之實。","sortOrder":62},
  {"id":"s_work_ttcm_8_63","chapterId":"ch_work_ttcm_8","text":"陰陽、刚柔、仁義之本立，而後知趨時應变。","sortOrder":63},
  {"id":"s_work_ttcm_8_64","chapterId":"ch_work_ttcm_8","text":"三才之道，氣也，质也，性也，其本則健順也。純乎陽而至健立，純乎陰而至順立，《周易》併建乾、坤於首，無有先後，天地一成之象也。無有地而無天、有天而無地之時，則無有有乾而無坤、有坤而無乾之道，無有陰無陽、有陽無陰之氣，無有刚無柔、有柔無刚之质，無有仁無義、有義無仁之性，無陽多陰少、陰多陽少、實有而虛無、明有而幽無之理，則屯、蒙明而鼎、革幽，鼎、革明而屯、蒙幽，六十四卦，六陰六陽具足，屈伸幽明各以其時而已。故小人有性，君子有情，趨時應变者惟其富有，是以可日新而不困。大易之蘊，唯張子所見，深切著明，盡三才之撰以體太極之誠，聖人复起，不能易也。邵子謂天开於子而無地，地辟於丑而無人，則無本而生，有待而滅，正與老、釋之妄同，非《周易》之道也。","sortOrder":64},
  {"id":"s_work_ttcm_8_65","chapterId":"ch_work_ttcm_8","text":"故“乾、坤毀則無以見《易》”。","sortOrder":65},
  {"id":"s_work_ttcm_8_66","chapterId":"ch_work_ttcm_8","text":"乾、坤非有毀也，曲學之士，執所見聞偶然之象，而雜以異端之小慧，見乾則疑無陰，見坤則疑無陽，見夬、姤則疑無剝、复，見屯、蒙則疑無鼎、革，因幽之不可見而疑其無，則是毀之矣。毀乾、坤十二位之實體，則六十二位之错綜，何據以趨時應变哉？","sortOrder":66},
  {"id":"s_work_ttcm_8_67","chapterId":"ch_work_ttcm_8","text":"六爻各盡利而動，","sortOrder":67},
  {"id":"s_work_ttcm_8_68","chapterId":"ch_work_ttcm_8","text":"筮之策，老則動而变，蓋道至其極而後可以变通，非富有不能日新。尧仁極矣，而後舜可用其竄殛；文王順極矣，而後武王可行其燮伐；德未盛而变，則妄矣。","sortOrder":68},
  {"id":"s_work_ttcm_8_69","chapterId":"ch_work_ttcm_8","text":"所以順陰陽、刚柔、仁義、性命之理也。","sortOrder":69},
  {"id":"s_work_ttcm_8_70","chapterId":"ch_work_ttcm_8","text":"其動也有大有小，有當位有不當位，蓋在天之氣有溫肅，在地之质有利钝，在人之性有偏倚，化不齊而究無損於太極之富有，其理固然。則雖凶而無悔，雖吝而無咎，善用之者皆可以盡天道人事之变而反其大經。故父顽而有至孝之子，國亡而有自靖之臣，極险阻以體易簡，則何屈非伸，而天下之理無不得。《易》之為君子謀者，順性命而变不失常也。","sortOrder":70},
  {"id":"s_work_ttcm_8_71","chapterId":"ch_work_ttcm_8","text":"故曰“六爻之動，三極之道也”。","sortOrder":71},
  {"id":"s_work_ttcm_8_72","chapterId":"ch_work_ttcm_8","text":"天、地、人所必有之变也。","sortOrder":72},
  {"id":"s_work_ttcm_8_73","chapterId":"ch_work_ttcm_8","text":"陽遍體眾陰，眾陰共事一陽，理也。","sortOrder":73},
  {"id":"s_work_ttcm_8_74","chapterId":"ch_work_ttcm_8","text":"體者，為之幹而達其情以治之也。順事，而承之也。此因時之变而言之，震、巽、坎、離、艮、兑，皆乾、坤之变也。若《易》之全體，乾、坤合德，君子小人同歸於道，天理人欲，從心不逾，則為理之大宗，無所容其亢抑矣。","sortOrder":74},
  {"id":"s_work_ttcm_8_75","chapterId":"ch_work_ttcm_8","text":"是故二君共一民，","sortOrder":75},
  {"id":"s_work_ttcm_8_76","chapterId":"ch_work_ttcm_8","text":"爭亂之端。","sortOrder":76},
  {"id":"s_work_ttcm_8_77","chapterId":"ch_work_ttcm_8","text":"一民事二君，","sortOrder":77},
  {"id":"s_work_ttcm_8_78","chapterId":"ch_work_ttcm_8","text":"立心不固。","sortOrder":78},
  {"id":"s_work_ttcm_8_79","chapterId":"ch_work_ttcm_8","text":"上與下皆小人之道也；","sortOrder":79},
  {"id":"s_work_ttcm_8_80","chapterId":"ch_work_ttcm_8","text":"上無讓德，下有貳心，亂世之道，小人之時為之。以此而推，心無定主，而役耳目以回惑於異端，氣不辅志，而任其便以張弛，皆小人之道。而忠信以為主，博學詳說以反約，斯君子之所尚。明體適用之學，於此辨之而已。","sortOrder":80},
  {"id":"s_work_ttcm_8_81","chapterId":"ch_work_ttcm_8","text":"一君而體二民，","sortOrder":81},
  {"id":"s_work_ttcm_8_82","chapterId":"ch_work_ttcm_8","text":"容保者大。","sortOrder":82},
  {"id":"s_work_ttcm_8_83","chapterId":"ch_work_ttcm_8","text":"二民而宗一君，","sortOrder":83},
  {"id":"s_work_ttcm_8_84","chapterId":"ch_work_ttcm_8","text":"大一統。","sortOrder":84},
  {"id":"s_work_ttcm_8_85","chapterId":"ch_work_ttcm_8","text":"上與下皆君子之道也。","sortOrder":85},
  {"id":"s_work_ttcm_8_86","chapterId":"ch_work_ttcm_8","text":"上不泄忘，下無異志，治世之道，君子之時為之。","sortOrder":86},
  {"id":"s_work_ttcm_8_87","chapterId":"ch_work_ttcm_8","text":"吉凶、变化、悔吝、刚柔，《易》之四象與！悔吝由贏不足而生，亦兩而已。","sortOrder":87},
  {"id":"s_work_ttcm_8_88","chapterId":"ch_work_ttcm_8","text":"天地之四象，陰、陽、刚、柔也；易之四象，則吉、凶、悔、吝也。吉凶，天之命，陰陽之变化也；悔吝，刚柔、贏不足之情，因乎地之质也：皆自兩儀而生。純陽為天，純陰為地，而天有陰，地有刚，又各自為陰陽；二而四，四而合二，道本如是，非判然一分而遂不相有也。在天有陰陽，在陽有老少，在數有九七，在地有柔刚，在陰有老少，在數有六八，於是而四象成。故《易》一爻之中，自陰有陽，有老有少，而四象備焉。震、坎、艮之一陽，老陰所变；巽、離、兑之一陰，老陽所变：故曰“四象生八卦”。邵子乃畫奇耦各一之象為兩儀，增為二畫之卦為四象，又增三畫之卦為四畫之卦凡十六，又增為五畫之卦凡三十有二，苟合其加一倍之法，立無名無象無義之卦，則使因倍而加，極之萬亿而不可象，非所謂致遠恐泥者欤！","sortOrder":88},
  {"id":"s_work_ttcm_8_89","chapterId":"ch_work_ttcm_8","text":"尚辭則言無所苟，","sortOrder":89},
  {"id":"s_work_ttcm_8_90","chapterId":"ch_work_ttcm_8","text":"尚，謂尊信而效法之。《易》辭本陰陽之定體以顯事理之幾微，尚之，修辭皆誠矣。","sortOrder":90},
  {"id":"s_work_ttcm_8_91","chapterId":"ch_work_ttcm_8","text":"尚变則動必精義，","sortOrder":91},
  {"id":"s_work_ttcm_8_92","chapterId":"ch_work_ttcm_8","text":"少不变，以循禮之中也；老变，以達事之窮也；尚之，隨時而求當，義必精矣。","sortOrder":92},
  {"id":"s_work_ttcm_8_93","chapterId":"ch_work_ttcm_8","text":"尚象則法必致用，","sortOrder":93},
  {"id":"s_work_ttcm_8_94","chapterId":"ch_work_ttcm_8","text":"推陰陽、刚柔、動止以製器，其用必利。","sortOrder":94},
  {"id":"s_work_ttcm_8_95","chapterId":"ch_work_ttcm_8","text":"尚占則謀必知來。","sortOrder":95},
  {"id":"s_work_ttcm_8_96","chapterId":"ch_work_ttcm_8","text":"因其時義以定吉凶，君子之謀與神合，知屈伸自然之理而順之也。","sortOrder":96},
  {"id":"s_work_ttcm_8_97","chapterId":"ch_work_ttcm_8","text":"四者非知神之所為，孰能與於此！","sortOrder":97},
  {"id":"s_work_ttcm_8_98","chapterId":"ch_work_ttcm_8","text":"《易》具其理而神存乎其中，必知神之所為，顯於象數而非徒象數，然後能學《易》而盡四者之用。王辅嗣之流，脱略象占，固有所末盡；而謂《易》但為占用，幾與壬遁、火珠林等，則健順毀而幾無以見《易》。然則四尚之義，缺一而不足以知《易》，故善言《易》者，其唯張子乎！","sortOrder":98},
  {"id":"s_work_ttcm_8_99","chapterId":"ch_work_ttcm_8","text":"《易》非天下之至精，則詞不足待天下之問；","sortOrder":99},
  {"id":"s_work_ttcm_8_100","chapterId":"ch_work_ttcm_8","text":"假設以啟疑而斷其必然也。天下之問至赜，《易》以易簡之詞盡之，問者各得焉，惟精於義而不倚形象之粗也。此言尚辭。","sortOrder":100},
  {"id":"s_work_ttcm_8_101","chapterId":"ch_work_ttcm_8","text":"非深，不足通天下之志；","sortOrder":101},
  {"id":"s_work_ttcm_8_102","chapterId":"ch_work_ttcm_8","text":"通天下之志，所以窮理也。此言尚变。","sortOrder":102},
  {"id":"s_work_ttcm_8_103","chapterId":"ch_work_ttcm_8","text":"非通变極數，則文不足以成物，象不足以製器，幾不足以成務；","sortOrder":103},
  {"id":"s_work_ttcm_8_104","chapterId":"ch_work_ttcm_8","text":"極數，盡數之損益而止於其則，故大衍止於五十，乾、坤之策止於三百六十，卦止於六十四，爻止於三百八十四，变通而有極，故言而有物，行而有製，製器而適於用。此言尚象。","sortOrder":104},
  {"id":"s_work_ttcm_8_105","chapterId":"ch_work_ttcm_8","text":"非周知兼體，則其神不能通天下之敬，不疾而速，不行而至。","sortOrder":105},
  {"id":"s_work_ttcm_8_106","chapterId":"ch_work_ttcm_8","text":"乾、坤併建，陰陽六位各至，足以隨時而相為隱顯以成错綜，則合六十四卦之德於乾、坤，而達乾坤之化於六十有二，道足而神行，其伸不齊，其屈不悔，故於天下之故，遺形器之滯累，而運以無方無體之大用，化之所以不可知也。此明《易》之為道，聖人以天性之神，盡天地之妙，而立為大經，達為百順，非其他象數之學所可與也。焦贛、京房、虞翻之流，惡足以知此，况如火珠林之鄙俗乎！","sortOrder":106},
  {"id":"s_work_ttcm_8_107","chapterId":"ch_work_ttcm_8","text":"示人吉凶，其道顯矣；","sortOrder":107},
  {"id":"s_work_ttcm_8_108","chapterId":"ch_work_ttcm_8","text":"貞妄得失，吉凶必應其則，示天下以可知也。","sortOrder":108},
  {"id":"s_work_ttcm_8_109","chapterId":"ch_work_ttcm_8","text":"知來藏往，其德行神矣；","sortOrder":109},
  {"id":"s_work_ttcm_8_110","chapterId":"ch_work_ttcm_8","text":"吉凶未著，從其貞妄之性情而早知其变之必至，所以詔天下於德者，其用神也。","sortOrder":110},
  {"id":"s_work_ttcm_8_111","chapterId":"ch_work_ttcm_8","text":"語蓍龟之用也。","sortOrder":111},
  {"id":"s_work_ttcm_8_112","chapterId":"ch_work_ttcm_8","text":"用，所以前民而正其行也。","sortOrder":112},
  {"id":"s_work_ttcm_8_113","chapterId":"ch_work_ttcm_8","text":"顯道者，危使平，易使傾，懼以終始，其要無咎之道也。","sortOrder":113},
  {"id":"s_work_ttcm_8_114","chapterId":"ch_work_ttcm_8","text":"吉凶之变，危而可使平，易而或以傾，得失爭於善惡之幾，能戒懼以持其終始，則要歸於無咎，其道至約而昭示無隱，所謂顯也，乃已成之象占也。","sortOrder":114},
  {"id":"s_work_ttcm_8_115","chapterId":"ch_work_ttcm_8","text":"神德行者，寂然不動，冥會於萬化之感而莫知為之者也。","sortOrder":115},
  {"id":"s_work_ttcm_8_116","chapterId":"ch_work_ttcm_8","text":"道雖顯於象占，而其所由然，不待事幾之至前，設其理於陰陽未剖之先，豫以應天下之感，人之所以不能知者，《易》已早知而待之。唯其達乎屈伸動靜之妙，故不俟時至事起而謀之，此不测之神固乎誠者也。","sortOrder":116},
  {"id":"s_work_ttcm_8_117","chapterId":"ch_work_ttcm_8","text":"受命如响，故“可與酬酢”；","sortOrder":117},
  {"id":"s_work_ttcm_8_118","chapterId":"ch_work_ttcm_8","text":"天道人事本通一而相酬答也。","sortOrder":118},
  {"id":"s_work_ttcm_8_119","chapterId":"ch_work_ttcm_8","text":"曲盡鬼謀，故“可以佑神”。","sortOrder":119},
  {"id":"s_work_ttcm_8_120","chapterId":"ch_work_ttcm_8","text":"佑，助也。鬼神之謀，奚能喻於人；而《易》曲盡以著其忠告，是贊助乎神也。","sortOrder":120},
  {"id":"s_work_ttcm_8_121","chapterId":"ch_work_ttcm_8","text":"开物於幾先，故曰“知來”；明患而弭其故，故曰”藏往”。","sortOrder":121},
  {"id":"s_work_ttcm_8_122","chapterId":"ch_work_ttcm_8","text":"弭患於前而後效著於後，《易》之戒占者，其貽謀久遠也。","sortOrder":122},
  {"id":"s_work_ttcm_8_123","chapterId":"ch_work_ttcm_8","text":"極數知來，前知也。","sortOrder":123},
  {"id":"s_work_ttcm_8_124","chapterId":"ch_work_ttcm_8","text":"前知者，非偶因一數之盈虛而测之；盡其數之所有，而萬变皆盡，來者無窮，莫之能逾也。","sortOrder":124},
  {"id":"s_work_ttcm_8_125","chapterId":"ch_work_ttcm_8","text":"前知其变，有道術以通之，君子所以措於民者遠矣。","sortOrder":125},
  {"id":"s_work_ttcm_8_126","chapterId":"ch_work_ttcm_8","text":"变無常而道自行乎其中，勸進其善之利而戒以惡之所自積，則民鹹可喻於君子之義，而天下萬世共由以利用安身。","sortOrder":126},
  {"id":"s_work_ttcm_8_127","chapterId":"ch_work_ttcm_8","text":"“絜靜精微”，不累其跡，知足而不賊，則於《易》深矣。","sortOrder":127},
  {"id":"s_work_ttcm_8_128","chapterId":"ch_work_ttcm_8","text":"此釋《禮記·經解》之言而示學《易》之法。絜靜者，不以私渎亂而絜清其志，靜以待吉凶之至也。精微者，察其屈伸消長之理而研於義之所宜也。不累其跡者，因數而知象，數為象立，不泥於數，固象而窮理，象為理設，不執於象也。知足不賊者，止於義之所可，而不謀利計功、僥幸於吉之先見以害正命也。如此以學《易》，則可以寡過；以占筮，則知懼而無咎矣。彼執象數而役志於吉凶者，固不足以與於《易》也。","sortOrder":128},
  {"id":"s_work_ttcm_8_129","chapterId":"ch_work_ttcm_8","text":"“天下之理得”，元也；","sortOrder":129},
  {"id":"s_work_ttcm_8_130","chapterId":"ch_work_ttcm_8","text":"萬事萬物皆天理之所秩叙，故體仁則統萬善。","sortOrder":130},
  {"id":"s_work_ttcm_8_131","chapterId":"ch_work_ttcm_8","text":"“會而通”，亨也；","sortOrder":131},
  {"id":"s_work_ttcm_8_132","chapterId":"ch_work_ttcm_8","text":"理無不通，故推而行之皆順。","sortOrder":132},
  {"id":"s_work_ttcm_8_133","chapterId":"ch_work_ttcm_8","text":"“說諸心”，利也；","sortOrder":133},
  {"id":"s_work_ttcm_8_134","chapterId":"ch_work_ttcm_8","text":"利合於義，則心得所安。","sortOrder":134},
  {"id":"s_work_ttcm_8_135","chapterId":"ch_work_ttcm_8","text":"“一天下之動”，貞也。","sortOrder":135},
  {"id":"s_work_ttcm_8_136","chapterId":"ch_work_ttcm_8","text":"大經正，則隨所動而皆不失其正，此推本而言之。謂乾具此四德，故以備萬善而协於一也。四德分而體用自相為因，元、貞，體也；亨、利，用也；惟元統天下之理，故於事通而於心說貞者，貞於其元。惟貞於仁，故通萬变而心常安，乃必通乎事而理始鹹得，說乎心而後居正不疑，則亨、利，用也而抑為體。故《文言》分析四德，而彖則大亨而利正，其義一也。孔子之《易》，曾何異於文王哉！","sortOrder":136},
  {"id":"s_work_ttcm_8_137","chapterId":"ch_work_ttcm_8","text":"乾之四德，終始萬物，迎之隨之，不見其首尾。","sortOrder":137},
  {"id":"s_work_ttcm_8_138","chapterId":"ch_work_ttcm_8","text":"天德之生殺，本無畛域；以一歲而言，循環往來，無有顯著之轍跡，非春果為首，冬果為尾；以萬物而言，各以其生殺為春秋，其春榮而冬落者，草木之凋者而已。蓋四德隨時而用，物亦隨所受而見為德，此見為義者彼見為仁，氤氲一氣之中，不倚一理以為先後，唯用之各得而已。故曰“天德不可為首”，有首有尾，則運窮於小成而有間斷矣。","sortOrder":138},
  {"id":"s_work_ttcm_8_139","chapterId":"ch_work_ttcm_8","text":"然後推本而言，當父母萬物。彖明萬物資始，故不得不以元配乾；坤其偶也，故不得以元配坤。","sortOrder":139},
  {"id":"s_work_ttcm_8_140","chapterId":"ch_work_ttcm_8","text":"推其父母萬物者而言之，則資始之德元為首；天生之，即地成之，故資生之德元為首。然未生而生，已生而繼其生，則萬物日受命於天地，而乾、坤無不為萬物之資，非初生之生理畢賦於物而後無所益。且一物有一物之始，即為一物之元，非天地定以何時為元而資之始生，因次亨、次利，待貞已竟而後复起元也。在人之成德而言，則仁義禮信初無定次。故求仁為本，而當其精義，則義以成仁；當其复禮，則禮以行仁；當其主信，則信以敦仁；四互相為緣起。此惟明於大化之浑淪與心源之寂感者，乃知元亨利貞統於乾、坤之妙，而四德分配之滯說，貞下起元之偏辭，不足以立矣。彖之以乾元坤元言資始資生者，就物之生，借端而言之爾。","sortOrder":140},
  {"id":"s_work_ttcm_8_141","chapterId":"ch_work_ttcm_8","text":"此章舊分為二章，今合之。","sortOrder":141},
  {"id":"s_work_ttcm_8_142","chapterId":"ch_work_ttcm_8","text":"仁統天下之善，禮嘉天下之會，義公天下之利，信一天下之動。","sortOrder":142},
  {"id":"s_work_ttcm_8_143","chapterId":"ch_work_ttcm_8","text":"惟其會於一原，故時措之而無不宜。不然，則一德之用在一事，而能周乎天下哉！先儒皆以智配貞，而貞者正而固；循物無违，正也，終始不渝，固也，則貞之為信，明矣。即以木火金水言之，坎之彖曰“行险而不失其信”，則君子之取於水者，取其不舍晝夜之誠，非取其曲流委順，遇員而員、遇方而方之诡隨也。君子之智以知德；仁而不愚，禮而不伪，義而不執，信而不谅，智可以周行乎四德而聽四德之用。智，知也，四德，行也。匪知之艱，惟行之艱，行焉而後可為德，《易》之言貞，立義精矣。張子之知德，迥出於諸子之上，於此信矣。","sortOrder":143},
  {"id":"s_work_ttcm_8_144","chapterId":"ch_work_ttcm_8","text":"六爻擬議，各正性命，故乾德旁通，不失太和而利且貞也。","sortOrder":144},
  {"id":"s_work_ttcm_8_145","chapterId":"ch_work_ttcm_8","text":"此釋乾彖“乾道变化”四句之義，以龍德擬議，六爻之道，自潛而亢，各有性命之正；時位不齊，應之異道，而皆不违乎太和之理，則無不利而不失其正，此純乾之所以利貞也。不然，因時蹈利，則违太和之全體而非貞矣。","sortOrder":145},
  {"id":"s_work_ttcm_8_146","chapterId":"ch_work_ttcm_8","text":"顏氏求龍德正中而未見其止，故擇中庸，得一善則拳拳服膺，叹夫子之忽焉前後也。","sortOrder":146},
  {"id":"s_work_ttcm_8_147","chapterId":"ch_work_ttcm_8","text":"得浑淪合一之理，則隨变化而性命各正，合太和之全體，顏子之所欲幾及而未逮也。","sortOrder":147},
  {"id":"s_work_ttcm_8_148","chapterId":"ch_work_ttcm_8","text":"乾三、四，位過中重刚，庸言庸行不足以濟之，","sortOrder":148},
  {"id":"s_work_ttcm_8_149","chapterId":"ch_work_ttcm_8","text":"九二得中，故庸言庸行足濟。","sortOrder":149},
  {"id":"s_work_ttcm_8_150","chapterId":"ch_work_ttcm_8","text":"雖大人之盛有所不安。外趨变化，內正性命，故其危其疑，","sortOrder":150},
  {"id":"s_work_ttcm_8_151","chapterId":"ch_work_ttcm_8","text":"九三曰“厲”，九四曰“或”。","sortOrder":151},
  {"id":"s_work_ttcm_8_152","chapterId":"ch_work_ttcm_8","text":"艱於見德者，時不得舍也。","sortOrder":152},
  {"id":"s_work_ttcm_8_153","chapterId":"ch_work_ttcm_8","text":"舍，止也。以庸言庸行為可據之德，止而不疑，則時可舍而舍矣。乾之三四，雖大人之庸德可行，而大經之正，必旁通於危疑，德不易見，安能據自信而釋其忧乎！舜以“不得乎親不可以為人”為危疑，而後庸德可見，時為之也。","sortOrder":153},
  {"id":"s_work_ttcm_8_154","chapterId":"ch_work_ttcm_8","text":"九五，大人化矣，天德位矣，成性聖矣，","sortOrder":154},
  {"id":"s_work_ttcm_8_155","chapterId":"ch_work_ttcm_8","text":"歷乎危疑而誠之至者，变無不通，故大化而聖。","sortOrder":155},
  {"id":"s_work_ttcm_8_156","chapterId":"ch_work_ttcm_8","text":"故既曰“利見大人”，又曰“聖人作而萬物睹”。","sortOrder":156},
  {"id":"s_work_ttcm_8_157","chapterId":"ch_work_ttcm_8","text":"為天下所利見而天下化之，大人之進乎聖也。蓋聖人之德，非於大人之外別有神变不测之道，但誠無不至，用以神而不用以跡，居德熟而危疑不易其心，及其至也，物自順之而聖德成矣。","sortOrder":157},
  {"id":"s_work_ttcm_8_158","chapterId":"ch_work_ttcm_8","text":"“亢龍有悔”，以位畫為言，若聖人則不失其正，何亢之有！","sortOrder":158},
  {"id":"s_work_ttcm_8_159","chapterId":"ch_work_ttcm_8","text":"上九之亢，聖人之窮，亦屈伸之常理，非聖人之亢有以致之。知進退存亡之必有，則安死全歸而道合於太虛，况窮困乎？位畫所直，聖人何疑焉！乾之六爻，純乎龍德。九二之學問宽仁，其本也；三四之危疑，所以通乎变也；九五之利見，变而通也；上九之亢，屈伸之常也；相因而互成，此乾道之旁通而無不利者，不失其正也。","sortOrder":159},
  {"id":"s_work_ttcm_8_160","chapterId":"ch_work_ttcm_8","text":"聖人用中之極，不勉而中；有大之極，不為其大。","sortOrder":160},
  {"id":"s_work_ttcm_8_161","chapterId":"ch_work_ttcm_8","text":"仁熟則不待勉，義精則下學上達，不顯其大，歷乎危疑而成性，九五之德也。","sortOrder":161},
  {"id":"s_work_ttcm_8_162","chapterId":"ch_work_ttcm_8","text":"大人望之，所謂絕尘而奔，峻極於天，不可階而升也。","sortOrder":162},
  {"id":"s_work_ttcm_8_163","chapterId":"ch_work_ttcm_8","text":"大人閒邪存誠而後光辉達，故不能测聖之藏。","sortOrder":163},
  {"id":"s_work_ttcm_8_164","chapterId":"ch_work_ttcm_8","text":"乾之九五曰“飛龍在天，利見大人”，乃大人造位天德，","sortOrder":164},
  {"id":"s_work_ttcm_8_165","chapterId":"ch_work_ttcm_8","text":"造，七到反，至也。位，臻其域也。","sortOrder":165},
  {"id":"s_work_ttcm_8_166","chapterId":"ch_work_ttcm_8","text":"成性跻聖者爾。","sortOrder":166},
  {"id":"s_work_ttcm_8_167","chapterId":"ch_work_ttcm_8","text":"以乾道保合太和，歷危疑而時乎中，大人義精仁熟而至乎聖，此孔子耳順、從心之候也。","sortOrder":167},
  {"id":"s_work_ttcm_8_168","chapterId":"ch_work_ttcm_8","text":"若夫受命所出，則所性不存焉。","sortOrder":168},
  {"id":"s_work_ttcm_8_169","chapterId":"ch_work_ttcm_8","text":"時至則聖人不违爾。","sortOrder":169},
  {"id":"s_work_ttcm_8_170","chapterId":"ch_work_ttcm_8","text":"故不曰“位乎君位”而曰“位乎天德”，不曰“大人君矣”而曰“大人造也”。","sortOrder":170},
  {"id":"s_work_ttcm_8_171","chapterId":"ch_work_ttcm_8","text":"乾體本六陽純成，而自爻言之，有漸造之象焉。惟德則日跻而聖，若位則乘時以登，無漸升之理。以為自潛而見，歷危疑躍飛而有天下，則是曹操、司馬懿之妄幹神器，皆大人矣。《易》不為小人謀，故必以言德者為正。","sortOrder":171},
  {"id":"s_work_ttcm_8_172","chapterId":"ch_work_ttcm_8","text":"庸言庸行，蓋天下經德達道，大人之德施於是者溥矣。","sortOrder":172},
  {"id":"s_work_ttcm_8_173","chapterId":"ch_work_ttcm_8","text":"溥，周遍也。明倫察物，無所遺也。","sortOrder":173},
  {"id":"s_work_ttcm_8_174","chapterId":"ch_work_ttcm_8","text":"天下之文明於是者著矣。","sortOrder":174},
  {"id":"s_work_ttcm_8_175","chapterId":"ch_work_ttcm_8","text":"秩叙明則禮樂興。","sortOrder":175},
  {"id":"s_work_ttcm_8_176","chapterId":"ch_work_ttcm_8","text":"然非窮变化之神以時措之宜，則或陷於非禮之禮，非義之義，","sortOrder":176},
  {"id":"s_work_ttcm_8_177","chapterId":"ch_work_ttcm_8","text":"時变而執其常，則不中而非禮，不宜而非義。惟盡人物之性，善惡、吉凶達乎天之併育併行不相悖害者以貞其大常，而後成己成物無有不化，此乾道之所以必歷三、四之危疑，而始得時中，以造飛龍之天德也。","sortOrder":177},
  {"id":"s_work_ttcm_8_178","chapterId":"ch_work_ttcm_8","text":"此顏子所以求龍德正中，乾乾進德，思處其極，未敢以方體之常安吾止也。","sortOrder":178},
  {"id":"s_work_ttcm_8_179","chapterId":"ch_work_ttcm_8","text":"顏子庸德已至，閒邪存誠，方進乎九三之惕厲，而未得九五之安止。方體之常，庸德之大綱也，拳拳服膺之善也。","sortOrder":179},
  {"id":"s_work_ttcm_8_180","chapterId":"ch_work_ttcm_8","text":"惟君子為能與時消息，順性命，躬天德而誠行之也。","sortOrder":180},
  {"id":"s_work_ttcm_8_181","chapterId":"ch_work_ttcm_8","text":"萬物皆備於我而會屈伸於一致，乃能與物消息。若大經未正而急於乘時，則性命不順，聖德之時中，與無忌憚之跡相似而實相违也。誠行之者，無非心理之實然。","sortOrder":181},
  {"id":"s_work_ttcm_8_182","chapterId":"ch_work_ttcm_8","text":"精義時措，故能保合太和，健利且貞，","sortOrder":182},
  {"id":"s_work_ttcm_8_183","chapterId":"ch_work_ttcm_8","text":"時措則利，保合則貞，而聖功唯在精義，精義則入神。","sortOrder":183},
  {"id":"s_work_ttcm_8_184","chapterId":"ch_work_ttcm_8","text":"孟子所謂始終條理，集大成於聖智者與！《易》曰：“大明終始，六位時成，時乘六龍以御天。乾道变化，各正性命，保合太和，乃利貞。”其此之謂乎！","sortOrder":184},
  {"id":"s_work_ttcm_8_185","chapterId":"ch_work_ttcm_8","text":"大明者，智之事也。天下之变不可测，而不能超乎大經，大經之法象有常，而其本諸心之不貳者，变化該焉。故庸德之修，進而歷危疑以盡变，具知萬变之不齊皆屈伸之常，天德之誠不息，則無屈不伸而萬物皆睹；是智之事，非徒聰明之察，乃刚健不息，歷变而常，力行精義而抵乎大明之效也。故乾卦閱潛、見、躍、飛而終始乎刚健，惟其不貳，是以不测，天德聖功，一而已矣。以卦象言之，天之純乎乾，無漸者也；以卦之數言之，筮者自一奇以至於十八变，純乎奇而得乾，有漸者也。卦言乾而不言天，天無為而運行有序，聖有功而成章始達，不得以天之浑成言乾，乾為天而卦非徒言天也。","sortOrder":185},
  {"id":"s_work_ttcm_8_186","chapterId":"ch_work_ttcm_8","text":"成性則跻聖而位天德。","sortOrder":186},
  {"id":"s_work_ttcm_8_187","chapterId":"ch_work_ttcm_8","text":"謂九五。","sortOrder":187},
  {"id":"s_work_ttcm_8_188","chapterId":"ch_work_ttcm_8","text":"乾九二正位於內卦之中，有君德矣，而非上治也。","sortOrder":188},
  {"id":"s_work_ttcm_8_189","chapterId":"ch_work_ttcm_8","text":"庸德盡於己，則秩叙正，可以君天下矣。非上治者，未能盡萬物之性，以達其变而使之化也。","sortOrder":189},
  {"id":"s_work_ttcm_8_190","chapterId":"ch_work_ttcm_8","text":"九五言上治者，言乎天之德，聖人之性，故舍曰君而謂之天。見大人，德與位之皆造也。","sortOrder":190},
  {"id":"s_work_ttcm_8_191","chapterId":"ch_work_ttcm_8","text":"君德正己以正物，天德正己而物自正。位，謂德效之成。","sortOrder":191},
  {"id":"s_work_ttcm_8_192","chapterId":"ch_work_ttcm_8","text":"大而得易簡之理，當成位乎天地之中，時舍而不受命，乾九二有焉。","sortOrder":192},
  {"id":"s_work_ttcm_8_193","chapterId":"ch_work_ttcm_8","text":"乾以易知，而兼言簡者，九二以陽居陰也。君德成矣而不欲受命，知前之有危疑，必乾惕而不可止故也。","sortOrder":193},
  {"id":"s_work_ttcm_8_194","chapterId":"ch_work_ttcm_8","text":"及夫化而聖矣，造而位天德矣，則富貴不足以言之。","sortOrder":194},
  {"id":"s_work_ttcm_8_195","chapterId":"ch_work_ttcm_8","text":"善世而不伐，欲罢而不能，加以乾乾夕惕，乃造於聖；聖則無疑於受命，時出則有天下而不與，時未出則以匹夫行天子之事，非徒富貴也。位天德者，德即其位也。","sortOrder":195},
  {"id":"s_work_ttcm_8_196","chapterId":"ch_work_ttcm_8","text":"“樂則行之，忧則违之”，主於求吾志而已，無所求於外。","sortOrder":196},
  {"id":"s_work_ttcm_8_197","chapterId":"ch_work_ttcm_8","text":"此聖功之始，暗然為己之修也。","sortOrder":197},
  {"id":"s_work_ttcm_8_198","chapterId":"ch_work_ttcm_8","text":"故善世博化，龍德而見者也；","sortOrder":198},
  {"id":"s_work_ttcm_8_199","chapterId":"ch_work_ttcm_8","text":"龍之為龍一也，蟄而見，見而飛，龍無異道，而蟄以求伸，道日盛，善世博化，光辉不能隱也。充實之美而進乎大，可以見矣。","sortOrder":199},
  {"id":"s_work_ttcm_8_200","chapterId":"ch_work_ttcm_8","text":"若潛而未見，則為己而已，未及人也。","sortOrder":200},
  {"id":"s_work_ttcm_8_201","chapterId":"ch_work_ttcm_8","text":"為己可以及人，然必成章而始達。","sortOrder":201},
  {"id":"s_work_ttcm_8_202","chapterId":"ch_work_ttcm_8","text":"“成德為行”，德成自信，則不疑所行，日見乎外可也。","sortOrder":202},
  {"id":"s_work_ttcm_8_203","chapterId":"ch_work_ttcm_8","text":"誠有諸己而充實，無疑於見之行矣。此初九之馴至乎九二也。","sortOrder":203},
  {"id":"s_work_ttcm_8_204","chapterId":"ch_work_ttcm_8","text":"乾九三修辭亦誠，非繼日待旦如周公，不足以終其業。","sortOrder":204},
  {"id":"s_work_ttcm_8_205","chapterId":"ch_work_ttcm_8","text":"修辭所以成天下之務，立誠所以正在己之經。九二德成而可見之行，九三則修應世之業。業因物而見功，事赜而变不测，事变之興，不易以達吾之義；惟處心危而歷事敏，業乃可終。故九二立本，九三趨時，成章而達也。","sortOrder":205},
  {"id":"s_work_ttcm_8_206","chapterId":"ch_work_ttcm_8","text":"九四以陽居陰，故曰“在淵”；","sortOrder":206},
  {"id":"s_work_ttcm_8_207","chapterId":"ch_work_ttcm_8","text":"心隱而不能急喻諸物也。","sortOrder":207},
  {"id":"s_work_ttcm_8_208","chapterId":"ch_work_ttcm_8","text":"能不忘於躍，乃可免咎。","sortOrder":208},
  {"id":"s_work_ttcm_8_209","chapterId":"ch_work_ttcm_8","text":"含德自信而不求物之喻，可靜而不可動，無以化天下，故必不忘躍。","sortOrder":209},
  {"id":"s_work_ttcm_8_210","chapterId":"ch_work_ttcm_8","text":"“非為邪也”，終其義也。","sortOrder":210},
  {"id":"s_work_ttcm_8_211","chapterId":"ch_work_ttcm_8","text":"然其不忘於躍，乃義之固然，变而不失其中，及物而非以失己，有密用焉，達此則可造於天德矣。義者，因時大正之謂；終其義，歷险而成乎易也。","sortOrder":211},
  {"id":"s_work_ttcm_8_212","chapterId":"ch_work_ttcm_8","text":"至健而易，至順而簡，","sortOrder":212},
  {"id":"s_work_ttcm_8_213","chapterId":"ch_work_ttcm_8","text":"反天下之大經，無所間雜，故易簡；天不能违，化物而倦，則健順至矣。","sortOrder":213},
  {"id":"s_work_ttcm_8_214","chapterId":"ch_work_ttcm_8","text":"故其险其阻，不可階而升，不可勉而至。","sortOrder":214},
  {"id":"s_work_ttcm_8_215","chapterId":"ch_work_ttcm_8","text":"心純乎理，天下之至難者也；見聞之知，勇敢之行，不足以企及也。","sortOrder":215},
  {"id":"s_work_ttcm_8_216","chapterId":"ch_work_ttcm_8","text":"仲尼猶天，“九五飛龍在天”，其致一也。","sortOrder":216},
  {"id":"s_work_ttcm_8_217","chapterId":"ch_work_ttcm_8","text":"聖功熟則不测而天矣。","sortOrder":217},
  {"id":"s_work_ttcm_8_218","chapterId":"ch_work_ttcm_8","text":"“坤至柔而動也刚”，乃積大势成而然也。","sortOrder":218},
  {"id":"s_work_ttcm_8_219","chapterId":"ch_work_ttcm_8","text":"惟刚乃可以載物，地之載必積廣厚，故曰地势坤。順理之至，於物無撓，非老氏致柔之說也。","sortOrder":219},
  {"id":"s_work_ttcm_8_220","chapterId":"ch_work_ttcm_8","text":"乾至健無體，為感速，故易知；","sortOrder":220},
  {"id":"s_work_ttcm_8_221","chapterId":"ch_work_ttcm_8","text":"乾，氣之健也。無體者，至健則不滯於一事，隨方即應，可以御萬理而不窮，故無所遲疑，洞達明示而易知。","sortOrder":221},
  {"id":"s_work_ttcm_8_222","chapterId":"ch_work_ttcm_8","text":"坤至順不煩，其施普，故簡能。","sortOrder":222},
  {"id":"s_work_ttcm_8_223","chapterId":"ch_work_ttcm_8","text":"坤，情之順也。順天而行，己無专見之能以煩扰爭功，而乾之所至，隨效法焉，故不言勞而功能自著。此以乾、坤之德言。","sortOrder":223},
  {"id":"s_work_ttcm_8_224","chapterId":"ch_work_ttcm_8","text":"坤先迷不知所從，故失道；後能順聽，則得其常矣。","sortOrder":224},
  {"id":"s_work_ttcm_8_225","chapterId":"ch_work_ttcm_8","text":"以順為德者，無必為之志，而聽乾之生，因而成之，則先無適從，而有所順聽乃得大常之理，所謂“無成有終”也，臣道也，婦道也，下學之道也。君子之學，以乾為主，知之而後效，故大學之始，必知止至善以立大經，而後循循以進，斯善用坤而不迷。","sortOrder":225},
  {"id":"s_work_ttcm_8_226","chapterId":"ch_work_ttcm_8","text":"造化之功，發乎動，","sortOrder":226},
  {"id":"s_work_ttcm_8_227","chapterId":"ch_work_ttcm_8","text":"不動則不生，由屈而伸，動之機為生之始，震也。","sortOrder":227},
  {"id":"s_work_ttcm_8_228","chapterId":"ch_work_ttcm_8","text":"畢達乎順，","sortOrder":228},
  {"id":"s_work_ttcm_8_229","chapterId":"ch_work_ttcm_8","text":"動而順其性，則物各自達，巽也。形諸明。","sortOrder":229},
  {"id":"s_work_ttcm_8_230","chapterId":"ch_work_ttcm_8","text":"畢達則形發而神見矣，離也。","sortOrder":230},
  {"id":"s_work_ttcm_8_231","chapterId":"ch_work_ttcm_8","text":"養諸容，","sortOrder":231},
  {"id":"s_work_ttcm_8_232","chapterId":"ch_work_ttcm_8","text":"不息其長養，惟其厚德能容也，坤也。","sortOrder":232},
  {"id":"s_work_ttcm_8_233","chapterId":"ch_work_ttcm_8","text":"載遂乎說，","sortOrder":233},
  {"id":"s_work_ttcm_8_234","chapterId":"ch_work_ttcm_8","text":"能容則物自得而欣畅，兑也。","sortOrder":234},
  {"id":"s_work_ttcm_8_235","chapterId":"ch_work_ttcm_8","text":"润勝乎健，","sortOrder":235},
  {"id":"s_work_ttcm_8_236","chapterId":"ch_work_ttcm_8","text":"“润”字疑誤。自得堅勝而成质，乾也。","sortOrder":236},
  {"id":"s_work_ttcm_8_237","chapterId":"ch_work_ttcm_8","text":"不匮乎勞，","sortOrder":237},
  {"id":"s_work_ttcm_8_238","chapterId":"ch_work_ttcm_8","text":"歷险阻而各有以自成，坎也。","sortOrder":238},
  {"id":"s_work_ttcm_8_239","chapterId":"ch_work_ttcm_8","text":"終始乎止。","sortOrder":239},
  {"id":"s_work_ttcm_8_240","chapterId":"ch_work_ttcm_8","text":"成則止矣。止者，即止其所動之功，終始一，則艮也。此釋“帝出乎震”一章之義，而以動為造化之權舆，則以明夫不動不止，而歷至於止皆以善其動而為功。彼以無為為化源者，終而不能始，屈而不能伸，死而不能生，昧於造化之理而與鬼為徒，其妄明矣。","sortOrder":240},
  {"id":"s_work_ttcm_8_241","chapterId":"ch_work_ttcm_8","text":"健、動、陷、止，刚之象；順、麗、入、說，柔之體。","sortOrder":241},
  {"id":"s_work_ttcm_8_242","chapterId":"ch_work_ttcm_8","text":"體，謂體性。此言八卦成能之用，故不言陰陽而言柔刚。","sortOrder":242},
  {"id":"s_work_ttcm_8_243","chapterId":"ch_work_ttcm_8","text":"“巽為木”，萌於下，滋於上；","sortOrder":243},
  {"id":"s_work_ttcm_8_244","chapterId":"ch_work_ttcm_8","text":"陰弱為萌，陽盛為滋。益盛也。","sortOrder":244},
  {"id":"s_work_ttcm_8_245","chapterId":"ch_work_ttcm_8","text":"“為繩直”，順以達也；","sortOrder":245},
  {"id":"s_work_ttcm_8_246","chapterId":"ch_work_ttcm_8","text":"陰不违陽，故順而直。達者，順之功效。","sortOrder":246},
  {"id":"s_work_ttcm_8_247","chapterId":"ch_work_ttcm_8","text":"“為工”，巧且順也；","sortOrder":247},
  {"id":"s_work_ttcm_8_248","chapterId":"ch_work_ttcm_8","text":"陰不亢而潛伏，巧也。順者，順物之理。","sortOrder":248},
  {"id":"s_work_ttcm_8_249","chapterId":"ch_work_ttcm_8","text":"“為白”，所遇而從也；","sortOrder":249},
  {"id":"s_work_ttcm_8_250","chapterId":"ch_work_ttcm_8","text":"遇藍則青，遇茜則赤；陰從於陽，無定质也。","sortOrder":250},
  {"id":"s_work_ttcm_8_251","chapterId":"ch_work_ttcm_8","text":"“為長，為高”，木之性也；“為臭”，風也，入也；","sortOrder":251},
  {"id":"s_work_ttcm_8_252","chapterId":"ch_work_ttcm_8","text":"臭因風而入，鼻不因形而達。","sortOrder":252},
  {"id":"s_work_ttcm_8_253","chapterId":"ch_work_ttcm_8","text":"“於人為寡發廣顙”，躁人之象也。","sortOrder":253},
  {"id":"s_work_ttcm_8_254","chapterId":"ch_work_ttcm_8","text":"陽亢於陰，故躁。凡言為者，皆謂变化之象也。萬物之形體才性，萬事之变遷，莫非陰陽、屈伸、消長之所成，故《說卦》略言之以通物理，而占者得其事應，皆造化必然之效。然可以理通而不可以象测，執而泥之，則亦射覆之賤術而已矣。","sortOrder":254},
  {"id":"s_work_ttcm_8_255","chapterId":"ch_work_ttcm_8","text":"“坎”為血卦，周流而勞，血之象也；","sortOrder":255},
  {"id":"s_work_ttcm_8_256","chapterId":"ch_work_ttcm_8","text":"入於险阻，故勞。血經營身中，勞則溢。","sortOrder":256},
  {"id":"s_work_ttcm_8_257","chapterId":"ch_work_ttcm_8","text":"“為赤”，其色也。","sortOrder":257},
  {"id":"s_work_ttcm_8_258","chapterId":"ch_work_ttcm_8","text":"血亦水穀之滋，得勞而赤。","sortOrder":258},
  {"id":"s_work_ttcm_8_259","chapterId":"ch_work_ttcm_8","text":"“離為乾卦”，“於木為科上槁”，附且躁也。","sortOrder":259},
  {"id":"s_work_ttcm_8_260","chapterId":"ch_work_ttcm_8","text":"“躁”，當作燥。一陰附於兩陽，熯之而燥。","sortOrder":260},
  {"id":"s_work_ttcm_8_261","chapterId":"ch_work_ttcm_8","text":"“艮為小石”，堅難入也；","sortOrder":261},
  {"id":"s_work_ttcm_8_262","chapterId":"ch_work_ttcm_8","text":"陽止於上，下有重陰不能入。","sortOrder":262},
  {"id":"s_work_ttcm_8_263","chapterId":"ch_work_ttcm_8","text":"“為径路”，通或寡也。","sortOrder":263},
  {"id":"s_work_ttcm_8_264","chapterId":"ch_work_ttcm_8","text":"止則寡通。","sortOrder":264},
  {"id":"s_work_ttcm_8_265","chapterId":"ch_work_ttcm_8","text":"“兑為附决”，內實則外附必决也；","sortOrder":265},
  {"id":"s_work_ttcm_8_266","chapterId":"ch_work_ttcm_8","text":"陽盛，陰雖附之，必為所决絕。","sortOrder":266},
  {"id":"s_work_ttcm_8_267","chapterId":"ch_work_ttcm_8","text":"為毀折，物成則上柔者必折也。","sortOrder":267},
  {"id":"s_work_ttcm_8_268","chapterId":"ch_work_ttcm_8","text":"一陰孤立於上，不能自固。","sortOrder":268},
  {"id":"s_work_ttcm_8_269","chapterId":"ch_work_ttcm_8","text":"“坤”為文，眾色也；“為眾”，容載廣也。","sortOrder":269},
  {"id":"s_work_ttcm_8_270","chapterId":"ch_work_ttcm_8","text":"一色表著曰章，眾色雜成曰文，坤廣容物，多受雜色。","sortOrder":270},
  {"id":"s_work_ttcm_8_271","chapterId":"ch_work_ttcm_8","text":"“乾為大赤”，其正色；","sortOrder":271},
  {"id":"s_work_ttcm_8_272","chapterId":"ch_work_ttcm_8","text":"此取乾南坤北之象。","sortOrder":272},
  {"id":"s_work_ttcm_8_273","chapterId":"ch_work_ttcm_8","text":"“為冰”，健極而寒甚也。","sortOrder":273},
  {"id":"s_work_ttcm_8_274","chapterId":"ch_work_ttcm_8","text":"又取乾位西北之象。於此見八卦方位，初無定在，隨所見而测之，皆可為方，故曰“神無方，易無體”，無方而非其方，無體而非其體也。分文王、伏羲方位之異，術士之說爾。","sortOrder":274},
  {"id":"s_work_ttcm_8_275","chapterId":"ch_work_ttcm_8","text":"“震為萑苇”，“為蒼筤竹”，“為旉”，皆蕃鮮也。","sortOrder":275},
  {"id":"s_work_ttcm_8_276","chapterId":"ch_work_ttcm_8","text":"旉，花也。蕃盛鮮明，動則榮也。","sortOrder":276},
  {"id":"s_work_ttcm_8_277","chapterId":"ch_work_ttcm_8","text":"一陷溺而不得出為坎，一附麗而不能去為離。","sortOrder":277},
  {"id":"s_work_ttcm_8_278","chapterId":"ch_work_ttcm_8","text":"一，奇畫，讀如奇。坎，陽陷陰中，入於坎宮；離，陰為主於內，二陽交附之。二卦皆以陽取義，不使陰得為主，扶陽抑陰之義。","sortOrder":278},
  {"id":"s_work_ttcm_8_279","chapterId":"ch_work_ttcm_8","text":"艮一陽為主於兩陰之上，各得其位而其势止也。易言光明者多艮之象，","sortOrder":279},
  {"id":"s_work_ttcm_8_280","chapterId":"ch_work_ttcm_8","text":"卦有艮體，則系之以光明。","sortOrder":280},
  {"id":"s_work_ttcm_8_281","chapterId":"ch_work_ttcm_8","text":"著則明之義也。","sortOrder":281},
  {"id":"s_work_ttcm_8_282","chapterId":"ch_work_ttcm_8","text":"陽見於外為著。陽明昭示而無所隱，異於震之動也微，坎之陷也匿。","sortOrder":282},
  {"id":"s_work_ttcm_8_283","chapterId":"ch_work_ttcm_8","text":"蒙無遽亨之理，由九二循循行時中之亨也。","sortOrder":283},
  {"id":"s_work_ttcm_8_284","chapterId":"ch_work_ttcm_8","text":"初生始蒙，其明未著，無能遽通乎萬事，惟九二得中，以陽居陰，循循漸啟其明，則隨時而養以中道，所以亨也。天之生人也，孩提之知識，惟不即發，異於雏犢之慧，故靈於萬物；取精用物，資天地之和，漸啟其明，而知乃通天之中也。聖人之教人，不能早喻以廣大高明之極致，敷五教以在宽而黎民時变，循文禮以善誘而高堅卓立，不使之迫於小成而養之以正，聖人之中也。故曰“大學之教存乎時”。","sortOrder":284},
  {"id":"s_work_ttcm_8_285","chapterId":"ch_work_ttcm_8","text":"“不終日貞吉”，言疾正則吉也。","sortOrder":285},
  {"id":"s_work_ttcm_8_286","chapterId":"ch_work_ttcm_8","text":"善惡之幾，决於一念；濡滯不决，則陷溺不振。","sortOrder":286},
  {"id":"s_work_ttcm_8_287","chapterId":"ch_work_ttcm_8","text":"仲尼以六二以陰居陰，獨無累於四，故其介如石；","sortOrder":287},
  {"id":"s_work_ttcm_8_288","chapterId":"ch_work_ttcm_8","text":"欲而能反於理，不以聲色味货之狎習相泥相取，一念决之而終不易。","sortOrder":288},
  {"id":"s_work_ttcm_8_289","chapterId":"ch_work_ttcm_8","text":"雖體柔順，以其在中而靜，何俟終日，必知幾而正矣。","sortOrder":289},
  {"id":"s_work_ttcm_8_290","chapterId":"ch_work_ttcm_8","text":"小人之誘君子，聲色货利之引耳目，急與之爭，必將不勝，惟靜以處之，則其不足與為緣之幾自見，故曰“無欲故靜”；靜則欲止不行，而所當為之義以靜極而動，沛然勇為而無非正矣。","sortOrder":290},
  {"id":"s_work_ttcm_8_291","chapterId":"ch_work_ttcm_8","text":"坎維心亨，故行有尚；外雖積险，苟處之心亨不疑，則難必濟而往有功也。","sortOrder":291},
  {"id":"s_work_ttcm_8_292","chapterId":"ch_work_ttcm_8","text":"陽在內，心象也。二陰陷陽，险矣；而陽刚居中，秉正不撓，直行而無忧疑，忠臣孝子之所以遂志而濟险，行其所當為，泰然處之而已。","sortOrder":292},
  {"id":"s_work_ttcm_8_293","chapterId":"ch_work_ttcm_8","text":"中孚，上巽施之，下悅承之，其中必有感化而出焉者。蓋孚者覆乳之象，有必生之理。","sortOrder":293},
  {"id":"s_work_ttcm_8_294","chapterId":"ch_work_ttcm_8","text":"中孚二陰在內，疑非施信之道；然以柔相感，如鳥之伏子，有必生之理，光武所謂“以柔道治天下”者，亦治道之一術也。敔按：孟子曰：“中也養不中，才也養不才。”中孚者，養道也，必信乃能養也","sortOrder":294},
  {"id":"s_work_ttcm_8_295","chapterId":"ch_work_ttcm_8","text":"物因雷動，雷動不妄，","sortOrder":295},
  {"id":"s_work_ttcm_8_296","chapterId":"ch_work_ttcm_8","text":"以其時出則固不妄。","sortOrder":296},
  {"id":"s_work_ttcm_8_297","chapterId":"ch_work_ttcm_8","text":"則物亦不妄，","sortOrder":297},
  {"id":"s_work_ttcm_8_298","chapterId":"ch_work_ttcm_8","text":"雷出而物生必信。","sortOrder":298},
  {"id":"s_work_ttcm_8_299","chapterId":"ch_work_ttcm_8","text":"故曰“物與無妄”。","sortOrder":299},
  {"id":"s_work_ttcm_8_300","chapterId":"ch_work_ttcm_8","text":"雷之動也，無恒日，無恒聲，無恒處，此疑於不测而非有誠然，陽氣發以應天，自與物候相感而不忒；聖人之動，神化不测，出人亿度之表，而乘時以應天，天下自效其誠。皆天理物性之實然，無所增損也。","sortOrder":300},
  {"id":"s_work_ttcm_8_301","chapterId":"ch_work_ttcm_8","text":"靜之動也，無休息之期，","sortOrder":301},
  {"id":"s_work_ttcm_8_302","chapterId":"ch_work_ttcm_8","text":"眾人之動，因感而動，事至而念起，事去而念息。君子於物感未交之际，耳目不倚於見聞，言動不形於聲色，而不顯亦臨，不諫亦入；其於靜也無瞬息之怠放而息，則其動也亦發邇而不忘遠，及遠而不泄邇，終身終日不使其心儳焉，此存心窮理盡性之學也。","sortOrder":302},
  {"id":"s_work_ttcm_8_303","chapterId":"ch_work_ttcm_8","text":"故地雷為卦，言“反”又言“复”；","sortOrder":303},
  {"id":"s_work_ttcm_8_304","chapterId":"ch_work_ttcm_8","text":"地，靜體也；雷，動幾也。反，止於靜也；复，興於動也。","sortOrder":304},
  {"id":"s_work_ttcm_8_305","chapterId":"ch_work_ttcm_8","text":"終則有始，循環無窮。","sortOrder":305},
  {"id":"s_work_ttcm_8_306","chapterId":"ch_work_ttcm_8","text":"事物有終始，心無終始。天之以冬終，以春始，以亥終，以子始，人謂之然爾；運行循環，天不自知終始也。謂十一月一陽生，冬至前一日無陽者，董仲舒之陋也。复之為卦，但取至靜而含動之象，豈有時哉！卦氣之說，小道之泥也。","sortOrder":306},
  {"id":"s_work_ttcm_8_307","chapterId":"ch_work_ttcm_8","text":"入，指其化而裁之爾；","sortOrder":307},
  {"id":"s_work_ttcm_8_308","chapterId":"ch_work_ttcm_8","text":"入，非收视反聽，寂靜以守黑之謂也；化之未形，裁之以神而節宣其化，入者所以出也。“入”，坊本作“人”，蓋誤。","sortOrder":308},
  {"id":"s_work_ttcm_8_309","chapterId":"ch_work_ttcm_8","text":"深，其反也；","sortOrder":309},
  {"id":"s_work_ttcm_8_310","chapterId":"ch_work_ttcm_8","text":"極深以窮其理，反求之內也。","sortOrder":310},
  {"id":"s_work_ttcm_8_311","chapterId":"ch_work_ttcm_8","text":"幾，其复也；","sortOrder":311},
  {"id":"s_work_ttcm_8_312","chapterId":"ch_work_ttcm_8","text":"幾，動而應以所精之義，复於外也。","sortOrder":312},
  {"id":"s_work_ttcm_8_313","chapterId":"ch_work_ttcm_8","text":"故曰“反复其道”，","sortOrder":313},
  {"id":"s_work_ttcm_8_314","chapterId":"ch_work_ttcm_8","text":"反而具复之道。","sortOrder":314},
  {"id":"s_work_ttcm_8_315","chapterId":"ch_work_ttcm_8","text":"又曰“出入無疾”。","sortOrder":315},
  {"id":"s_work_ttcm_8_316","chapterId":"ch_work_ttcm_8","text":"其人不忘，故其出不妄，動靜一致，而靜不偏枯，動不凌競矣。","sortOrder":316},
  {"id":"s_work_ttcm_8_317","chapterId":"ch_work_ttcm_8","text":"“益長裕而不設”，益以實也；","sortOrder":317},
  {"id":"s_work_ttcm_8_318","chapterId":"ch_work_ttcm_8","text":"益，損外卦四爻之陽以益初爻，使群陰得主，陽以富有之實而益人，故施之可裕，而非所不可損者強與之。蓋益者否之变，益之以陽，所以消否。敔按：三陽三陰之卦，皆自否、泰而來，故曰“益者否之变”","sortOrder":318},
  {"id":"s_work_ttcm_8_319","chapterId":"ch_work_ttcm_8","text":"妄加以不誠之益，非益也。","sortOrder":319},
  {"id":"s_work_ttcm_8_320","chapterId":"ch_work_ttcm_8","text":"非所當得而益之為不誠。","sortOrder":320},
  {"id":"s_work_ttcm_8_321","chapterId":"ch_work_ttcm_8","text":"井渫而不食，強施行，惻然且不售，作《易》者之叹與！","sortOrder":321},
  {"id":"s_work_ttcm_8_322","chapterId":"ch_work_ttcm_8","text":"強施行，不忍置也；惻然，不食而情愈迫也。作《易》者，謂周公。周公盡心王室而成王不受訓，心懷耿忧，所以叹也。其後孔子於魯，孟子於齊，知不可而為之，世終莫知，聖賢且無知之何。故竭忠盡教而人不寤，君子之所深惻也。","sortOrder":322},
  {"id":"s_work_ttcm_8_323","chapterId":"ch_work_ttcm_8","text":"阖戶，靜密也；辟戶，動達也；","sortOrder":323},
  {"id":"s_work_ttcm_8_324","chapterId":"ch_work_ttcm_8","text":"陰爻耦，辟象也；而言阖戶者，坤之德順，以受陽之施，阖而納之，處靜以藏動也。陽之爻奇，阖象也；而言辟戶者，乾之德健而發，施於陰者無所吝，而動則無不達也。陰、陽，质也；乾、坤，性也；阖辟之體用，互用不倚於质之所偏，此乾、坤之互為质性，不爽夫太和也。","sortOrder":324},
  {"id":"s_work_ttcm_8_325","chapterId":"ch_work_ttcm_8","text":"形开而目睹耳聞，受於陽也。","sortOrder":325},
  {"id":"s_work_ttcm_8_326","chapterId":"ch_work_ttcm_8","text":"形，陰之靜也。开者，陽氣動而开之，睹聞乘其動而達焉。雖陰魄發光，而必待开於陽，故辟者陽之功能，寐則陰函陽而閟之於內，陰之效也。靜以居動，則動者不離乎靜，動以動其靜，則靜者亦動而靈，此一阖一辟所以為道也。敔按：莊子曰：“其寐也魂交，其覺也形开”，張子蓋取交言，而以《易》阖其辟之義通之","sortOrder":326},
  {"id":"s_work_ttcm_8_327","chapterId":"ch_work_ttcm_8","text":"辭各指其所之，聖人之情也。","sortOrder":327},
  {"id":"s_work_ttcm_8_328","chapterId":"ch_work_ttcm_8","text":"指，示也；所之者，人所行也。吉凶存乎命而著乎象，人所攸往之善，存乎性而親其所趨。聖人正天下以成人之美、遠人之惡者，其情於辭而見。故《易》之《系辭》，非但明吉凶，而必指人以所趨向。","sortOrder":328},
  {"id":"s_work_ttcm_8_329","chapterId":"ch_work_ttcm_8","text":"指之以趨時盡利，順性命之理，臻三極之道也。","sortOrder":329},
  {"id":"s_work_ttcm_8_330","chapterId":"ch_work_ttcm_8","text":"指示占者使崇德而廣業，非但告以吉凶也。趨時，因時擇中，日乾夕惕也；盡利，精義而行，則物無不利也。能率吾性之良能以盡人事，則在天之命，順者俟之，逆者立之，而人極立，贊天地而參之矣。蓋一事之微，其行其止，推其所至，皆天理存亡之幾。精義以時中，則自寢食言笑以至生死禍福之交，皆與天道相為陟降。因爻立象，因事明占，而昭示顯道，無一而非性命之理。《易》為君子謀，初非以趨利避害也。","sortOrder":330},
  {"id":"s_work_ttcm_8_331","chapterId":"ch_work_ttcm_8","text":"能從之，則不陷於凶悔矣，","sortOrder":331},
  {"id":"s_work_ttcm_8_332","chapterId":"ch_work_ttcm_8","text":"因所占以進退精義，則無不利矣。","sortOrder":332},
  {"id":"s_work_ttcm_8_333","chapterId":"ch_work_ttcm_8","text":"所謂“变動以利言”者也。","sortOrder":333},
  {"id":"s_work_ttcm_8_334","chapterId":"ch_work_ttcm_8","text":"变動，謂占者玩占而徙義；利者，利用而合於義也。","sortOrder":334},
  {"id":"s_work_ttcm_8_335","chapterId":"ch_work_ttcm_8","text":"然爻有攻取愛惡，本情素動，因生吉凶悔吝而不可变者；","sortOrder":335},
  {"id":"s_work_ttcm_8_336","chapterId":"ch_work_ttcm_8","text":"時位不相當，陰陽不相协，故天數人事，有攻取愛惡之不同，性情動於積素以生吉凶悔吝，旦夕莫可挽回者，非天數之固然，攻取愛惡，所酿成者漸也。","sortOrder":336},
  {"id":"s_work_ttcm_8_337","chapterId":"ch_work_ttcm_8","text":"乃所謂“吉凶以情遷”者也。","sortOrder":337},
  {"id":"s_work_ttcm_8_338","chapterId":"ch_work_ttcm_8","text":"君子之情豫定，則先迷而後必得；小人之情已淫，則惡積而不可掩。故履信思順，則天佑而無不利，迷复則十年有凶；非理無可复，情已遷則不可再返也。","sortOrder":338},
  {"id":"s_work_ttcm_8_339","chapterId":"ch_work_ttcm_8","text":"能深存《系辭》所命，則二者之動見矣。","sortOrder":339},
  {"id":"s_work_ttcm_8_340","chapterId":"ch_work_ttcm_8","text":"命，告也，爻所告人者也。二者，盡利之道，遷变之情也。情遷者，君子安命而無求，利告者，君子盡道以補過，惟深察乎《系辭》，則自辨其所之矣。","sortOrder":340},
  {"id":"s_work_ttcm_8_341","chapterId":"ch_work_ttcm_8","text":"又有義命當吉、當凶、當否、當亨者，當吉則居富貴而不疑，當凶則罹死亡而不恤，當否則退藏以聽小人之利，當亨則大行而司袞鉞之權。","sortOrder":341},
  {"id":"s_work_ttcm_8_342","chapterId":"ch_work_ttcm_8","text":"聖人不使避凶趨吉，一以貞勝而不顧。","sortOrder":342},
  {"id":"s_work_ttcm_8_343","chapterId":"ch_work_ttcm_8","text":"辭明示以凶而不為謀趨吉之道，貞勝則凶不避也。","sortOrder":343},
  {"id":"s_work_ttcm_8_344","chapterId":"ch_work_ttcm_8","text":"如“大人否亨”、","sortOrder":344},
  {"id":"s_work_ttcm_8_345","chapterId":"ch_work_ttcm_8","text":"雖否而亨。","sortOrder":345},
  {"id":"s_work_ttcm_8_346","chapterId":"ch_work_ttcm_8","text":"“有損自天”、","sortOrder":346},
  {"id":"s_work_ttcm_8_347","chapterId":"ch_work_ttcm_8","text":"禍福忽至而不知所自來。","sortOrder":347},
  {"id":"s_work_ttcm_8_348","chapterId":"ch_work_ttcm_8","text":"“過涉滅顶凶無咎”、雖凶無咎。","sortOrder":348},
  {"id":"s_work_ttcm_8_349","chapterId":"ch_work_ttcm_8","text":"損益“龟不克违”，","sortOrder":349},
  {"id":"s_work_ttcm_8_350","chapterId":"ch_work_ttcm_8","text":"福至非其所欲而不能辭。","sortOrder":350},
  {"id":"s_work_ttcm_8_351","chapterId":"ch_work_ttcm_8","text":"及“其命亂也”之類。","sortOrder":351},
  {"id":"s_work_ttcm_8_352","chapterId":"ch_work_ttcm_8","text":"雖吉而非正命。","sortOrder":352},
  {"id":"s_work_ttcm_8_353","chapterId":"ch_work_ttcm_8","text":"三者情異，不可不察。","sortOrder":353},
  {"id":"s_work_ttcm_8_354","chapterId":"ch_work_ttcm_8","text":"有陨自天不克违，則慎所以處之；其命亂，則必去之；否亨、凶無咎，則决於赴難而不懼。三者，天數物情之所必有，貞勝而不為所動，聖人之情亦見乎辭。此《大易》所以與術數之說喻義喻利之分也。","sortOrder":354},
  {"id":"s_work_ttcm_8_355","chapterId":"ch_work_ttcm_8","text":"因爻象之既動，明吉凶於未形，故曰“爻象動乎內，吉凶見乎外”。","sortOrder":355},
  {"id":"s_work_ttcm_8_356","chapterId":"ch_work_ttcm_8","text":"爻象以理而生象數，在人為善惡得失之幾初動於心，故曰內；吉凶因象數而成得失之由，在人為事起物應而成败著見，故曰外。","sortOrder":356},
  {"id":"s_work_ttcm_8_357","chapterId":"ch_work_ttcm_8","text":"“富有”者，大無外也；","sortOrder":357},
  {"id":"s_work_ttcm_8_358","chapterId":"ch_work_ttcm_8","text":"神行於天地之間，無所不通，天之包地外而併育併行者，乾道也。","sortOrder":358},
  {"id":"s_work_ttcm_8_359","chapterId":"ch_work_ttcm_8","text":"“日新”者，久無窮也。","sortOrder":359},
  {"id":"s_work_ttcm_8_360","chapterId":"ch_work_ttcm_8","text":"順受陽施以成萬化而不息，榮枯相代而弥見其新，坤道也。","sortOrder":360},
  {"id":"s_work_ttcm_8_361","chapterId":"ch_work_ttcm_8","text":"顯，其聚也；隱，其散也。","sortOrder":361},
  {"id":"s_work_ttcm_8_362","chapterId":"ch_work_ttcm_8","text":"聚則積之大而可見，散則極於微而不可見。顯且隱，幽明所以存乎象；於其象而觀之，則有幽明之異，人所知也。","sortOrder":362},
  {"id":"s_work_ttcm_8_363","chapterId":"ch_work_ttcm_8","text":"聚且散，推荡所以妙乎神。","sortOrder":363},
  {"id":"s_work_ttcm_8_364","chapterId":"ch_work_ttcm_8","text":"其聚其散，推荡之者神為之也，而其必信乎理者誠也。以《易》言之，乾陽顯而陰隱，坤陰顯而陽隱，屯、蒙、鼎、革、剝、复、夬、姤之屬相错而迭為隱顯，聚之著也。乾、坤併建，而大生廣生以備天下之险阻，位有去來，時有衰王，維之荡之，日月、雷風、男女、死生、榮謝，同歸而殊涂，萬化不测而必肖其性情，神之妙也，非象所得而現矣。","sortOrder":364},
  {"id":"s_work_ttcm_8_365","chapterId":"ch_work_ttcm_8","text":"“变化進退之象”雲者，進退之動也微，必验之於变化之著，故察進退之理為難，察变化之象為易。","sortOrder":365},
  {"id":"s_work_ttcm_8_366","chapterId":"ch_work_ttcm_8","text":"变者，陰变為陽；化者，陽化為陰；六十四卦互相变易而象成。進退者，推荡而屈伸也；推之則伸而進，荡之則屈而退，而变化生焉。此神之所為，非存神者不能知其必然之理。然學《易》者必於变化而察之，知其當然而後可進求其所以然，王弼“得言忘象，得意忘言”之說非也。","sortOrder":366},
  {"id":"s_work_ttcm_8_367","chapterId":"ch_work_ttcm_8","text":"“忧悔吝者存乎介”，欲觀《易》象之小疵，宜存志靜，知所動之幾微也。","sortOrder":367},
  {"id":"s_work_ttcm_8_368","chapterId":"ch_work_ttcm_8","text":"悔吝非凶，故曰小疵。爻之有悔吝，動违其時，在幾微之間爾。靜察其理，則正而失宜，過不在大，審之於獨知之际，以消息其應违，不容不戒懼矣。","sortOrder":368},
  {"id":"s_work_ttcm_8_369","chapterId":"ch_work_ttcm_8","text":"往之為義，有已往，","sortOrder":369},
  {"id":"s_work_ttcm_8_370","chapterId":"ch_work_ttcm_8","text":"如“素履往”之類。","sortOrder":370},
  {"id":"s_work_ttcm_8_371","chapterId":"ch_work_ttcm_8","text":"有方往，","sortOrder":371},
  {"id":"s_work_ttcm_8_372","chapterId":"ch_work_ttcm_8","text":"如“往蹇”之類。","sortOrder":372},
  {"id":"s_work_ttcm_8_373","chapterId":"ch_work_ttcm_8","text":"臨文者不可不察。","sortOrder":373},
  {"id":"s_work_ttcm_8_374","chapterId":"ch_work_ttcm_8","text":"已往則保成而補過，方往則勉慎以圖功，察其文，可以因其占而得所宜。","sortOrder":374},
  {"id":"s_work_ttcm_9_1","chapterId":"ch_work_ttcm_9","text":"張子正蒙註卷八","sortOrder":1},
  {"id":"s_work_ttcm_9_2","chapterId":"ch_work_ttcm_9","text":"樂器篇","sortOrder":2},
  {"id":"s_work_ttcm_9_3","chapterId":"ch_work_ttcm_9","text":"此篇釋《詩》《書》之義。而先之以《樂》，《樂》與《詩》相為體用者也。","sortOrder":3},
  {"id":"s_work_ttcm_9_4","chapterId":"ch_work_ttcm_9","text":"樂器有相，周、召之治與！","sortOrder":4},
  {"id":"s_work_ttcm_9_5","chapterId":"ch_work_ttcm_9","text":"相，韦表糠里。《記》曰“治亂以相”，相之音菀而不宣，所以節音之雜亂，周、召之治還醇止亂之道。","sortOrder":5},
  {"id":"s_work_ttcm_9_6","chapterId":"ch_work_ttcm_9","text":"其有雅，太公之志乎！","sortOrder":6},
  {"id":"s_work_ttcm_9_7","chapterId":"ch_work_ttcm_9","text":"雅，柷類，以木為桶，中有椎，击之。《記》曰“訊疾以雅”，促樂使疾也，功以速成而定，故曰“太公之志”。","sortOrder":7},
  {"id":"s_work_ttcm_9_8","chapterId":"ch_work_ttcm_9","text":"雅者正也，直己而行正也，故訊疾蹈厲者，太公之事邪！","sortOrder":8},
  {"id":"s_work_ttcm_9_9","chapterId":"ch_work_ttcm_9","text":"敬勝怠，義勝欲，正己而正人，以伐無道，事不得缓。","sortOrder":9},
  {"id":"s_work_ttcm_9_10","chapterId":"ch_work_ttcm_9","text":"《詩》亦有《雅》，亦正言而直歌之，無隱諷譎諫之巧也。","sortOrder":10},
  {"id":"s_work_ttcm_9_11","chapterId":"ch_work_ttcm_9","text":"正《雅》直言功德，变《雅》正言得失，異於風之隱譎，故謂之《雅》，與樂器之雅同義。即此以明《詩》《樂》之理一。","sortOrder":11},
  {"id":"s_work_ttcm_9_12","chapterId":"ch_work_ttcm_9","text":"《象武》，武王初有天下，象文王武功之舞，歌《維清》以奏之。自註：成童舞之","sortOrder":12},
  {"id":"s_work_ttcm_9_13","chapterId":"ch_work_ttcm_9","text":"戡黎伐崇，文王之武功。","sortOrder":13},
  {"id":"s_work_ttcm_9_14","chapterId":"ch_work_ttcm_9","text":"《大武》，武王没，嗣王象武王之功之舞，歌《武》以奏之。自註：冠者舞酌，周公没，嗣王以武功之成由周公，告其成於宗廟之歌也。自註：十三舞焉","sortOrder":14},
  {"id":"s_work_ttcm_9_15","chapterId":"ch_work_ttcm_9","text":"“酌”，《禮記》作“勺”。此明《詩》《樂》之合一以象功。學者學《詩》則學樂，興與成，始終同其條理。惟其興發志意於先王之盛德大業，則動靜交養，以墒於四支，發於事業，蔑不成矣。","sortOrder":15},
  {"id":"s_work_ttcm_9_16","chapterId":"ch_work_ttcm_9","text":"興己之善，觀人之志，群而思無邪，怨而止禮義，入可事親，出可事君。但言君父，舉其重者也。","sortOrder":16},
  {"id":"s_work_ttcm_9_17","chapterId":"ch_work_ttcm_9","text":"奋發於為善而通天下之志，群而貞，怨而節，盡己與人之道，盡於是矣。事父事君以此，可以寡過，推以行之，天下無非中正和平之節，故不可以不學。","sortOrder":17},
  {"id":"s_work_ttcm_9_18","chapterId":"ch_work_ttcm_9","text":"志至詩至，有象必可名，有名斯有體，故禮亦至焉。","sortOrder":18},
  {"id":"s_work_ttcm_9_19","chapterId":"ch_work_ttcm_9","text":"象，心有其成事之象也。禮，見於事而成法則也。詩以言達志，禮以實副名，故學詩可以正志，可以立體。","sortOrder":19},
  {"id":"s_work_ttcm_9_20","chapterId":"ch_work_ttcm_9","text":"幽贊天地之道，非聖人而能哉！","sortOrder":20},
  {"id":"s_work_ttcm_9_21","chapterId":"ch_work_ttcm_9","text":"凡有其理而未形，待人而明之者，皆幽也。聖人知化之有神，存乎变合而化可顯，故能助天地而終其用。","sortOrder":21},
  {"id":"s_work_ttcm_9_22","chapterId":"ch_work_ttcm_9","text":"詩人謂“後稷之穡，有相之道”，贊育之一端也。","sortOrder":22},
  {"id":"s_work_ttcm_9_23","chapterId":"ch_work_ttcm_9","text":"天能生之，地能成之，而斟酌飽滿以全二氣之粹美者，人之能也。穡有可丰美之道而未盡昭著，後稷因天之能，盡地之利，以人能合而成之，凡聖人所以用天地之神而化其已成之质，使充實光辉，皆若此。","sortOrder":23},
  {"id":"s_work_ttcm_9_24","chapterId":"ch_work_ttcm_9","text":"禮矯實求稱，或文或质，居物後而不可常也。","sortOrder":24},
  {"id":"s_work_ttcm_9_25","chapterId":"ch_work_ttcm_9","text":"實，情也，情不足則益之以文，情有餘則存之以质。物亦實也，情已動而事且成，乃因時因事而損益之，在情事之後，矯之正也。文质各矯其偏，故不可常。","sortOrder":25},
  {"id":"s_work_ttcm_9_26","chapterId":"ch_work_ttcm_9","text":"他人才未美，故絢飾之以文；莊薑才甚美，乃更絢飾之用质素。","sortOrder":26},
  {"id":"s_work_ttcm_9_27","chapterId":"ch_work_ttcm_9","text":"质已成之後，禮因損益之以致美，無一定之絢在才质之先也。此明因才節宣之道存乎禮，故有其质者，不可不學禮以善其後。","sortOrder":27},
  {"id":"s_work_ttcm_9_28","chapterId":"ch_work_ttcm_9","text":"下文“繪事後素”，素謂其材，字雖同而義施各異，故設色之工，材黃白者必繪以青赤，材赤黑必繪以粉素。","sortOrder":28},
  {"id":"s_work_ttcm_9_29","chapterId":"ch_work_ttcm_9","text":"繪非異色，則文不足以宣，故禮以人之情而著其美，酌情事之異而損有餘、補不足也。敔接：此章註義，亦就張子之意而通之","sortOrder":29},
  {"id":"s_work_ttcm_9_30","chapterId":"ch_work_ttcm_9","text":"“陟降庭止”，上下無常，非為邪也，進德修業，欲及時也。“在帝左右”，所謂欲及時者與！","sortOrder":30},
  {"id":"s_work_ttcm_9_31","chapterId":"ch_work_ttcm_9","text":"作而有為，上也，陟也；退而自省，下也，降也；一陟一降，皆有天理之明明赫赫者臨之於庭，則動靜無恒而一於正道。不執一，則存省愈嚴，陟降一心，德業一致，此朝乾夕惕、存神盡性之密用，作聖之功於斯至矣。","sortOrder":31},
  {"id":"s_work_ttcm_9_32","chapterId":"ch_work_ttcm_9","text":"《江沱》之媵以類行而欲丧朋，故無怨；嫡以類行而不能丧其朋，故不以媵備數。","sortOrder":32},
  {"id":"s_work_ttcm_9_33","chapterId":"ch_work_ttcm_9","text":"類者，貴賤之分，朋，私心也。媵安於卑賤之類而忘己私，嫡處於尊貴而恃其類，懷私以不能容物，此得朋丧朋之異，公私之分也。","sortOrder":33},
  {"id":"s_work_ttcm_9_34","chapterId":"ch_work_ttcm_9","text":"卒能自悔，得安貞之吉，乃終有慶而其嘯也歌。","sortOrder":34},
  {"id":"s_work_ttcm_9_35","chapterId":"ch_work_ttcm_9","text":"自悔，則能丧其私而先迷後得矣。坤之為德，以厚載有容為美，而私心間之，則吝而驕；惟去私以廣容，而後能承天以利正，婦道也，臣道也，下學遜志，遏欲以存理之始功也。","sortOrder":35},
  {"id":"s_work_ttcm_9_36","chapterId":"ch_work_ttcm_9","text":"采枲耳，議酒食，女子所以奉賓祭、厚君親者足矣；又思酌使臣之勞，推及求賢審官，王季、文王之心，豈是過與！","sortOrder":36},
  {"id":"s_work_ttcm_9_37","chapterId":"ch_work_ttcm_9","text":"此引伸毛《傳》之旨而廣言之。盡仁孝以為本，而推以愛賢任官，王季、文王之德也；後妃以順承之，則乾、坤合德矣。","sortOrder":37},
  {"id":"s_work_ttcm_9_38","chapterId":"ch_work_ttcm_9","text":"《甘棠》初能使民不忍去，中能使民不忍傷，卒能使民知心敬而不渎之以拜，","sortOrder":38},
  {"id":"s_work_ttcm_9_39","chapterId":"ch_work_ttcm_9","text":"以拜為致敬之辭，於義未安。","sortOrder":39},
  {"id":"s_work_ttcm_9_40","chapterId":"ch_work_ttcm_9","text":"非善教寢明，能取是於民哉！","sortOrder":40},
  {"id":"s_work_ttcm_9_41","chapterId":"ch_work_ttcm_9","text":"由善教，故仁聲作。","sortOrder":41},
  {"id":"s_work_ttcm_9_42","chapterId":"ch_work_ttcm_9","text":"“振振”，勸使勉也；“歸哉歸哉”，序其情也。","sortOrder":42},
  {"id":"s_work_ttcm_9_43","chapterId":"ch_work_ttcm_9","text":"先勸君子急公而後望其歸，發乎情，止乎禮義。","sortOrder":43},
  {"id":"s_work_ttcm_9_44","chapterId":"ch_work_ttcm_9","text":"“卷耳”，念臣下小勞則思小飲之，","sortOrder":44},
  {"id":"s_work_ttcm_9_45","chapterId":"ch_work_ttcm_9","text":"兕觥。","sortOrder":45},
  {"id":"s_work_ttcm_9_46","chapterId":"ch_work_ttcm_9","text":"大勞則思大飲之，","sortOrder":46},
  {"id":"s_work_ttcm_9_47","chapterId":"ch_work_ttcm_9","text":"金罍。","sortOrder":47},
  {"id":"s_work_ttcm_9_48","chapterId":"ch_work_ttcm_9","text":"甚則知其怨苦噓叹。婦人能此，則陰诐私謁害政之心，知其無也。","sortOrder":48},
  {"id":"s_work_ttcm_9_49","chapterId":"ch_work_ttcm_9","text":"一於正則不邪。","sortOrder":49},
  {"id":"s_work_ttcm_9_50","chapterId":"ch_work_ttcm_9","text":"“綢直如發”，貧者紒縱無餘，順其發而直韜之爾。","sortOrder":50},
  {"id":"s_work_ttcm_9_51","chapterId":"ch_work_ttcm_9","text":"縱以帛斂發而作紒，古者紒不露發，帛有餘，則斜纏繞之，帛不足，則裁直條如其發之長而直韜之，此言俭而不失其容也。","sortOrder":51},
  {"id":"s_work_ttcm_9_52","chapterId":"ch_work_ttcm_9","text":"《蓼萧》《棠華》“有譽處兮”，皆謂君接己溫厚，則下情得伸，讒毀不入而美名可保也。","sortOrder":52},
  {"id":"s_work_ttcm_9_53","chapterId":"ch_work_ttcm_9","text":"處，謂居之安也。讒毀之人，皆由君有刻薄疑忌之心；君仁臣忠，無所容其間矣。","sortOrder":53},
  {"id":"s_work_ttcm_9_54","chapterId":"ch_work_ttcm_9","text":"《商頌》“顧予烝嘗，湯孫之將”，言祖考來顧以助湯孫也。","sortOrder":54},
  {"id":"s_work_ttcm_9_55","chapterId":"ch_work_ttcm_9","text":"祭者，子孫之心，然必時和年丰，天人胥洽，而後禮備；而孝思可伸，則在祖考之佑助也。古者以祭成為大福。敔按：引此亦與“陟降庭止，在帝左右”之意相通","sortOrder":55},
  {"id":"s_work_ttcm_9_56","chapterId":"ch_work_ttcm_9","text":"“鄂不韡韡”，兄弟之見，不致文於初，本諸誠也。","sortOrder":56},
  {"id":"s_work_ttcm_9_57","chapterId":"ch_work_ttcm_9","text":"鄂，花萼；不，音跗；花承蒂小茎也。花方含蕊，文未著，而韡韡之生意在中，興兄弟之好一本諸誠，非徒尚文。","sortOrder":57},
  {"id":"s_work_ttcm_9_58","chapterId":"ch_work_ttcm_9","text":"《采苓》之詩，舍旃則無然，為言則求所得，所譽必有所试，厚之至也。","sortOrder":58},
  {"id":"s_work_ttcm_9_59","chapterId":"ch_work_ttcm_9","text":"舍旃，毀之令斥也；無然，無毀也；為言，扬其美也；求所得，察其何所得當於道。譽必试也，毀則無譽，必试而謂之厚者，人之刻薄賊恩，喜怒自任，非其本心；惟輕信人言而不自求諸心，能不因人為毀譽，則好惡從心而傷害於物者多矣。","sortOrder":59},
  {"id":"s_work_ttcm_9_60","chapterId":"ch_work_ttcm_9","text":"簡，略也，無所難也，甚則不恭焉。","sortOrder":60},
  {"id":"s_work_ttcm_9_61","chapterId":"ch_work_ttcm_9","text":"難，去聲。於物無所難，以為不足较也。","sortOrder":61},
  {"id":"s_work_ttcm_9_62","chapterId":"ch_work_ttcm_9","text":"賢者仕祿，非迫於飢寒，不恭莫甚焉。","sortOrder":62},
  {"id":"s_work_ttcm_9_63","chapterId":"ch_work_ttcm_9","text":"孔子為委吏乘田，免於飢寒則去之。此伶官非以貧故，而謂世不足與有為，仕於卑賤，不恭之甚矣。","sortOrder":63},
  {"id":"s_work_ttcm_9_64","chapterId":"ch_work_ttcm_9","text":"“簡兮簡兮”，雖刺時君不用，然為士者不能無太簡之譏，故詩人陳其容色之盛，善御之強，","sortOrder":64},
  {"id":"s_work_ttcm_9_65","chapterId":"ch_work_ttcm_9","text":"推其賢以责備之。","sortOrder":65},
  {"id":"s_work_ttcm_9_66","chapterId":"ch_work_ttcm_9","text":"與夫君子由房由敖、不語其材武者異矣。","sortOrder":66},
  {"id":"s_work_ttcm_9_67","chapterId":"ch_work_ttcm_9","text":"君子陽陽，安分自得，無疾世之意，故無责焉。","sortOrder":67},
  {"id":"s_work_ttcm_9_68","chapterId":"ch_work_ttcm_9","text":"“破我斧”，“缺我斨”，言四國首亂，乌能有為，徒破缺我斧斨而已；","sortOrder":68},
  {"id":"s_work_ttcm_9_69","chapterId":"ch_work_ttcm_9","text":"四國：商、奄、管、蔡。","sortOrder":69},
  {"id":"s_work_ttcm_9_70","chapterId":"ch_work_ttcm_9","text":"周公征而安之，愛人之至也。","sortOrder":70},
  {"id":"s_work_ttcm_9_71","chapterId":"ch_work_ttcm_9","text":"谅其無能為而不窮兵致讨，念其愚而安之，周公之心，純乎仁愛。","sortOrder":71},
  {"id":"s_work_ttcm_9_72","chapterId":"ch_work_ttcm_9","text":"《伐柯》言正當加禮於周公，取人以身也。","sortOrder":72},
  {"id":"s_work_ttcm_9_73","chapterId":"ch_work_ttcm_9","text":"屈己而後能下賢。","sortOrder":73},
  {"id":"s_work_ttcm_9_74","chapterId":"ch_work_ttcm_9","text":"其終見《書》“予小子其新逆”。","sortOrder":74},
  {"id":"s_work_ttcm_9_75","chapterId":"ch_work_ttcm_9","text":"成王終成此詩之志。","sortOrder":75},
  {"id":"s_work_ttcm_9_76","chapterId":"ch_work_ttcm_9","text":"九罭，言王見周公當大其禮命，則大人可致也。","sortOrder":76},
  {"id":"s_work_ttcm_9_77","chapterId":"ch_work_ttcm_9","text":"君臣合德則禮命自隆，大人以道致，所謂“同聲相應，同氣相求”也。","sortOrder":77},
  {"id":"s_work_ttcm_9_78","chapterId":"ch_work_ttcm_9","text":"《狼跋》，美周公不失其聖，卒能感人心於和平也。","sortOrder":78},
  {"id":"s_work_ttcm_9_79","chapterId":"ch_work_ttcm_9","text":"庸人處变而不知自裁以禮，其賢者則改節降志以自貶損而免患，若郭子儀是已。聖人達於屈伸之感而貞其大常，靜正而物自感，心無私累，則物我之氣俱順。人心之和平，公心之和平化之也。","sortOrder":79},
  {"id":"s_work_ttcm_9_80","chapterId":"ch_work_ttcm_9","text":"《甫田》“歲取十千”，一成之田九萬畝。","sortOrder":80},
  {"id":"s_work_ttcm_9_81","chapterId":"ch_work_ttcm_9","text":"九萬畝，百井也。按四井為邑，四邑為丘，四丘為甸，甸地方八里，旁加一里為成，止六十五井，五萬八千五百畝，此雲“九萬畝”未詳。","sortOrder":81},
  {"id":"s_work_ttcm_9_82","chapterId":"ch_work_ttcm_9","text":"公取十千畝，九一之法也。","sortOrder":82},
  {"id":"s_work_ttcm_9_83","chapterId":"ch_work_ttcm_9","text":"後稷之生，當在尧舜之中年，","sortOrder":83},
  {"id":"s_work_ttcm_9_84","chapterId":"ch_work_ttcm_9","text":"舜攝政而使稷教稼穡，已強仕矣，此雲“中年”，未詳。","sortOrder":84},
  {"id":"s_work_ttcm_9_85","chapterId":"ch_work_ttcm_9","text":"而《詩》雲“上帝不寧”，疑在尧時高辛子孫為二王後，而詩人稱帝爾。","sortOrder":85},
  {"id":"s_work_ttcm_9_86","chapterId":"ch_work_ttcm_9","text":"此謂上帝為天子之稱，疑者，未定之辭。實則稷蓋帝挚之子，生於諸侯废挚、尧即位之初。挚，尧兄也，兄废弟立，未嘗改姓易服，不得稱“二王後”。此說未安。","sortOrder":86},
  {"id":"s_work_ttcm_9_87","chapterId":"ch_work_ttcm_9","text":"《唐棣》，枝類棘枝，隨節屈曲，","sortOrder":87},
  {"id":"s_work_ttcm_9_88","chapterId":"ch_work_ttcm_9","text":"未詳。","sortOrder":88},
  {"id":"s_work_ttcm_9_89","chapterId":"ch_work_ttcm_9","text":"其華一偏一反，","sortOrder":89},
  {"id":"s_work_ttcm_9_90","chapterId":"ch_work_ttcm_9","text":"向外生者偏，內出者反。","sortOrder":90},
  {"id":"s_work_ttcm_9_91","chapterId":"ch_work_ttcm_9","text":"左右相矯，因得全體均正。偏，喻管、蔡失道，反，喻周公誅殛。言我豈不思兄弟之愛，以權宜合義，主在遠者爾。","sortOrder":91},
  {"id":"s_work_ttcm_9_92","chapterId":"ch_work_ttcm_9","text":"所系者家國之大。","sortOrder":92},
  {"id":"s_work_ttcm_9_93","chapterId":"ch_work_ttcm_9","text":"唐棣本文王之詩，","sortOrder":93},
  {"id":"s_work_ttcm_9_94","chapterId":"ch_work_ttcm_9","text":"以“唐棣”為“棠棣”，又雲“文王作”，蓋誤。","sortOrder":94},
  {"id":"s_work_ttcm_9_95","chapterId":"ch_work_ttcm_9","text":"此一章周公製作，序己情而加之，","sortOrder":95},
  {"id":"s_work_ttcm_9_96","chapterId":"ch_work_ttcm_9","text":"謂周公增此一章。","sortOrder":96},
  {"id":"s_work_ttcm_9_97","chapterId":"ch_work_ttcm_9","text":"仲尼以不必常存而去之。","sortOrder":97},
  {"id":"s_work_ttcm_9_98","chapterId":"ch_work_ttcm_9","text":"漢註合上“可與共學”為一章，以偏反之反為反經合權之比，而張子因之，義多未順。張子之學主於心得，於博學詳說之功多所簡忽，若此類是也。","sortOrder":98},
  {"id":"s_work_ttcm_9_99","chapterId":"ch_work_ttcm_9","text":"日出而陰升自西，日迎而會之，雨之候也，","sortOrder":99},
  {"id":"s_work_ttcm_9_100","chapterId":"ch_work_ttcm_9","text":"日自東而西，微雨自西而東，與日柑會合，陰陽和則雨。","sortOrder":100},
  {"id":"s_work_ttcm_9_101","chapterId":"ch_work_ttcm_9","text":"喻昏姻之得禮者也；","sortOrder":101},
  {"id":"s_work_ttcm_9_102","chapterId":"ch_work_ttcm_9","text":"陽迎陰，男下女，以崇廉節也。","sortOrder":102},
  {"id":"s_work_ttcm_9_103","chapterId":"ch_work_ttcm_9","text":"日西矣而陰生於東，","sortOrder":103},
  {"id":"s_work_ttcm_9_104","chapterId":"ch_work_ttcm_9","text":"日已去而陰逐其後，日無會陰之心，陰強奔隨之，雨終不成。","sortOrder":104},
  {"id":"s_work_ttcm_9_105","chapterId":"ch_work_ttcm_9","text":"喻昏姻之失道者也。","sortOrder":105},
  {"id":"s_work_ttcm_9_106","chapterId":"ch_work_ttcm_9","text":"“朝隮於西，崇朝其雨”，正而和也；“螮蝀在東，則人莫敢指”，不正之氣也。張子此說為長。朱子謂虹蜺天之淫氣，不知微雨漾日光而成虹，人見之然爾，非實有虹也。言虹飲於井者，野人之說。","sortOrder":106},
  {"id":"s_work_ttcm_9_107","chapterId":"ch_work_ttcm_9","text":"鶴鳴而子和，言出之善者與！","sortOrder":107},
  {"id":"s_work_ttcm_9_108","chapterId":"ch_work_ttcm_9","text":"善則物必應。","sortOrder":108},
  {"id":"s_work_ttcm_9_109","chapterId":"ch_work_ttcm_9","text":"鶴鳴魚潛，畏聲聞之不臧者與！","sortOrder":109},
  {"id":"s_work_ttcm_9_110","chapterId":"ch_work_ttcm_9","text":"鶴鳴而聲聞於天，魚潛而或在渚，不善則不可掩也。故必善其鳴而慎其潛，乃以得臧。取喻同而義異，《易》以言好仁之益，《詩》以示惡不仁之警。","sortOrder":110},
  {"id":"s_work_ttcm_9_111","chapterId":"ch_work_ttcm_9","text":"“歍彼晨風，鬱彼北林”，晨風雖鷙击之鳥，猶時得退而依深林而止也。","sortOrder":111},
  {"id":"s_work_ttcm_9_112","chapterId":"ch_work_ttcm_9","text":"興勞人之不得息。","sortOrder":112},
  {"id":"s_work_ttcm_9_113","chapterId":"ch_work_ttcm_9","text":"《漸漸之石》言“有豕白蹢，烝涉波矣”。豕之負涂曳泥，其常性也；今豕足皆白，眾與涉波而去，水患之多為可知也。","sortOrder":113},
  {"id":"s_work_ttcm_9_114","chapterId":"ch_work_ttcm_9","text":"水患多則征人勞。","sortOrder":114},
  {"id":"s_work_ttcm_9_115","chapterId":"ch_work_ttcm_9","text":"“君子所貴乎道者三”，猶“王天下有三重焉”，言也，動也，行也。","sortOrder":115},
  {"id":"s_work_ttcm_9_116","chapterId":"ch_work_ttcm_9","text":"君子所貴乎道，求之身而已；言、行、動皆本諸身之道，立其本而中和致，乃可以製禮作樂。若讀數文章稽於眾，習之者能贊之，猶笾豆之事，任之有司可也。故道以反經為大。","sortOrder":116},
  {"id":"s_work_ttcm_9_117","chapterId":"ch_work_ttcm_9","text":"耇造德降，則民誠和而鳳可致；故鳴鳥聞，所以為和氣之應也。“誠”，當作“諴”","sortOrder":117},
  {"id":"s_work_ttcm_9_118","chapterId":"ch_work_ttcm_9","text":"天地人物之氣，其原一也。民和則天和不幹，天和則物效其和，德施普降，和氣達於萬民，而物應之不爽矣。","sortOrder":118},
  {"id":"s_work_ttcm_9_119","chapterId":"ch_work_ttcm_9","text":"九畴次叙：民資以生，莫先天材，故首曰五行；","sortOrder":119},
  {"id":"s_work_ttcm_9_120","chapterId":"ch_work_ttcm_9","text":"畴，事也；九事皆帝王臨民之大法。五行者，非天化之止於此，亦非天之秩分五者而不相為通，特以民生所資，厚生利用，需此五者，故炎上、润下、曲直、從革、稼穡及五味，皆就人所資用者言之。五行，天產之才以養民，而善用之者君道也；五事，天命之性以明民，而善用之者君德也；皆切乎民事而言，故曰范，曰畴。漢以後儒者不察，雜引術數家言，分配支離，皆不明於《洪范》之旨；而医卜星命之流，因緣附會以生克休王之鄙說。張子决言其為資生之材以辟邪說，韙矣。","sortOrder":120},
  {"id":"s_work_ttcm_9_121","chapterId":"ch_work_ttcm_9","text":"君天下必先正己，故次五事；","sortOrder":121},
  {"id":"s_work_ttcm_9_122","chapterId":"ch_work_ttcm_9","text":"正己而後可正人，踐形盡性，所以正己。","sortOrder":122},
  {"id":"s_work_ttcm_9_123","chapterId":"ch_work_ttcm_9","text":"己正然後邦得而治，故次八政；","sortOrder":123},
  {"id":"s_work_ttcm_9_124","chapterId":"ch_work_ttcm_9","text":"八政以節宣五行而立為常典。","sortOrder":124},
  {"id":"s_work_ttcm_9_125","chapterId":"ch_work_ttcm_9","text":"政不時舉必昏，故次五紀；","sortOrder":125},
  {"id":"s_work_ttcm_9_126","chapterId":"ch_work_ttcm_9","text":"合於天乃順於人。","sortOrder":126},
  {"id":"s_work_ttcm_9_127","chapterId":"ch_work_ttcm_9","text":"五紀明然後時措得中，故次建皇極；","sortOrder":127},
  {"id":"s_work_ttcm_9_128","chapterId":"ch_work_ttcm_9","text":"極建則隨時以處中。","sortOrder":128},
  {"id":"s_work_ttcm_9_129","chapterId":"ch_work_ttcm_9","text":"求大中不可不知權，故次三德；","sortOrder":129},
  {"id":"s_work_ttcm_9_130","chapterId":"ch_work_ttcm_9","text":"刚柔正直，各適其宜，權也。","sortOrder":130},
  {"id":"s_work_ttcm_9_131","chapterId":"ch_work_ttcm_9","text":"權必有疑，故次稽疑；循常而行，人謀定則可不待卜筮，行權有疑，而後决之以鬼謀。","sortOrder":131},
  {"id":"s_work_ttcm_9_132","chapterId":"ch_work_ttcm_9","text":"可征然後疑决，故次庶征；卜筮隱而天象顯。","sortOrder":132},
  {"id":"s_work_ttcm_9_133","chapterId":"ch_work_ttcm_9","text":"福極征，然後可不勞而治，故九以向勸終焉。刑賞合天則大法行，而非徒恃法也。","sortOrder":133},
  {"id":"s_work_ttcm_9_134","chapterId":"ch_work_ttcm_9","text":"五為數中，故皇極處之；權過中而合義者也，故三德處六。次叙之說，亦理之一端。以洛書證之，抑有不盡然者，讀者不必泥也。","sortOrder":134},
  {"id":"s_work_ttcm_9_135","chapterId":"ch_work_ttcm_9","text":"“親親尊尊”。周道也。","sortOrder":135},
  {"id":"s_work_ttcm_9_136","chapterId":"ch_work_ttcm_9","text":"又曰“親親尊賢”。周公治魯之道。","sortOrder":136},
  {"id":"s_work_ttcm_9_137","chapterId":"ch_work_ttcm_9","text":"義雖各施，然而親均則尊其尊，尊均則親其親為可矣。親尊互酌而重者見矣。","sortOrder":137},
  {"id":"s_work_ttcm_9_138","chapterId":"ch_work_ttcm_9","text":"若親均尊均，則齒不可以不先，此施於有親者不疑。昭穆亦序齒之推也。","sortOrder":138},
  {"id":"s_work_ttcm_9_139","chapterId":"ch_work_ttcm_9","text":"若尊賢之等，則於親之殺，必權而後行。賢均則以親疏尊卑為等。","sortOrder":139},
  {"id":"s_work_ttcm_9_140","chapterId":"ch_work_ttcm_9","text":"急親賢為尧、舜之道，親賢，謂親而賢者。","sortOrder":140},
  {"id":"s_work_ttcm_9_141","chapterId":"ch_work_ttcm_9","text":"然則親之賢先得之於疏之賢者為必然。先得，急之也；謂先舉而尊之。","sortOrder":141},
  {"id":"s_work_ttcm_9_142","chapterId":"ch_work_ttcm_9","text":"尧明俊德於九族而九族睦，明，顯也；表而尊之，則人皆喻於為善之榮。","sortOrder":142},
  {"id":"s_work_ttcm_9_143","chapterId":"ch_work_ttcm_9","text":"章俊德於百姓而萬邦协，黎民雍；九族之賢既舉而後舉庶士。百姓，謂百官賜族姓者。","sortOrder":143},
  {"id":"s_work_ttcm_9_144","chapterId":"ch_work_ttcm_9","text":"皋陶亦以惇叙九族、庶明励翼為邇可遠之道；庶明，庶士之賢者。邇可遠，謂即邇以及遠。","sortOrder":144},
  {"id":"s_work_ttcm_9_145","chapterId":"ch_work_ttcm_9","text":"則九族勉敬之人固先明之，然後遠者可次叙而及。周道以親親為本，一尧、舜之道也。","sortOrder":145},
  {"id":"s_work_ttcm_9_146","chapterId":"ch_work_ttcm_9","text":"《大學》謂“克明俊德”為自明其德，不若孔氏之註愈。","sortOrder":146},
  {"id":"s_work_ttcm_9_147","chapterId":"ch_work_ttcm_9","text":"義民，安分之良民而已；仅免於惡而不足與為善。","sortOrder":147},
  {"id":"s_work_ttcm_9_148","chapterId":"ch_work_ttcm_9","text":"俊民，俊德之民也。俊，大也；德大則所施亦大。","sortOrder":148},
  {"id":"s_work_ttcm_9_149","chapterId":"ch_work_ttcm_9","text":"官能則准牧無義民，乡党自好者，可使安於野而不可使在官。","sortOrder":149},
  {"id":"s_work_ttcm_9_150","chapterId":"ch_work_ttcm_9","text":"治昏則俊民用散。","sortOrder":150},
  {"id":"s_work_ttcm_9_151","chapterId":"ch_work_ttcm_9","text":"取小善而弃大德，昏主之所以坏風俗也；雖聖世不能無乡原，惟置而不用，則不足以賊德。","sortOrder":151},
  {"id":"s_work_ttcm_9_152","chapterId":"ch_work_ttcm_9","text":"五言樂語，歌詠五德之言也。","sortOrder":152},
  {"id":"s_work_ttcm_9_153","chapterId":"ch_work_ttcm_9","text":"樂語，所歌之文詞。","sortOrder":153},
  {"id":"s_work_ttcm_9_154","chapterId":"ch_work_ttcm_9","text":"“卜不習吉”，言卜官將占，先决問人心，有疑乃卜，無疑則否。","sortOrder":154},
  {"id":"s_work_ttcm_9_155","chapterId":"ch_work_ttcm_9","text":"理顯於明而故索之幽，徒亂德而已。","sortOrder":155},
  {"id":"s_work_ttcm_9_156","chapterId":"ch_work_ttcm_9","text":"“朕志無疑，人謀佥同”。故無所用卜；鬼神必依，龟筮必從。","sortOrder":156},
  {"id":"s_work_ttcm_9_157","chapterId":"ch_work_ttcm_9","text":"幽明無二理。","sortOrder":157},
  {"id":"s_work_ttcm_9_158","chapterId":"ch_work_ttcm_9","text":"故不必卜筮，玩習其吉以渎神也。","sortOrder":158},
  {"id":"s_work_ttcm_9_159","chapterId":"ch_work_ttcm_9","text":"謀已决而欲得吉占，玩神以自快而已。","sortOrder":159},
  {"id":"s_work_ttcm_9_160","chapterId":"ch_work_ttcm_9","text":"衍忒未分，有悔吝之防，此卜筮之所由作也。","sortOrder":160},
  {"id":"s_work_ttcm_9_161","chapterId":"ch_work_ttcm_9","text":"衍忒，數之過也。事非常而過於常數，為之則悔，不為則吝，故卜筮以决之。若吉凶之數適如其理，則受人之天下而不辭，蹈白刃而不避，何卜筮之有！卜筮者，所以審在己之悔吝，而非為吉凶也。","sortOrder":161},
  {"id":"s_work_ttcm_9_162","chapterId":"ch_work_ttcm_9","text":"王禘篇","sortOrder":162},
  {"id":"s_work_ttcm_9_163","chapterId":"ch_work_ttcm_9","text":"此篇略釋《三禮》之義，皆禮之大者，先王所以順天之秩叙而精其義者也。張子之學以立禮為本，而言禮則辨其大而遺其細。蓋大經有一定之理，而恭敬、撙節、退讓之宜，則存乎人之隨時以處中，而不在乎度數之察也。","sortOrder":163},
  {"id":"s_work_ttcm_9_164","chapterId":"ch_work_ttcm_9","text":"“禮不王不禘”，則知諸侯歲闕一祭為不禘明矣。","sortOrder":164},
  {"id":"s_work_ttcm_9_165","chapterId":"ch_work_ttcm_9","text":"謂夏、商春礿夏禘，即於夏季時享行大禘，諸侯不禘，則夏不祭。","sortOrder":165},
  {"id":"s_work_ttcm_9_166","chapterId":"ch_work_ttcm_9","text":"至周以祠為春，以禴為夏，宗廟歲六享，則二享四祭為六矣。","sortOrder":166},
  {"id":"s_work_ttcm_9_167","chapterId":"ch_work_ttcm_9","text":"二享：禘、祫；四祭：祠、禴、嘗、烝。","sortOrder":167},
  {"id":"s_work_ttcm_9_168","chapterId":"ch_work_ttcm_9","text":"諸侯不禘，其四享與！","sortOrder":168},
  {"id":"s_work_ttcm_9_169","chapterId":"ch_work_ttcm_9","text":"四時之祭闕其一，合祫而四。周製，諸侯各以其方助祭天子，故其時不行宗廟之祭。","sortOrder":169},
  {"id":"s_work_ttcm_9_170","chapterId":"ch_work_ttcm_9","text":"夏、商諸侯，夏特一祫，《王製》謂“礿則不禘，禘則不嘗”，假其名以見時祀之數爾；作《記》者不知文之害意，過矣。","sortOrder":170},
  {"id":"s_work_ttcm_9_171","chapterId":"ch_work_ttcm_9","text":"《王製》蓋謂諸侯祠則不礿，礿則不嘗，亦言闕一祭爾。假夏、商時享之名謂礿為禘，於文未審，恐讀者不察，且疑諸侯之亦禘，害於禮矣。夏、商諸侯，夏時天子大禘之時而祫祭，非禘也。作《記》者，漢文帝博士。","sortOrder":171},
  {"id":"s_work_ttcm_9_172","chapterId":"ch_work_ttcm_9","text":"禘於夏、周當是“商”字之訛為春夏，嘗於夏、商為秋冬，作《記》者交舉，以二氣對互而言爾。言禘以該礿，言嘗以該烝，《禮記》专言禘嘗者，以陰陽二氣之变，故於夏秋之交相對而言，略春冬而舉夏秋，要以夏、商之禮為名；若周，則禘在時享之外。","sortOrder":172},
  {"id":"s_work_ttcm_9_173","chapterId":"ch_work_ttcm_9","text":"享嘗雲者，享為追享朝享，禘亦其一爾。","sortOrder":173},
  {"id":"s_work_ttcm_9_174","chapterId":"ch_work_ttcm_9","text":"所自出之帝遠矣，故雲追享。朝享者，諸侯觐王亦有享禮，以下奉上之通詞，故禘亦可雲享。","sortOrder":174},
  {"id":"s_work_ttcm_9_175","chapterId":"ch_work_ttcm_9","text":"嘗以配享，亦對舉秋冬而言也。夏、商以禘為時祭，知追事之必在夏也。","sortOrder":175},
  {"id":"s_work_ttcm_9_176","chapterId":"ch_work_ttcm_9","text":"謂夏、商因夏之時祭而行大禘，故以與嘗對舉，嘗言秋冬，享言春夏。","sortOrder":176},
  {"id":"s_work_ttcm_9_177","chapterId":"ch_work_ttcm_9","text":"然則夏、商天子，歲乃五享，","sortOrder":177},
  {"id":"s_work_ttcm_9_178","chapterId":"ch_work_ttcm_9","text":"謂五祭。","sortOrder":178},
  {"id":"s_work_ttcm_9_179","chapterId":"ch_work_ttcm_9","text":"禘列四祭，併祫而五也。","sortOrder":179},
  {"id":"s_work_ttcm_9_180","chapterId":"ch_work_ttcm_9","text":"以不王不禘，禘為大享，故知夏禘之外不更別行時祭。","sortOrder":180},
  {"id":"s_work_ttcm_9_181","chapterId":"ch_work_ttcm_9","text":"周改禘為禴，","sortOrder":181},
  {"id":"s_work_ttcm_9_182","chapterId":"ch_work_ttcm_9","text":"則天子享六，禘祫給二祭，於四祭外別舉之。","sortOrder":182},
  {"id":"s_work_ttcm_9_183","chapterId":"ch_work_ttcm_9","text":"諸侯不禘，祫而不禘。","sortOrder":183},
  {"id":"s_work_ttcm_9_184","chapterId":"ch_work_ttcm_9","text":"又歲闕一祭，則亦四而已矣。《王製》所謂天子犆礿、祫禘、祫嘗、祫烝，既以禘為時祭，則祫可同時而舉。自註：礿以物薄，而犆嘗從舊","sortOrder":184},
  {"id":"s_work_ttcm_9_185","chapterId":"ch_work_ttcm_9","text":"祫禘雲者，據夏、商而言；祫禘、祫嘗、祫烝，謂隨三時可併行祫祭。","sortOrder":185},
  {"id":"s_work_ttcm_9_186","chapterId":"ch_work_ttcm_9","text":"諸侯礿犆，自註：如天子禘一犆一祫，言於夏禘之時正為一祭，","sortOrder":186},
  {"id":"s_work_ttcm_9_187","chapterId":"ch_work_ttcm_9","text":"不祫也。","sortOrder":187},
  {"id":"s_work_ttcm_9_188","chapterId":"ch_work_ttcm_9","text":"特一祫而已。","sortOrder":188},
  {"id":"s_work_ttcm_9_189","chapterId":"ch_work_ttcm_9","text":"祫隨秋冬行之。","sortOrder":189},
  {"id":"s_work_ttcm_9_190","chapterId":"ch_work_ttcm_9","text":"然則不王不禘，又著見於此矣。","sortOrder":190},
  {"id":"s_work_ttcm_9_191","chapterId":"ch_work_ttcm_9","text":"大禘不得言犆言祫；諸侯之言禘，非禘也，孟夏時享之名也。","sortOrder":191},
  {"id":"s_work_ttcm_9_192","chapterId":"ch_work_ttcm_9","text":"又雲嘗祫烝祫，則嘗蒸且祫無疑矣。","sortOrder":192},
  {"id":"s_work_ttcm_9_193","chapterId":"ch_work_ttcm_9","text":"秋嘗冬烝，可於一時併行，祫祭實止一祫也。","sortOrder":193},
  {"id":"s_work_ttcm_9_194","chapterId":"ch_work_ttcm_9","text":"若周製亦當闕一時之祭，則當雲諸侯祠則不禴，禴則不嘗。","sortOrder":194},
  {"id":"s_work_ttcm_9_195","chapterId":"ch_work_ttcm_9","text":"以夏、商之禮言，故雲禘。若以周製言之，則當雲祠禴，不當雲礿禘；作《記》者雜用三代之文，故害於意。反复釋此，所以申明不王不禘之大義。","sortOrder":195},
  {"id":"s_work_ttcm_9_196","chapterId":"ch_work_ttcm_9","text":"庶子不祭祖，自註：不止言王考而已","sortOrder":196},
  {"id":"s_work_ttcm_9_197","chapterId":"ch_work_ttcm_9","text":"大夫三廟而上，皆有祖廟祀始受命者。","sortOrder":197},
  {"id":"s_work_ttcm_9_198","chapterId":"ch_work_ttcm_9","text":"明其宗也；自註：明宗子當祭也","sortOrder":198},
  {"id":"s_work_ttcm_9_199","chapterId":"ch_work_ttcm_9","text":"庶子即為大夫，不得专立祖廟，後世乃可祖之；若宗子，則雖不為大夫，亦必祭祖。","sortOrder":199},
  {"id":"s_work_ttcm_9_200","chapterId":"ch_work_ttcm_9","text":"不祭祢，自註：以父為親之極甚者，故又發此文","sortOrder":200},
  {"id":"s_work_ttcm_9_201","chapterId":"ch_work_ttcm_9","text":"上庶子對繼祖之宗子而言，此庶子兼對繼祢之宗子而言。苟為庶子，則祢且不祭，况祖乎！明其宗也。","sortOrder":201},
  {"id":"s_work_ttcm_9_202","chapterId":"ch_work_ttcm_9","text":"唯繼祢之宗子乃得祭祢；庶子貴，以其牲就宗子而行事。","sortOrder":202},
  {"id":"s_work_ttcm_9_203","chapterId":"ch_work_ttcm_9","text":"庶子不為長子斬，不繼祖與祢故也。自註：此以服言，不以祭言，故又發此義","sortOrder":203},
  {"id":"s_work_ttcm_9_204","chapterId":"ch_work_ttcm_9","text":"凡庶子皆不繼祖，即有繼祢者，亦不為其長子斬，况繼祢者雖嫡長，但繼己而已，非祖祢之繼，義不得伸。","sortOrder":204},
  {"id":"s_work_ttcm_9_205","chapterId":"ch_work_ttcm_9","text":"“庶子不祭殇與無後者”，註：“不祭殇者，父之庶”，註，鄭氏註也。不繼祢之庶子，不繼己之殇。","sortOrder":205},
  {"id":"s_work_ttcm_9_206","chapterId":"ch_work_ttcm_9","text":"蓋以殇未足語世數，特以己不祭祢，故不祭之。","sortOrder":206},
  {"id":"s_work_ttcm_9_207","chapterId":"ch_work_ttcm_9","text":"此釋鄭註，言殇非父之適孫，不足列世數。己既非繼祢之宗，則殇卑賤不得祭。","sortOrder":207},
  {"id":"s_work_ttcm_9_208","chapterId":"ch_work_ttcm_9","text":"“不祭無後者，祖之庶也”，","sortOrder":208},
  {"id":"s_work_ttcm_9_209","chapterId":"ch_work_ttcm_9","text":"二句，鄭氏註文。於祖為庶孫，雖於祢為適子，可以祭殇，而不可以祭諸父崑弟之無後者。","sortOrder":209},
  {"id":"s_work_ttcm_9_210","chapterId":"ch_work_ttcm_9","text":"雖無後，以其成人備世數，當祔祖以祭之，己不祭祖，故不得而祭之也。","sortOrder":210},
  {"id":"s_work_ttcm_9_211","chapterId":"ch_work_ttcm_9","text":"釋鄭註，言己不敢入祖廟而祭，則共其祭物而宗子主焉，己不祭也。","sortOrder":211},
  {"id":"s_work_ttcm_9_212","chapterId":"ch_work_ttcm_9","text":"“祖庶之殇則自祭之也”，","sortOrder":212},
  {"id":"s_work_ttcm_9_213","chapterId":"ch_work_ttcm_9","text":"二句鄭氏註文。己為祖庶，於祢為適，則可祭己之適殇。","sortOrder":213},
  {"id":"s_work_ttcm_9_214","chapterId":"ch_work_ttcm_9","text":"言庶孫則得祭其子之殇者，以己為其祖矣，無所祔之也。","sortOrder":214},
  {"id":"s_work_ttcm_9_215","chapterId":"ch_work_ttcm_9","text":"釋鄭註，言庶子，祖之庶也。己之殇，己之適長殇，己為其祖者，己可祭祢為殇之祖矣。無所祔，言不須祔於己之祖廟。","sortOrder":215},
  {"id":"s_work_ttcm_9_216","chapterId":"ch_work_ttcm_9","text":"“凡所祭殇者唯適子”，鄭氏註文。此適子，謂殇。","sortOrder":216},
  {"id":"s_work_ttcm_9_217","chapterId":"ch_work_ttcm_9","text":"此據《禮》天子下祭殇五，皆適子適孫之類。故知凡殇非適不得特祭，惟從祖祔食。","sortOrder":217},
  {"id":"s_work_ttcm_9_218","chapterId":"ch_work_ttcm_9","text":"釋鄭註，言必有承祖世爵之貴乃特祭之，其他則難世數，必祔食乃祭。","sortOrder":218},
  {"id":"s_work_ttcm_9_219","chapterId":"ch_work_ttcm_9","text":"“無後者，謂諸父崑弟”，","sortOrder":219},
  {"id":"s_work_ttcm_9_220","chapterId":"ch_work_ttcm_9","text":"鄭氏註文。","sortOrder":220},
  {"id":"s_work_ttcm_9_221","chapterId":"ch_work_ttcm_9","text":"殇與無後者如祖廟在小宗之家，祭之如在大宗。自註：見《曾子問》註","sortOrder":221},
  {"id":"s_work_ttcm_9_222","chapterId":"ch_work_ttcm_9","text":"此引伸鄭註而言。祖廟在小宗之家，謂大夫更立祖廟別為一宗者。如在大宗，即祔於小宗家之廟，不必合於大宗，從祖而已。","sortOrder":222},
  {"id":"s_work_ttcm_9_223","chapterId":"ch_work_ttcm_9","text":"殷而上七廟，自祖考而下五，併遠廟為祧者二，","sortOrder":223},
  {"id":"s_work_ttcm_9_224","chapterId":"ch_work_ttcm_9","text":"據《王製》而言。","sortOrder":224},
  {"id":"s_work_ttcm_9_225","chapterId":"ch_work_ttcm_9","text":"無不遷之太祖廟。至周有不毀之祖，","sortOrder":225},
  {"id":"s_work_ttcm_9_226","chapterId":"ch_work_ttcm_9","text":"謂後稷。","sortOrder":226},
  {"id":"s_work_ttcm_9_227","chapterId":"ch_work_ttcm_9","text":"則三昭三穆，四為親廟，二為文、武二世室，併始祖而七。","sortOrder":227},
  {"id":"s_work_ttcm_9_228","chapterId":"ch_work_ttcm_9","text":"謂周之親廟止於四世，五世則祧。","sortOrder":228},
  {"id":"s_work_ttcm_9_229","chapterId":"ch_work_ttcm_9","text":"諸侯無二祧，","sortOrder":229},
  {"id":"s_work_ttcm_9_230","chapterId":"ch_work_ttcm_9","text":"謂世室。","sortOrder":230},
  {"id":"s_work_ttcm_9_231","chapterId":"ch_work_ttcm_9","text":"故五。","sortOrder":231},
  {"id":"s_work_ttcm_9_232","chapterId":"ch_work_ttcm_9","text":"四親廟，與始封之君而五。","sortOrder":232},
  {"id":"s_work_ttcm_9_233","chapterId":"ch_work_ttcm_9","text":"大夫無不遷之祖，則一昭一穆，","sortOrder":233},
  {"id":"s_work_ttcm_9_234","chapterId":"ch_work_ttcm_9","text":"父與王父。","sortOrder":234},
  {"id":"s_work_ttcm_9_235","chapterId":"ch_work_ttcm_9","text":"與祖考而三，","sortOrder":235},
  {"id":"s_work_ttcm_9_236","chapterId":"ch_work_ttcm_9","text":"祖考，謂曾祖。大夫不世官，祀之三世而止。","sortOrder":236},
  {"id":"s_work_ttcm_9_237","chapterId":"ch_work_ttcm_9","text":"故以祖考通謂為太祖。","sortOrder":237},
  {"id":"s_work_ttcm_9_238","chapterId":"ch_work_ttcm_9","text":"名為太祖，實祖考也；以西向之尊，故稱太祖。","sortOrder":238},
  {"id":"s_work_ttcm_9_239","chapterId":"ch_work_ttcm_9","text":"若祫，則請於其君，併高祖幹祫之。自註：幹祫之，不當祫而特祫之也","sortOrder":239},
  {"id":"s_work_ttcm_9_240","chapterId":"ch_work_ttcm_9","text":"併，合也；幹，求也。大夫不得合祭，貴大夫請於君而得行合食之禮。","sortOrder":240},
  {"id":"s_work_ttcm_9_241","chapterId":"ch_work_ttcm_9","text":"孔註“王製謂周製”，亦粗及之而不詳爾。","sortOrder":241},
  {"id":"s_work_ttcm_9_242","chapterId":"ch_work_ttcm_9","text":"孔註，孔穎達疏。《王製》所雲，非周製也。天子諸侯親廟各四，所謂五世而斬也。然二昭二穆必於四世，胡氏謂父死子繼，兄終弟及，皆為一世，則有兄弟踵立，如齊桓公四子皆為君，則不得祀其祖；且兄弟為昭穆而昭穆亂，其說非也。人君無子，則早立繼嗣，必以其昭穆，其未立者，非如漢之冲、质，君道未成，則自私而輕宗廟，當以無後祔食之例祔於祖廟，而不入世數。可知雖天子諸侯無後，亦不得特立廟也。","sortOrder":242},
  {"id":"s_work_ttcm_9_243","chapterId":"ch_work_ttcm_9","text":"“鋪筵設同幾”，疑左右幾一雲。","sortOrder":243},
  {"id":"s_work_ttcm_9_244","chapterId":"ch_work_ttcm_9","text":"享祖考以妣合食則設同幾。言同者，以別於左右各一幾也。疑者，釋其疑之謂。","sortOrder":244},
  {"id":"s_work_ttcm_9_245","chapterId":"ch_work_ttcm_9","text":"交鬼神異於人，故夫婦而同幾。","sortOrder":245},
  {"id":"s_work_ttcm_9_246","chapterId":"ch_work_ttcm_9","text":"人道則夫婦有別，交祖考者以神道，神則陰陽合德而資生，孝子慈孫以其精意感神於漠，即己之志氣而神在焉。己為考妣合一之身，不得有陰陽男女之異，鬼神無嫌，不必別也。","sortOrder":246},
  {"id":"s_work_ttcm_9_247","chapterId":"ch_work_ttcm_9","text":"求之或於室，或於祊也。","sortOrder":247},
  {"id":"s_work_ttcm_9_248","chapterId":"ch_work_ttcm_9","text":"於室者，正祭；於祊，繹祭也。一神而求之多方，神無定在也。夫婦同幾而不嫌於同，一神兩求而不嫌於異，知分合聚散之理，然後知禮之精義而入神。","sortOrder":248},
  {"id":"s_work_ttcm_9_249","chapterId":"ch_work_ttcm_9","text":"祭社稷五祀百神者，以百神之功報天之德爾。","sortOrder":249},
  {"id":"s_work_ttcm_9_250","chapterId":"ch_work_ttcm_9","text":"百神，皆天之神所分著者也，隨所著而報之。天德無方體，唯天子饗帝然。抑分而使人各效其報，以不忘資始之德。","sortOrder":250},
  {"id":"s_work_ttcm_9_251","chapterId":"ch_work_ttcm_9","text":"故以天事鬼神，事之至也，理之盡也。","sortOrder":251},
  {"id":"s_work_ttcm_9_252","chapterId":"ch_work_ttcm_9","text":"事鬼神而歸本於天，乃窮理以盡人事之至。淫祀者以鬼事鬼，不當於禮，其黷甚矣。","sortOrder":252},
  {"id":"s_work_ttcm_9_253","chapterId":"ch_work_ttcm_9","text":"“天子因生以賜姓，諸侯以字為謚”當是“氏”字之訛，蓋以尊統上、卑統下之義。","sortOrder":253},
  {"id":"s_work_ttcm_9_254","chapterId":"ch_work_ttcm_9","text":"天子賜諸侯之姓，推原其所自生，故魯、衛同於姬，齊、紀同於薑，本所自出之帝，統於一尊，所以尊諸侯而上之。諸侯賜大夫之氏，因王父之字為氏，不得上統於始祖，分族命氏，以明其所自出之卑。君臣之分，於斯著矣。","sortOrder":254},
  {"id":"s_work_ttcm_9_255","chapterId":"ch_work_ttcm_9","text":"“天子因生以賜姓”，難以命於下之人，亦尊統上之道也。","sortOrder":255},
  {"id":"s_work_ttcm_9_256","chapterId":"ch_work_ttcm_9","text":"下之人，同姓之大夫也。天子命其大夫之氏，亦必分而各使為氏，與侯國同。天子之大夫视侯，然唯諸侯則因生賜姓，而大夫否，尊統於上不得及下也。子男雖卑，君道也；天子之大夫雖貴，臣道也。","sortOrder":256},
  {"id":"s_work_ttcm_9_257","chapterId":"ch_work_ttcm_9","text":"此章舊分為二，今合之。","sortOrder":257},
  {"id":"s_work_ttcm_9_258","chapterId":"ch_work_ttcm_9","text":"據《玉藻》，疑天子聽朔於明堂，諸侯則於太廟，就藏朔之處告祖而行。","sortOrder":258},
  {"id":"s_work_ttcm_9_259","chapterId":"ch_work_ttcm_9","text":"聽朔，頒朔也。諸侯奉朔藏於太廟，每月告祖而行。胡氏曰：“月，王月也。王者贊天敷治，自己製之，諸侯不敢自专，待命於尊親。”","sortOrder":259},
  {"id":"s_work_ttcm_9_260","chapterId":"ch_work_ttcm_9","text":"受命祖廟，作龟祢宮，次序之宜。","sortOrder":260},
  {"id":"s_work_ttcm_9_261","chapterId":"ch_work_ttcm_9","text":"此師行之禮，受命宜於尊者，卜吉宜於親者。","sortOrder":261},
  {"id":"s_work_ttcm_9_262","chapterId":"ch_work_ttcm_9","text":"公之士及大夫之眾臣為“眾臣”，公之卿大夫、卿大夫之室老及家邑之士為“貴臣”。","sortOrder":262},
  {"id":"s_work_ttcm_9_263","chapterId":"ch_work_ttcm_9","text":"公之士，公之眾有司也；大夫之眾臣仕於大夫為群有司，非室老，又非宰邑者也。卿、大夫，公之貴臣；室老、邑宰，大夫之貴臣。","sortOrder":263},
  {"id":"s_work_ttcm_9_264","chapterId":"ch_work_ttcm_9","text":"上言“公士”，所以別士於公者也；","sortOrder":264},
  {"id":"s_work_ttcm_9_265","chapterId":"ch_work_ttcm_9","text":"此釋丧禮之文。別士於公，與士於家者也。士於家，更不在公室眾臣之列，愈賤而服愈降。","sortOrder":265},
  {"id":"s_work_ttcm_9_266","chapterId":"ch_work_ttcm_9","text":"下言“室老士”，所以別士於家者也。","sortOrder":266},
  {"id":"s_work_ttcm_9_267","chapterId":"ch_work_ttcm_9","text":"別士於家者，於公之士也，公之士不為大夫服。","sortOrder":267},
  {"id":"s_work_ttcm_9_268","chapterId":"ch_work_ttcm_9","text":"眾臣杖不以杖即位，疑義與庶子同。","sortOrder":268},
  {"id":"s_work_ttcm_9_269","chapterId":"ch_work_ttcm_9","text":"分卑則不得伸其哀。","sortOrder":269},
  {"id":"s_work_ttcm_9_270","chapterId":"ch_work_ttcm_9","text":"“適士”，疑諸侯荐於天子之士及王朝爵命之通名。","sortOrder":270},
  {"id":"s_work_ttcm_9_271","chapterId":"ch_work_ttcm_9","text":"諸侯所荐，仕於天子而受三命為士者，與諸侯之士有功而王命之者，皆曰適士。適士，對庶士之稱。","sortOrder":271},
  {"id":"s_work_ttcm_9_272","chapterId":"ch_work_ttcm_9","text":"蓋三命方受位天子之朝，於王朝有班位。","sortOrder":272},
  {"id":"s_work_ttcm_9_273","chapterId":"ch_work_ttcm_9","text":"一命再命受職受服者，疑官長自辟除，未有位於王朝，故謂之“官師”而已。","sortOrder":273},
  {"id":"s_work_ttcm_9_274","chapterId":"ch_work_ttcm_9","text":"官長，六官之長，諸侯自命者亦如之。","sortOrder":274},
  {"id":"s_work_ttcm_9_275","chapterId":"ch_work_ttcm_9","text":"“小事則专達”，蓋得自達於其君，不俟聞於長者，禮所謂“達官”者也。","sortOrder":275},
  {"id":"s_work_ttcm_9_276","chapterId":"ch_work_ttcm_9","text":"引《周禮》以證《禮記》達官之義。","sortOrder":276},
  {"id":"s_work_ttcm_9_277","chapterId":"ch_work_ttcm_9","text":"所謂“達官之長”者，得自達之長也；","sortOrder":277},
  {"id":"s_work_ttcm_9_278","chapterId":"ch_work_ttcm_9","text":"官皆統於六官為之長，而達官又各有長，如今製钦天監行人司遙屬禮部，而監正司正又為之長。","sortOrder":278},
  {"id":"s_work_ttcm_9_279","chapterId":"ch_work_ttcm_9","text":"所謂“官師”者，次其長者也。然則達官之長必三命而上者，官師則中士而再命者，庶士則一命為可知。","sortOrder":279},
  {"id":"s_work_ttcm_9_280","chapterId":"ch_work_ttcm_9","text":"《周禮》“小事則专達”，天子之官也。諸侯亦有達官之長，故以《周禮》推之，知其亦有专達之官，而有長有貳，長上士，貳則中、下士，故達官之長，於諸侯為貴臣。","sortOrder":280},
  {"id":"s_work_ttcm_9_281","chapterId":"ch_work_ttcm_9","text":"“賜官”，使臣其屬也。自註：若卿大夫以室老士為貴臣，未賜官則不得臣其士也","sortOrder":281},
  {"id":"s_work_ttcm_9_282","chapterId":"ch_work_ttcm_9","text":"明非但諸侯得有其臣，卿大夫既賜官，亦得臣其室老士。","sortOrder":282},
  {"id":"s_work_ttcm_9_283","chapterId":"ch_work_ttcm_9","text":"祖廟未毀，教於公宮。","sortOrder":283},
  {"id":"s_work_ttcm_9_284","chapterId":"ch_work_ttcm_9","text":"女子許嫁，教之三月。","sortOrder":284},
  {"id":"s_work_ttcm_9_285","chapterId":"ch_work_ttcm_9","text":"則知諸侯於有服族人亦引而親之，如家人焉。","sortOrder":285},
  {"id":"s_work_ttcm_9_286","chapterId":"ch_work_ttcm_9","text":"女子既然，則男子可知。諸侯絕期，而雲有服者，以士禮推之，五世內服屬也。","sortOrder":286},
  {"id":"s_work_ttcm_9_287","chapterId":"ch_work_ttcm_9","text":"“下而飲”者，不勝者自下堂而受飲也。其爭也，爭為謙讓而已。","sortOrder":287},
  {"id":"s_work_ttcm_9_288","chapterId":"ch_work_ttcm_9","text":"自安於不能，讓道也。","sortOrder":288},
  {"id":"s_work_ttcm_9_289","chapterId":"ch_work_ttcm_9","text":"君子之射，以中為勝，不必以貫革為勝。侯以布，鵠以革，其不貫革而墜於地者，中鵠為可知矣。","sortOrder":289},
  {"id":"s_work_ttcm_9_290","chapterId":"ch_work_ttcm_9","text":"鵠，栖皮於布，侯之中也。布易貫，革難貫，至革而墜，中可知矣。","sortOrder":290},
  {"id":"s_work_ttcm_9_291","chapterId":"ch_work_ttcm_9","text":"此“為力不同科”之一也。","sortOrder":291},
  {"id":"s_work_ttcm_9_292","chapterId":"ch_work_ttcm_9","text":"有力則貫，無力則否，先王因材取人而不求備，於《射禮》見其一。","sortOrder":292},
  {"id":"s_work_ttcm_9_293","chapterId":"ch_work_ttcm_9","text":"“知死而不知生，傷而不弔。”","sortOrder":293},
  {"id":"s_work_ttcm_9_294","chapterId":"ch_work_ttcm_9","text":"傷，哭也。","sortOrder":294},
  {"id":"s_work_ttcm_9_295","chapterId":"ch_work_ttcm_9","text":"畏、厭、溺可傷尤甚，故特致哀死者，","sortOrder":295},
  {"id":"s_work_ttcm_9_296","chapterId":"ch_work_ttcm_9","text":"畏，兵死；厭，木石厭死；溺，没水死。","sortOrder":296},
  {"id":"s_work_ttcm_9_297","chapterId":"ch_work_ttcm_9","text":"不弔生者以異之。","sortOrder":297},
  {"id":"s_work_ttcm_9_298","chapterId":"ch_work_ttcm_9","text":"雖知生亦不弔，蓋哀致於死者，則不暇及於生者。而致其親之死於畏、厭、溺，則不孝慈矣，雖與相知，絕之可也。為君父戰而死者，非畏也，不在不弔之科。","sortOrder":298},
  {"id":"s_work_ttcm_9_299","chapterId":"ch_work_ttcm_9","text":"且“如何不淑”之詞，無所施焉。","sortOrder":299},
  {"id":"s_work_ttcm_9_300","chapterId":"ch_work_ttcm_9","text":"有故而死，無容問之。此舊註文，申釋之以明情與文之必稱。","sortOrder":300},
  {"id":"s_work_ttcm_9_301","chapterId":"ch_work_ttcm_9","text":"“博依善依”，永而歌樂之也；","sortOrder":301},
  {"id":"s_work_ttcm_9_302","chapterId":"ch_work_ttcm_9","text":"習其音調也。","sortOrder":302},
  {"id":"s_work_ttcm_9_303","chapterId":"ch_work_ttcm_9","text":"“雜服”，雜習於製數服近之文也。","sortOrder":303},
  {"id":"s_work_ttcm_9_304","chapterId":"ch_work_ttcm_9","text":"近，猶習也。音調文儀，非禮樂之至，然器由道設，舍器而無以見道。","sortOrder":304},
  {"id":"s_work_ttcm_9_305","chapterId":"ch_work_ttcm_9","text":"《春秋》大要，天子之事也。","sortOrder":305},
  {"id":"s_work_ttcm_9_306","chapterId":"ch_work_ttcm_9","text":"大要，謂褒貶寓刑賞之權。","sortOrder":306},
  {"id":"s_work_ttcm_9_307","chapterId":"ch_work_ttcm_9","text":"故曰：“知我者其唯《春秋》乎，罪我者其唯《春秋》乎！”","sortOrder":307},
  {"id":"s_work_ttcm_9_308","chapterId":"ch_work_ttcm_9","text":"胡氏之說備矣。","sortOrder":308},
  {"id":"s_work_ttcm_9_309","chapterId":"ch_work_ttcm_9","text":"“苗而不秀者”與下“不足畏也”為一說。","sortOrder":309},
  {"id":"s_work_ttcm_9_310","chapterId":"ch_work_ttcm_9","text":"一說，猶言一章。","sortOrder":310},
  {"id":"s_work_ttcm_10_1","chapterId":"ch_work_ttcm_10","text":"張子正蒙註卷九","sortOrder":1},
  {"id":"s_work_ttcm_10_2","chapterId":"ch_work_ttcm_10","text":"乾稱篇上","sortOrder":2},
  {"id":"s_work_ttcm_10_3","chapterId":"ch_work_ttcm_10","text":"此篇張子書於四牖示學者，題曰订顽；伊川程子以啟爭為疑，改曰西銘。龟山楊氏疑其有體無用，近於墨氏，程子為辨明其理一分殊之義，論之詳矣。抑考君子之道，自漢以後，皆涉獵故跡，而不知聖學為人道之本。然濂溪周子首為《太極圖說》以究天人合一之原，所以明夫人之生也，皆天命流行之實，而以其神化之粹精為性，乃以為日用事物當然之理，無非陰陽变化自然之秩叙，有不可违。然所疑者，自太極分為兩儀，運為五行，而乾道成男，坤道成女，皆乾、坤之大德，資生資始；則人皆天地之生，而父母特其所禪之幾。則人可以不父其父而父天，不母其母而母地，與《六經》《語》《孟》之言相為蹠盭，而與釋氏真如緣起之說雖異而同。則濂溪之旨，必有為推本天親合一者，而後可以合乎人心、順乎天理而無敝；故張子此篇不容不作，而程子一本之說，誠得其立言之奧而釋學者之疑。竊嘗沉潛體玩而見其立義之精。其曰“乾稱父，坤稱母”，初不曰“天吾父，地吾母”也。從其大者而言之，則乾坤為父母，人物之胥生，生於天地之德也固然矣；從其切者而言之，則別無所謂乾，父即生我之乾，別無所謂坤，母即成我之坤；惟生我者其德統天以流形，故稱之曰父，惟成我者其德順天而厚載，故稱之曰母。故《書》曰“唯天地萬物父母”，統萬物而言之也；《詩》曰：“欲報之德，昊天罔極”，德者，健順之德，則就人之生而切言之也。盡敬以事父，則可以事天者在是；盡愛以事母，則可以事地者在是；守身以事親，則所以存心養性而事天者在是；推仁孝而有兄弟之恩、夫婦之義、君臣之道、朋友之交，則所以體天地而仁民愛物者在是。人之與天，理氣一也；而繼之以善，成之以性者，父母之生我，使我有形色以具天性者也。理在氣之中，而氣為父母之所自分，則即父母而溯之，其德通於天地也，無有間矣。若舍父母而親天地，雖極其心以扩大而企及之，而非有惻怛不容已之心動於所不可昧。是故於父而知乾元之大也，於母而知坤元之至也，此其誠之必幾，禽獸且有覺焉，而况於人乎！故曰“一陰一陽之謂道”，乾、坤之謂也；又曰“繼之者善，成之者性”，誰繼天而善吾生？誰成我而使有性？則父母之謂矣。繼之成之，即一陰一陽之道，則父母之外，天地之高明博厚，非可躐等而與之親，而父之為乾、母之為坤，不能離此以求天地之德，亦照然矣。張子此篇，補天人相繼之理，以孝道盡窮神知化之致，使學者不舍閨庭之愛敬，而盡致中和以位天地、育萬物之大用，誠本理之至一者以立言，而辟佛、老之邪迷，挽人心之橫流，真孟子以後所未有也。惜乎程、朱二子引而不發，未能洞示來茲也！此篇朱子摘出別行，而張子門人原合於全書，今仍附之篇中，以明張子學之全體。","sortOrder":3},
  {"id":"s_work_ttcm_10_4","chapterId":"ch_work_ttcm_10","text":"乾稱父，坤稱母；","sortOrder":4},
  {"id":"s_work_ttcm_10_5","chapterId":"ch_work_ttcm_10","text":"謂之父母者，亦名也；其心之心不忍忘，必不敢背者，所以生名之實也。惟乾之健，故不敢背，惟坤之順，故不忍忘，而推致其極，察乎天地，切求之近以念吾之所生成，則太和絪緼，中含健順之化，誠然而不可昧。故父母之名立，而稱天地為父母，跡異而理本同也。朱子曰：“天地者其形體，跡之與父母異者也；乾坤者其性情，理之同者也。”","sortOrder":5},
  {"id":"s_work_ttcm_10_6","chapterId":"ch_work_ttcm_10","text":"予茲藐焉，乃混然中處。","sortOrder":6},
  {"id":"s_work_ttcm_10_7","chapterId":"ch_work_ttcm_10","text":"混然，合而無間之謂。合父母之生成於一身，即合天地之性情於一心也。","sortOrder":7},
  {"id":"s_work_ttcm_10_8","chapterId":"ch_work_ttcm_10","text":"故天地之塞，吾其體；天地之帥，吾其性。","sortOrder":8},
  {"id":"s_work_ttcm_10_9","chapterId":"ch_work_ttcm_10","text":"塞者，流行充周；帥，所以主持而行乎秩叙也。塞者，氣也，氣以成形；帥者，志也，所謂天地之心也。天地之心，性所自出也。父母載乾、坤之德以生成，則天地運行之氣，生物之心在是，而吾之形色天性，與父母無二，即天地無二也。","sortOrder":9},
  {"id":"s_work_ttcm_10_10","chapterId":"ch_work_ttcm_10","text":"民，吾同胞；物，吾與也。","sortOrder":10},
  {"id":"s_work_ttcm_10_11","chapterId":"ch_work_ttcm_10","text":"由吾同胞之必友愛，交與之必信睦，則於民必仁，於物必愛之理，亦生心而不容已矣。","sortOrder":11},
  {"id":"s_work_ttcm_10_12","chapterId":"ch_work_ttcm_10","text":"大君者，吾父母宗子；其大臣，宗子之家相也。","sortOrder":12},
  {"id":"s_work_ttcm_10_13","chapterId":"ch_work_ttcm_10","text":"家之有宗子，父母所尊奉，乃天之秩叙，在人心理，必奉此而安者。唯其必有是心，必有是理，故“三月無君則皇皇如也”，“居是邦則事其大夫之賢者”，皆不容已之誠，而人道之所自立也。","sortOrder":13},
  {"id":"s_work_ttcm_10_14","chapterId":"ch_work_ttcm_10","text":"尊高年，所以長其長；慈孤弱，所以幼其幼。","sortOrder":14},
  {"id":"s_work_ttcm_10_15","chapterId":"ch_work_ttcm_10","text":"家之有長幼，必敬而慈之，故心從其類，有觸必感。此理人皆有之，最為明切。","sortOrder":15},
  {"id":"s_work_ttcm_10_16","chapterId":"ch_work_ttcm_10","text":"聖，其合德；賢，其秀也。","sortOrder":16},
  {"id":"s_work_ttcm_10_17","chapterId":"ch_work_ttcm_10","text":"合德，謂與父母之德合；秀者，父母所矜愛之賢子孫也。希聖友賢，成身以順親，即所以順天。","sortOrder":17},
  {"id":"s_work_ttcm_10_18","chapterId":"ch_work_ttcm_10","text":"凡天下疲癃殘疾茕獨鳏寡，皆吾兄弟之顛連而無告者也。","sortOrder":18},
  {"id":"s_work_ttcm_10_19","chapterId":"ch_work_ttcm_10","text":"顛連無告而無惻隱之心，則兄弟亦可不恤，故曰“苟能充之，足以保四海，苟不充之，不足以保妻子”，生理之明昧而已。","sortOrder":19},
  {"id":"s_work_ttcm_10_20","chapterId":"ch_work_ttcm_10","text":"“於時保之”，子之翼也；“樂且不忧”，純乎孝者也。","sortOrder":20},
  {"id":"s_work_ttcm_10_21","chapterId":"ch_work_ttcm_10","text":"守身以敬親而事天，則悅親而樂天，無小大之異也。","sortOrder":21},
  {"id":"s_work_ttcm_10_22","chapterId":"ch_work_ttcm_10","text":"违曰悖德，害仁曰賊，濟惡者不才；其踐形，惟肖者也。","sortOrder":22},
  {"id":"s_work_ttcm_10_23","chapterId":"ch_work_ttcm_10","text":"父母繼健順之理以生成，吾所求肖者此也。親志以從而無违為順，然有可從、不可從之異，而理則唯其善而從之者為順。不從其善而從其不善，或至於殘害天理，則賊所生之理矣。濟惡而不能幹蠱，父母成乎惡而為天之蠹矣；故必踐形斯為肖子，肖乾坤而後肖父母，為父母之肖子，則可肖天地矣。故舜所踐者瞽瞍之形，而與天合德。","sortOrder":23},
  {"id":"s_work_ttcm_10_24","chapterId":"ch_work_ttcm_10","text":"知化則善述其事，窮神則善繼其志。","sortOrder":24},
  {"id":"s_work_ttcm_10_25","chapterId":"ch_work_ttcm_10","text":"化者，天地生物之事；父母之必教育其子，亦此事也。善述者，必至於知化，而引伸之以陶成乎萬物。神者，天地生物之心理，父母所生氣中之理，亦即此也善繼者，必神無不存，而合撰於乾坤以全至德。","sortOrder":25},
  {"id":"s_work_ttcm_10_26","chapterId":"ch_work_ttcm_10","text":"不愧屋漏為無忝，存心養性為匪懈。","sortOrder":26},
  {"id":"s_work_ttcm_10_27","chapterId":"ch_work_ttcm_10","text":"止惡於幾微，存誠於不息，聖功之至，亦止以敬親之身而即以昭事上帝矣。","sortOrder":27},
  {"id":"s_work_ttcm_10_28","chapterId":"ch_work_ttcm_10","text":"惡旨酒，崇伯子之顧養；育英才，穎封人之錫類。","sortOrder":28},
  {"id":"s_work_ttcm_10_29","chapterId":"ch_work_ttcm_10","text":"惟遏欲可以養親，可以奉天；惟與人為善，則廣吾愛而弘天地之仁。","sortOrder":29},
  {"id":"s_work_ttcm_10_30","chapterId":"ch_work_ttcm_10","text":"不弛勞而底豫，舜其功也；","sortOrder":30},
  {"id":"s_work_ttcm_10_31","chapterId":"ch_work_ttcm_10","text":"不可逆者親，而有時不能順，舜盡誠而終於大順，以此知天地之变化剝复無恒，而大人拨亂反治，惟正己立誠而可挽氣化之偏。","sortOrder":31},
  {"id":"s_work_ttcm_10_32","chapterId":"ch_work_ttcm_10","text":"無所逃而待烹，申生其恭也。","sortOrder":32},
  {"id":"s_work_ttcm_10_33","chapterId":"ch_work_ttcm_10","text":"道盡則安命，而不以死為忧，蓋生我者乾、坤之大德，非己自有生而天奪之。故身為父母之身，殺之生之無可逃之義；德未至於聖，無如自靖以俟命。","sortOrder":33},
  {"id":"s_work_ttcm_10_34","chapterId":"ch_work_ttcm_10","text":"體其受而歸全者，參乎；","sortOrder":34},
  {"id":"s_work_ttcm_10_35","chapterId":"ch_work_ttcm_10","text":"全形以歸父母，全性以歸天地，而形色天性初不相離，全性乃可以全形。","sortOrder":35},
  {"id":"s_work_ttcm_10_36","chapterId":"ch_work_ttcm_10","text":"勇於從而順令者，伯奇也。","sortOrder":36},
  {"id":"s_work_ttcm_10_37","chapterId":"ch_work_ttcm_10","text":"勇於從，不畏難也。乾坤之德，易簡而已，而险阻該焉。故父母無不愛之子而不無苦難之令，勇於從則皆順矣。","sortOrder":37},
  {"id":"s_work_ttcm_10_38","chapterId":"ch_work_ttcm_10","text":"富貴福泽，將厚吾之生也；貧賤忧戚，庸玉汝於成也。","sortOrder":38},
  {"id":"s_work_ttcm_10_39","chapterId":"ch_work_ttcm_10","text":"乾坤之德至矣，或厚其生，或玉於成，皆所以成吾之德；父母之愛與勞，體此者也。無往而不體生成之德，何驕怨之有！","sortOrder":39},
  {"id":"s_work_ttcm_10_40","chapterId":"ch_work_ttcm_10","text":"存，吾順事；没，吾寧也。","sortOrder":40},
  {"id":"s_work_ttcm_10_41","chapterId":"ch_work_ttcm_10","text":"有一日之生，則受父母之生於一日，即受天地之化於一日，順事以没，事親之事畢，而無扰陰陽之和以善所歸，則適得吾常而化自正矣。","sortOrder":41},
  {"id":"s_work_ttcm_10_42","chapterId":"ch_work_ttcm_10","text":"此章切言君於修身立命存心養性之功，皆吾生所不容已之事，而即心以體之，則莫切於事親，故曰“仁之實，事親是也”。事親之中，天德存焉，則精義以存誠，誠有不容自諉者。若其負父母之生我，即負天地之大德。學者誠服膺焉，非徒扩其量之弘，而日乾夕惕之心，常有父母以臨之，惟恐或蔽於私，以悖德而賊仁，則成身之功，不待警而自篤矣。程、朱二子發明其體之至大，而未極其用之至切，蓋欲使學者自求之，而非可以論說窮其蘊也。","sortOrder":42},
  {"id":"s_work_ttcm_10_43","chapterId":"ch_work_ttcm_10","text":"乾稱篇下","sortOrder":43},
  {"id":"s_work_ttcm_10_44","chapterId":"ch_work_ttcm_10","text":"此篇張子書之東牖以示學者，名曰砭愚，蓋以砭二氏之愚而明聖道之要，程子改曰東銘。舊說唯“戲言出於思也”以下為東銘，今按十七篇之數，則此二篇合為一篇明矣，正之。","sortOrder":44},
  {"id":"s_work_ttcm_10_45","chapterId":"ch_work_ttcm_10","text":"凡可状，皆有也；","sortOrder":45},
  {"id":"s_work_ttcm_10_46","chapterId":"ch_work_ttcm_10","text":"實有其體，故可状。","sortOrder":46},
  {"id":"s_work_ttcm_10_47","chapterId":"ch_work_ttcm_10","text":"凡有，皆象也；","sortOrder":47},
  {"id":"s_work_ttcm_10_48","chapterId":"ch_work_ttcm_10","text":"天地之間所有者，形质雖殊而各肖其所生，皆天之所垂象者也。","sortOrder":48},
  {"id":"s_work_ttcm_10_49","chapterId":"ch_work_ttcm_10","text":"凡象，皆氣也。","sortOrder":49},
  {"id":"s_work_ttcm_10_50","chapterId":"ch_work_ttcm_10","text":"使之各成其象者，皆氣所聚也，故有陰有陽，有柔有刚，而聲色、臭味、性情、功效之象著焉。","sortOrder":50},
  {"id":"s_work_ttcm_10_51","chapterId":"ch_work_ttcm_10","text":"氣之性本虛而神，","sortOrder":51},
  {"id":"s_work_ttcm_10_52","chapterId":"ch_work_ttcm_10","text":"性，謂其自然之良能，未聚則虛，虛而能有，故神。虛則入萬象之中而不礙，神則生萬变之质而不窮。","sortOrder":52},
  {"id":"s_work_ttcm_10_53","chapterId":"ch_work_ttcm_10","text":"則神與性乃氣所固有，自其变化不测，則謂之神；自其化之各成而有其條理，以定志趣而效功能者，則謂之性。氣既神矣，神成理而成乎性矣，則氣之所至，神必行焉，性必凝焉，故物莫不含神而具性，人得其秀而最靈者爾。耳目官骸亦可状之象，凝滯之质，而良知良能之靈無不貫彻，蓋氣在而神與性偕也。","sortOrder":53},
  {"id":"s_work_ttcm_10_54","chapterId":"ch_work_ttcm_10","text":"此鬼神所以體物而不遺也。","sortOrder":54},
  {"id":"s_work_ttcm_10_55","chapterId":"ch_work_ttcm_10","text":"鬼神者，氣之往來屈伸者也，物以之終，以之始，孰能遺之。此言天下當有之物，皆神之所流行，理之所融結，大而山泽，小而崑虫草木，靈而為人、顽而為物，形形色色，重濁凝滯之质氣皆淪浃其中，與為屈伸。蓋天包地外而入於地中，重泉確石，天無不彻之化，則即象可以窮神，於形色而見天性，所以辟釋氏幻妄起滅，老、莊有生於無之陋說，而示學者不得離皆備之實體以求見性也。","sortOrder":55},
  {"id":"s_work_ttcm_10_56","chapterId":"ch_work_ttcm_10","text":"至誠，天性也；","sortOrder":56},
  {"id":"s_work_ttcm_10_57","chapterId":"ch_work_ttcm_10","text":"至誠者，實有之至也。目誠能明，耳誠能聰，思誠能睿，子誠能孝，臣誠能忠，誠有是形則誠有是性，此氣之保合太和以為定體者也。","sortOrder":57},
  {"id":"s_work_ttcm_10_58","chapterId":"ch_work_ttcm_10","text":"不息，天命也。","sortOrder":58},
  {"id":"s_work_ttcm_10_59","chapterId":"ch_work_ttcm_10","text":"天之命物，於無而使有，於有而使不窮，屈伸相禪而命之者不已，蓋無心而化成，無所倚而有所作止，方來不倦，成功不居；是以聰明可以日益，仁義可以日充。雖在人有學問之事，而所以能然者莫非天命。惟天有不息之命，故人得成其至誠之體；而人能成其至誠之體，則可以受天不息之命。不然，二氣之妙合自流行於兩間，而時雨不能润槁木，白日不能炤幽穀，命自不息而非其命，唯其有形不踐而失吾性也。","sortOrder":59},
  {"id":"s_work_ttcm_10_60","chapterId":"ch_work_ttcm_10","text":"人能至誠，則性盡而神可窮矣；","sortOrder":60},
  {"id":"s_work_ttcm_10_61","chapterId":"ch_work_ttcm_10","text":"有至誠之性在形中而盡之，則知神之妙萬物也。凡吾身之形，天下之物，形质嗜欲之粗滯，皆神之所不遺者。","sortOrder":61},
  {"id":"s_work_ttcm_10_62","chapterId":"ch_work_ttcm_10","text":"不息，則命行而化可知矣。","sortOrder":62},
  {"id":"s_work_ttcm_10_63","chapterId":"ch_work_ttcm_10","text":"天命不息，而人能瞬存息養，晨乾夕惕，以順天行，則刻刻皆與天相陟降，而受天之命，無有所遺，於凡萬物变化，萬事险阻，皆有百順至當之理，隨喜怒哀樂而合於太和，所以感人心於和平而贊天地之化育者，自無間矣。","sortOrder":63},
  {"id":"s_work_ttcm_10_64","chapterId":"ch_work_ttcm_10","text":"學未至知化，非真得也。自註：舍氣，有象否？非象，有意否？","sortOrder":64},
  {"id":"s_work_ttcm_10_65","chapterId":"ch_work_ttcm_10","text":"既言“學必至於知化”，又雲舍氣無象、非象無意，以見知化之學，非索之於虛空变幻之中，即此形形色色庶物人倫之理，無一義之不精，無一物之不體，則極盡乎氣之良能而化即在是，此至誠之所以無息。彼不誠無物者，以介然之悟，立幻妄之教，指休歇為究竟，事至物遷而不能繼，性之不盡而欲至於命，其狂愚甚矣。","sortOrder":65},
  {"id":"s_work_ttcm_10_66","chapterId":"ch_work_ttcm_10","text":"有無虛實通為一物者，性也；","sortOrder":66},
  {"id":"s_work_ttcm_10_67","chapterId":"ch_work_ttcm_10","text":"此理體验乃知之，於有而可不礙其未有，於未有而可以為有，非見見聞聞之所能逮。惟性則無無不有，無虛不實，有而不拘，實而不滯。故仁義禮智，求其形體，皆無也，虛也；而定為體，發為用，則皆有也，實也。耳之聰，目之明，心之睿，麗於事物者，皆有也，實也；而用之不测，則無也，虛也。至誠者，無而有，虛而實者也，此性之體撰為然也。","sortOrder":67},
  {"id":"s_work_ttcm_10_68","chapterId":"ch_work_ttcm_10","text":"不能為一，非盡性也。","sortOrder":68},
  {"id":"s_work_ttcm_10_69","chapterId":"ch_work_ttcm_10","text":"视之而見，聽之而聞，則謂之有；目窮於视，耳窮於德，則謂之無；功效可居，則謂之實；顽然寂靜，則謂之虛，故老氏以兩間為橐龠，釋氏以法界為夢幻，知有之有，而不知無之有；知虛之虛，而不知虛之實，因謂實不可居而有為妄。此正彼所謂徇耳目、內通而外於心知，捏目生花，自迷其頭者，而謂之盡性，可乎？","sortOrder":69},
  {"id":"s_work_ttcm_10_70","chapterId":"ch_work_ttcm_10","text":"飲食男女皆性也，","sortOrder":70},
  {"id":"s_work_ttcm_10_71","chapterId":"ch_work_ttcm_10","text":"理皆行乎其中也。","sortOrder":71},
  {"id":"s_work_ttcm_10_72","chapterId":"ch_work_ttcm_10","text":"是乌可滅！","sortOrder":72},
  {"id":"s_work_ttcm_10_73","chapterId":"ch_work_ttcm_10","text":"釋、老亦非能滅之，姑為之說爾。","sortOrder":73},
  {"id":"s_work_ttcm_10_74","chapterId":"ch_work_ttcm_10","text":"然則有無皆性也，是豈無對！","sortOrder":74},
  {"id":"s_work_ttcm_10_75","chapterId":"ch_work_ttcm_10","text":"老、釋以無在有外，夐然無對之孤光為性，惟不知神之與氣，氣之與形，相淪貫而為一體，虛者乃實之藏，而特聞見之所不逮爾。","sortOrder":75},
  {"id":"s_work_ttcm_10_76","chapterId":"ch_work_ttcm_10","text":"莊、老、浮屠為此說久矣，果畅真理乎？","sortOrder":76},
  {"id":"s_work_ttcm_10_77","chapterId":"ch_work_ttcm_10","text":"莊、老言虛無，言體之無也；浮屠言寂滅，言用之無也；而浮屠所雲真空者，則亦銷用以歸於無體。蓋晉、宋間人緣飾浮屠以莊、老之論，故教雖異而實同，其以飲食男女為妄，而廣徒眾以聚食，天理終不可滅。唯以孩提之愛為貪癡，父母為愛惑所感，毀人倫，滅天理，同於盜賊禽獸爾。","sortOrder":77},
  {"id":"s_work_ttcm_10_78","chapterId":"ch_work_ttcm_10","text":"天包載萬物於內，所感所性，乾坤、陰陽二端而已；","sortOrder":78},
  {"id":"s_work_ttcm_10_79","chapterId":"ch_work_ttcm_10","text":"陰陽實體，乾坤其德也。體立於未形之中，而德各效焉，所性也。有陰則必順以感乎陽，有陽則必健以感乎陰，相感以動而生生不息，因使各得陰陽之撰以成體而又生其感。","sortOrder":79},
  {"id":"s_work_ttcm_10_80","chapterId":"ch_work_ttcm_10","text":"無內外之合，無耳目之引取，與人物蕞然異矣。","sortOrder":80},
  {"id":"s_work_ttcm_10_81","chapterId":"ch_work_ttcm_10","text":"人物各成其蕞然之形，性藏不著而感以其畛，故見物為外，見己為內，色引其目而目蔽於色，聲引其耳而耳蔽於聲，因以所見聞者為有，不可見聞者為無，不能如天地之陰陽浑合，包萬物之屈伸而無所蔽也。","sortOrder":81},
  {"id":"s_work_ttcm_10_82","chapterId":"ch_work_ttcm_10","text":"人能盡性知天，不為蕞然起見，則幾矣。","sortOrder":82},
  {"id":"s_work_ttcm_10_83","chapterId":"ch_work_ttcm_10","text":"知其性之無不有而感以其動，感則明，不感則幽，未嘗無也，此不為耳目蕞然之見聞所域者也。","sortOrder":83},
  {"id":"s_work_ttcm_10_84","chapterId":"ch_work_ttcm_10","text":"有無一，內外合。自註：庸聖同","sortOrder":84},
  {"id":"s_work_ttcm_10_85","chapterId":"ch_work_ttcm_10","text":"雖愚不肖，苟非二氏之徒愚於所不見，則於見聞之外，亦不昧其有理，人倫庶物之中，亦不昧其有不可見之理而不可滅，此有無之一，庸之同於聖也。既已為人，則感必因乎其類，目合於色，口合於食，苟非如二氏之愚，欲閉內而滅外，使不得合，則雖聖人不能舍此而生其知覺，但即此而得其理爾。此內外之合，聖之同於庸也。","sortOrder":85},
  {"id":"s_work_ttcm_10_86","chapterId":"ch_work_ttcm_10","text":"此人心之所自來也。","sortOrder":86},
  {"id":"s_work_ttcm_10_87","chapterId":"ch_work_ttcm_10","text":"內心合外物以啟覺，心乃生焉，而於未有者知其有也；故人於所未見未聞者不能生其心。","sortOrder":87},
  {"id":"s_work_ttcm_10_88","chapterId":"ch_work_ttcm_10","text":"若聖人則不专以聞見為心，故能不专以聞見為用。","sortOrder":88},
  {"id":"s_work_ttcm_10_89","chapterId":"ch_work_ttcm_10","text":"流俗以逐聞見為用，釋、老以滅聞見為用，皆以聞見為心故也。昧其有無通一之性，則不知無之本有，而有者正所以載太虛之理。此盡心存神之功，唯聖人能純體之，超乎聞見，而聞見皆資以備道也。","sortOrder":89},
  {"id":"s_work_ttcm_10_90","chapterId":"ch_work_ttcm_10","text":"此章舊連下節為一，今分之。","sortOrder":90},
  {"id":"s_work_ttcm_10_91","chapterId":"ch_work_ttcm_10","text":"無所不感者，虛也；感即合也，鹹也。","sortOrder":91},
  {"id":"s_work_ttcm_10_92","chapterId":"ch_work_ttcm_10","text":"至虛之中，陰陽之撰具焉，絪緼不息，必無止機。故一物去而一物生，一事已而一事興，一念息而一念起，以生生無窮，而盡天下之理，皆太虛之和氣必動之幾也。陰陽合而後仁義行，倫物正，感之效也；無所不合，感之周遍者也，故謂之鹹。然則莫妙於感，而大經之正，百順之理在焉，二氏欲滅之，愚矣。","sortOrder":92},
  {"id":"s_work_ttcm_10_93","chapterId":"ch_work_ttcm_10","text":"以萬物本一，故一能合異；以其能合異，故謂之感；若非有異則無合。","sortOrder":93},
  {"id":"s_work_ttcm_10_94","chapterId":"ch_work_ttcm_10","text":"天下之物，皆天命所流行，太和所屈伸之化，既有形而又各成其陰陽刚柔之體，故一而異，惟其本一，故能合；惟其異，故必相須以成而有合。然則感而合者，所以化物之異而適於太和者也；非合人倫庶物之異而統於無異，則仁義不行。資天下之有以用吾之虛，鹹之彖辭曰：“觀其所感而天地萬物之情見矣。”見其情乃得其理，則盡性以合天者，必利用此幾而不容滅矣。","sortOrder":94},
  {"id":"s_work_ttcm_10_95","chapterId":"ch_work_ttcm_10","text":"天性，乾坤、陰陽也，","sortOrder":95},
  {"id":"s_work_ttcm_10_96","chapterId":"ch_work_ttcm_10","text":"我之性，乾坤之性，皆不越陰陽健順之二端，純驳、良楛、靈蠢，隨其质而皆兼體。","sortOrder":96},
  {"id":"s_work_ttcm_10_97","chapterId":"ch_work_ttcm_10","text":"二端，故有感；本一，故能合。","sortOrder":97},
  {"id":"s_work_ttcm_10_98","chapterId":"ch_work_ttcm_10","text":"健順刚柔，相須以濟，必感於物以生其用，而二端本太和，感之斯合矣。以知聲色、臭味、君臣、父子、賓主、賢愚，皆吾性相須以合一之誠，不容滅也。","sortOrder":98},
  {"id":"s_work_ttcm_10_99","chapterId":"ch_work_ttcm_10","text":"天地生萬物，所受雖不同，皆無須臾之不感，所謂性即天道也。","sortOrder":99},
  {"id":"s_work_ttcm_10_100","chapterId":"ch_work_ttcm_10","text":"天地之寒暑雨暘、風雷霜露、生長收藏，皆陰陽相感以為大用，萬物之所自生，即此動幾之成也。故萬物之情，無一念之間，無一刻之不與物交；嗜欲之所自興，即天理之所自出。耽嗜欲者迷於一往，感以其蕞然之聞見而不鹹爾，非果感之為害也。若君子瞬有存，息有養，晨乾夕惕，以趨時而應物，則即所感以見天地萬物之情，無物非性所皆備，即無感而非天道之流行矣。蓋萬物即天道以為性，陰陽具於中，故不窮於感，非陰陽相感之外，別有寂然空窅者以為性。釋氏欲却感以護其蕞然之靈，违天害性甚矣。","sortOrder":100},
  {"id":"s_work_ttcm_10_101","chapterId":"ch_work_ttcm_10","text":"感者，性之神；性者，感之體。自註：在人在天，其究一也","sortOrder":101},
  {"id":"s_work_ttcm_10_102","chapterId":"ch_work_ttcm_10","text":"健順，性也；動靜，感也；陰陽合於太和而相容，為物不貳，然而陰陽已自成乎其體性，待感而後合以起用。天之生物，人之成能，非有陰陽之體，感無從生，非乘乎感以動靜，則體中槁而不能起無窮之體。體生神，神复立體，由神之复立體，說者遂謂初無陰陽，靜乃生陰，動乃生陽，是徒知感後之體，而不知性在動靜之先本有其體也。","sortOrder":102},
  {"id":"s_work_ttcm_10_103","chapterId":"ch_work_ttcm_10","text":"惟屈伸動靜終始之能一也，故所以妙萬物而謂之神，通萬物而謂之道，體萬物而謂之性。","sortOrder":103},
  {"id":"s_work_ttcm_10_104","chapterId":"ch_work_ttcm_10","text":"屈伸動靜，感也，感者，因與物相對而始生，而萬物之靜躁、刚柔、吉凶、順逆，皆太和絪緼之所固有，以始於異而終於大同，則感雖乘乎異而要协於一也。是以神無不妙，道無不通，皆原於性之無不體；在天者本然，而人能盡性體道以窮神，亦惟不失其感之正爾。","sortOrder":104},
  {"id":"s_work_ttcm_10_105","chapterId":"ch_work_ttcm_10","text":"至虛之實，實而不固；至靜之動，動而不窮。","sortOrder":105},
  {"id":"s_work_ttcm_10_106","chapterId":"ch_work_ttcm_10","text":"在天者和氣絪緼於太虛，充塞無間，中涵神妙，隨形賦牛而不滯。在聖人無私而虛，虛以體理，無理不實；無欲而靜，靜以應感，無感不通。","sortOrder":106},
  {"id":"s_work_ttcm_10_107","chapterId":"ch_work_ttcm_10","text":"實而不固，則一而散；","sortOrder":107},
  {"id":"s_work_ttcm_10_108","chapterId":"ch_work_ttcm_10","text":"天以之併育不害，聖人以之與時偕行。","sortOrder":108},
  {"id":"s_work_ttcm_10_109","chapterId":"ch_work_ttcm_10","text":"動而不窮，則往且來。","sortOrder":109},
  {"id":"s_work_ttcm_10_110","chapterId":"ch_work_ttcm_10","text":"天以之運行不息，聖人以之屈伸合一，是窮神盡性，合天之道，惟在至虛之實，至靜之動而已。流俗滯於物以為實，逐於動而不反，異端虛則丧實，靜則废動，皆违性而失其神也。","sortOrder":110},
  {"id":"s_work_ttcm_10_111","chapterId":"ch_work_ttcm_10","text":"性通極於無，氣其一物爾。","sortOrder":111},
  {"id":"s_work_ttcm_10_112","chapterId":"ch_work_ttcm_10","text":"無，謂氣未聚，形未成，在天之神理。此所言氣，謂成形以後形中之氣，足以有為者也。氣亦受之於天，而神為之御，理為之宰，非氣之即為性也。","sortOrder":112},
  {"id":"s_work_ttcm_10_113","chapterId":"ch_work_ttcm_10","text":"命禀同於性，遇乃適然焉。","sortOrder":113},
  {"id":"s_work_ttcm_10_114","chapterId":"ch_work_ttcm_10","text":"天命之以生，即命之以性，性善而無惡，命亦吉而無凶；若否泰、利钝，因乎時之所遇，天化之屈伸，不以一人而設，遇之者吉凶殊爾。","sortOrder":114},
  {"id":"s_work_ttcm_10_115","chapterId":"ch_work_ttcm_10","text":"人一己百，人十己千，然有不至，猶難語性，可以言氣。","sortOrder":115},
  {"id":"s_work_ttcm_10_116","chapterId":"ch_work_ttcm_10","text":"在氣則有愚明、柔強之異，而性不異。故善學者存神而氣可变化，若恃氣之清刚，則終有所限。","sortOrder":116},
  {"id":"s_work_ttcm_10_117","chapterId":"ch_work_ttcm_10","text":"行同報異，猶難語命，可以言遇。","sortOrder":117},
  {"id":"s_work_ttcm_10_118","chapterId":"ch_work_ttcm_10","text":"比幹之死，孔、孟之窮，非天命之使然，所遇之時然也。故君子言知命、立命而不言安命，所安者遇也。以遇為命者，不知命者也。","sortOrder":118},
  {"id":"s_work_ttcm_10_119","chapterId":"ch_work_ttcm_10","text":"浮屠明鬼，謂有識之死，受生循環，遂厭苦求免，可謂知鬼乎？","sortOrder":119},
  {"id":"s_work_ttcm_10_120","chapterId":"ch_work_ttcm_10","text":"鬼者，歸也，歸於太虛之絪緼也。","sortOrder":120},
  {"id":"s_work_ttcm_10_121","chapterId":"ch_work_ttcm_10","text":"以人生為妄，可謂知人乎？","sortOrder":121},
  {"id":"s_work_ttcm_10_122","chapterId":"ch_work_ttcm_10","text":"人者，陰陽合德之神所聚，而相陰陽以协天地萬物之居者也。","sortOrder":122},
  {"id":"s_work_ttcm_10_123","chapterId":"ch_work_ttcm_10","text":"天人一物，辄生取舍，可謂知天乎？","sortOrder":123},
  {"id":"s_work_ttcm_10_124","chapterId":"ch_work_ttcm_10","text":"天之用在人，人之體無非天，天至虛而實，人實而含虛，聲色、臭味、父子、君臣、賓主、賢愚，皆天理之所顯現而流行，非空之而別有天也。","sortOrder":124},
  {"id":"s_work_ttcm_10_125","chapterId":"ch_work_ttcm_10","text":"孔、孟所謂天，彼所謂道。","sortOrder":125},
  {"id":"s_work_ttcm_10_126","chapterId":"ch_work_ttcm_10","text":"道一也，在天則為天道，在人則有人道。人之所謂道，人道也。人道不违於天，然強求同於天之虛靜，則必不可得，而終歸於無道。","sortOrder":126},
  {"id":"s_work_ttcm_10_127","chapterId":"ch_work_ttcm_10","text":"惑者指“遊魂為变”為輪回，未之思也。","sortOrder":127},
  {"id":"s_work_ttcm_10_128","chapterId":"ch_work_ttcm_10","text":"《易》言“遊魂為变”，謂魂返於天，唯天所变化，而非人之所能與。儒之驳者，惑於浮屠，謂死而魂不散，遊於兩間為中陰，身复隨因而变四生之果，誣聖教以助邪說，愚矣！","sortOrder":128},
  {"id":"s_work_ttcm_10_129","chapterId":"ch_work_ttcm_10","text":"大學當先知天德，知天德則知聖人，知鬼神。","sortOrder":129},
  {"id":"s_work_ttcm_10_130","chapterId":"ch_work_ttcm_10","text":"天之所以為天而化生萬物者，太和也，陰陽也，聚散之神也。聖人，體此者也；鬼神，其聚散之幾也。","sortOrder":130},
  {"id":"s_work_ttcm_10_131","chapterId":"ch_work_ttcm_10","text":"今浮屠極論要歸，必謂死生轉流，非得道不免，謂之悟道，可乎？自註：悟則有義有命，均死生一天人，惟知晝夜，通陰陽，體之不二","sortOrder":131},
  {"id":"s_work_ttcm_10_132","chapterId":"ch_work_ttcm_10","text":"死生流轉，無蕞然之形以限之，安得复即一人之神識還為一人，若屈伸乘時，則天德之固然，必不能免；假令能免，亦复何為？生而人，死而天，人盡人道而天還天德，其以合於陰陽之正者，一也。","sortOrder":132},
  {"id":"s_work_ttcm_10_133","chapterId":"ch_work_ttcm_10","text":"自其說炽傳中國，儒者未容窥聖學門牆，已為引取，淪胥其間，指為大道。","sortOrder":133},
  {"id":"s_work_ttcm_10_134","chapterId":"ch_work_ttcm_10","text":"由其不窥聖學，乍於流俗利欲之中聞清脱之說，意為歆動，或遂譏聖學為卑近，或誣聖學為一致，皆所必然。","sortOrder":134},
  {"id":"s_work_ttcm_10_135","chapterId":"ch_work_ttcm_10","text":"其俗達之天下，致善惡、知愚、男女、臧獲，人人著信。","sortOrder":135},
  {"id":"s_work_ttcm_10_136","chapterId":"ch_work_ttcm_10","text":"天下豈有男女、臧獲、淫坊、屠肆而可與語上之理？士君子不以為辱而指之為大道，愚矣哉！","sortOrder":136},
  {"id":"s_work_ttcm_10_137","chapterId":"ch_work_ttcm_10","text":"使英才閒氣，生則溺耳目恬習之事，長則師世儒宗尚之言，遂冥然被驅，","sortOrder":137},
  {"id":"s_work_ttcm_10_138","chapterId":"ch_work_ttcm_10","text":"如李習之、趙閱道、張子韶，皆英才也，被其驅而陷於邪，惜哉！","sortOrder":138},
  {"id":"s_work_ttcm_10_139","chapterId":"ch_work_ttcm_10","text":"因謂聖人可不修而至，大道可不學而知。故未識聖人心，已謂不必求其跡；未見君子志，已謂不必事其文。","sortOrder":139},
  {"id":"s_work_ttcm_10_140","chapterId":"ch_work_ttcm_10","text":"近世王氏良知之說正若此，一以浮屠言語道斷、心行路絕、迥脱根尘、不立知見為宗。","sortOrder":140},
  {"id":"s_work_ttcm_10_141","chapterId":"ch_work_ttcm_10","text":"此人倫所以不察，庶物所以不明，治所以忽，德所以亂，異言滿耳，上無禮以防其伪，下無學以稽其弊。","sortOrder":141},
  {"id":"s_work_ttcm_10_142","chapterId":"ch_work_ttcm_10","text":"王氏之學，一傳而為王畿，再傳而為李贽，無忌憚之教立，而廉恥丧、盜賊興，中國淪没，皆惟怠於明倫察物而求逸獲，故君父可以不恤，名義可以不顧。陆子靜出而宋亡，其流禍一也。","sortOrder":142},
  {"id":"s_work_ttcm_10_143","chapterId":"ch_work_ttcm_10","text":"自古诐淫邪遁之詞，翕然併興，一出於佛氏之門者千五百年，自非獨立不懼，精一自信，有大過人之才，何以正立其間，與之较是非、計得失？","sortOrder":143},
  {"id":"s_work_ttcm_10_144","chapterId":"ch_work_ttcm_10","text":"精者研幾精求，必求止於至善，惟精而後能一。","sortOrder":144},
  {"id":"s_work_ttcm_10_145","chapterId":"ch_work_ttcm_10","text":"釋氏語實际，乃知道者所謂誠也，天德也。","sortOrder":145},
  {"id":"s_work_ttcm_10_146","chapterId":"ch_work_ttcm_10","text":"既謂之實际，則必實有之而為事理之所自出，唯誠與天德可以當之。空則不實，莽荡虛枵則無际。","sortOrder":146},
  {"id":"s_work_ttcm_10_147","chapterId":"ch_work_ttcm_10","text":"其語到實际，則以人生為幻妄，有為為疣赘，以世界為陰濁，遂厭而不有，遺而弗存；就使得之，乃誠而惡明者也。","sortOrder":147},
  {"id":"s_work_ttcm_10_148","chapterId":"ch_work_ttcm_10","text":"釋氏之實际，大率以耳目之窮，疑其無有者也。生而與世相感，雖厭之，安能離之，雖遺之，安能使之無存！自欺而謂有得，信為實而自謂誠，於人倫庶物不明矣，則固伪而不誠矣。安有誠而惡明者哉！","sortOrder":148},
  {"id":"s_work_ttcm_10_149","chapterId":"ch_work_ttcm_10","text":"儒者則因明致誠，因誠致明，故天人合一，致學而可以成聖，得天而未始遺人，《易》所謂不遺、不流、不過者也。","sortOrder":149},
  {"id":"s_work_ttcm_10_150","chapterId":"ch_work_ttcm_10","text":"誠者，天之實理；明者，性之良能。性之良能出於天之實理，故交相致，而明誠合一。必於人倫庶物，研幾、精義、力行以推致其極，馴致於窮神，則天下之理得，而成位乎其中矣。","sortOrder":150},
  {"id":"s_work_ttcm_10_151","chapterId":"ch_work_ttcm_10","text":"彼語雖似是，觀其發本要歸，與吾儒二本殊歸矣。","sortOrder":151},
  {"id":"s_work_ttcm_10_152","chapterId":"ch_work_ttcm_10","text":"其發本也，下愚厭苦求樂之情；其要歸則求必不可得之真空而已。語似是者，謂戒邪淫、殺、盜之類。","sortOrder":152},
  {"id":"s_work_ttcm_10_153","chapterId":"ch_work_ttcm_10","text":"道一而已，此是則彼非，此非則彼是，固不當同日而語。","sortOrder":153},
  {"id":"s_work_ttcm_10_154","chapterId":"ch_work_ttcm_10","text":"後世陆子靜、王伯安必欲同之。","sortOrder":154},
  {"id":"s_work_ttcm_10_155","chapterId":"ch_work_ttcm_10","text":"其言流遁失守，","sortOrder":155},
  {"id":"s_work_ttcm_10_156","chapterId":"ch_work_ttcm_10","text":"始以白骨微尘為觀，不可行則轉曰事事無礙。","sortOrder":156},
  {"id":"s_work_ttcm_10_157","chapterId":"ch_work_ttcm_10","text":"窮大則淫，","sortOrder":157},
  {"id":"s_work_ttcm_10_158","chapterId":"ch_work_ttcm_10","text":"無量無邊，凭空為猖狂之語。","sortOrder":158},
  {"id":"s_work_ttcm_10_159","chapterId":"ch_work_ttcm_10","text":"推行則诐，","sortOrder":159},
  {"id":"s_work_ttcm_10_160","chapterId":"ch_work_ttcm_10","text":"為人之所不為，不為人之所為。","sortOrder":160},
  {"id":"s_work_ttcm_10_161","chapterId":"ch_work_ttcm_10","text":"致曲則邪，","sortOrder":161},
  {"id":"s_work_ttcm_10_162","chapterId":"ch_work_ttcm_10","text":"下而以金銀琉璃誘貪夫，以地獄饿鬼怖懦夫，以因果誘布施，不耕坐食。","sortOrder":162},
  {"id":"s_work_ttcm_10_163","chapterId":"ch_work_ttcm_10","text":"求之一卷之中，此弊數數有之。","sortOrder":163},
  {"id":"s_work_ttcm_10_164","chapterId":"ch_work_ttcm_10","text":"欲自回互，成其妄說故也。","sortOrder":164},
  {"id":"s_work_ttcm_10_165","chapterId":"ch_work_ttcm_10","text":"大率知晝夜陰陽，則能一性命；能知性命，則能知聖人，知鬼神。彼欲直語太虛，不以晝夜陰陽暴其心，則是未始見易；","sortOrder":165},
  {"id":"s_work_ttcm_10_166","chapterId":"ch_work_ttcm_10","text":"西域愚陋之民，本不足以知性命。中國之儒者，抑不能深研而體验之，而淫於邪說。故聞太虛之名，則以為空無所有而已，明則謂之有，幽則謂之無，豈知错綜往來，易之神乎！","sortOrder":166},
  {"id":"s_work_ttcm_10_167","chapterId":"ch_work_ttcm_10","text":"未始見易，則雖欲免陰陽晝夜之累，末由也已。","sortOrder":167},
  {"id":"s_work_ttcm_10_168","chapterId":"ch_work_ttcm_10","text":"彼欲免累者，怖死而已，故欲無生。陰陽晝夜，本非累也；見為累，安能免乎！","sortOrder":168},
  {"id":"s_work_ttcm_10_169","chapterId":"ch_work_ttcm_10","text":"易且不見，又乌能更語真际！","sortOrder":169},
  {"id":"s_work_ttcm_10_170","chapterId":"ch_work_ttcm_10","text":"易，感之神也。真际，性之體也。","sortOrder":170},
  {"id":"s_work_ttcm_10_171","chapterId":"ch_work_ttcm_10","text":"舍真际而談鬼神，妄也。","sortOrder":171},
  {"id":"s_work_ttcm_10_172","chapterId":"ch_work_ttcm_10","text":"其言鬼神也，無異於淫巫之陋。","sortOrder":172},
  {"id":"s_work_ttcm_10_173","chapterId":"ch_work_ttcm_10","text":"所謂實际，彼徒能語之而已，未始心解也。","sortOrder":173},
  {"id":"s_work_ttcm_10_174","chapterId":"ch_work_ttcm_10","text":"正蒙一編，所以發實际之藏也。","sortOrder":174},
  {"id":"s_work_ttcm_10_175","chapterId":"ch_work_ttcm_10","text":"《易》謂“原始反終故知死生之說”者，謂原始而知生，則求其終而知死必矣，此夫子所以直子路之問而不隱也。","sortOrder":175},
  {"id":"s_work_ttcm_10_176","chapterId":"ch_work_ttcm_10","text":"始終，非有無之謂也；始者聚之始，日增而生以盛，終者聚之終，數盈則日退而息於幽。非有則無以始，終而無則亦不謂之終矣，所自始者即所自終。故夫子令子路原始以知終，非拒其問之不切而不告也。","sortOrder":176},
  {"id":"s_work_ttcm_10_177","chapterId":"ch_work_ttcm_10","text":"體不偏滯，乃可謂無方無體。偏滯於晝夜陰陽者，物也；","sortOrder":177},
  {"id":"s_work_ttcm_10_178","chapterId":"ch_work_ttcm_10","text":"滯於有者不知死，滯於無者不知生。流俗異端，皆執物之滯於陰陽晝夜以為有無。","sortOrder":178},
  {"id":"s_work_ttcm_10_179","chapterId":"ch_work_ttcm_10","text":"若道，則兼體而無累也。","sortOrder":179},
  {"id":"s_work_ttcm_10_180","chapterId":"ch_work_ttcm_10","text":"為主於無聲無臭之中而不累於無，流行於人倫庶物之繁而不累於有，能明太虛之有實，乃可知萬象之皆神。","sortOrder":180},
  {"id":"s_work_ttcm_10_181","chapterId":"ch_work_ttcm_10","text":"以其兼體，故曰“一陰一陽”，","sortOrder":181},
  {"id":"s_work_ttcm_10_182","chapterId":"ch_work_ttcm_10","text":"言陰陽之均有也。此以靜生陰、動生陽言之。","sortOrder":182},
  {"id":"s_work_ttcm_10_183","chapterId":"ch_work_ttcm_10","text":"又曰“陰陽不测”，","sortOrder":183},
  {"id":"s_work_ttcm_10_184","chapterId":"ch_work_ttcm_10","text":"靜而生陰，非無陽；動而生陽，非無陰。","sortOrder":184},
  {"id":"s_work_ttcm_10_185","chapterId":"ch_work_ttcm_10","text":"又曰“一阖一辟”，","sortOrder":185},
  {"id":"s_work_ttcm_10_186","chapterId":"ch_work_ttcm_10","text":"陰受陽施而阖，陽施於陰而辟。","sortOrder":186},
  {"id":"s_work_ttcm_10_187","chapterId":"ch_work_ttcm_10","text":"又曰“通乎晝夜”。","sortOrder":187},
  {"id":"s_work_ttcm_10_188","chapterId":"ch_work_ttcm_10","text":"阖辟陰陽雖迭相為用，而道貫其中，晝夜一也。語其推行故曰“道”，在天為推行之理，在人則率之以行。","sortOrder":188},
  {"id":"s_work_ttcm_10_189","chapterId":"ch_work_ttcm_10","text":"語其不测故曰“神”，","sortOrder":189},
  {"id":"s_work_ttcm_10_190","chapterId":"ch_work_ttcm_10","text":"道為神所著之跡，神乃道之妙也。","sortOrder":190},
  {"id":"s_work_ttcm_10_191","chapterId":"ch_work_ttcm_10","text":"語其生生故曰“易”，","sortOrder":191},
  {"id":"s_work_ttcm_10_192","chapterId":"ch_work_ttcm_10","text":"不滯於一端而貫通乎終始，故变易而皆以順乎大經，易所著，其错綜化生之象。","sortOrder":192},
  {"id":"s_work_ttcm_10_193","chapterId":"ch_work_ttcm_10","text":"其實一物，指事異名爾。","sortOrder":193},
  {"id":"s_work_ttcm_10_194","chapterId":"ch_work_ttcm_10","text":"道函神而神成乎道，易於此生焉，則以明夫聚散死生皆在道之中，而非滅盡無餘，幻妄又起，別有出離之道也。","sortOrder":194},
  {"id":"s_work_ttcm_10_195","chapterId":"ch_work_ttcm_10","text":"大率天之為德，虛而善應，","sortOrder":195},
  {"id":"s_work_ttcm_10_196","chapterId":"ch_work_ttcm_10","text":"吉凶無成心，故曰虛。","sortOrder":196},
  {"id":"s_work_ttcm_10_197","chapterId":"ch_work_ttcm_10","text":"其應非思慮聰明可求，故謂之神。","sortOrder":197},
  {"id":"s_work_ttcm_10_198","chapterId":"ch_work_ttcm_10","text":"理有其定，合則應，或求而不得，或不求而得，人見其不测，不知其有定而謂之神。","sortOrder":198},
  {"id":"s_work_ttcm_10_199","chapterId":"ch_work_ttcm_10","text":"老氏况諸穀，以此。","sortOrder":199},
  {"id":"s_work_ttcm_10_200","chapterId":"ch_work_ttcm_10","text":"老氏見其自然之應，而以穀之應聲比之，亦相似矣。而穀無聲之實，天有應之理，則非老氏所知也。","sortOrder":200},
  {"id":"s_work_ttcm_10_201","chapterId":"ch_work_ttcm_10","text":"太虛者，氣之體。","sortOrder":201},
  {"id":"s_work_ttcm_10_202","chapterId":"ch_work_ttcm_10","text":"太虛之為體，氣也。氣未成象，人見其虛，充周無間者皆氣也。","sortOrder":202},
  {"id":"s_work_ttcm_10_203","chapterId":"ch_work_ttcm_10","text":"氣有陰陽。敔按：此二句指陰陽合於太和之氣","sortOrder":203},
  {"id":"s_work_ttcm_10_204","chapterId":"ch_work_ttcm_10","text":"此動靜之先，陰陽之本體也。","sortOrder":204},
  {"id":"s_work_ttcm_10_205","chapterId":"ch_work_ttcm_10","text":"屈伸相感之無窮，故神之應也無窮；","sortOrder":205},
  {"id":"s_work_ttcm_10_206","chapterId":"ch_work_ttcm_10","text":"氣有陰陽二殊，故以異而相感，其感者即其神也。無所不感，故神不息而應無窮。","sortOrder":206},
  {"id":"s_work_ttcm_10_207","chapterId":"ch_work_ttcm_10","text":"其散無數，故神之應也無數。","sortOrder":207},
  {"id":"s_work_ttcm_10_208","chapterId":"ch_work_ttcm_10","text":"既感而成象，漸以成形，靈蠢、大小、流峙、死生之散殊，雖各肖其所生而各自為體，不可以數計，而神皆行乎其間。無數者，不可紀之辭。性情、形象、色聲、臭味，無相肖者，人事之得失、悔吝亦如之。但此陰陽之变化屈伸，無有乖越，而欲分類自言之，則終不可得。邵子以數限之，愚所未詳。","sortOrder":208},
  {"id":"s_work_ttcm_10_209","chapterId":"ch_work_ttcm_10","text":"雖無窮，其實湛然；","sortOrder":209},
  {"id":"s_work_ttcm_10_210","chapterId":"ch_work_ttcm_10","text":"非逐物而應之，虛靜而含至理則自應。","sortOrder":210},
  {"id":"s_work_ttcm_10_211","chapterId":"ch_work_ttcm_10","text":"雖無數，其實一而已。","sortOrder":211},
  {"id":"s_work_ttcm_10_212","chapterId":"ch_work_ttcm_10","text":"無數者，不出陰陽之二端；陰陽之合於太和者，一也。","sortOrder":212},
  {"id":"s_work_ttcm_10_213","chapterId":"ch_work_ttcm_10","text":"陰陽之氣，散則萬殊，人莫知其一也；","sortOrder":213},
  {"id":"s_work_ttcm_10_214","chapterId":"ch_work_ttcm_10","text":"有形有象之後，執形執象之異而不知其本一。","sortOrder":214},
  {"id":"s_work_ttcm_10_215","chapterId":"ch_work_ttcm_10","text":"合則混然，人不見其殊也。","sortOrder":215},
  {"id":"s_work_ttcm_10_216","chapterId":"ch_work_ttcm_10","text":"象未著，形未成，人但見太虛之同於一色，而不知其有陰陽自有無窮之應。","sortOrder":216},
  {"id":"s_work_ttcm_10_217","chapterId":"ch_work_ttcm_10","text":"形聚為物，","sortOrder":217},
  {"id":"s_work_ttcm_10_218","chapterId":"ch_work_ttcm_10","text":"神在形中。","sortOrder":218},
  {"id":"s_work_ttcm_10_219","chapterId":"ch_work_ttcm_10","text":"形潰反原。","sortOrder":219},
  {"id":"s_work_ttcm_10_220","chapterId":"ch_work_ttcm_10","text":"形散而氣不損。","sortOrder":220},
  {"id":"s_work_ttcm_10_221","chapterId":"ch_work_ttcm_10","text":"反原者，其遊魂為变與！","sortOrder":221},
  {"id":"s_work_ttcm_10_222","chapterId":"ch_work_ttcm_10","text":"遊於太虛以聽天之变化。","sortOrder":222},
  {"id":"s_work_ttcm_10_223","chapterId":"ch_work_ttcm_10","text":"所謂变者，對聚散、存亡為文，","sortOrder":223},
  {"id":"s_work_ttcm_10_224","chapterId":"ch_work_ttcm_10","text":"聚而散，散而聚，故時存時亡。","sortOrder":224},
  {"id":"s_work_ttcm_10_225","chapterId":"ch_work_ttcm_10","text":"非如螢雀之化，指前後身而為說也。","sortOrder":225},
  {"id":"s_work_ttcm_10_226","chapterId":"ch_work_ttcm_10","text":"散而反原，無复有形之蕞然者以拘之。即前身為後身，釋氏之陋說也。","sortOrder":226},
  {"id":"s_work_ttcm_10_227","chapterId":"ch_work_ttcm_10","text":"益物必誠，如天之生物，日進日息；","sortOrder":227},
  {"id":"s_work_ttcm_10_228","chapterId":"ch_work_ttcm_10","text":"息，長也。誠者，如其應得之理而予之，不計功，不謀利，自見為不容已，無所吝而不倦也。誠，故於物無所矯強，而因材之篤不妄，此天之所以神也。至誠之教育而物自化亦如之，惟誠斯感而神。","sortOrder":228},
  {"id":"s_work_ttcm_10_229","chapterId":"ch_work_ttcm_10","text":"自益必誠，如川之方至，日增日得。","sortOrder":229},
  {"id":"s_work_ttcm_10_230","chapterId":"ch_work_ttcm_10","text":"以實理為學，貞於一而通於萬，則學問思辨皆逢其原，非少有得而自恃以止也。自益益人，皆唯盡其誠，而非在聞見作為之間，此存神之所以百順也。","sortOrder":230},
  {"id":"s_work_ttcm_10_231","chapterId":"ch_work_ttcm_10","text":"施之妄，學之不勤，","sortOrder":231},
  {"id":"s_work_ttcm_10_232","chapterId":"ch_work_ttcm_10","text":"恃聰明聞見，而不存神以體實理，其教人必抑人從己，其自為學必矜妙悟而不求貫通，怠於精義，必成乎妄也。","sortOrder":232},
  {"id":"s_work_ttcm_10_233","chapterId":"ch_work_ttcm_10","text":"欲自益且益人，難矣哉！","sortOrder":233},
  {"id":"s_work_ttcm_10_234","chapterId":"ch_work_ttcm_10","text":"異端之教學以之。","sortOrder":234},
  {"id":"s_work_ttcm_10_235","chapterId":"ch_work_ttcm_10","text":"《易》曰：“益長裕而不設。”信夫！","sortOrder":235},
  {"id":"s_work_ttcm_10_236","chapterId":"ch_work_ttcm_10","text":"設者，非理所固有，隨意所見，立科范以求益於其中也。小有所覺，大有所迷，妾而已矣，惟求速獲而倦勤故也。蓋誠原不息，息則不誠。張子之言天道、聖學，皆上達之旨，而要歸於不妄而勤，所以體自強不息之天德，為下學處心用力之實功，示學有以企及，至深切矣。","sortOrder":236},
  {"id":"s_work_ttcm_10_237","chapterId":"ch_work_ttcm_10","text":"將修己，必先厚重以自持；厚重知學，德乃進而不固矣。","sortOrder":237},
  {"id":"s_work_ttcm_10_238","chapterId":"ch_work_ttcm_10","text":"妄而不勤者，必輕佻而驕吝，誠之不存，神去之矣。","sortOrder":238},
  {"id":"s_work_ttcm_10_239","chapterId":"ch_work_ttcm_10","text":"忠信進德，惟尚友而急賢；欲勝己者親，無如改過之不吝。","sortOrder":239},
  {"id":"s_work_ttcm_10_240","chapterId":"ch_work_ttcm_10","text":"過之成也，成於徇跡而妄動；徇物欲，徇意氣，皆妾感之跡也。改過不吝，反而求之於心之安，則賢者樂與之親而氣不妄動，神乃可存，所學皆天德之實矣。靜专動直，氣正而不息，作聖之功，反求諸身心而已也。敔按：此章釋《論語》“君子不重”章之旨，為下東銘所元本","sortOrder":240},
  {"id":"s_work_ttcm_10_241","chapterId":"ch_work_ttcm_10","text":"戲言出於思也，戲動作於謀也。","sortOrder":241},
  {"id":"s_work_ttcm_10_242","chapterId":"ch_work_ttcm_10","text":"言動雖無大咎，而非理所以應然，任一時之適者，皆戲也。心無遊泆之情，則戲言何自而生；不謀非所當為之事，則戲動何自而成？凝神正氣，則二者之失亡矣。敔按：此“思”字猶《易》“朋從爾思”之思","sortOrder":242},
  {"id":"s_work_ttcm_10_243","chapterId":"ch_work_ttcm_10","text":"發乎聲，見乎四支，謂非己心，不明也；欲人無己疑，不能也。","sortOrder":243},
  {"id":"s_work_ttcm_10_244","chapterId":"ch_work_ttcm_10","text":"見於身則已動其心，加於人則人見其妄，而謂偶然言動，無關得失乎！蘇子瞻之所以淫昵而召禍也。","sortOrder":244},
  {"id":"s_work_ttcm_10_245","chapterId":"ch_work_ttcm_10","text":"過言非心也，過動非誠也。","sortOrder":245},
  {"id":"s_work_ttcm_10_246","chapterId":"ch_work_ttcm_10","text":"非物理之應得，任聞見之小辨以言動，雖始非不善而終成乎惡，謂之過。非心者，非其初心，非誠者，非心之實得。敔按：心者，自盡之心；誠者，實有之理，忠信是也","sortOrder":246},
  {"id":"s_work_ttcm_10_247","chapterId":"ch_work_ttcm_10","text":"失於聲，缪迷其四體，謂己當然，自誣也；欲他人己從，誣人也。","sortOrder":247},
  {"id":"s_work_ttcm_10_248","chapterId":"ch_work_ttcm_10","text":"始亦有意於善，而過則終成乎惡矣。不存誠精義以求至當，自恃其初心之近道自誣，則未有能強人者也。王介甫之所以怙過而取之於天下也。","sortOrder":248},
  {"id":"s_work_ttcm_10_249","chapterId":"ch_work_ttcm_10","text":"或者以出於心者歸咎為己戲，失於思者自誣為己誠；敔按：出於實心者必不戲，失於浮思者必不誠","sortOrder":249},
  {"id":"s_work_ttcm_10_250","chapterId":"ch_work_ttcm_10","text":"謂為戲，無傷於大義；誣為誠，謂可不怍於天人；自命為君子而成乎妄人。","sortOrder":250},
  {"id":"s_work_ttcm_10_251","chapterId":"ch_work_ttcm_10","text":"不知戒其出汝者，歸咎其不出汝者，長傲且遂非，不知孰甚焉！敔按：戒其出汝者，謂戒其朋從之思；歸咎其不出汝者，謂心不自盡，歸咎於偶戲","sortOrder":251},
  {"id":"s_work_ttcm_10_252","chapterId":"ch_work_ttcm_10","text":"謂己戲而人何疑之已甚，謂偶有過而人不相谅以信從，則怨天尤人，而不知下學之不立其基也。重則無戲，改則無過，瞬有存，息有養，何暇至於戲！過豈有不知，知豈有复行者乎！合天存神之學，切於身心者如此，下學而作聖之功在矣，盡己而化物之道存矣，故正蒙以此終焉。","sortOrder":252},
  {"id":"s_work_ttcm_11_1","chapterId":"ch_work_ttcm_11","text":"自叙","sortOrder":1},
  {"id":"s_work_ttcm_11_2","chapterId":"ch_work_ttcm_11","text":"境識生則患不得，熟則患失之。與其失之也，寧不得，此予所知而自懼者也。五十以前不得者多矣，五十以後，未敢謂得。一往每幾於失，中間不無力為檠括，而檠括之難，予自知之，抑自提之。","sortOrder":2},
  {"id":"s_work_ttcm_11_3","chapterId":"ch_work_ttcm_11","text":"詩言志，又曰詩以道性情。賦亦詩之一也。人苟有志，死生以之，性亦自定，情不能不因時爾。楚人之謂葉公子高，一曰君胡胄，一曰君胡不胄，雲胄雲不胄，皆情之至者也。葉公子高處此，殆有難言者。甲寅以還，不期身遇之。或謂予胡胄，或謂予胡不胄，皆愛我者，誰知予情。予且不能自言，况望知者哉！","sortOrder":3},
  {"id":"s_work_ttcm_11_4","chapterId":"ch_work_ttcm_11","text":"此十年中，別有《柳岸吟》，欲遇一峰白沙定山，於流連骀宕中學詩，幾四十年。自應舍旃，以求適於柳風桐月，則與馬班顏謝了不相應，固其所已。彼體自張子寿《感遇》开之先，朱文公遂大振金玉。竊謂使彭泽能早知此，當不仅為彭泽矣；阮步兵仿佛此意，而自然別為酒人。故和阮和陶，各如其量，止於阮陶之邊际，不能欺也。庚申上巳湘西草堂記。","sortOrder":4},
];

export const ttcmOverrides: Record<string, Record<string, [string, string, string]>> = {};
